INSERT INTO `locales_quest` (`entry`,`Details_loc2`) VALUES (12192,'Les Sombrefers ont pris une raclée ! Lorsqu’ils se sont repliés sur le Sinistre écluseur, ils ont perdu un bout de leur transport. Mieux encore, vous avez protégé le camp… pour aujourd’hui.$B$BAllez voir Bizzle et racontez-lui votre triomphe face aux Sombrefer.') ON DUPLICATE KEY UPDATE `Details_loc2`=IF(COALESCE(`Details_loc2`,'')='',VALUES(`Details_loc2`),`Details_loc2`);
INSERT INTO `locales_quest` (`entry`,`Objectives_loc2`) VALUES (12192,'Parlez à Bizzle Soulevite au campement de la fête des Brasseurs.') ON DUPLICATE KEY UPDATE `Objectives_loc2`=IF(COALESCE(`Objectives_loc2`,'')='',VALUES(`Objectives_loc2`),`Objectives_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (24,'La tête de Shadumbra ?$B$BNul ne saurait dire combien de nos frères de la Horde ont été les victimes de cette bête au cours des années. Grâce à votre bravoure, nul autre ne connaîtra ce destin.$B$BLe chef de guerre Hurlenfer entendra parler de vos exploits, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5061,'Très impressionnant, $N. Vous pouvez désormais acquérir votre forme aquatique, et cela sera un plaisir pour moi de vous l\'enseigner.$B$BDe plus, pour récompenser votre performance lors des deux dernières épreuves, je vous donne cet objet. J\'espère qu\'il vous sera utile dans votre rôle de protecteur de la nature et de gardien de l\'équilibre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (32,'Oui… J\'ai déjà eu affaire à ces bêtes dans le passé. Fizzledowser a été bien avisé de vous envoyer avec ce rapport.$B$BCes créatures vont consumer le désert de Tanaris très rapidement. Elles ne sont rien de moins que l\'un des plus grands dangers auxquels nous aurons jamais à faire face. Retenez ce nom, $N : les silithides. Les insectes mentionnés ici sont des silithides et ce sont les instruments de l\'une des plus grandes menaces que l\'Alliance et la Horde affronteront jamais.$B$BSi seulement nous avions été plus perspicaces.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (53,'Vieilli en fût, et par le charbon filtré$BIl passe sur vos lèvres, pour ensuite votre esprit transpercer.$BMaintenant buvons, pour vous un toast portons$BEt tant que vous êtes là, un toast pour Grimbooze Thunderbrew aussi portons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (63,'Vous placez les bracelets au milieu du brasero, puis versez la potion de Brine dans les flammes. Les gouttes crépitent lorsqu\'elles tombent dans le feu et vous commencez à entonner les mots simples de l\'incantation que vous a appris Islen.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (96,'C\'est la preuve que je demandais. Vous avez fait du bon travail, $N.$B$BJe vous félicite et je vous remets ceci : votre totem d\'eau.$B$BUtilisez-le à bon escient, et bonne chance.$B$BVotre prochaine épreuve est pour bientôt, apprenez bien vos leçons. L\'eau pure ne soigne pas uniquement les gens blessés, mais a bien d\'autres effets. Je vous suggère de chercher un maître des chamans quand vous aurez le temps. Il pourra peut-être vous apprendre d\'autres sorts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (100,'Merci à vous. Merci aux chamans.$B$BLa corruption diminue, mais la vie continue à décliner. C\'est aux chamans de protéger la vie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (184,'C\'est inutile. Regardez la date sur le courrier. Les Froncebouille occupent illégalement la ferme des Jansen depuis cinq ans. Ils n\'ont jamais réussi à réparer leur chariot.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (191,'Vous prenez un moment pour vous féliciter intérieurement du degré d\'habileté que vous avez atteint pour la chasse à la panthère.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (195,'Hemet Nesingwary junior doutait de vous, mais ses doutes étaient infondés. Vous avez littéralement massacré ces raptors !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (220,'Ah, une fiole d\'eau créée bénite par Brine. Et apportée par vos soins, de surcroît.$B$BLe liquide de cette fiole sera crucial pour créer votre sapta, mais également pour une autre tâche.$B$BVous devrez utiliser le sapta que je vais confectionner pour voir les esprits de l\'eau, à l\'autel de la forêt des Pins argentés, au sud d\'Undercity. Quant aux gouttes qui resteront, je vous dirai quoi en faire si vous pensez que vous êtes prêt.$B$BAlors, êtes-vous prêt pour un nouveau voyage, $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (254,'Vous creusez dans la saleté molle au-dessus de la tombe... et vous trouvez les restes d\'un cercueil.$B$BVous sentez le cercueil vibrer sous l\'effet de ce qui semble être des griffes qui raclent à l\'intérieur, et vous entendez le grincement de dents en décomposition...$B$BAllez-vous ouvrir le cercueil et récupérer le cœur de l\'Embaumeur ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (31,'Très impressionnant, $N. Vos ancêtres seraient ravis de vos progrès ! Vous pouvez maintenant acquérir votre forme aquatique, et cela sera un plaisir pour moi de vous l\'enseigner.$B$BDe plus, pour votre performance lors des deux dernières épreuves, je vous offre cet objet. J\'espère qu\'il vous sera utile dans votre rôle de protecteur de la nature et de gardien de l\'équilibre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (283,'Merci, sincèrement, $N ! Vous avez sauvé le Barrage de Formepierre ! Sans votre aide, les terroristes Sombrefer se seraient sûrement emparés de ce point stratégique. Vous êtes la fierté du royaume et de l\'Alliance, brave $C.$B$BLe Barrage est de nouveau en sécurité... du moins pour l\'instant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (295,'Vous avez fait du bon boulot en éliminant ces raptors, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (397,'Le Maître a dit de donner cadeau à $N. Zggi veut garder joli cadeau mais Zggi connaître mieux pas trahir Maître.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (431,'Vous vous emparez d\'une bougie et la mettez dans votre sac.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (620,'Bonjour. Etes vous en affaire avec moi ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (686,'Donc le roi Magni Bronzebeard lui-même vous a envoyé ?$B$BEh bien ! Cela doit être important !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (700,'Le granit ne semble être qu\'un minuscule souvenir comparé à la grande vie d\'un nain. Mais aucun nain ne restera sur cette planète pour l\'éternité.$B$BEspérons simplement que le Mémorial constituera un rappel pour ceux qui parcourront la grande Azeroth de l\'avenir, afin qu\'ils n\'oublient pas que c\'est pour eux que de courageux guerriers tels que Sully Balloo ont si vaillamment donné leurs vies.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (768,'Ah, ces pièces sont parfaites. Elles feront de beaux articles de cuir.$B$BVoici, $N, prenez cela en guise de récompense...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (779,'Vous placez les Pierres runiques dans leur alcôves respectives et soudain un violent grondement fait trembler la terre tandis que le Sceau se brise.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (795,'Vous placez les Pierres runiques dans leur alcôves respectives et soudain un violent grondement fait trembler la terre tandis que le Sceau se brise.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (862,'D\'ordinaire je n\'aime pas manger ces rongeurs quand ils sont si… si… verts. Je les lasse pourrir quelques semaines pour que le fumet ressorte vraiment. Mais vous avez l\'air si affamé. Laissez-moi vous faire un bon brouet de rat. Et c\'est parti...$B$BTenez, voilà pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (889,'Bien. Que l\'esprit d\'Agammagan vous guide, $N. Revenez me voir si vous désirez davantage de la magie d\'Agammagan.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (896,'Regardez-moi la taille de ce caillou ! On est riche ! Voyons voir, d’après les taux auxquels se vendent les pierres en partance pour Terremine, je devrais pouvoir calculer votre part. Ne vous en faites pas, vous aurez cinquante pour cent !$B$BUn instant… Je pense que cela devrait faire le compte. C’est un plaisir de faire des affaires avec vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (926,'Ces pierres sont imprégnées d\'énergie magique, mais d\'une énergie affaiblie, volontairement. Elles sont très instables et une fois prises sur la table, elles se consumeront très rapidement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (964,'Ça va marcher, $N ! À mon tour maintenant : je vais les imprégner de l\'agent durcissant nécessaire à leur résistance au processus intense de forge qu\'ils auront à traverser.$B$BLa prochaine étape sera de trouver un moule approprié pour la clé. Je connais un forgeron gobelin à Tanaris qui a fait, dans le passé, des moules pour des objets macabres semblables. Il travaille, à l\'instar de tous les gobelins, pour celui qui paye le plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (968,'Ah ! Une copie des « Puissances d\'en bas ». Un texte intéressant, on peut le dire. Et d\'aucuns pourraient le trouver utile…$B$BMais celle-ci est dans un triste état. Et regardez ! Il y a des annotations en marge de presque toutes les pages !$B$BHum... Je connais cette copie. Je l\'ai vendue à Bolgar l\'année dernière. Êtes-vous... l\'un de ses amis ? Oui, il me semblait bien que vous l\'étiez ! Vous avez ce même feu dans le regard !$B$BBien, par définition, un ami de Bolgar est mon ami. Et l\'on prend soin des siens, n\'est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (972,'Prenez le sapta d\'eau et trouvez l\'étendue d\'eau corrompue dans la forêt des Pins argentés, $N. J\'ai une grande confiance en vos compétences.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (996,'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Elle commence immédiatement à se défaire de sa forme souillée pour s\'épanouir en une plante vibrante de santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (998,'Vous appliquez deux doses de baume végétal cénarien sur la fleur-de-vent. Il commence immédiatement à se défaire de sa forme souillée pour s\'épanouir en une plante vibrante de santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1027,'Vous avez trouvé le dernier morceau ? C\'est merveilleux pour vous... et pour Raene.$B$BJe pense qu\'il faut maintenant réparer, n\'est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1055,'Vous avez réussi, $N ! Bravo !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1067,'Une toxine de l\'apothicaire Lydon ? Très bien. Si je le connais bien, alors cette toxine sera très efficace contre la KapitalRisk…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1086,'C\'est intéressant, effectivement.$B$BVous et Gaxim avaient très bien œuvré, $N. Merci.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1103,'Une toxine de l\'apothicaire Lydon ? Très bien. Si je le connais bien, alors cette toxine sera très efficace contre la KapitalRisk…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1120,'De la bière ? Comme c\'est aimable ! Merci !$B$BNous ne devrions pas boire avec la course qui se prépare, mais… mes gars peuvent en boire juste un peu. En plus, elle ne doit pas être très forte, n\'est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1121,'Mais qu\'avons-nous là ? De la bibine, hein ?$B$BBien, ça ne me dérange pas si nous en avons juste un petit peu…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1130,'Ah ! $N ! Vous voilà ! Il est temps d\'envisager un voyage par les contrées lointaines, n\'est-ce pas ?$B$BSi c\'est le cas, jeune $C, écoutez...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1135,'Ah ! Voilà des poches qui débordent presque de venin, $N ! En général, il n\'y a que sur les jeunes wyvernes ou les femelles fertiles que l\'on peut en trouver. Il a dû y avoir un véritable massacre, là-haut à Haut-perchoir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1185,'Hé, vous revoilà ! Je veux dire, bonjour $N ! Oui, salut à vous et à personne d\'autre !$B$BLaissez-moi vous expliquer !$B$BL\'objet que vous avez trouvé à Silithus se trouvait être un livre. C\'est un journal écrit dans un très ancien dialecte que nous appelons le darnassien. Cela prendra un bon moment, mais je suis sur le bon chemin pour finir le travail. Je pense que vous savez déjà que ce que vous avez découvert est extrêmement précieux pour le Cercle.$B$BLa Mère de la tanière est très heureuse de cette trouvaille !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1192,'Excellent ! Je vais former l\'équipe pour travailler tout de suite sur les composants dont nous avons besoin pour la prochaine course.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1301,'James ? Eh bien, il est parti il y a quelque temps.$B$BIl a entendu le deuxième appel des trompes du patriotisme, je suppose. Pas dur de deviner pourquoi. Avec toutes ces saletés à Lordaeron, nombreux sont ceux qui ont rejoint Jaina Proudmoore lorsqu\'elle est partie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1418,'Helgrum veut un compte rendu, hein ? J\'ai envoyé une estafette à Stonard il n\'y a pas trois jours. A-t-il échoué dans sa mission ? Si Stonard n\'a pas reçu mon rapport, alors il semblerait que oui.$B$BEspérons que le prochain messager que j\'enverrai sera meilleur, ou qu\'il aura plus de chance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1421,'Ah, vous les avez trouvés ! Avec ça, les sorciers de Rempart-du-Néant vont pouvoir continuer leur travail. Je ne sais pas vraiment ce qu\'ils font, mais ça a un rapport avec la Porte des ténèbres dans les Terres foudroyées, et c\'est vital pour la sécurité de l\'Alliance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1452,'Je vois que vous n\'avez pas eu de problèmes pour me dénicher ce dont j\'avais besoin ! Vous parlez d\'une besogne que vous avez dû faire dans la lointaine Kalimdor.$B$BÇa va me prendre du temps pour extraire la substantifique moelle de ces gésiers et de ces foies.$B$BAlors je pourrai me servir une bonne vieille boisson qui arrache et vous dire enfin c\'que vous voulez savoir.$B$BHic !$B$BÇa m\'fait trembler rien qu\'de repenser à c\'vieux marais.$B$BLaissez-moi préparer le bébé en vitesse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1462,'Prenez ceci et n\'oubliez pas qu\'un sapta est sacré !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1463,'Je vous en donne un de bonne foi. Vous avez déjà prouvé votre valeur une fois, mais je pense que vous devriez être plus soigneux à l\'avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1469,'Rhapsody Shindigger ! C\'est ça… Comment j\'ai pu oublier un tel nom ?$B$BAlors il était au courant depuis tout ce temps pour le temple englouti ? Eh bien, cela aurait pu vous épargner de la marche à pied.$B$BMais cet artefact atal\'ai ! Quelle trouvaille !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1498,'Vous avez bien agi, $N.$B$BLes vils quasits ne sont que des marionnettes dirigées par des puissances agissant au sein de la Lame ardente, mais votre succès en présage de plus grands à l\'avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1499,'Vous avez bien agi, $N.$B$BLes vils quasits ne sont que des marionnettes dirigées par des puissances agissant au sein de la Lame ardente, mais votre succès en présage de plus grands à l\'avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1502,'Mes yeux se sont depuis longtemps desséchés à force de fixer les flammes de la forge, mais il y a certaines choses que je peux encore voir.$B$BEt si vous avez trouvé votre chemin jusqu\'ici, je peux deviner la nature de votre demande.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1504,'Vous avez réussi, $N. Je vais maintenant vous montrer comment invoquer un marcheur du Vide semblable à celui que vous venez de battre.$B$BVous savez certainement que nous nourrissons de grandes espérances vous concernant, et pour l\'instant, vous ne nous avez pas déçus. Ne laissez pas cela vous monter à la tête non plus, sachant que les tâches qui vous restent à accomplir feront passer celle que vous venez de remplir pour une promenade de santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1506,'Bien. J\'ai eu peur qu\'Ophek ne vous trouve pas.$B$BIl est temps que j\'approfondisse votre apprentissage de $C. Quelles que soient les affaires que vous avez en cours, elles attendront.$B$BJe suppose que ça ne pose pas de problème ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1508,'Êtes-vous venu m\'apporter des nouvelles de Dogran ? Il était censé revenir il y a plusieurs jours, mais je n\'ai pas de nouvelles…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1509,'Zankaja ? La compagne de ce Dogran, c\'est ça ?$B$BOui, j\'ai entendu parler de lui, mais ce ne sont pas de bonnes nouvelles…$B$BNon, il n\'est pas mort. Mais il est blessé et prisonnier des hurans.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1510,'Un autre $R, hein ? J\'espère que vous n\'êtes pas venu pour l\'autre. Il n\'y est pas arrivé. Ces gobelins ne l\'ont pas raté.$B$BIl a dit avoir besoin d\'un breuvage de guérison, mais il n\'a pas ajouté grand-chose.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1511,'Eh bien, il serait temps ! Dogran est en train de crever ici, en attendant ce breuvage.$B$BNous devons lui apporter cela immédiatement, mais la plupart des grunts d\'ici sont sortis pour ravitailler le camp.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1512,'Si vous me dites que cela suffira, alors je vous fais confiance, $N. Permettez-moi de le laver quand même. Virginal et brillant, il attirera encore mieux la succube.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1513,'Succès ! Soyez certain que c\'est bien ce que j\'attendais de mon meilleur élève.$B$BVous avez démontré votre valeur, et c\'est avec plaisir que je vais vous montrer comment invoquer votre succube dominée. Partez à présent, vous avez beaucoup à apprendre, et la prochaine fois que je vous verrai, je m\'attends à ce que vous maîtrisiez totalement votre succube.$B$BLaissez le chagrin de Dogran et de Zankaja à ceux qui ont de nombreuses années à vivre, mais conservez ce souvenir comme une protection contre les ruses des sombres pouvoirs que vous avez appris à invoquer aujourd\'hui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1515,'Ah ! $N... La terre apprécie grandement votre présence en ce lieu.$B$BLié à elle par le corps et l\'esprit, vous irez de l\'avant en sachant que les montagnes sont votre force, les plaines votre patience et le monde lui-même votre essence.$B$BIl vous suffit de vous tenir devant la terre avec humilité pour réussir ce rite. Mais les autres ne sont pas aussi passifs. Ils peuvent être chaotiques et souvent violents, mais telle est la nature des éléments. Des natures différentes s\'opposant l\'une à l\'autre. Vous devez parvenir à connaître ces choses intimement...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1517,'Bien, $N. Le fait que vous soyez revenu signifie que vous êtes préparé pour la prochaine étape.$B$BDe tous les éléments, la terre représente la fondation de toute chose. C\'est votre force, votre endurance et votre patience. La Terre-mère vous protégera, mais seulement si vous lui témoignez le respect qui lui est dû. Elle est la base de la vie, et en observant ses lois, vous gagnerez en sagesse. N\'oubliez jamais les secrets qu\'elle partage avec vous.$B$BJe vais préparer votre sapta à présent. En l\'acceptant, une nouvelle voie s\'ouvrira devant vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1522,'Hmmm, Searn vous envoie, c\'est cela ?$B$BTrès bien, on peut toujours faire confiance à Searn. Cela veut dire que vous êtes prêt à approcher le prochain sapta, le sapta de feu.$B$BJe lis déjà dans vos yeux la flamme, le désir. Vous avez goûté au pouvoir, et maintenant vous en voulez plus. Patience, $N. Souvenez-vous de ce que la terre vous a appris. La puissance et la destruction viendront facilement, mais vous devez toujours savoir retenir votre main.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1525,'Cela fera parfaitement l\'affaire, $N.$B$BLe feu représente bien plus de choses que le simple chaos ou la destruction. Vous feriez bien de vous en souvenir... Il est également lié à la vie et à la création. Tout est ainsi lié. Les forces s\'opposent les unes aux autres, mais l\'une ne peut pas exister sans l\'autre. Chacune éteint l\'autre, mais lui donne également un nouveau sens. N\'oubliez jamais cela.$B$BAssocier différents types de magie ne témoigne pas simplement d\'une grande compétence, mais essentiellement d\'une grande sagesse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1526,'Alors que vous placez la braise dans la coupe, une flamme blanche et chaude s\'embrase. Vous sentez les effets magiques du sapta parcourir vos veines, et le feu danse rythmiquement devant vous.$B$BVous placez l\'extrémité de la torche à l\'intérieur de la coupe, et elle s\'embrase immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1527,'Votre esprit brûle avec plus d\'ardeur que toutes les torches qu\'il m\'a été donné de voir, $N, et vous pouvez en être fier. Si vous continuez dans cette voie, vous pourrez commander à tous les éléments, et nos semblables, en quête d\'un guide ou de sagesse, vous consulteront. Laissez-moi être le premier à vous féliciter et à vous présenter votre nouveau totem.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1528,'Le vent venu de l\'horizon vous rejoint vite. La terre est ferme sous vos pieds. Votre esprit est réchauffé par le feu. Je pense qu\'il est temps pour vous d\'apprendre la pureté de l\'eau.$B$BVotre chemin vous a déjà mené loin, et votre esprit vous donnera la force de continuer. Mais il vous appartient d\'effectuer le dernier pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1529,'Le vent venu de l\'horizon vous rejoint vite. La terre est ferme sous vos pieds. Votre esprit est réchauffé par le feu. Je pense qu\'il est temps pour vous d\'apprendre la pureté de l\'eau.$B$BVotre chemin vous a déjà mené loin, et votre esprit vous donnera la force de continuer. Mais il vous appartient d\'effectuer le dernier pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1530,'Oui ?$B$BMmm ! Je crois savoir ce que vous allez me demander : pourquoi une personne vit-elle au plus profond des Tarides, sans protection, avec des hurans la menaçant de toutes parts ? Eh bien, nous avons tous nos raisons pour justifier nos actes ! La véritable question est : qu\'est-ce qui vous amène au fin fond des Tarides pour parler à une femme qui n\'a visiblement aucune inquiétude quant à sa propre sécurité ?$B$BJe parie que nous connaissons tous deux la réponse, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1531,'Pour le moment, je vais vous donner de quoi focaliser vos sorts et appeler les esprits de l\'air. Prenez ce totem, et quand vous serez prêt revenez me voir pour approfondir votre enseignement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1534,'Merveilleux, $N. À présent que les trois échantillons sont rassemblés, je peux créer une fiole de l\'eau la plus pure. Elle sera nécessaire aux prochaines étapes de votre rite de passage.$B$BIl me plaît de vous voir parmi nous, $N. Tous les chamans sont fiers de vous, et j\'espère entendre bientôt parler de vos futurs exploits.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1535,'Je pensais bien que votre tentative de prendre de l\'eau du bassin allait provoquer quelques effusions de sang. Il est bien dommage que les hurans ne comprennent pas que toutes les choses vivantes sont liées, que leur avidité ne fait qu\'engendrer douleur et souffrance pour leur peuple. Que ne pourraient-ils accomplir s\'ils mettaient de côté leurs différences pour unir leurs clans ?$B$BOui, c\'est dommage... Mais c\'est très certainement une bénédiction pour les autres races des Tarides.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1536,'C\'est bien, $N. Vous êtes dévouée à votre tâche et savez trouver ce qui est nécessaire.$B$Bje n\'ai besoin que d\'un autre échantillon pour créer le réactif nécessaire à votre sapta. Cela plaira également à Islen.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1581,'Ils sont parfaitement préparés. Vous prenez grand soin de votre affaire, $N, et c\'est très important pour une alchimiste.$B$BVoici vos herbes, fraîchement récoltées. Puissent-elles vous être d\'une grande utilité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1639,'Salut, beau gosse ! Qu\'est-ce qu\'un mignon comme vous fait au « Cochon siffleur » ? Faites attention, vous pourriez vous casser un ongle...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1651,'Nous avons réussi, $N ! Merci de votre aide. Vous avez été vraiment incroyable. Je n\'aurais jamais cru qu\'un $C puisse contenir autant d\'ennemis à la fois.$B$BVous avez montré votre bravoure face à cette force écrasante.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1682,'Voici quelques armes, tout juste sorties de la forge. Elles sont faites avec le Minerai d\'Umbral que vous m\'avez apporté !$B$BS\'il vous plaît, $N, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1683,'Beau travail, $N. Il est bon de savoir que Vorlus est mort et que notre Puits de lune a retrouvé sa quiétude ; il est bon de savoir que les jeunes guerriers s\'empressent de garder notre cher Teldrassil à l\'abri de la corruption.$B$BMaintenant commençons votre entraînement...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1689,'Vous avez fait mieux que ce à quoi je m\'attendais, $N, mais aussi bien que je l\'espérais. Maintenant, vous pouvez apprendre comment contrôler un marcheur du Vide, c\'est un allié précieux pour traverser les épreuves.$B$BJe n\'ai plus rien à vous apprendre aujourd\'hui, mais je n\'ai pas fini avec vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1692,'Ah ! Du minerai d\'Elunite. C\'est un métal délicat à travailler, il est béni par la déesse Elune elle-même. Cela va être un honneur d\'en faire des armes.$B$BAttendez le temps que je travaille...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1698,'Ah ! Vous avez entendu parler de mon défi, n\'est-ce pas ?$B$BBien. Asseyez-vous, prenez un verre et savourez-le... Car c\'est peut-être le dernier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1700,'Furen a écrit ça ? Comment ose-t-il ? C\'est moi qui lui ai tout appris ! Penser qu\'il puisse m\'apprendre quelque chose est scandaleux ! Scandaleux !$B$BHum... Mais il y a quelque chose dans ses notes que j\'aimerais tenter...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1705,'Beau travail ! Maintenant veuillez m\'excuser, je dois aller travailler...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1708,'Voilà c\'est ça ! Bien joué ! Maintenant, laissez-moi travailler et appliquer les méthodes de Furen et nous verrons le résultat !$B$BOh ! Ça alors ! Par exemple ! Je sais juste que l\'armure sera très très très, TRÈS résistante !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1711,'J\'ai fini votre armure, et j\'en suis satisfait. Les techniques de Furen cadrent parfaitement avec les miennes et je suis sûr que cette armure est extrêmement résistante.$B$BMerci, $N. Et qu\'elle vous serve pour vos combats futurs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1712,'Vous avez rassemblé les composants pour mon sort, et vous avez montré votre force et votre adresse. Mais la prochaine partie de notre quête est bien plus périlleuse.$B$BEspérons que votre force ne faiblira pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1713,'Vous avez réussi ! Vous avez vaincu le Cyclonien et récupéré son Cœur de tourbillon !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1714,'Le charme s\'enfonce lentement dans le chaudron...$B$BUne grosse bulle se forme à la surface du liquide et éclate...$B$B... Et un morceau de roche en fusion apparaît.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1717,'Je suis ravi que quelqu\'un ait pris soin de vous, $N. Je commençais à m\'inquiéter. Cela aurait été une honte de vous perdre, après tout le temps que j\'ai investi en vous.$B$BMais nous parlerons plus tard. Votre entraînement est la seule chose importante en ce moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1789,'Si vous n\'arrivez pas à aider Narm en utilisant le Symbole de vie, $N, alors revenez me voir et je vous en procurerai un autre. Il est important pour mon mari et moi que vous y arriviez. S\'il vous plaît, hâtez-vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1790,'Hâtez-vous, $N, de nombreuses vies seront en danger si vous échouez.$B$BSi pour une raison quelconque vous n\'arrivez pas à aider Gazin et Henze, revenez me voir et je vous donnerai un autre Symbole de vie pour cette entreprise.$B$BNe prenez pas cela pour de la charité : vous devez prouver que vous êtes un $C aussi brave que les autres, et des échecs répétés auraient des répercussions plus tard.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1792,'J\'ai le Cœur de tourbillon, et je suis prêt à le placer dans le réceptacle de votre choix.$B$BChoisissez l\'arme, $N, et sachez que ce pouvoir est le pouvoir du Cyclonien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1803,'Bien bien bien ! Qu\'est-ce que nous avons là ?$B$BC\'est impressionnant, $N. Je ne pensais pas que cela serait possible, mais il est vraiment là dans mes mains, le Tome de la Cabale en intégralité.$B$BPermettez-moi d\'y jeter un coup d\'oeil avant que vous ne l\'emportiez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1842,'Ah, vous les avez ! Maintenant, de la même façon que les satyres sucent la force d\'Ashenvale, je vais sucer le pouvoir de ces sabots et l\'utiliser pour mon ouvrage…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1846,'Bravo ! Ils ont l\'air costauds. Je pense qu\'ils feront tout à fait l\'affaire. Comment ces orcs ont-ils pris le fait que vous leur empruntiez leurs tibias, $N ? Ils ont beaucoup protesté ?$B$BC\'était une autre plaisanterie. Vous ne riez pas ?$B$BJe ne suis pas très drôle ces jours-ci...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1859,'Très bien ! Je constate avec plaisir que Kaplak a réussi à vous faire venir.$B$BNous avons à parler d\'un certain nombre de choses, dont votre avenir au sein de la Main.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1861,'Merci, $N. Je vais rechercher des traces de magie dans cette eau, en espérant qu\'elle n\'en révèle pas... Ou alors cela voudrait dire que ceux qui boivent depuis longtemps l\'eau du lac Miroir ne pourront être guéris.$B$BVoici pour vous, $N. Prenez cet orbe ou ce bâton en récompense. Puisse-t-il bien vous servir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1882,'Ah ! Quel beau spécimen ! Je vais l\'envoyer à nos apothicaires pour étudier l\'étendue de la contamination des Maleterres.$B$BEn remerciement, $N, vous pouvez choisir un orbe ou un bâton. L\'un ou l\'autre vous sera utile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1939,'Je vous salue, $N. Je suis heureux de vous voir et j\'espère que vous aurez le temps d\'écouter la parole d\'un vieil homme...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1941,'Voici votre robe. C\'est l\'une des plus belles que j\'ai confectionnées ! Portez-la avec fierté. Et si les gens vous interrogent, dites-leur qu\'elle sort de l\'atelier des couturiers Larson !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1942,'Votre habit est prêt. Cette soie que vous avez apportée était si belle... Ça ne vous fait rien si je l\'ai cousu un peu court pour pouvoir en conserver un morceau ?$B$BMais non, je plaisante ! Il vous ira comme un gant, au plus fort de l\'aventure comme dans les occasions plus mondaines ! Profitez-en bien !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1944,'Ah très bien ! Je crois que les satyres de Xavian vous ont causé quelques soucis ?$B$BMerci, $N. Je vais immédiatement étudier cet échantillon d\'eau de Xavian.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1947,'Doucement ! L\'instant est délicat et il ne faut pas me déranger !$B$BUn instant...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1950,'Oh ! Maintenant je me souviens...$B$BJ\'avais oublié que j\'avais jeté cette petite malédiction à Johnson. Je ne me souviens pas pourquoi j\'ai fait ça, mais il est certain qu\'il le méritait, ce petit ingrat !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1951,'Voilà ! C\'est exactement ce dont j\'avais besoin pour préparer le rituel de création de votre baguette magique ! J\'espère que vous n\'avez pas eu trop de mal à le trouver…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1952,'Voici les baguettes que j\'ai fabriquées. Choisissez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1953,'Ah, oui. Vous voulez un orbe ou un bâton, $N ? Très bien. Je vous aiderai.$B$BMais je dois d\'abord vous prévenir : le processus est dangereux et pourrait provoquer votre mort !$B$BOu la mienne. La mort de quelqu\'un en tout cas...$B$BEspérons que ce soit celle de quelqu\'un d\'autre, vous ne croyez pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1954,'Oh ! Il est chouette ! Non, enfin, pas "chouette" comme un bon verre de quelque chose de frais un jour de canicule !$B$BEn fait, il n\'est pas CHOUETTE du tout, maintenant que j\'y repense ! Pas le bon verre, l\'orbe !$B$BEssayez de suivre, $N ! Concentrez-vous, si vous voulez terminer cette tâche un jour !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1955,'Bien joué, $N ! Vous avez donné à ce démon une leçon qu\'il n\'oubliera pas de sitôt.$B$BIl réfléchira à deux fois avant de repasser sa sale tête dans ce monde, pour chercher le stupide mortel qui l\'a battu. Probablement avec des amis cette fois. De grands amis écailleux qui ne demanderaient pas mieux que de vous déchirer en tout petits morceaux |2 mort-vivant.$B$BJe ne vous ai pas fait peur, n\'est-ce pas... $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1962,'Voici votre robe, $N. Portez-la bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1978,'Hum, c\'est intéressant… Les Traqueurs noirs ont admirablement fait leur travail en furetant ainsi.$B$BD\'après ce que j\'ai compris, vous méritez également notre gratitude pour votre performance. J\'espère que cela deviendra quelque chose de routinier pour vous, $N, mes Traqueurs noirs ont toujours besoin de gens de valeur parmi eux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (1998,'Vous avez réussi, $N. Je constate que vous avez rendu beaucoup de services aux Traqueurs noirs, en prouvant votre valeur et il est peut-être temps que nous commencions votre initiation aux Arts de l\'ombre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2205,'Vous m\'avez trouvé et à vous regarder, je dirais que ce fut long et difficile, car vous me paraissez, physiquement et psychiquement, bien diminué.$B$BVoudriez-vous que Renzik vous accompagne à une auberge ou êtes-vous prêt dès à présent pour une mission ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2218,'Alors, vous croyez êt\' une vraie crapule ? Un qu\'est destiné à êt\' parmi les rares choisis de Blackbeard, un officier du Cercle secret ?$B$BY\'a qu\'un bon à rien, un impertinent pour êt\' aussi imbu de lui-même.$B$BMais c\'est exactement c\'qu\'on recherche! Alors bienvenue, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2238,'Shut ! Moins de bruit, idiot. Ils vont nous entendre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2239,'Longue marche ? Par ma barbe !$B$BZ\'avez réussi, $N. Prenez cette dague et disparaissez. Le Cercle vous rappellera quand la troisième étape sera sur le point d\'commencer.$B$BC\'est quoi la troisième étape ? C\'est celle qui vient après la deuxième, et j\'peux aussi vous botter l\'train.$B$BÇa vous dit ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2241,'Si j\'avais conservé chaque fleur que ce balourd de Jannok m\'a envoyée, j\'aurais eu de quoi ouvrir un magasin de fleurs. Mais bon, il semble toutefois que le dernier courrier de Jannok puisse être utile.$B$BSeriez-vous intéressé par un travail, $C?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2281,'Ah, z\'êtes un peu maladroit d\'vos dix doigts, hein ? Bah, pas grave, $N, j\'en ai transformé des plus mauvais que vous en vrais voleurs accomplis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2282,'Vous l\'avez forcé ? Joli travail, $N.$B$BSi vous mourez maintenant nous saurons que c\'est par stupidité, pas par inexpérience !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2298,'Il est toujours bon d\'avoir dans ses rangs un des voleurs de Hulfdan !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2340,'C\'est bon. On peut garder le sac, aussi ? Merci... J\'apprécie.$B$BCe collier est notre meilleure prise ! Pleurez pas, y vous irait pas de toute façon. Ah ! Ah !$B$BBon, un marché, c\'est un marché. Voici votre part. On aura peut-être encore du boulot pour vous plus tard, mais en attendant, du vent !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2359,'Ça expliquerait les pantins défias que Kearnen et vous avez vus hors de la tour, $N. Et l\'implication de la KapitalRisk avec les Défias, ou encore l\'étrange cargaison venue du bois de la Pénombre...$B$BSi j\'en crois ce livre, les trolls Zanzil de Strangleronce ont découvert une potion pour réveiller les morts... Ou, pour être plus clair, un poison.$B$BVous ne serez d\'aucune aide au SI:7 sans une bonne connaissance des poisons, $N... Surtout avec la recette de fabrication des morts-vivants à portée de la main.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2379,'Zando\'zan avait peut-être tort. Zando\'zan présente des excuses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2381,'Incroyable ! Impossible ! Etonnant... Vous avez du talent, $N. Ou alors vous avez une veine de... Bref...$B$BVoici votre part du butin. Ce truc vous fera sûrement plus d\'usage qu\'à moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2382,'Encore un ? Les cinq derniers que ces trolls inconscients m\'ont envoyés ont fini dans l\'estomac des requins. Espérons que vous valez un peu mieux, hein ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2399,'Eh bien $N, vous avez dû plaire au Sage Truthseeker pour qu\'il vous donne cela ! Il vous offre aussi un échantillon de ses potions : vous pouvez choisir entre 5 Potions de guérison supérieures ou 5 Potions de mana supérieures.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2440,'Eh bien $N, vous avez dû plaire au Sage Truthseeker pour qu\'il vous donne cela ! Il vous offre aussi un échantillon de ses potions : vous pouvez choisir entre 5 Potions de guérison supérieures ou 5 Potions de mana supérieures.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2458,'Ça fait plaisir de voir un autre agent de la Main brisée par ici, mais les fusées, c\'était peut-être un peu trop !$B$BLa prochaine fois que vous voudrez me parler, soufflez deux fois dans ce sifflet et je saurai que vous faites partie des alliés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2478,'Pauvre Fizzule ! C\'était un bon agent, l\'un des meilleurs. Hélas, c\'est le prix à payer, $N ! Être un agent de la Main brisée est dangereux.$B$BVous avez fait et bien fait votre devoir, $C. Cela aurait été dommage que vous ne surviviez pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2479,'Vous semblez délicieusement pâle, $C. Et quel est cet arôme écœurant que vous dégagez ? Je dois le savoir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2480,'Le remède est prêt ! Buvez cette antitoxine et cette folie rampante s\'arrêtera, mais je ne suis pas capable de faire quoi que ce soit pour l\'odeur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2521,'Mes yeux me trompent-ils ? Impossible ! Où avez-vous ?... Comment ?...$B$BMaintenant, peut-être qu\'une faille va pouvoir s\'ouvrir afin que nous retournions chez nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2522,'Tout simplement stupéfiant ! Je doutais que vous puissiez trouver une autre sphère, et pourtant elle est là et elle bat dans ma main.$B$BBien joué, $N !$B$BSi vous en trouvez une autre – et je crois que c\'est presque impossible – rapportez-la-moi et je vous récompenserai de nouveau.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2523,'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2584,'Je dois vous avertir, $N, il ne sert à rien de mélanger entre elles les formules que j\'ai créées. Les propriétés de la dernière formule que vous avalerez auront toujours priorité sur les enchantements plus anciens, ce qui aura pour effet de les annuler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2586,'Excellent travail, $N. Voici un échantillon de la préparation pour vous ; j\'utiliserai le reste pour mes recherches.$B$BChaque fois que vous voudrez plus de préparation de scorpok, revenez me voir et nous conclurons un accord.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2604,'J\'arriverai peut-être un jour à isoler les enzymes actives de cette préparation, et ainsi renforcer son efficacité. Malheureusement, vous devez vous contenter de ce que je suis capable de produire aujourd\'hui. Revenez me voir si vous voulez plus de Gomme de gésier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2607,'Il est grand temps ! Mettez simplement le fromage sur la table et barrez-vous. Osborne vous payera en sortant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2608,'Donnez-moi un moment pour discuter avec mes confrères, $N. Docteur Montgomery, M. Noarm, réunissons-nous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2609,'Ce que je fais ? Qu\'est-ce que j\'ai l\'air de faire ? Je mets au point un remède pour soigner votre itis ! Ne jouez pas les indignés avec moi maintenant, $N !$B$BPlus que quelques secondes. Là ! Pulvérisez juste un peu de ce médicament fantastique sur vous et vous retrouverez la pêche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2741,'Vous placez l\'œuf d\'hippogryphe dans la machine. Des signaux sonores s\'enchaînent, sur un fond de bruits mécaniques.$B$BEt le Calibre-œuf a pesé, mesuré et empaqueté votre œuf. Ça c\'est du service rapide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2757,'Par la barbe de Blackhoof ! Enfin quelqu\'un digne de l\'Ordre du Mithril !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2758,'Très bien, $N ! Écoutez et apprenez.$B$BL\'art de la forge ne vient jamais d\'ici !$B$BL\'art de la forge ne vient jamais d\'ici !$B$BL\'art de la forge ne peut venir que d\'ici !$B$BMaintenant vous connaissez l\'origine de l\'art de la forge.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2762,'C\'est une maîtresse cruelle, n\'est-ce pas, $N ? Je parle du vrai-argent, naturellement. Eh oui ! Il a fallu à Galvan une décennie passée dans les montagnes d\'Alterac pour apprendre cette leçon. Prenez ceci et apprenez-en autant que vous pourrez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2847,'Eh bien, $N, je suis heureux de vous avoir à mes côtés ! Vous avez pris une bonne décision en tant que tanneur, ceux qui portent des armures en cuir loueront votre nom et votre art lorsque vous aurez appris à confectionner des armures en cuir sauvage.$B$BAu travail ! Par où désirez-vous commencer ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2850,'L\'équipement de la nuit que vous m\'avez fourni correspond parfaitement à ma commande, $N. Je n\'en attendais pas moins d\'un ouvrier du cuir tel que vous.$B$BVous avez bien gagné ce patron. Je vous le donne en espérant que vous en tirerez profit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2851,'Une fois de plus, vous avez traité une commande difficile avec l\'habileté d\'un professionnel. Vous avez bien mérité ce patron, ainsi que mes remerciements.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2857,'L\'équipement de la nuit que vous m\'avez fourni respecte parfaitement les critères que je vous avais donnés, $N. Je n\'en attendais pas moins d\'un artisan du cuir tel que vous.$B$BVous avez bien gagné le patron du casque en cuir sauvage. Je vous le donne en espérant que vous en tirerez de bons profits.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2858,'Une fois de plus, vous avez produit ces objets avec le talent d\'un vrai professionnel. Vous avez gagné ce patron, ainsi que mes félicitations.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2878,'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2922,'C\'est merveilleux ! Merci, $N ! Je me mets au travail immédiatement !$B$BPauvre, pauvre Techbot… Tout ira bien, tu seras bientôt réparé.$B$BOù ai-je mis cette prise pour ma clé à molette hydraulique ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2948,'Ah, exactement ce dont j\'avais besoin ! Un jour, quand je sortirai de cette injuste affliction, je fabriquerai pour vous, pour TOUT LE MONDE, les plus beaux bijoux d\'Azeroth ! En tout cas, merci pour les ingrédients. Je demande normalement dix fois ce prix pour un anneau de cette qualité...$B$BD\'ailleurs, à propos d\'anneaux, voici le vôtre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2949,'Un anneau de Gnomeregan ? Voyons... non ce n\'est pas le mien, mais c\'est intéressant.$B$BCette histoire n\'aurait pas pu arriver à de plus parfaits crétins. Quels imbéciles ! Ils sont la risée de tous, depuis des années, et soudain, voilà qu\'ils feraient de meilleurs anneaux que nous ?$B$BLes nains sombrefers avaient l\'anneau ? Voilà qui est plus intéressant ! Peut-être les gnomes ont-ils volé les plans de leurs golems et les ont modifiés. Ces Sombrefer, ils veulent vraiment s\'attirer tous les bénéfices. Il faut tirer cela au clair.$B$BQuant à cet anneau...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2950,'Voici votre anneau, il est bien plus puissant qu\'auparavant. Merci encore pour l\'information sur les nains sombrefers. On dirait que ces gnomes ont soudain été frappés d\'une inspiration digne des gobelins.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2952,'D\'un coup le Décapeur 5200 s\'arrête net. Un petit carillon émet un "ding" clair et la trappe de l\'appareil s\'ouvre. À l\'intérieur de la machine vous découvrez une petite boîte garnie d\'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu\'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n\'a pas fonctionné.$B$BBon, il n\'y a qu\'un seul moyen de savoir si l\'objet à bel et bien été nettoyé ou non...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2953,'Le Brille-o-Matic 5200 se met en action, vrombissant et crachotant tandis qu\'à l\'intérieur, sur l\'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !$B$BLe Brille-o-Matic 5200 s\'arrête et émet un « ding ! » pour indiquer qu\'il a terminé son travail. La trappe s\'ouvre, dévoilant une petite boîte, ornée d\'un joli nœud.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (2983,'Hum, <Swart> vous envoie, n\'est-ce pas ?$B$BOn peut lui faire confiance, cela signifie que vous avez l\'expérience requise pour le prochain sapta, le <Sapta de feu>.$B$BJe vois votre désir d\'apprendre brûler dans vos pupilles. Vous avez de grands pouvoirs et l\'envie d\'en connaître de plus grands encore. Patience, $N. Rappelez-vous : force et pouvoir de destruction viendront facilement, le tout est de savoir se retenir à bon escient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3002,'Fascinant, $N...$B$BCet orbe est aussi puissant que dangereux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3087,'En tant que $C, mes compétences rivalisent avec les pouvoirs arcaniques des mages, les prouesses martiales des guerriers ou même les actes bénis de nos bien-aimés chamans. Être $C nécessite concentration et dévouement. Continuons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3091,'Chacun son rôle dans notre tribu. Chacun doit aussi passer par les mêmes rites. Ne laissez jamais votre orgueil vous dire le contraire.$B$BJe reste ici pour former de nouveaux guerriers qui recherchent la gloire des combats et qui suivent la voie de nos plus vénérables ancêtres. Revenez me voir après un peu d\'entraînement et je ferai ce que je peux pour parfaire votre formation. Allez avec la bénédiction de la tribu, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3093,'Nous allons nous voir souvent dans les jours à venir. Vous repartirez à chaque fois avec plus de puissance... Et de préparation. Tel la Flamme éternelle, votre esprit brillera de mille feux.$B$BEn route, $N. Mettez-vous à l\'épreuve. Je serai là quand vous en aurez besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3095,'Je serai là pour vous aider à mesure que vous gagnerez de l\'expérience... Venez me trouver aussi souvent que vous le souhaitez. Mes honoraires sont peut-être bas, mais tout ce que je vous apprendrai vous sera de la plus grande utilité.$B$BPartez, mettez à l\'épreuve votre technique. Vous connaîtrez bien d\'autres choses avec l\'expérience, même certaines choses dont je ne peux vous parler ici. Sachez juste que Sylvanas aura besoin de guerriers de votre genre dans l\'avenir. Vous serez le fondement de notre salut. Ne l\'oubliez pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3097,'Il y a une chose que vous devez savoir : nous avons survécu grâce à notre seule volonté. C\'est notre foi en nous-mêmes qui nous distingue des autres. Et avec nos pouvoirs, nous allons bouleverser la totalité d\'Azeroth. Le faible cherchera votre protection. Les lépreux vous appelleront Prince. Et l\'ignorant cherchera vos conseils. C\'est mon devoir que de m\'assurer que vous disposiez de tous les outils nécessaires quand le temps viendra. À mesure que vous gagnerez en expérience, venez me voir. Je vous donnerai de plus puissants pouvoirs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3098,'Revenez souvent me voir si vous souhaitez avoir la puissance suffisante pour écraser nos opposants. Les règles de la magie s\'appliquent aussi à vous, $N. Vous sentirez toujours la corruption vous suivre comme une meute de loups affamés dans la nuit. Sa caresse ne sera pas sans créer une certaine dépendance, un vieux compagnon qui voudrait toujours être à vos côtés. Mais il y a moyen de contrer ces effets. Ces choses ne vous contrôlent que si vous les laissez faire.$B$BPartez maintenant, revenez vers moi quand vous aurez gagné en puissance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3104,'Ha ha, je savais bien que mes mises en garde ne seraient d\'aucun effet. Donc vous n\'avez pas peur ? Pas peur d\'accepter votre destin ? Pas peur de défier les dieux et toutes les autres forces qui se dresseront entre vous et la poursuite du savoir et du pouvoir ?$B$BJe ne vous mens pas, $N, vous inspirerez autant de crainte que de respect. Mais sachez aussi que je serai là si vous avez besoin d\'entraînement. Venez me trouver pour gagner en puissance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3107,'Les humains nous ont appris des tas de choses sur la Lumière sacrée et à quel point leur ordre était important pour eux... et pour la protection d\'Azeroth. Nous avons beaucoup de respect pour cette tradition bien ancrée. D\'une seule action, d\'un seul sacrifice peut dépendre la douleur ou le salut.$B$BNous allons travailler ensemble un petit moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3117,'À mesure que vous comprendrez ce que Sombrevallon peut vous apporter, venez me trouver. Je vous montrerai quel est le rôle d\'un $C et ce dont vous êtes capable.$B$BLes temps sont dangereux, $N, ne vous fiez pas trop aux talents de vos familiers : certaines choses en ce monde sont bien plus dangereuses que vous ne le pensez. Qu\'Elune soit avec vous et revenez bientôt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3118,'D\'ici là, sachez que nous sommes très demandés en ces temps troublés. La paix avec les autres races peut se briser à tout moment et on parle beaucoup de membres de la Horde qui chercheraient à semer les graines de la discorde. N\'oubliez pas ça.$B$BRepassez me voir quand vous aurez acquis plus de puissance et d\'entraînement. Je veillerai à vous entraîner d\'avantage. Il est vital que vous sachiez bien manier votre arme de prédilection, entre autres choses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3119,'Ne vous préoccupez pas trop du monde qui s\'étend sous Teldrassil pour le moment. Chaque chose en son temps. Allez parler aux autres gens de Sombrevallon : ils vous en diront plus sur ce qui s\'y est passé. Aidez de la façon dont vous pourrez et si vous sentez le besoin de plus d\'entraînement, passez me voir et je vous apprendrai ce que je peux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3363,'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3421,'Je vais vous renvoyer au camp de Sanath à présent.$B$BNe faites pas attention à ses mauvaises manières. Il est brusque envers tout le monde, sauf envers le maître. Peut-être apprendra-t-il la leçon un jour ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3526,'Souhaitez-vous admirer la vue depuis le sommet de l\'un des Colosses jumeaux ? Je peux vous y envoyer, $R.$B$BRéfléchissez quand même à la façon de redescendre. C\'est un voyage que l\'on ne peut faire que dans un seul sens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3567,'Je n\'aurais jamais rêvé que l\'élixir puisse prendre forme aussi rapidement. Merci, $N. Je vais travailler sur le reste de ces échantillons tout de suite. Je suis sûr qu\'ils seront bientôt utilisables par Dame Sylvanas et les Réprouvés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3570,'Votre tâche à Azshara est terminée. Je dois maintenant forger ce qui va vous être nécessaire pour poursuivre vos aventures.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3630,'Oh, un jeune ingénieur qui veut poursuivre l\'étude de la seule, la vraie discipline d\'ingénierie ! Pardonnez ce ton mélodramatique, mon ami. Alors que notre situation devient de plus en plus difficile, c\'est toujours une joie de voir qu\'un autre ingénieur répond à l\'appel de clairon de la véritable ingénierie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3631,'Encore une fois, vous m\'honorez de votre présence. Comme c\'est aimable de votre part.$B$BMes acolytes m\'avaient dit que vous ne viendriez jamais. Je leur ai répondu que je n\'en doutais pas. Lorsqu\'il s\'agit de puissance, vous ressemblez à un papillon attiré par les flammes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3632,'Oh, un jeune ingénieur qui veut poursuivre l\'étude de la seule, la vraie discipline d\'ingénierie ! Pardonnez ce ton mélodramatique, mon ami. Alors que notre situation devient de plus en plus difficile, c\'est toujours une joie de voir qu\'un autre ingénieur répond à l\'appel de clairon de la véritable ingénierie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (3643,'En ce jour, vous devenez un veritable ingénieur, $N. Ne vous occupez pas de toutes ces bombes et des autres explosifs, parce qu’il est temps de briller !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4123,'Vous avez le Cœur ! Incroyable ! Il est encore plus beau que je ne l\'imaginais !$B$BJe vous en prie, $N, prenez ceci comme paiement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10939,'Ainsi donc, vous avez rassemblé une suite de Tempêtes. En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4448,'Vous appliquez quatre doses de Baume végétal cénarien sur le dragon nocturne. La plante commence immédiatement à se débarrasser de sa forme corrompue et refleurit pour devenir une plante vibrante de santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4461,'Vous appliquez trois doses de baume cénarien sur la navetille. Elle commence immédiatement à se débarrasser de sa forme corrompue, et s\'épanouit en une plante vibrante de santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4463,'Prenez votre babiole, imbécile. Et laissez-moi poursuivre mes recherches !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4464,'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4465,'Vous appliquez du baume végétal de Cénarius sur la fleur-de-chant. Elle commence immédiatement à abandonner sa forme corrompue pour fleurir comme une plante vivace et radieuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4481,'C\'est une insulte à sa mémoire... Un simple mortel comme vous, terminant l\'oeuvre de sa vie.$B$BPrenez votre cristal et partez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4542,'Encore des mauvaises nouvelles ! Ces centaures vont trop loin ! Ils ont attaqué un de mes convois de ravitaillement et ont tué tout le groupe. C\'est un outrage, et il ne restera pas impuni !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4603,'Le Brille-o-Matic 5200 se met en action, vrombissant et crachotant tandis qu\'à l\'intérieur, sur l\'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !$B$BLe Brille-o-Matic 5200 s\'arrête et émet un « ding ! » pour indiquer qu\'il a terminé son travail. La trappe s\'ouvre, dévoilant une petite boîte, ornée d\'un joli nœud.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4604,'Le Brille-o-Matic 5200 se met en action, vrombissant et crachotant tandis qu\'à l\'intérieur, sur l\'objet, la crasse est pulvérisée par les enzymes de nettoyage spéciales mises au point par les gnomes !$B$BLe Brille-o-Matic 5200 s\'arrête et émet un « ding ! » pour indiquer qu\'il a terminé son travail. La trappe s\'ouvre, dévoilant une petite boîte, ornée d\'un joli nœud.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4605,'D\'un coup le Décapeur 5200 s\'arrête net. Un petit carillon émet un "ding" clair et la trappe de l\'appareil s\'ouvre. À l\'intérieur de la machine vous découvrez une petite boîte garnie d\'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu\'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n\'a pas fonctionné.$B$BBon, il n\'y a qu\'un seul moyen de savoir si l\'objet à bel et bien été nettoyé ou non...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4606,'D\'un coup le Décapeur 5200 s\'arrête net. Un petit carillon émet un "ding" clair et la trappe de l\'appareil s\'ouvre. À l\'intérieur de la machine vous découvrez une petite boîte garnie d\'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu\'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n\'a pas fonctionné.$B$BBon, il n\'y a qu\'un seul moyen de savoir si l\'objet à bel et bien été nettoyé ou non...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4701,'Ne pensez plus à sa souffrance, $N. La bête était corrompue ; c\'était un produit de la magie noire. Vous avez rendu un grand service à l\'Alliance et vous serez récompensé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4768,'Excellent. La formule gravée sur cette tablette demandera plusieurs jours d\'études pour la comprendre, mais ça en vaut la peine, j\'en suis sûre.$B$BMerci, $N. Vous avez été d\'une aide inestimable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4769,'C\'est vrai. Je crois qu\'une tablette est conservée au pic Blackrock ; dessus sont inscrites de vieilles recettes d\'alchimie. Je suis contente que vous soyez là, j\'ai besoin de vos services pour la récupérer.$B$BInstallez-vous confortablement, que je vous explique cela en détail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4771,'Vous avez réussi ! Vectus est défait ! Et le Gambit de l\'aube… a-t-il fonctionné ?$B$BHm… Peut-être que ma machine n\'a pas été à la hauteur de mes espoirs, mais vous avez réussi tout de même. Bien joué, $N !$B$BL\'Aube d\'argent et le bon peuple d\'Azeroth vous sont redevables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4785,'Voilà, $N. Et s\'il vous plaît, dites à Menara que nous la saluons.$B$BNous espérons beaucoup de vous. Peut-être que, lorsque la Légion sera à genoux, votre nom et votre puissance seront loués haut et fort. Je suis impatient !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4802,'Mau\'ari peut utiliser ce juju pour $N... Utiliser la Cache de Mau\'ari pour la lancer sur vous ou l\'un de vos alliés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4941,'<Thrall a l\'air consterné par les nouvelles que vous venez d\'apporter.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4961,'Bien joué, $N ! Vous avez donné une leçon à ce démon ; il n\'est pas prêt de l\'oublier. Vous avez fait preuve de bravoure et de puissance. Je suppose qu\'il est temps que vous retourniez voir Menara, avec l\'orbe purifié, pour l\'utiliser à bon escient.$B$BBonne chance, $C. Peut-être que nos chemins se croiseront à nouveau.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4964,'C\'est fait, $N. Il vous suffit de me dire ce que vous préférez. Un bâton que vous utiliserez à deux mains, ou un orbe que vous pourrez utiliser avec une dague ou une épée.$B$BSe mesurer au gangrechien était un haut fait. Je pense que votre objet vous sera utile à l\'avenir. Continuez à vous entraîner pour maîtriser les arts, $N. J\'attends des nouvelles de vos exploits.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4965,'Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.$B$BC\'est une bonne chose de voir quelqu\'un de votre trempe rechercher la puissance autrement qu\'à travers la connaissance.$B$BAlors, pensez-vous être prêt $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4967,'Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.$B$BC\'est une bonne chose de voir quelqu\'un de votre trempe rechercher la puissance autrement qu\'à travers la connaissance.$B$BAlors, pensez-vous être prêt $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4968,'Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.$B$BC\'est une bonne chose de voir quelqu\'un de votre trempe rechercher la puissance autrement qu\'à travers la connaissance.$B$BAlors, pensez-vous être prêt $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4969,'Ah, vous devez chercher quelque chose de plus... consistant. Je peux vous aider si vous êtes prêt.$B$BC\'est une bonne chose de voir quelqu\'un de votre trempe rechercher la puissance autrement qu\'à travers la connaissance.$B$BAlors, pensez-vous être prêt $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (4974,'Vous avez porté un coup fatal aux forces de Blackrock, $N. Leur Chef de guerre mort, la légion Blackrock est une fois de plus plongée dans le chaos.$B$BPour honorer vos efforts héroïques, le peuple de Kalimdor sera récompensé !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5068,'Grand merci, $N ! Je peux me remettre enfin au travail.$B$BAvez-vous trouvé quelque chose d\'intéressant au camp des Tombe-hiver ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5082,'Bienvenue aux Maleterres, héros. C\'est la plus dangereuse des frontières d\'Azeroth, avec l\'ombre menaçante du Fléau à l\'est, et plus à l\'est encore. Je suis heureux de constater que l\'appel au sens du devoir de la Horde n\'a pas trouvé sourde oreille en vous !$B$BSi vous êtes prêts à vous salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5093,'Bienvenue aux Maleterres, héros. C\'est la plus dangereuse des frontières d\'Azeroth, avec l\'ombre menaçante du Fléau à l\'est, et plus à l\'est encore. Je suis heureux de constater que l\'appel au sens du devoir de la Horde n\'a pas trouvé sourde oreille en vous !$B$BSi vous êtes prêts à vous salir les mains, il y a de quoi faire pour les héros ici, à la limite des Maleterres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5143,'Vous avez donné vos meilleures offrandes, et la nature se pliera bientôt à votre volonté. Lorsque vous quitterez ma tutelle, votre travail sera lui-même une force de la nature.$B$BPour apprendre cet art à l\'avenir, il vous suffit de venir me parler. Je vous dispenserai toutes les connaissances qu\'il vous faut encore acquérir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5148,'Vous avez donné vos meilleures offrandes, et la nature se pliera bientôt à votre volonté. Lorsque vous quitterez ma tutelle, votre travail sera lui-même une force de la nature.$B$BPour apprendre cet art à l\'avenir, il vous suffit de venir me parler. Je vous dispenserai toutes les connaissances qu\'il vous faut encore acquérir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5150,'Les pousses posées devant elle, Dadanga semble satisfaite.$B$BElle pousse un petit paquet enveloppé de brun vers vous, en échange du petit cadeau !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5155,'Bien, $N ! Leur nombre s\'amenuisant, nous pouvons davantage faire pression sur eux.$B$BQuelle a été votre première impression de leur pouvoir ? Etaient-ils aussi forts que vous le pensiez ? Plus forts ? Ou peut-être n\'ont-ils constitués aucun défi pour vous. Ça ne serait pas quelque chose, ça ?$B$BNous discuterons plus tard des détails de vos exploits. Il y a d\'autres choses qui demandent notre attention maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5160,'Des centaines et des centaines de pages de gribouillis ésotériques composent l\'essentiel de ce livre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5164,'Ne comprenez-vous toujours pas ? Le voyage était la destination. Pouvez-vous ignorer les cicatrices des combats ? La peine que vous avez eue ?$B$BDu fait d\'avoir survécu à cette épreuve, vous en êtes sorti grandi. Cette cuirasse n\'est qu\'un pâle reflet de vos propres dons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5166,'Ne comprenez-vous toujours pas ? Le voyage était la destination. Pouvez-vous ignorer les cicatrices des combats ? La peine que vous avez eue ?$B$BDu fait d\'avoir survécu à cette épreuve, vous en êtes sorti grandi. Cette cuirasse n\'est qu\'un pâle reflet de vos propres dons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5218,'L\'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s\'en échappent. Les créatures du Fléau même éloignées du chaudron semblent reculer au fur et à mesure que les nouveaux composants se répandent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5221,'L\'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s\'en échappent. Les créatures du Fléau, même éloignées du chaudron, semblent reculer au fur et à mesure que les nouveaux composants se répandent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5224,'L\'ajout des composants à la mixture dans le chaudron change peu à peu sa couleur et celle des vapeurs qui s\'en échappent. Les créatures du Fléau, même éloignées du chaudron, semblent reculer au fur et à mesure que les nouveaux composants se répandent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5242,'La Terre-mère soit louée ! Merci $N ! C\'est un grand jour, pour sûr !$B$BLe Conseil des ombres aura du mal à retrouver le niveau de puissance qu\'il avait autrefois avec ce coup porté à sa hiérarchie. Vous avez accompli un haut fait aujourd\'hui !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5246,'Les pages sont restées intouchées pendant de très longues années…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5247,'En utilisant ces composants, j\'espère pouvoir souder les différents fragments… afin d\'en faire ce qu\'ils étaient autrefois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5248,'Par pitié…laissez moi….') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5252,'Est-ce… ce à quoi je pense ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5253,'J\'ai entendu parler du cristal de Zin-Malor. Celui qui le détient devient le maître d\'une puissance des arcanes incroyable, mais seulement s\'il le mérite. Je suis impressionné que vous l\'ayez retrouvé et encore plus que, connaissant vos limites, vous ne l\'ayez pas utilisé.$B$BMerci de me l\'avoir apporté, $N. Nous le garderons en sûreté, et puissent les âmes damnées qui le gardaient autrefois trouver enfin le repos.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5262,'Qu\'est-ce que cela signifie pour la Croisade ? Se peut-il qu’ils aient été sous l\'influence de ce démon ? Servant sans s\'en douter un mal bien plus grand encore ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5283,'Qu\'il en soit ainsi, $N. Après ceci, plus moyen de reculer. Il n\'est pas trop tard pour devenir un fabricant de jouets, ou, un fabricant d\'armes.$B$BJe suis certain que vous prendrez la bonne décision') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5284,'Il était temps ! J\'ai des clients qui attendent.$B$BDonnez-les-moi et faites bien attention, vous allez prendre votre première leçon dans votre carrière d\'Armurier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5301,'C\'est la dernière phase avant de commencer votre carrière de fabricant d\'armures, $N. Si vous choisissiez d\'abandonner, ce serait maintenant votre dernière chance. Sinon, préparez-vous à une vie de gloire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5302,'Ceci est l\'ultime étape avant de commencer votre nouvelle carrière de fabricant d\'armes, $N. Voudriez-vous y renoncer que cela serait votre dernière chance. Sinon, préparez-vous à être consumé par le savoir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5407,'Félicitations, $N. Je suis heureux de vous donner une marque de valeur de l\'Aube d\'argent !$B$BChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l\'Aube d\'argent sera assurément en bonne position quand le temps sera venu de porter l\'attaque ultime contre le Fléau. J\'espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5421,'Ah, mec… Le travail bien fait, y’a rien de mieux ! Surtout quand c’est quelqu’un d’autre qui le fait… hein ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5463,'Vous placez le souvenir de mémoire sur le sol maculé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5464,'Tout comme l\'âme s\'est attachée au souvenir de mémoire, elle s\'attachera à la forme charnelle de Ras Murmegivre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (5943,'Il n\'est pas certain que cela soit une bonne proposition d\'être payé autant pour protéger la caravane de Gizelton. Cork et Gréeur ne gagnent qu\'une pièce d\'or par semaine, mais du moment qu\'ils payent pour mes kodos je ne m\'occupe pas de la façon dont ils gèrent leurs affaires.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6068,'Oui, je pense que vous pouvez le faire aussi...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6069,'Oui, je pense qu\'il est temps de vous entraîner...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6074,'Oui, je pense qu\'il est temps...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6122,'Par Elune, cette eau est infecte ! Ce n\'est pas étonnant que les daims soient malades.$B$BQuelque chose pollue l\'eau, et du coup corrompt toutes celles de Sombrivage. Les daims malades ont été vus dans toutes cette zone, pas seulement près de la rivière. Même si l\'eau semble être la cause de cette épidémie, il y a quelque chose d\'autre qui se passe ici.$B$BCurieusement, c\'est cette eau qui va nous permettre d\'élaborer un remède. Pendant que je fais mes recherches, allez me chercher quelques objets pour préparer le remède...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6123,'Vous vous êtes bien acquitté de votre tâche : soigner les daims malades de Sombrivage. Ils sont les innocentes victimes de la corruption qui se répand sur le pays. À Darnassus, certains ont conscience du péril… et d\'autres ont choisi d\'ignorer les signes. J\'espère que vous ne serez pas de ceux qui se mettent des oeillères pour éviter de voir les faits tels qu\'ils sont, $N.$B$BQuoiqu\'il en soit, vous avez fait vos preuves comme ami de la nature et du Cercle - ceci en sera le symbole.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6124,'Bon retour parmi nous ! J\'ai suivi vos progrès depuis votre départ, et je dois admettre que j\'ai été surpris en apprenant la situation à Auberdine. Elle mérite une investigation plus approfondie, car l\'introduction de tels poisons dans l\'environnement est un facteur de déséquillibre.$B$BJe constate que vous gardez votre sang-froid dans les situations critiques. Pour cela, je vous récompense en vous donnant un pouvoir permanent sur le poison. Utilisez-le à bon escient, $N... à bon escient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6146,'Où étiez-vous ? Nous vous pensions entre les mains du Fléau.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6164,'Et voilà ! Ma parole ! J\'avais oublié qu\'il était aussi plein !$B$BC\'est un jour glorieux, $N ! Prodigieux ! Un incroyablement bon jour, je vous le dis !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6383,'Pour clore la Chasse d\'Ashenvale, vous devrez affronter trois créatures légendaires. Vous allez devoir les rechercher et vous mesurer à leur malice et leur force. En accomplissant cela, vous apprendrez des choses sur vous. Ces créatures sont : l\'ours Ursangous, le sabre-de-nuit Shadumbra et l\'hippogryphe Serres-tranchantes.$B$BLes créatures de la Chasse d\'Ashenvale sont puissantes, et vous aurez peut-être besoin d\'aide pour les vaincre. Si vous les battez, apportez-en-moi la preuve.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6403,'<Bolvar tient le médaillon brisé.>$B$BLa magie qui s\'y trouve doit être éveillée. L\'oeil du dragon doit être mis en phase.$B$BLe sacrifice de Windsor a libéré notre royaume, mais la menace d\'Onyxia et des siens se dessine toujours.$B$BCe médaillon est ce qui retient captifs mon esprit et mon corps. C\'est également ce qui me donne accès à l\'esprit d\'Onyxia, à ses secrets. Les visions sont plus floues à présent, mais il est des choses dont je me souviens tout de même.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6502,'Cette amulette vous fournira l\'accès que vous cherchiez. Le repaire d\'Onyxia se trouve dans la baie d\'Âprefange. Tant que vous tenez l\'amulette ses gardiens ne peuvent pas vous empêcher d\'entrer.$B$BLe Vol bleu vous souhaite bonne chance, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6566,'Êtes-vous prêt pour cette tâche ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6567,'Laissez Myranda jeter un œil, $N.$B$BOh oui, ceux-ci feront parfaitement l\'affaire.$B$BAvec ces réactifs, Myranda va créer pour vous un médaillon qui vous fournira une illusion capable de tromper le portier des dragons noirs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6569,'Il n\'existe qu\'un chemin pour entrer dans l\'antre du dragon, $N.$B$BVoyez-vous, seuls les dragons noirs les plus puissants sont autorisés à entrer dans l\'antre de la Mère des couvées. De nombreuses épreuves doivent être passées, et la clé doit être rituellement enchantée par le général Drakkisath en personne !$B$BÉtant donné que vous n\'êtes pas un draconien noir, vous allez certainement rencontrer des difficultés pour obtenir le droit de passage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6570,'Les effectifs de nos troupes sont-ils tombés si bas que Nefarian m\'envoie des chiots ? Vous ne passerez jamais mes épreuves, avorton.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6581,'C\'est parfait, c\'est exactement ce que je voulais ! Eh bien, voilà la cargaison.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6601,'C\'est comme quand les dragons parlent, $N, il y a plus d\'air chaud que d\'informations intéressantes. On ne peut que s\'attendre à un comportement pompeux et agressif de leur part.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6602,'<Rexxar a un rictus.>$B$BLe récit de vos exploits sera conté pendant les années à venir, $N. Cette Amulette drakefeu est la clé du repaire d\'Onyxia. Rassemblez vos forces et partez en campagne au nom de la Horde !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6642,'Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l\'accès aux commerces anciens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6643,'Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l\'accès aux commerces anciens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6644,'Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l\'accès aux commerces anciens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6645,'Votre offre a été acceptée. Vous avez obtenu une faveur. Continuez et on vous autorisera l\'accès aux commerces anciens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6681,'Excellent, jeune larron.$B$BVous avez l\'air d\'avoir souffert un peu, mais ce n\'est pas terminé.$B$BUn long voyage vous attend – long et enrichissant. Voulez-vous enfin saisir votre chance avec les maîtres de Ravenholdt ?$B$BAdressez-vous aux gardes dehors. Ils vous diront quoi faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6741,'Merci encore, $N. La Horde est fière de vous…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6781,'Ce sont de bonnes pièces, $N. Je peux m’en servir pour fabriquer de l’équipement pour nos troupes.$B$BSi nous avons assez de matériel, nous pourrons peut-être déployer des troupes endurcies !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6801,'Le sang de nos ennemis a été versé. Je vais le mélanger avec celui qui a déjà été récolté. Une fois l’offrande complète, le Seigneur de glace montrera à ces chiens de Foudrepique ce qu’est la colère du clan Loup-de-givre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6822,'Vos exploits contre nos ennemis ont retenti dans les chambres des Seigneurs des eaux, $N. Certains disent que votre forme est trop petite et fragile pour combattre dans notre guerre, mais vous avez beaucoup gagné. Vous avez gagné notre respect. C\'est incroyable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6823,'Vous avez les mains ! Les capitaines du feu battus ! Je ne l\'aurais pas cru possible, si je n\'avais pas su de quoi vous êtes capable.$B$B$N, vos exploits sont innombrables, mais cette nouvelle victoire va retentir jusqu\'au coeur des Seigneurs des eaux. Votre nom sera un jour une légende pour nous.$B$BRevenez me voir, $N. J\'aurai peut-être une autre tâche à vous confier...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6825,'La flotte se nourrit de leur chair. Cela consume l\'ennemi.$B$BLe vol est imminent !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6826,'Encore ! Encore ! Il en faut plus car ils seront bientôt prêts !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6881,'Bien joué, $N. Je vais me servir du pouvoir de ce charme pour augmenter la magie qui a déjà été collectée. Lorsque nous aurons assez de puissance, je focaliserai les énergies et j’appellerai le Seigneur des forêts pour aider notre cause.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6941,'Le vol sera bientôt prêt. Continuez vos efforts !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6942,'Il faut que ça entre, soldat ! Les griffons de Nid-de-l\'Aigle seront prêts à frapper en un rien de temps !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (6943,'Vous ne voyez pas ? Regardez, soldat ! Ils approchent ! Bientôt, l\'escadrille d\'Ichman frappera de nouveau au cœur de la vallée ! Les Foudrepiques régneront dans les cieux !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7101,'J’ai entendu dire que vous aviez réussi. Cela me plaît…$B$BNos troupes vont bientôt charger les troupes de l’Alliance en toute impunité, et leur montrer que la vallée d’Alterac ne leur appartient pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7161,'Vous ressentez comme une brûlure, pas vrai ? C’est votre âme qui s’éveille. Votre esprit a accepté l’appel de la bataille.$B$BVous êtes maintenant un Loup-de-givre, $N. Félicitations.$B$BPortez cet insigne avec vous en toutes circonstances. Au fur et à mesure de votre montée en grade, je le remplacerai par d’autres insignes, plus puissants.$B$BEt qui sait ? Un jour peut-être, vous serez Exalté parmi le clan Loup-de-givre. Si ce jour arrive, vous recevrez l’Œil du Commandement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7168,'Que nos ennemis voient qu’un soldat d’élite les a tués ! Battez-vous ! Battez-vous pour la gloire des Foudrepiques !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7281,'Vos exploits ne passent pas inaperçus, $N.$B$BJe ne dois pas perdre de temps s\'il faut le sauver. Sylvanas doit être contactée !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7282,'Vous avez bien brûlé le cadavre, n\'est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7385,'Le sang de nos ennemis a été versé. Je vais le mélanger avec celui qui a déjà été récolté. Une fois l’offrande complète, le Seigneur de glace montrera à ces chiens de Foudrepique ce qu’est la colère du clan Loup-de-givre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7386,'Bien joué, $N. Je vais me servir du pouvoir de ces charmes pour augmenter la magie qui a déjà été collectée. Lorsque nous aurons assez de puissance, je focaliserai les énergies et j’appellerai le Seigneur des forêts pour aider notre cause.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7429,'Oh, merci de m\'avoir libéré ! Vous – vous êtes numéro un. Tous les autres sont numéro deux – ou moins. Merci de m’avoir libéré !$B$BJe savais que j’avais autre chose à faire de ma vie que de servir d’apéritif à un ogre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7500,'Très bon travail, $R. Si vous trouvez d\'autres livres, n\'hésitez pas à nous les retourner.  $B  $BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7505,'Très bon travail, $R. Si vous trouvez d\'autres livres, n\'hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7541,'Il faudra du temps pour que nos savants étudient le pendentif que vous nous avez rapporté. J\'aimerais vous offrir un petit témoignage de notre reconnaissance, pour le service que vous avez rendu à la Horde.$B$BMerci, $N. Vos actions vous font honneur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7563,'# Achèvement$B$B"Ah, très bien. Je vais le distiller pour en faire de l\'encre, et l\'utiliser pour rédiger le parchemin que je vous ai promis. Je m\'en garderai peut-être un peu pour moi, car à ce que j\'ai entendu dire, c\'est un euphorisant…"') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7564,'# Achèvement - Gorzeeki Fouregard$B$B"Oh, du sang. Ça doit venir de maître Mor\'zul. Il adore ce truc, surtout quand il est répandu. Moi, je le préfère dans les veines d\'un petit rongeur. Comme ça, il reste chaud… jusqu\'à ce que vous en ayez envie.$B$BC\'est un sang puissant. Mor\'zul doit être en train de préparer un autre parchemin pour invoquer un destrier de l\'effroi ! Comme c\'est excitant !$B$BMais si c\'est ça, c\'est vous qui allez accomplir le rituel… Il va vous falloir bien d\'autres choses que du sang, mon ami."') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7581,'Ah, excellent travail. Ce sang annulera les défenses magiques du garde funeste.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7582,'Je n\'ai plus qu\'à combiner le sang des Follengeance avec ces cristaux et la prison sera prête à l\'emploi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7583,'Vous avez accompli mes volontés. Vous êtes prête à apprendre à invoquer et à contrôler la bête.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7601,'Oh, la barbe... Ça recommence…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7602,'Laissez-moi une minute, et je combinerai les essences pour en faire du Gangrefeu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7603,'Un marché est un marché ! Vite, prenez ça et écrivez-le. Moi, je n\'ai pas le temps ! Ma plus grande invocation est en cours !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7621,'$C vous allez subir une série d\'épreuves au cours desquelles tous vos talents seront poussés à leurs limites.$B$BÉcoutez attentivement mon histoire.$B$BAttention, vous devrez achever cette tâche seul. Je conseille à vos alliés de rester à distance. Toute intervention extérieure entraînera un châtiment sévère.$B$BLe Destin vous a conduit ici, vous et vous seul. Battez-vous avec honneur. Que la Lumière vous protège !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7626,'Très bien ! J\'espère que vous n\'avez pas eu trop de mal à vous procurer ces élixirs. Parfois, les alchimistes se montrent ridiculement attachés à leurs créations.$B$BJe vais fabriquer la cloche et la garder jusqu\'à ce que vous soyez prêt pour le rituel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7627,'Nous y voilà ! J\'ai entendu dire que l\'on ne trouvait ce minerai que dans les profondeurs de Blackrock, et je suis sûr que les éclats n\'ont pas été faciles à obtenir non plus. La détermination dont font preuve les démonistes ne cesse jamais de m\'impressionner. Si vous consacriez autant d\'énergie à attraper des cafards, nous pourrions faire un festin magnifique !$B$BPardon, je digresse. Je vais fabriquer la roue, et je la conserverai jusqu\'à ce que vous soyez prêt pour le rituel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7628,'Ah, très bien. J\'en ai besoin pour contenir le feu de la chandelle. Maintenant que je les ai, je peux la fabriquer. Je la garderai jusqu\'à ce que vous soyez prêt à commencer le rituel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7629,'Ah, bien. J\'eevee a preparé le parchemin. Comment était la Scholomance ? Un endroit charmant, n\'est-ce pas ? Et les cafards y sont particulièrement délicieux.$B$BBien joué, $N, et merci de m\'avoir ramené ma bouteille. Je l\'ai depuis longtemps… et elle n\'est pas à vendre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7630,'Vous l\'avez ! Bon travail ! Maintenant, je peux créer la magnétite. Quand vous serez prêt à lancer le Cercle d\'invocation supérieure, vous aurez besoin de magnétite pour que le rituel ne fasse pas long feu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7631,'Vous avez triomphé de l\'esprit du destrier de l\'effroi. Ses flancs spectraux irradient la rage, mais vous savez que l\'âme de la bête vous appartient.$B$BIl murmure de sombres connaissances dans votre esprit, et vous instille le moyen d\'invoquer un destrier de l\'effroi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7633,'Votre dilligence et votre intégrité ont été notées, $C.$B$BNous sommes les Anciens, les protecteurs de cette forêt qui fut grande, autrefois. Nos formes physiques ont été détruites il y a dix mille ans lorsqu\'Archimonde et la Légion ardente ont marché sur le mont Hyjal. Malgré tout, nos esprits demeurent intacts.$B$BNous avons des tâches à vous proposer. Des tâches qui vous donneront accès à nos secrets, si vous les accomplissez.$B$BSi vous y parvenez, revenez à ce rocher et nous répondrons à votre appel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7634,'Que ces feuilles protègent vos flèches de tout mal. Que vos flèches touchent juste. Que les ennemis de notre monde soient écrasés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7635,'Ce dragon était réellement abominable. Ce tendon empeste le mal.$B$BDonnez-moi un moment pour le purifier et appliquer les enchantements idoines.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7637,'Soyez béni, ami $C. Votre don est largement supérieur à ce qui était nécessaire. Votre sacrifice nous aidera à récupérer ce que nous avons perdu, mais aussi à soulager les misères des pauvres gens d\'Ironforge.$B$BÀ présent, laissez-moi m\'assurer que j\'ai préparé cet encensoir de manière à ce qu\'il réponde à vos besoins…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7638,'Je suis content de vous voir, $N. Je sais que vous attendiez depuis longtemps que je vous explique comment vous procurer votre destrier, et le moment est venu.$B$BVous allez affronter de nombreuses épreuves, mais l\'essentiel est que vous ayez la volonté de surmonter les obstacles qui vous attendent. Ce n\'est pas un exercice – vous avez progressé bien au-delà des simples tests qui ont ponctué votre éducation. Vous devrez arracher votre futur compagnon aux griffes même du mal que vous avez passé votre vie à combattre$B$BÉcoutez bien, car votre heure a sonné !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7639,'Oui, il conviendra. Au cours de cette affaire, vous aurez à accomplir plus d\'un sacrifice. Je suis content de voir que vous en êtes capable. Le sacrifice est un élément clé dans ce qui est nécessaire pour remplir les devoirs d\'un $C... Mais je n\'ai pas besoin de vous sermonner là-dessus.$B$BÀ présent, $N, j\'ai besoin que vous fassiez preuve de jugement. Cet encensoir sera votre canal pour dispenser votre jugement aux esprits torturés des régions que nous avons perdu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7640,'Très bien, $N. Passer le jugement de la Lumière sur ceux qui vivent dans les ténèbres est une tâche que nous devons accomplir avec zèle et énergie. Votre sacrifice à Ironforge et le jugement des esprits de Val-Terreur correspondent à cet idéal.$B$BPour votre prochaine étape, vous aurez besoin des deux. Vous allez devoir récupérer l\'esprit d\'un destrier mort qui, pour l\'heure, sert le chevalier de la mort Ravassombre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7642,'Bien... c\'est exactement ce qu\'il me faut. Vous êtes un $C plein de ressources, pas vrai ?  $B  $BParfait, allons finir ce caparaçon !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7645,'OUI, MAINTENANT QUE... attendez... vous me donnez aussi de l\'or ? Mais ce n\'est pas vous qui m\'avez traitée de folle... de cinglée complètement tordue, en fait... Mais vous êtes quand même prêt à vous sacrifier pour des actes que vous n\'avez pas commis ?  $B  $BJe vous avais mal jugé, $N. Si vous avez encore besoin de fourrage, venez me voir. Je vous l\'offrirai. Merci... noble $C.  $B  $BMais je garde quand même l\'argent - je ne suis pas cinglée au point de refuser une fortune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7646,'Ils sont parfaits, $N – les dernières pièces sont en place. Votre temps est enfin venu !  $B  $BDans les profondeurs du Grand ossuaire de la Scholomance se trouvent les restes de maintes créatures. Parmi elles, un destrier qui, autrefois, fut d\'une grande noblesse. Son âme ravagée sert à présent de monture au chevalier de la mort Ravassombre. C\'est lui que nous devons affronter, et c\'est sa monture que vous allez juger. Vous êtes le seul à pouvoir racheter son âme et la libérer de sa servitude, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7670,'Je suis content de vous voir, $N. Je sais que vous attendiez depuis longtemps que je vous explique comment vous procurer votre destrier, et le moment est venu.$B$BVous allez traverser de nombreuses épreuves, mais l\'essentiel est que vous ayez la volonté de surmonter les obstacles qui vous attendent. Ce n\'est pas un exercice – vous avez progressé bien au-delà des simples tests qui ont ponctué votre éducation. Vous devrez arracher votre futur compagnon aux griffes même du mal que vous avez passé votre vie à combattre$B$BÉcoutez bien, car votre heure a sonné !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7737,'Continuez à apporter du résidu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7781,'Il est inutile de vous expliquer la signification de cette action, $N. Ce jour vivra dans l’Histoire. Voici des années que l’Alliance n’avait pas remporté une victoire de cette ampleur – en supposant que cela lui soit jamais arrivé !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7783,'Vous faites une fois encore honneur à la Horde, $N. Le fils de l\'Aile de mort gît à vos pieds. Le très maléfique doit probablement s’agiter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7784,'Choisissez votre récompense afin que je puisse exhiber cette tête aux yeux de tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7785,'Puissiez-vous être protégé durant votre croisade. Puisse le maître bénir vos efforts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7786,'Même dans mes rêves les plus fous, je n\'avais osé espérer ce jour.$B$BRegarde, mortel.$B$BCONTEMPLE CELUI QUI EST PLUS VIEUX QUE LA VIE ELLE-MÊME !$B$BCONTEMPLE CELUI QUI A AFFRONTÉ LES TITANS ET LES DIEUX !$B$BLÈVE-TOI, MAÎTRE ! LIBÈRE-TOI DE TES CHAÎNES !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7787,'Je vous en supplie, ne me frappez pas ! Prenez-la ! Prenez la lame ! Laissez Demitrian refaire sa pitoyable vie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7838,'Le sol de l’arène est rouge du sang que vous avez versé. Je suis fier de vous nommer Grand maître de l’arène !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7842,'Oh, ça va être bien ! Plus qu\'une étape, et les Wildhammer verront qu\'on ne plaisante pas avec les trolls !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7885,'Formidable ! Voilà qui ira très bien ! Je viens juste de remarquer une déchirure dans une tente là-bas, et c\'est exactement ce qu\'il me faut pour la raccommoder !$b$bMerci beaucoup, $n. Ces renforts d\'armure vont nous épargner de grosses dépenses. Voici vos bons, vous les avez bien mérités !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7893,'Merci, $N. J\'utiliserai ces pierres pour un rituel de gain de force que j\'ai appris d\'une tablette ancienne au plus profond des jungles de Strangleronce.$B$BOn dit que celle qui accomplira correctement ce rite sacré aura la force et l\'endurance de dix taurens !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7902,'Ah, les plumes ! Elles sont magnifiques, vous ne trouvez pas ! Ce serait facile d\'enflammer les imaginations avec de telles merveilles !$B$BVous êtes si généreuse, $N. Le sourire sur le visage de nos visiteurs quand ils verront le spectacle est en soi une grande récompense, mais veuillez également prendre ces bons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7903,'Formidable ! Vous avez les yeux ! J\'espère que vous avez trouvé effrayant de chasser ces chauves-souris, parce que si ça a fait peur à un $C courageux comme vous, ces yeux vont certainement terrifier les visiteurs de la foire.$B$BPrenez ces bons, $N, et merci de m\'avoir rendu ce service.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7927,'Ainsi donc, vous avez rassemblé une suite de Portails... En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7930,'Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !$B$BSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7931,'Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !$B$BSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7932,'Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !$B$BSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7933,'Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !$B$BSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7936,'Et voilà l’heureux gagnant ! Un lot digne d’un roi ! Mes félicitations, mon ami !$B$BSi vous avez d’autres bons à échanger, n’hésitez pas à revenir me voir ! Tant que la foire de Sombrelune sera ici, j’échangerai vos bons contre des lots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7938,'Une fouille rapide du coffre révèle un coffret à l\'intérieur ! On dirait que vous avez trouvé votre surprise !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7939,'Encore merci, $N. Profitez bien de vos bons, et parlez à vos amis de la foire de Sombrelune !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7942,'Et voilà, $N. Des bons de la foire de Sombrelune rien que pour vous. Comme on dit, ne faites pas d’excès !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (7946,'Merci, $N. Voici votre œuf ! Il n’est pas encore tout à fait prêt à éclore, mais quand le moment sera venu, vous aurez un familier fantastique !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8041,'Salut, $C. je suis Jin\'rokh le Briseur, un troll de Mugamba. La tribu de Zandalar reconnaît la valuer de vos exploits. Nous saluons votre ténacité la et la force de votre volonté.$B$BPortez ce talisman autour de votre cou, $C. Laissez la force du Mont Mugamba s\'écouler dans votre être. Que sa force vous aider à frapper nos ennemis !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8043,'Utilisez votre force nouvelle pour détruire les Gurubashi !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8044,'Zul\'jin envierait vos exploits, $C. Partez au combat, conquérant !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8075,'Je sais ce que vous avez dû traverser pour me ramener ce Parangon de puissance, $N. Vaincre le mal qui suinte de Zul\'Gurub comme le pus d\'une blessure infectée n\'a pas été facile, mais maintenant que tout est fait et dit, vous serez révéré parmi les Zandalar pendant des siècles et des siècles !$B$BPrenez ce haubert d\'augure, et portez-le avec fierté !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8101,'$N, le caillou enchâssé dans la monture de ce talisman provient du mont Kajaro, dans les Mers du sud. Le mont Kajaro souffre d\'une grande instabilité, car il est secoué par des éruptions volcaniques fréquentes, et souvent magiques.$B$BQuand votre lien avec les trolls de Zandalar grandira, la puissance de ce caillou fera de même. Utilisez son pouvoir pour frapper nos ennemis. Soyez comme la montagne : vif, explosif, mortel…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8102,'Soyez inéluctable, comme les fleuves de lave du Kajaro.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8103,'Continuez le massacre des trolls de Zul\'Gurub. Hakkar doit comprendre que le monde ne se soumettra pas à sa volonté indomptable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8106,'Acceptez ce talisman, $C. Acceptez-le et utilisez son pouvoir pour abattre nos ennemis communs.$B$BSachez que vous portez autour du cou un morceau d\'histoire. Kezan était autrefois un immense territoire de l\'empire Zandalar. Hélas, la souillure des princes marchands gobelins a fini par chasser mes fiers frères et sœurs de cette région.$B$BKezan est maintenant le site de la capitale gobeline d\'Undermine ; mais sachez qu\'avant d\'être souillée, elle abritait la grandeur. Même aujourd\'hui, Kezan est considérée comme une terre sacrée par mon peuple.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8108,'Ce n\'est qu\'en combinant nos efforts que nous parviendrons à arrêter l\'Écorcheur d\'âmes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8116,'Vous et Maywiki avez quelque chose en commun, gamin. Nous sommes des chamans ! Mais bon, Maywiki est plutôt une mystique, et vous un second couteau. Enfin, nous savons tous deux ce qu\'apportent les grands esprits.$B$BJe vous offre cet orbe, pour que vous le portiez en collier. Regardez à l\'intérieur, et vous verrez le village de Voodress dans les Mers du sud ! Qu\'il élève vos esprits !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8117,'Regardez-le maintenant, $N. Voodress est encore plus visible, non ? Laissez le pouvoir primordial s\'écouler en vous…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8118,'Prenez gardes aux mauvais esprits hakkari. Je vous jure qu\'ils font froid dans le dos.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8141,'Vous progressez rapidement, jeune $C. Il est sans doute temps de vous initier pour vous faire entrer dans le Shera Ali\'kh -  la Main de la Mort, en zandalari. Pendant des milliers d\'années, nous avons été les assassins de l\'empire Zandalar. Mais nous sommes restés oisifs pendant trop longtemps, permettant aux Hakkari d\'accroître leurs forces. Aujourd\'hui, nous devons à nouveau affronter Hakkar, mais cette fois sans le soutien d\'une nation troll unifiée. Ce sont vous et vos alliés qui devez nous aider à vaincre le Dieu du Sang et ses séides !$B$BPortez ce talisman, qui vous aidera dans vos pérégrinations.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8143,'Il ne reste plus qu\'une seule amélioration à placer sur le talisman, $C. Quand le temps sera venu, je l\'appliquerai.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8151,'Mon rôle n\'est plus de chasser, mais d\'apprendre aux chasseurs. Tel est le destin qui m\'a été offert.$B$BConfectionnez avec moi un charme du $C : un ensemble de trophées pris sur vos proies qui vous rappellera vos épreuves et triomphes passés. Je garderai le charme, mais je vous récompenserai avec autre chose.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8153,'Vous devez avoir une vue aiguisée et une patience à toute épreuve pour avoir récupéré ces ramures. Beau travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8186,'Utilisez-le à bon escient, $C. Ne faites preuve d\'aucun pitié envers les Hakkari !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8194,'Si ça vous va, ça me va !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8195,'Excellent ! Cette série de pièces complète admirablement notre collection... Nous l\'utiliserons pour défendre la tribu face aux menées du Dieu sanglant. Vous avez mérité cette marque d\'honneur, $N, ainsi que les remerciements de la tribu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8196,'Un juste échange, mon ami. Dégustez les succulents fruits des Mers du sud, avec la bénédiction de la tribu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8224,'*Bzzz*$B$BIdentification du Talang dezien terminée.$B$BVotre récompense est disponible.$B$B*Clic-clic* *Bzzzz*') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8228,'Il y aura un concours de pêche à Baie-du-Butin ce dimanche ! Voici ses règles si vous souhaitez y participer !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8229,'Concours de pêche à Baie-du-Butin ce dimanche ! Voilà les règles !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8231,'Il est difficile de vaincre les vandales des flots, surtout dans leur environnement humide.$B$BVous avez prouvé que vous étiez prêt à chasser des proies encore plus redoutables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8238,'Excellent ! Cette série de pièces complète admirablement notre collection... Nous l\'utiliserons pour défendre la tribu face aux menées du Dieu sanglant. Vous avez mérité cette marque d\'honneur, $N, ainsi que les remerciements de la tribu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8239,'Excellent ! Cette série de pièces complète admirablement notre collection... Nous l\'utiliserons pour défendre la tribu face aux menées du Dieu sanglant. Vous avez mérité cette marque d\'honneur, $N, ainsi que les remerciements de la tribu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8246,'Un juste échange, mon ami. Veuillez accepter ce cachet avec la bénédiction de la tribu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8249,'Que ces couteaux trouvent une place dans le cœur de quelqu\'un.$B$BEt ce n\'est pas une image.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8250,'<Sanath ricane.>$B$BL\'archimage Xylem attend votre arrivée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8255,'C\'est une bonne chose que le chemin divin vous ait conduit jusqu\'à nous, $N. Vos croyances ne vous empêchent pas d\'accomplir les tâches que nécessite la préparation de ce baume. Voyez-vous, le coursier est sacré pour le Cercle cénarien. En tuer un pour quelque raison que ce soit, même si c\'est réellement nécessaire, affaiblit notre esprit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8256,'Je ne peux pas dire que je sois ravi de manipuler une substance si infecte, mais c\'est un mal nécessaire. Merci, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8257,'Vous avez tué Morphaz et vous nous avez rapporté son sang. C\'est une nouvelle merveilleuse. J\'ai peine à y croire.$B$BNous allons combiner les ingrédients immédiatement. Ensuite, nous commencerons à soigner les arbres et les créatures de Gangrebois. Il faudra une vie entière pour défaire ce qui s\'est produit ici, mais vous nous en avez donné les moyens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8303,'Vous êtes l\'espoir de Kalimdor, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8316,'La guerre arrive, $N, et avec elle des horreurs encore inconnues. Vous avez fait tout ce que nous vous demandions, et pour cela, vous serez récompensé.$B$BSi jamais cette… cette prophétie devait se réaliser…$B$BAlors, notre avenir à tous s\'arrêtera là.$B$BCes armements vous seront extrêmement utiles pour votre campagne dans ce désert.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8319,'Très bon travail ! Je glisserai un mot en votre faveur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8324,'Excellent ! Je suis très impatient de les lire. Je vous en prie, continuez à m\'apporter ici tous les textes cryptés que vous trouverez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8326,'La tour et ses environs devraient être relativement sûrs désormais, au moins pour un moment. Vous nous avez procuré une petite zone de paix, ce qui est bien, mais si nous voulons survivre, nous devons reprendre le contrôle de toute l’île. Pour cela, vous devrez affronter des dangers bien plus redoutables qu’une poignée de lynx et de wyrms de mana.$B$BPrenez ceci, $N, je ne doute pas que vous en fassiez bon usage dans les tâches qui vous attendent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8328,'Ah, $N. À ce que j’ai compris, vous êtes parmi les nouveaux mages de l’île, n’est-ce pas ? Bien, vous êtes au bon endroit. Si vous cherchez à maîtriser les arcanes, je peux vous y aider… tant que vous aurez les moyens de payer le coût de votre entraînement… et la capacité à vous concentrer sur mes leçons.$b$bAllez, commençons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8330,'Bien joué, je savais que vous seriez idéal pour ce travail. Lorsque nous pourrons de nouveau nous servir de nos installations extérieures, tous ces objets me seront fort utiles.$B$BComme je le disais, gardez donc la sacoche. Par ailleurs, cette pièce d’armure pourrait vous être utile. Considérez-la comme une compensation adéquate pour une tâche simple, mais accomplie avec conscience !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8333,'Voilà, $N. Un nouveau médaillon de statut du Crépuscule. Utilisez-le sagement… Bonne chance contre le Conseil abyssal !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8334,'La mort de nos sylveniers ne m’apporte aucune joie, mais elle me montre que vous êtes prêt pour la tâche la plus importante qui reste à accomplir sur l’île de Haut-soleil. Prenez ceci et faites-en bon usage. Vous aurez besoin d’un esprit rapide et d’un bon équipement pour affronter ce qui vous attend. Notre reconquête de l’île en dépend.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8336,'Splendide ! Elles feront parfaitement l’affaire. J\'ai beaucoup réfléchi au sujet du malaise qui pèse actuellement sur l’île de Haut-soleil. L’une des stratégies possibles était de récupérer ces esquilles arcaniques sur les animaux de l’île. Je vais pouvoir m’en servir pour mes expériences et, peut-être, découvrir le coupable.$B$BQuoi qu’il en soit, je me chargerai des recherches. Quant à vous… permettez-moi de vous faire profiter de cette incantation. Je pense que vous en aurez l’usage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8338,'Voilà qui est… fort intéressant. Et lorsque je dis intéressant, je veux dire perturbant.$B$BAprès la destruction du puits de soleil, la reprise en main de l’île s’est avérée plus difficile que prévue. Je soupçonne l’île d’être corrompue par une source impure. Cette esquille pourrait nous aider à découvrir ce qu’il en est vraiment.$B$BVous avez eu raison de me la remettre, $N. Prenez ceci, en récompense de votre diligence. Merci.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8345,'Ah, $N, merci d\'avoir partagé avec moi votre expérience au sanctuaire de Dath’Remar. Avant tout, vous êtes digne d\'éloges pour votre sens du devoir et votre respect. Ils vous serviront bien, tant ici que dans le reste d’Azeroth.$B$BQuant à cette sensation étrange, elle participe certainement de la corruption dont souffre l’île de Haut-soleil. Nous garderons cet endroit à l’œil. Merci de nous avoir prévenus !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8350,'Merci, j’apprécie cette livraison rapide.$B$BEt puisque vous êtes là, profitez-en pour vous détendre. Si ce n’est pas déjà fait, vous devriez vous procurer une pierre de foyer et vous lier à cette auberge. Grâce à la pierre de foyer, vous pouvez revenir automatiquement à une auberge, une fois par heure. Si, par malheur, vous perdez votre pierre de foyer, rendez-vous à n’importe quelle auberge, l’aubergiste sera ravi de vous en donner une.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8351,'Oui, c\'est vrai, $N. J\'ai une tâche très difficile devant moi…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8355,'Wou-wou ! Bien joué, $N ! Voici votre bonbon.$B$BJoyeuse Sanssaint !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8368,'Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l\'honneur que vous avez gagné se répande sur toutes nos terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8376,'La guerre arrive, $N, et avec elle des horreurs encore inconnues. Vous avez fait tout ce que nous vous demandions, et pour cela, vous serez récompensée.$B$BSi jamais cette… cette prophétie devait se réaliser…$B$BAlors, notre avenir à tous s\'arrêtera là.$B$BCes armes vous seront extrêmement utiles pour votre campagne dans ce désert.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8377,'La guerre arrive, $N, et avec elle des horreurs encore inconnues. Vous avez fait tout ce que nous vous demandions, et pour cela, vous serez récompensé.$B$BSi jamais cette… cette prophétie devait se réaliser…$B$BAlors, notre avenir à tous s\'arrêtera là.$B$BCes armes vous seront extrêmement utiles pour votre campagne dans ce désert.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
