INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8382,'La guerre arrive, $N, et avec elle des horreurs encore inconnues. Vous avez fait tout ce que nous vous demandions, et pour cela, vous serez récompensé.$B$BSi jamais cette… cette prophétie devait se réaliser…$B$BAlors, notre avenir à tous s\'arrêtera là.$B$BCes armes vous seront extrêmement utiles pour votre campagne dans ce désert.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8386,'Bon travail, $N. Grâce à vous, nos défenses naturelles de l\'Ashenvale resteront encore intactes pour un jour…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8388,'Vous continuez à faire honneur à la Horde, $N. Je suis heureux de voir que vous ne vous êtes pas ramolli.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8389,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8413,'Il était temps. J\'mérite une bonne nuit de sommeil ! Le totem des esprits me protègera.$B$BJe collectionne des trucs et des machins d\'puis longtemps. Vous voulez quelque chose pour vot\' peine ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8414,'Chasser le mal d\'une pierre du Fléau est une entreprise risquée, car cela attire l\'attention des morts-vivants sur des lieues et des lieues. Mais la Lumière est forte en vous, $N, et je n\'ai aucune peur pour vous...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8418,'Voilà qui est excellent, $N. Je suis quelque peu surpris, mais il ne faisait pour moi aucun doute que vous ne nous laisseriez pas tomber.$B$BJ\'ai l\'honneur de vous faire don de l\'une des pierres de pouvoir sacrées. Faites-en bon usage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8425,'Enfin je sens à nouveau le froid de l\'acier, même si ce n\'est que pour un instant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8426,'Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l\'honneur que vous avez gagné se répande sur toutes nos terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8430,'Excellent ! Vous avez prouvé votre valeur en défendant nos opérations dans le goulet des Warsong ! Que la nouvelle de l\'honneur que vous avez gagné se répande sur toutes nos terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8431,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8432,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8433,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8434,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8435,'Bien joué, $C ! Vous nous avez bien aidés à assurer l\'emprise de la Horde sur le goulet des Warsong !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8463,'Excellent travail, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8468,'Son destin a enfin rattrapé cette vermine de Thaelis. Bon travail, $N. Les Déshérités devraient nous laisser tranquilles pour un moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8469,'Vous faites une fois encore la preuve de votre honneur! Je veillerai à ce que vos exploits soient connus parmi les miens.$B$BSi vous trouvez d’autres perles tombe-hiver, n’oubliez pas de me les ramener. À chaque fois que vous m’en procurerez une série, je parlerai de vous à la tribu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8472,'Vous avez fait du bon travail, $N. Tant que nos sanctum des arcanes ne fonctionnent pas à plein régime, ces batteries nous apporteront un soutien bienvenu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8473,'C’est donc fait. Maudits soient ces temps qui nous poussent à prendre de pareilles mesures… et maudit soit notre ennemi, le Fléau !$B$BRetenez bien ceci, $N. Nos terres doivent être protégées quel qu’en soit le prix. Nous triompherons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8474,'Ce… ce pendentif. Je l’ai donné au vieux Blanchécorce lorsque son peuple nous a aidés à rebâtir notre village.$B$BJe suppose que cela veut dire qu’il…$B$B<L’$R se racle la gorge et essaye de retrouver son sang-froid.>$B$BMerci de me l’avoir apporté, $N. J\'ai quelque chose à vous demander.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8475,'Nous ne nous attendons pas à ce que le Fléau renonce à ses attaques dans un avenir proche, mais nous savons apprécier toute aide que nous recevons pour la défense de la brèche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8476,'C’est du bon travail, $N. Avec plus de gens comme vous, nous rendrons bientôt leur gloire passée à nos terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8477,'Les rumeurs disaient vrai, $N. Ce marteau est à la fois léger et puissant. Il me permettra d’achever plusieurs projets. Et bien sûr, vous serez le premier à choisir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8479,'Ouais, l’ami. Zul’Marosh, il l’a cherché. Il a brûlé le village de Ven\'jashi. Je tue beaucoup d’Amani avant qu’il me mettent en cage. Je cache quelque chose dans le sable. Ça mon cadeau pour vous.$B$BAh… ah, le poison… lui s\'étendre. Se r\'poser maintenant...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8480,'Excellent travail, $N. Nous allons montrer aux Déshérités de quel bois nous sommes faits !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8482,'Vous avez vraiment trouvé cela sur un elfe de la nuit ? Pourtant, c’est écrit dans la langue des nains…$B$BD’après ce que j’arrive à en comprendre, la personne qui a écrit ça n’a pas causé la défaillance, mais a été envoyée pour espionner ses conséquences. Ils disent que nos tentatives sont imprudentes et dangereuses... mais qui ?$B$BBien sûr ! Cet envoyé de Forgefer ! Quelle folie d’avoir fait confiance à quelqu’un de l’Alliance !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8483,'Ainsi donc, c’est fait. Excellent travail !$B$BL’information a été transmise au forestier général et croyez-moi, les nains vont payer fort cher leur trahison.$B$BVous avez rendu aujourd’hui un grand service à votre peuple, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8486,'Merci, $N. Maintenant que les âmes en peine sont sous contrôle, nous pouvons envoyer quelqu’un évaluer les dégâts. Espérons que ce n’est rien de permanent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8487,'Excellent. Je vais lancer un enchantement d\'accroissement sur les échantillons afin de pouvoir analyser plus précisément la contamination du sol.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8488,'Mes tentatives sont sans espoir, $N. La nature même du sol a été altérée... la contamination est irréversible. Merci pour votre aide. J\'ai besoin de vous demander un dernier service.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8490,'Excellent. Les défenses devraient contenir le Fléau un peu plus longtemps. Merci pour votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8491,'Elles feront parfaitement l\'affaire, $N. Prenez cette pièce d\'armure en récompense. Je pourrai en faire plus avec les fourrures que vous m\'avez apportées.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8492,'# Achèvement$B$BVous avez réussi, mon gars ! Nous allons mettre ces barres de cuivre sur notre pile et en faire bon usage pour la confection de notre matériel de guerre sans plus attendre. Ce sont les efforts de gens comme vous qui me rendent fier de servir l\'Alliance. Bon travail, soldat !  $B  $BEt si par hasard, vous trouvez d\'autres barres de cuivre sur votre chemin, faites-les-moi parvenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8495,'Il doit faire froid, aujourd\'hui, dans les Steppes ardentes. Hé, regardez, c\'est $N, et il m\'a apporté un cadeau. Vingt barres de fer ! J\'en rêvais depuis si longtemps.  $B  $BBon, trêve de plaisanteries, merci, $N. Vous faites honneur à votre nom et à l\'Alliance. Maintenant, retournez là-bas et rapportez-moi d\'autres matériaux pour l\'effort de guerre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8500,'Excellent, $C ! Du bon boulot. Je vais veiller à ce que ces barres soient correctement empilées, puis remises aux forgerons et aux ingénieurs qui préparent le matériel de l\'armée. Encore merci, et si vous récupérez d\'autres barres de thorium, vous savez où me trouver.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8505,'Nous apprécions beaucoup votre contribution, $C. Nous ne pourrons briser l\'impitoyable progression des silithides – et la force qui les pousse à nous attaquer – que grâce aux efforts combinés de tous. Même la Horde fait provision de [lotus pourpre](/wotlk/fr/item=8831/lotus-pourpre).') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8509,'Bon travail, $C. Je dois dire que c\'est une bonne surprise. Vous n\'imaginez pas le nombre de gens qui se présentent, proposent leur aide… et ne reviennent jamais. Laissez-moi le temps de mettre votre contribution dans une caisse et de noter votre nom sur l\'inventaire. Ensuite, nous verrons si j\'ai encore besoin de plantes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8513,'Waouh ! J\'ai l\'impression que ça ne fait pas cinq minutes que vous vous êtes porté volontaire. Merci beaucoup pour ce don. Je vais empaqueter et compter tout ça. Pour sûr, vous avez ensoleillé ma journée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8518,'Vous méritez des félicitations, $N. Nous sommes en train de nous mettre sur le pied de guerre. Dans de telles circonstances, la cupidité en pousse certains à se remplir les poches. Vous avez prouvé, encore et encore, que votre dévouement envers l\'Alliance – et envers tout Azeroth – passait en premier.  $B  $BPuisse Elune vous bénir toujours !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8521,'Vous êtes plein d\'abnégation. Merci infiniment de votre contribution à l\'effort de guerre. Ce sont des gens comme vous qui feront la différence entre victoire et défaite à Ahn\'Qiraj. J\'espère que cela suffira.  $B  $BEncore merci, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8524,'Deux pour l\'Alliance, un pour moi, deux pour l\'Alliance, un pour moi… Hé bien, mon petit poissonnier c\'est du bon travail. Je vois que vous allez vraiment faire honneur au club. Mais j\'ai bien l\'impression qu\'on aura besoin d\'encore plus de thon. Et si vous y retourniez et que vous en pêchiez un peu plus ? J\'entends déjà mon estomac qui gargouille…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8525,'Je savais que vous y arriverez, mon petit. Vous avez l\'air d\'une personne qui sait ce qu\'elle aime. Et dans ce cas, vous aimez me faire plaisir, à moi et à mes supérieurs. Je vous assure que vous y arrivez très bien.$B$BHa ha ha ! Bon, allez, je vais ranger ces poissons, puis nous aurons une petite conversation, vous et moi, sur vos vingt prochains thons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8532,'Ces barres feront l\'affaire. Merci de ne pas les avoir polies. Pas besoin qu\'elles soient jolies, elles vont être utilisées pour fabriquer des fournitures militaires. Je vais les mettre en piles, et je veillerai à ce qu\'elles soient bien employées. Revenez me voir si vous voulez m\'en fournir une autre vingtaine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8533,'Vous m\'avez prouvé votre valeur une fois encore, $C. Je veillerai à ce que toutes ces barres de cuivre soient utilisées en temps et heure. Pour l\'instant, je vais les placer sur la palette et les comptabiliser. Si cela vous dit, vous pourriez peut-être nous aider à en rassembler encore plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8536,'Excellent travail, $N.  Voici votre prochaine mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8537,'Excellent travail, $N.  Voici votre prochaine mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8538,'Vous avez rendu un service exceptionnel à notre cause aujourd\'hui, $N. Vous avez vaincu certains de nos ennemis les plus redoutables. Je vous félicite du fond du coeur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8544,'Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8545,'Ça démarre bien, entre vous et moi, $C. Ça fait vingt barres de mithril que je peux mettre sur la pile et rayer d\'ma liste. On en f\'ra bon usage – des fournitures pour la guerre.$B$BN\'hésitez pas à rev\'nir me voir, passqu\'on dirait qu\'on n\'a pas fini d\'avoir besoin d\'barres de mithril.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8549,'Et ainsi, tous nos gestes nous rapprochent de la guerre. Merci pour tous les efforts que vous avez dû consentir pour récolter cette pacifique, $C. Je vous assure qu\'elle sera utilisée à bon escient, et que votre contribution n\'est pas passée inaperçue, $N. Si vous le souhaitez, vous pourrez toujours me ramener d\'autres fleurs. En attendant, que la Terre-mère vous guide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8555,'Eranikus, Vaelastrasz, et Azuregos... Vous avez certainement entendu parler de ces dragons, mortel. Ce n\'est pas une simple coïncidence si chacun d\'eux a joué un grand rôle comme gardien de ce monde.$B$BMalheureusement, et ma propre naïveté en est en partie responsable, ces gardiens ont tous succombé à de terribles tragédies, si terribles qu\'elles ont alimenté ma méfiance à l\'égard de votre espèce.$B$BCherchez-les… Et préparez-vous au pire, $R.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8562,'Je ne m’attendais pas à vous voir revenir, $N.$B$BVous avez une destinée supérieure à celle de la plupart des immortels.$B$BEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.$B$BAcceptez cette cuirasse comme symbole de la gloire et du fardeau qu’engendrent vos actes.$B$BPuisse son pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8564,'Soyez la bienvenue, $N. Je suis la matrone Arène. J’offre mes services à ceux qui souhaitent devenir prêtres. Les ignorants s’imaginent souvent que notre voie est celle de la paix, mais en ce qui concerne les elfes de sang, ils se trompent. Nous soignons les corps et les esprits, mais pour tous ceux qui nous font du tort, nous sommes aussi le poing de la vengeance.$b$bJe vais vous former. Tout ce que je vous demande, c\'est de payer les inévitables coûts de formation et d’avoir l’esprit ouvert. Si vous acceptez ces conditions, nous pouvons commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8573,'Un travail remarquable, $N. Au nom du Cercle cénarien, acceptez ceci. Vous l\'avez bien mérité, mon ami !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8577,'Je n’y crois pas, il a fini par me retrouver ! J’étais sûr qu’il avait perdu ma trace quand j’étais en Outreterre. Je ne retournerai pas là-bas, $R, ah, ça non ! J’en ai assez d’être son meilleur ami pour la vie à mi-temps, et son esclave à plein temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8579,'Je vois que vous n’êtes pas un mortel ordinaire, $N. Vous avez une chance de triompher du Dieu très ancien. Elle est infime, soit, mais pour l’heure, elle est meilleure que les nôtres. Il s’attend à voir arriver des dragons. Il ne vous attend pas.$B$BIl y a mille ans, Nozdormu et Forteramure ont vaincu les Qiraji grâce à une alliance entre les dragons et les peuples mortels. Nous allons passer un pacte similaire. Gagnez la confiance du Vol de bronze et vous gagnerez notre confiance. Alors, nous ferons de vous un véritable champion.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8581,'C\'est pas pour rire, $C ? Vous avez ramené ses fleurs de feu à Pele\'keiki si vite que ça ? Pele\'keiki va les compter tout de suite ! Pele\'keiki est si content qu\'il va dire à tout le monde que $N est le meilleur récolteur de fleurs de feu de tous les récolteurs de fleurs de feu. Pele\'keiki a très envie que la guerre commence. On mettra le feu au ciel de Silithus, pas vrai, frangin  ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8583,'Un travail à la fois précis et excellent, $N. Votre promptitude et votre motivation sont dignes d\'éloges. Je veillerai à ce que ce lotus pourpre ne soit pas gaspillé.$B$BMerci encore. Si vous vous procurez d\'autres plants de lotus pourpre, n\'hésitez pas à venir me trouver aussi vite que possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8585,'Regardez les nuances de la chair de ces filets ! C’est fantastique !$B$BBon, maintenant, pour ce poulet… Hmm, attendez voir. Il va me falloir quelques minutes pour préparer la recette.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8586,'C’est prêt ! Je vous présente la plus grande de mes créations : les pyro-côtelettes de chimaerok à la Dirge !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8588,'Oh, alors vous avez le [cuir lourd](/wotlk/fr/item=4234/cuir-lourd) dont j\'ai besoin ? Et ce sont d\'excellentes peaux, $C, votre lame est bien aiguisée ! Bon, maintenant que nous sommes partis du bon pied, vous et moi, je veillerai à ce que votre contribution à la cause soit bien employée. Et si vous tombez sur d\'autres morceaux de [cuir lourd](/wotlk/fr/item=4234/cuir-lourd), revenez me voir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8589,'Oh merci l\'ami ! Merci infiniment pour tout ce [cuir lourd](/wotlk/fr/item=4234/cuir-lourd) ! Chaque petit morceau nous rapproche du quota. Je vais les mettre sur la pile, pour que les artisans du cuir puissent commencer à travailler dessus.  $B  $BMerci encore, $N. Et si vous trouvez d\'autres piles de cuir épais, vous savez où me trouver.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8595,'Vous continuez à bien nous servir, $N. Notre pacte est maintenu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8597,'Le livre a disparu ! En revanche, il y a une lettre sur la terre fraîchement remuée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8599,'Quoi ?  $B  $B  $B<Narain se met à pianoter.>  $B  $BEh bien, euh… Qu\'est-ce que vous voulez que je fasse ? C\'est un poisson ! Un POISSON ! Et je suis un gnome. C\'est sans espoir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8600,'Très bien. C\'est un travail passable, même si certaines de ces peaux sont un peu déchiquetées sur les bords. Mais bon, vous avez terminé votre tâche, et vous avez mérité votre récompense. Si vous vous procurez une autre pile de morceaux de [cuir robuste](/wotlk/fr/item=8170/cuir-robuste), hâtez-vous de me la ramener.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8601,'De l\'entraînement, encore de l\'entraînement, toujours de l\'entraînement. Un couteau bien aiguisé et l\'art de s\'en servir vous aideront à faire votre chemin dans le monde, $N. Les bords de ces morceaux de cuir semblent bien plus réguliers que ceux de votre précédente livraison. Auriez-vous changé de couteau ?$B$BPeu importe. Merci pour vos efforts. Votre don a été enregistré, et je vous promets que nous en ferons bon usage. Si vous entrez en possession d\'autres morceaux de cuir robuste, n\'hésitez pas à revenir me parler, j\'en aurai sans doute encore besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8602,'Grâce aux objets que vous avez ramenés et aux écailles des Qiraji tués, je vous façonne ces espauliers, mortel. Puissent-ils vous octroyer la protection dont vous avez besoin ! Puisse leur vue épouvanter nos ennemis !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8604,'Je vous présente mes remerciements, $C, et la gratitude la Horde. Si vous souhaitez continuer à contribuer à l\'effort de guerre, et si vous vous procurez d\'autres bandages en laine, revenez me voir. D\'ici là, que vous ancêtres vous gardent !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8605,'Vous êtes un $C honorable ! Je veillerai à ce que ces bandages parviennent à bon port. Je vous remercie, pour moi comme pour la Horde.  $B  $BAllez en paix, $N, et ne manquez pas de revenir me voir si vous avez des surplus de bandages en laine. Nous avons vraiment besoin d\'aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8606,'J’ai peur que nous n’ayons sous-estimé ces voleurs de livres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8607,'Ils sont acceptables – étonnant. Peut-être avais-je sous-estimé vos \'capacités\', $C. Peut-être. Vous avez accompli une tâche fort simple, pour laquelle vous allez recevoir une récompense disproportionnée. Mais que cela ne vous monte pas à la tête. Si vous voulez vraiment faire vos preuves, vous devriez repartir et me ramener un autre paquet de bandages en tisse-mage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8608,'Vous y êtes arrivé une nouvelle fois, $C. Voilà qui est stupéfiant. Bah, on dit que je sais bien choisir mes serviteurs… Très bien, je noterai votre nom à côté de votre contribution et vous recevrez la considération qui vous est due. Si vous voulez vraiment prouver votre valeur, je vous conseille de repartir et de vous procurer un autre paquet de bandages en tisse-mage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8611,'D\'acc, ce tas de viande de loup me va. J\'vais saler tout ça et l\'empaqueter. Espérons qu\'il sera encore mangeable le moment venu.$B$BMerci pour la livraison, $C. Ça vous dirait de m\'en ramener une autre plâtrée ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8615,'Merci d\'avoir participé à l\'effort de guerre, $C. Bien des gens auraient choisi d\'ignorer nos besoins, optant à la place pour le profit. Mais contrairement à vous, ceux-là ne bénéficieront pas de la gratitude de la Horde. Leurs cœurs sont vides, alors que le vôtre doit être empli de la satisfaction qui naît d\'un don vraiment altruiste.$B$BUne fois encore, merci. Si vous trouvez le temps de nous aider une nouvelle fois avant que nos préparatifs soient achevés, vous me trouverez ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8619,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8620,'Fantastique ! Je n’arrive pas à croire que vous vous soyez donné tout ce mal ! Vous êtes quoi, une sorte de machine ? À votre place, j’aurais laissé le monde imploser.$B$BJe vous tire mon turban, messire ! Et toute bonne action mérite une récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8627,'Je ne m’attendais pas à vous voir revenir, $N.$B$BVous avez une destinée supérieure à celle de la plupart des immortels.$B$BEn tuant C’Thun, vous avez sauvé Azeroth, et vous avez fait pencher les plateaux de la balance dans des événements cosmiques qui dépassent votre compréhension.$B$BAcceptez cette cuirasse comme symbole de la gloire et du fardeau qu’engendrent vos actes.$B$BPuisse son pouvoir vous aider dans les défis qui vous attendent, tueur de dieu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8635,'Les batailles des âges anciens sont les graines des légendes du présent. Vous vivez en un temps de héros, mon enfant. Puisse votre légende s\'enracine et prospérer !$B$BJe vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8636,'La substance de la vie est condamnée à mourir et à retourner à la terre, mais la substance de l\'esprit est éternelle. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime….') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8642,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8643,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8644,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8645,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8646,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
