INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8688,'Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, $N. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
