INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8727,'Chacune des innombrables étoiles qui brillent dans les cieux renferme la réponse à un mystère terrestre, $N. Puissent les sages – et les chanceux – les contempler et découvrir la vérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8728,'Un marché est un marché. J’espère simplement que vous savez dans quoi vous vous engagez, $N. C’est vraiment se donner beaucoup de mal pour une simple partie de pêche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8729,'Bien joué, $N. Je serai bientôt capable de refaçonner le sceptre des Sables changeants.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8730,'L’âme de Vaelastrasz repose en paix, champion. Tous les Aspects observent vos progrès avec un grand intérêt. Sachez que vous avez de puissants alliés.$B$BJ’ai reçu l’ordre de vous offrir quelque chose pour vous aider dans votre lutte. Faites-en bon usage…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8734,'Il serait impossible d\'attirer Eranikus hors du Rêve s\'il refusait de le quitter. Ses desseins, cependant, l\'obligent à entrer dans notre monde. Il cherche à détruire la manifestation vivante de Malfurion. S\'il y parvenait, cela signifierait la fin de l\'un des plus puissants alliés du Rêve. Le Cauchemar consumerait tout ce qui resterait si Malfurion tombait…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8735,'Êtes-vous prêt ? Ce monde est-il prêt pour ce que vous êtes sur le point d\'invoquer. Je l\'ignore… mais mon devoir me lie à Malfurion. Le devoir et l\'honneur…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8748,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie du protecteur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8749,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie du protecteur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8750,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie du protecteur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8751,'Levez-vous, Protecteur de Kalimdor ! Levez-vous et que tous reconnaissent votre valeur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8752,'Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.$B$BLa chevalière du conquérant rendra vos attaques physiques beaucoup plus meurtrières.$B$BMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8758,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie de l\'invocateur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8759,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie de l\'invocateur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8760,'Vos progrès au sein de la Progéniture sont très impressionnants, $N. Puissez-vous ne jamais quitter la voie de l\'invocateur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8761,'Levez-vous, Grand Invocateur ! Levez-vous et que tous reconnaissent votre valeur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8764,'Portez-vous bien, $N. Si vous changez d\'avis, je serai là pour vous aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8778,'Ah oui, cela nous rendra bien service ! Mille mercis, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8781,'Oh, excellent ! Ils vont arrêter de venir me voir pour se plaindre que leurs lames sont émoussées. Merci, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8786,'Excellent travail, $N. Nous allions en manquer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8787,'Ah oui… Je vais les distribuer aux soldats, $N. La légion d\'Orgrimmar vous remercie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8792,'Throm\'ka, $C ! Il est bon de voir une foule de membres de la Horde, tels que vous, $N, s\'empresser de jeter les bases de notre future guerre à Ahn\'Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn\'Qiraj.$B$BMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8794,'Throm\'ka, $C ! Il est bon de voir une foule de membres de la Horde, tels que vous, $N, s\'empresser de jeter les bases de notre future guerre à Ahn\'Qiraj. Nos efforts ici nous garantissent la victoire contre les silithides et leurs maîtres maléfiques qui se terrent dans Ahn\'Qiraj.$B$BMaintenant que vous êtes là, discutez avec les collecteurs et proposez votre aide à ceux qui récupèrent des matières premières qui vous intéressent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8802,'Le Maître a laissé ceci pour vous, champion. De sa cache intemporelle, une collection d\'artefacts couvrant des milliers d\'années – le choix vous appartient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8857,'Oh, quelle merveilleuse carcasse ! J\'en ferai des poulets extraordinaires ! Bien joué, mon garçon !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8858,'Excellent. Nous pourrons certainement utiliser cette chitine pour en faire des armures ultra-solides. Voici les richesses promises.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8859,'Excellent et juste à temps ! Bon travail, mon gars.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8862,'Parfait… J\'accepte ces pièces des ancêtres.  Prenez cette chandelle d\'Elune avec ma bénédiction. Et tenez, voici quelques feux d\'artifice en prime.  $B  $BQue la Fête lunaire vous soit joyeuse et pleine de divertissements, $N.  $B  $BEt si vous décidez d\'affronter Présage et ses serviteurs, vous verrez qu\'une chandelle d\'Elune peut se révéler très utile…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8866,'Il est doux de savoir que les peuples de cette terre rendent encore hommage aux races anciennes. Je vous souhaite bonne chance, $N, et vous offre ce gage de mon estime…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8874,'Soyez le bienvenu, $N. Vous venez ici pour vous joindre à la fête ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8882,'Et voici votre schéma… Étudiez-le attentivement, et apprenez-le…  $B  $BBonne chance, $N. Que votre célébration rivalise avec celle de la Fête lunaire elle-même !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8884,'Bon travail, $C. Si on peut se fier à l\'odeur, on dirait que vous apportez tout ce que je vous ai demandé, et peut-être même plus. Je suis certain que nous saurons quoi en faire. Un ragoût ou quelque chose de semblable.$B$BHélas, il semble que vos efforts n\'aient pas été suffisants. Les murlocs ne battent pas en retraite. Une action plus directe est nécessaire !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8886,'Vous avez réussi ! Vous m\'avez sauvée de la ruine et vengée de ces horribles créatures !$B$BMaintenant, si j\'arrivais à convaincre ces beaux forestiers de m\'aider à charger la cargaison, je pourrais enfin partir d\'ici ! Il faudra que je revienne quand Velendris aura repris le mouillage.$B$BTenez, prenez ces pièces. C\'est tout ce que je peux vous donner, mais c\'est la moindre des choses pour vous remercier de vos efforts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8888,'Le magistère s\'inquiétait pour moi ? Comme c\'est gentil à lui. Dommage qu\'il ne m\'ait pas témoigné plus d\'intérêt avant, quand nous étions sur la Flèche.$B$BMais peu importe maintenant. Écoutez-moi attentivement, $C, car j\'ai une faveur à vous demander.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8889,'Je vous suis reconnaissante pour votre aide, mais je suis aussi attristée d\'apprendre que certains de mes camarades apprentis ont succombé à leur addiction.$B$BMaintenant que l\'alimentation de la Flèche a été coupée, je crois que je vais rester ici un moment et voir si la situation se calme assez longtemps pour que je puisse me glisser là-bas et récupérer leurs restes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8890,'Non ! J\'ai trop tardé. Tout est de ma faute.$B$BJ\'ai perdu le contrôle de mes recherches sur la purification de sources de magie alternatives avant de pouvoir y mettre fin. Si seulement j\'y étais allé moi-même... Si seulement ils m\'avaient écouté, et tenu compte de mes avertissements !$B$BJ\'ai du sang sur les mains, $C. Je vous remercie cependant d\'avoir donné le repos aux âmes torturées de mes anciens apprentis. C\'est une mince consolation de savoir qu\'ils ne demeurent pas dans cet état auquel un elfe de sang préfère la mort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8891,'La voilà, $N, la preuve de mon crime. Ce journal contient toutes mes malencontreuses études.$B$BJ\'ai poursuivi mes recherches sans tenir compte des avertissements, jusqu\'à ce qu\'il soit presque trop tard. Puis, quand j\'ai compris mon erreur, j\'ai fait ce que j\'ai pu. Mais à ce moment, certains de mes élèves étaient déjà allés trop loin. J\'ai fait évacuer la Flèche pour les éloigner de la corruption, mais dans ma hâte, j\'ai oublié de couper les sources d\'énergie.$B$BJe vais brûler ce volume afin que personne d\'autre ne devienne la victime de son contenu. Mon seul but était d\'aider les sin\'dorei.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8892,'Voilà qui leur apprendra à nous laisser tranquilles. Bon travail, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8893,'Vous placez l\'œuf d\'hippogryphe dans la machine. Des signaux sonores s\'enchaînent, sur un fond de bruits mécaniques.$B$BEt le Calibre-œuf a pesé, mesuré et empaqueté votre œuf. Ça c\'est du service rapide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8894,'Bon, je suppose qu’il faudra bien que cela fasse l’affaire, n’est-ce pas ? Merci de votre aide, $C. J’espère que tout ce gâchis sera nettoyé lorsque le magistère reviendra à la flèche de Ternesoir.$B$BTenez, prenez cette menue monnaie. Ce n’est pas grand-chose, mais c’est tout ce que j’ai pour l’instant. Oh, vous seriez gentil d’en tuer quelques autres en partant, si cela ne vous dérange pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8895,'Merci, $N. J’attendais cette lettre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8923,'Formidable ! J\'étais justement sur le point d\'en manquer !$B$BVous dites que c\'est [Mokvar](/wotlk/fr/npc=16012/mokvar) qui vous envoie ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8924,'Oui, ils conviendront à merveille !  $B  $BEn captant les énergies de l\'autre monde que contiennent ces substances, nous allons pouvoir prendre contact avec ceux dont les âmes n\'ont pas encore tout à fait quitté le nôtre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8932,'Vous avez respecté votre part du marché, je respecterai la mienne.$B$BSouvenez-vous quand même que je garde les meilleures pièces tant que vous n\'avez pas terminé votre tâche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8935,'Vous avez respecté votre part du marché, je respecterai la mienne.$B  $BSouvenez-vous quand même que je garde les meilleures pièces tant que vous n\'avez pas terminé votre tâche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8944,'Notre accord tient toujours. Souvenez-vous, ce n\'est qu\'un avant-goût de ce qui vous attend. Si vous m\'aidez à échapper à mon destin, je vous remettrai des objets réellement puissants.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8946,'Ce médaillon… vous l\'avez trouvée ! Je peux enfin reposer en paix.$B$BJe vais répondre à vos questions, $N. Mais dépêchez-vous, car je ne resterai pas longtemps en ce monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8948,'Vous dites qu\'Anthion vous envoie ? Je pensais qu\'il était mort. Bon, je suppose que j\'ai déjà entendu des choses plus étranges dans ma vie.$B$BTrès bien, que voulez-vous que je fasse avec cette bannière ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8956,'Je n\'arrive pas à croire que nous soyons condamnés à mort à cause d\'un médaillon ridicule ! Êtes-vous sûr qu\'Anthion a parlé de Bodley ?$B$BBref… vous avez fait votre travail, parlons donc de votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8962,'Du bon travail, $N. Je vais imprégner le brasero de l\'essence des restes.$B$BVous aurez juste à descendre dans les profondeurs du pic Blackrock, jusqu\'aux appartements du maître de guerre Voone à Tazz\'Alaor, puis à utiliser le brasero pour invoquer l\'esprit corrompu de mon ancien associé, Mor Grayhoof. Il ne connaîtra pas le repos tant que vous ne lui aurez pas repris le morceau d\'amulette.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8964,'Du bon travail, $N. Je vais imprégner le brasero avec l\'essence de l\'épée.$B  $BIl ne vous restera plus qu\'à aller devant le trône cramoisi, à l\'intérieur du Bastion écarlate de Stratholme, et à y utiliser le brasero pour faire apparaître mes anciens associés, Jarien et Sothos. Leurs âmes ont été encore plus perverties par le morceau de l\'amulette et l\'esprit qu\'il contient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8977,'Excellent ! C\'est du bon travail, $N. Je n\'ai pas complètement confiance dans les talents du gobelin, mais je n\'ai pas le choix…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8985,'Du bon travail, $N. Je vais imprégner le brasero de l\'essence de la relique.  $B  $BIl ne vous restera plus qu\'à aller au sanctuaire d\'Eldretharr, dans l\'aile est de Hache-tripes, et à utiliser le brasero pour invoquer l\'esprit de mon ancienne associée, Isalien. Le morceau de l\'amulette, et surtout la portion d\'âme du seigneur Valthalak qu\'il renferme, ont corrompu son esprit.  $B  $BOh, à propos, il me restait un peu du varech de sang que vous m\'avez rapporté de l\'île d\'Alcaz. Je vous ai préparé quelques potions. Faites votre choix !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8990,'Merci d\'avoir apporté le repos à l\'âme d\'[Isalien](/wotlk/fr/npc=16097/isalien), $N. Elle trouvera peut-être la paix auprès de sa déesse. Mais la tâche qui nous attend est la plus difficile de toutes.  $B  $BIl nous manque encore quelques objets pour que le brasero soit capable d\'invoquer le seigneur Valthalak. Il va falloir que vous les récoltiez et que vous me les rameniez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8995,'Heureusement pour vous, je sais que vous n\'êtes pas l\'un de mes voleurs.$B$BÀ présent, je vais reprendre ce qui m\'appartient, mortel ! Rendez-moi l\'amulette !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8997,'Je suis heureuse de voir que vous revenez sans une égratignure, $N. Vous avez l\'air en bonne forme, même si vous semblez quelque peu fatigué.$B$BVenez, racontez-moi ce qui s\'est passé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (8998,'C\'est bon de voir que vous avez survécu, $N. Vous avez l\'air en forme, et j\'ai même l\'impression que ces événements vous ont endurci.$B$BVenez, racontez-moi ce qui s\'est passé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9017,'Nous avons été maudits pour un simple médaillon. Ce seigneur Valthalak est vraiment, vraiment rancunier.$B$BNous allons essayer de trouver les morceaux manquants, si possible avant que je me fasse tuer. Mais d\'abord, parlons de votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9022,'Nous avons été maudits pour un simple médaillon. Ce seigneur Valthalak est vraiment, vraiment rancunier.$B$BNous allons essayer de trouver les morceaux manquants, si possible avant que je me fasse tuer. Mais d\'abord, parlons de votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9023,'Ravenholdt vous remercie, héros ! Faites votre choix !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9029,'Une odeur agréable s\'échappe du chaudron.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9035,'Ils sont partis maintenant. Je les ai terrifiés avec une boule de feu bien placée. Malheureusement pour moi, ils ont jeté notre précieux paquet dans la rivière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9042,'Rappelez-vous, le poignet est le cinquième point le plus vulnérable du corps ! Protégez vos poignets, et vos poignets protègeront vos coudes... probablement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9060,'Un ceinturon de roi ! Et il est pour vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9061,'Les protège-poignets sont prêts. Amusez-vous bien !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9062,'Le livre est complètement trempé. L’instructeur Antheol ne va pas aimer ça du tout.$B$BTenez, prenez cet argent. J’ai une idée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9063,'Vous avez fait un long voyage pour me rencontrer, $C, et vous arrivez juste à temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9064,'Vous dites que ces deux crétins incompétents vous ont donné de l’argent pour me mentir ? Vous avez bien fait de venir me voir, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9066,'Beau travail, $N. Ne vous inquiétez pas pour eux, les transformations ne sont pas permanentes. En revanche, il faudra qu’ils le méritent pour redevenir mes apprentis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9076,'Vous avez réussi à le vaincre ! Mais c’est bien parce que mes hommes l’avaient affaibli avant que vous ne l’acheviez…$B$BAllons, je plaisante, $C. Vous avez fait du bon travail. Si vous restez sobre, vous finirez par vous faire un nom.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9116,'Vos habits sont prêts, $N. Que ceux qui cherchent à nuire à notre monde soient châtiés par le feu des justes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9118,'Vos habits sont prêts, $N. Que ceux qui cherchent à nuire à notre monde soient châtiés par le feu des justes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9119,'Regardez autour de vous. Tout n’est pas pour le mieux dans le meilleur des mondes possibles.$B$BNous avons une grave panne au sanctum occidental, et nous allons devoir faire tout notre possible pour empêcher la crise de s’aggraver.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9121,'Vous allez sentir un léger picotement, $N. C\'est normal, ça veut dire que ça fonctionne. Quand ce sera terminé, vous pourrez entrer dans Naxxramas en marchant sur le portail runique dans Pestebois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9127,'Mon rêve de devenir danseur à plein temps à la discothèque de Gadgetzan va bientôt devenir réalité ! Continuez à faire du bon travail, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9130,'Lymel veut que vous alliez à Lune-d’argent pour lui ramener ses fournitures, pas vrai ? Bien sûr que je peux vous y envoyer rapidement… moyennant un peu d’argent, ça va sans dire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9132,'C\'est tout ce que vous m\'apporterez ? On dirait que vous ne m\'avez pas entendu la première fois. Il m\'en faut PLUS !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9133,'Hein ? Le cerveau décomposé de Lymel a fini par s\'évader de son crâne ? Elle veut tout ça !?$B$BVous avez engagé des porteurs pour vous aider ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9134,'Un billet de retour pour Tranquillien dans les Terres fantômes, donc ? Bien sûr. Vous y serez en un rien de temps !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9137,'Merci, $N. Votre travail est d\'une importance vitale pour le succès de notre campagne contre le Fléau.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9138,'Un travail remarquable ! Hélas, il nous reste beaucoup à faire pour chasser le Fléau de la puissante Quel’Thalas !$B$B Tenez, prenez cet argent… je sais, ce n’est pas grand-chose, mais vous l’avez bien gagné.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9139,'Votre succès à Brume-d’or nous rapproche un peu de la reconquête de notre pays. Mais ne vous y trompez pas, $C, le combat est loin d’être terminé.$B$BTenez, vous avez bien mérité ceci. Vous risquez d’en avoir besoin lorsque vous prendrez les armes contre le village de Coursevent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9140,'Vous avez réussi, $N. Vous avez brisé l’étreinte du Fléau sur les trois villages ! Dorénavant, nous pourrons concentrer nos forces plus facilement contre le Fléau dans la Malebrèche et à Mortholme, au sud.$b$bTenez, choisissez ce que vous préférez. Comptez-vous rester dans la région ? Nous pourrions avoir encore besoin de votre aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9142,'C\'est vous qui en vouliez, feignant, alors venez pas pleurer sur la commande. Honorez-la ou détruisez-la.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9144,'Aidez-moi, étrangère. Je dois… atteindre Tranquillien… Je ne peux pas me permettre… d’échouer.$B$B<Ses yeux se révulsent, et l’$R perd de nouveau connaissance.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9146,'Sombres nouvelles, en vérité. J\'ai clairement surestimé les capacités de commandement de Tomathren. Je vais envoyer un groupe les récupérer, lui et Valanna.$B$BMalheureusement, nous sommes toujours sans nouvelles du forestier Salissa. Je crains le pire en ce qui la concerne.$B$BVous avez rendu un grand service aux pérégrins aujourd\'hui, $C. Acceptez cette modeste marque de notre reconnaissance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9148,'Enfin ! Nous attendons la réponse du seigneur régent depuis des semaines ! Laissez-moi regarder...$B$B<Vandril commence à lire la lettre.>$B$BQuoi ? Une présence maléfique ? Il sent une présence maléfique dans les Terres fantômes ?! Sans blague ? Même moi, j\'aurais pu le lui dire !$B$BC’est pour ça qu’on a attendu si longtemps ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9149,'Excellent ! Ces épines dorsales vont m’être très utiles ! Lorsque j’aurai trouvé un remède à la peste, je deviendrai célèbre et je ne manquerai pas de mentionner votre nom !$b$bEn attendant, prenez ça comme récompense. Vous pourriez en avoir besoin si vous retournez sur la côte.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9150,'Leur puissance est remarquable, $N. Je suis très content de votre travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9151,'C’est Darenis qui vous envoie ? Très bien, je suppose que votre aide nous sera utile pour combattre les forces de Dar\'Khan.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9152,'Maintenant que tout est là, je vais enfin pouvoir ouvrir ma boutique. Je suis sûr que le grand exécuteur sera ravi d’entendre que la guerre contre Dar’Khan et le Fléau peut commencer.$b$bBien sûr, il y a aussi la question secondaire de votre récompense. Très bien, $c, voilà la somme à laquelle j’avais fait allusion. N’hésitez surtout pas à repasser me voir si vous ressentez le besoin de faire un peu de commerce.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9153,'Vous avez bien fait, $N. C\'est par petits pas que nous pourrons triompher de cette nouvelle menace du Fléau.$B$BReposez-vous et reprenez des forces, mais ne tardez pas trop à retourner au front, sans quoi nous risquerions de perdre le terrain que nous avons gagné aujourd\'hui.$B$BPour vous aider dans vos batailles à venir, nous allons vous permettre d\'obtenir certains de nos objets spéciaux en échange d\'autres runes nécrotiques.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9155,'Pas mal, $N. Continuez comme ça, nous avons besoin de gens comme vous par ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9156,'Ah... Luzran et Putrepoing ! Alors, on fait moins les malins maintenant ? En tous cas vous êtes toujours aussi moches !$b$bPrenez cette prime, $N. Vous l’avez bien méritée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9157,'Avec ces colliers nous allons pouvoir invoquer à nouveau Aquantion. L’élémentaire rebelle payera et nos morts seront vengés !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9158,'Vous avez bien fait, $N. C’est important de ne pas laisser la peste contaminer la faune encore saine des Chants éternels. Si vous cherchez de quoi vous occuper, j’ai encore du travail pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9159,'Vous avez fait votre travail consciencieusement, et j’aimerais vous offrir une récompense appropriée. Nous avons besoin de plus d’alliés avec votre courage et votre détermination, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9160,'Dommage que les plans des elfes de la nuit d’An’daroth n’aient pas été plus simples à déchiffrer. Cependant, ces objets qui ressemblent à de petits arbres magiques surmontés d’orbes chargés semblent très intéressants. Nous allons employer des méthodes de renseignement plus directes.$B$BTenez, prenez ces potions et ces quelques pièces. Je pense que vous en aurez l’usage avant que nous n\'en ayons fini avec les elfes de la nuit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9161,'Après avoir feuilleté les premières pages de ce vieux livre, vous arrivez à la conclusion qu’il a autrefois appartenu à celui que l’on connaît sous le nom de Dar’Khan Drathir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9162,'Ces informations sont très précieuses, $N. Nous avions tous entendu parler du plan de Dar’Khan pour voler la puissance du puits de soleil pour le Fléau, mais nombre des choses relatées là-dedans nous sont complètement inconnues. Ce livre va intéresser le magistère Kaendris au sanctum du Soleil.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9163,'C’est très troublant ! Ces plans montrent des troupes des elfes de la nuit à An’daroth, ce que nous savions déjà, mais aussi à An’owyn, un nexus tellurique plus éloigné vers le sud-est.$b$bIl y a un troisième nexus à l’est qui n’est pas mentionné. Son nom est An’talas. Tout cela ne me dit rien qui vaille, $c.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9164,'Excellent travail, $N. Sans votre aide, ces prisonniers auraient perdu leur âme et leur raison au contact du Fléau.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9167,'Vous avez porté un coup décisif à la mainmise du Fléau sur la région.$B$BMaintenant que cet ignoble traître est mort, ce n’est plus qu’une question de temps avant que nous ne retrouvions nos terres et notre grandeur passée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9170,'Les armées de Dar’Khan vont bientôt succomber. Le Fléau n’a plus la moindre chance face à la puissance combinée des sin’dorei et des Réprouvés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9172,'Ce livre… ce n’est pas possible ! C’est l’écriture de Dar’Khan en personne. Il doit contenir des informations qui nous révèleront le point faible de nos adversaires.$B$BVous avez eu raison de venir nous voir, $N. Les pérégrins ont fait preuve de beaucoup de sagesse en nous laissant le soin de régler ce problème. Cette armure devrait vous aider à servir notre cause.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9173,'Je suis sûr que dame Sylvanas sera contente de savoir que nous progressons.$B$BPrenez cet argent pour votre peine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9174,'Vous avez vengé nos morts et brisé l’étreinte d’Aquantion sur nos âmes. Nous pouvons enfin trouver la paix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9176,'Les rumeurs disaient vrai ! La pierre de lumière et la pierre de flammes existent vraiment ! Nous utiliserons leur puissance pour forger des armes contre Dar\'Khan.$B$BUtilisez-les quand le moment sera venu, et les énergies du puits de soleil, enfermées dans ces objets, le vaincront avec la puissance même qu\'il cherchait à nous voler !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9178,'Ouaip, ça sera bien utile pour les armes de choc de l\'infanterie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9180,'<Sylvanas vous arrache le collier des mains.>$B$BC\'est impossible ! Après tout ce temps, je pensais l\'avoir perdu pour toujours.$B$B<Après un long silence, la Dame semble reprendre conscience de ce qui l\'entoure.>$B$BAvez-vous cru que cela m\'amuserait ? Pensez-vous que je regrette le temps où je n\'étais pas la reine des Réprouvés ? Tout comme vous, il ne signifie rien pour moi. Alleria Coursevent n\'est qu\'un souvenir disparu depuis longtemps.$B$B<Elle laisse tomber l\'amulette au sol.>$B$BVous pouvez à présent vous retirer de ma vue, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9185,'Les renforts d\'armure robustes ont de nombreux usages, $N. On peut en faire AUTRE CHOSE que les mettre sur certaines pièces d\'armure pour qu\'elles protègent mieux. Celui-là, par exemple, je vais m\'en faire un couvre-théière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9186,'Croyez-le ou non, ces ceintures sont encore plus dingues que les bandeaux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9187,'Les druides vont sans aucun doute apprécier l\'habileté et le talent qui ont été consacrés à confectionner ces pantalons. Tous nos remerciements, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9192,'Vous avez réussi à faire une belle boucherie, $C. Nous allons pouvoir remettre les mineurs au travail. Ils seront sûrement déçus de la fin de la pause, mais nous devons produire plus d’armes et d’armures, et pour cela il nous faut du minerai.$B$BTenez, prenez ça en récompense pour avoir fait votre devoir. Allez faire réparer votre armure et vos armes, et buvez un coup à ma santé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9193,'Écœurant, mais indispensable, je vous l’assure. Vous nous avez rendu service en enquêtant, $C. Tenez, prenez ceci, pour marquer à la fois notre reconnaissance et notre générosité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9195,'Maintenant nous sommes sur la même longueur d\'onde, $C. Des trucs qui font BOUM !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9196,'Ils ont dû couter un joli paquet à fabriquer. J\'ai raison ou j\'ai raison, $N ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9198,'Des tubes en thorium ? Ça alors, merci.$B$B<Le maître-fourrier Stonebruiser lance le lot de tubes en thorium sur un grand tas de bric-à-brac divers.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9199,'Des prêtres trolls qui animent des momies... habile ! Les trolls Ombrepins essayent de faire grossir leurs rangs par la nécromancie. Je parie que ces oracles utilisaient les jujus dans leurs rituels de réanimation.$B$BUne fois de plus vous avez rempli votre mission avec la classe d’un $C en route pour la gloire. Prenez ceci, avec notre gratitude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9200,'L\'utilité de ces potions est évidente.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9209,'La magie dérisoire de ces enchantements stimule ma colère, et la colère me donne de la force.$B$BApportez-m’en encore et vous recevrez une autre Garde sauvage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9211,'<Mataus empoche l\'or.>$B$BBonne chance pour vos coûts de réparation, $R. Naxxramas est parfois "désobligeante" avec les profanes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9212,'En parvenant à la sortir de là vivant, vous avez démontré aujourd’hui que vous êtes de l’étoffe dont on fait un $C vraiment héroïque. Je suppose que nous allons également devoir lancer une offensive pour nettoyer ces catacombes. Comme si les trolls vivants ne nous causaient pas déjà assez d’ennuis !$B$BVous avez accompli un haut fait aujourd’hui, et je me dois de vous récompenser. Faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9214,'Je vais immédiatement envoyer quelques forestiers pour estimer les dégâts que vous avez causés aux trolls Ombrepins. Si ces armes sont la marque de votre réussite, je ne doute pas que nous pourrons finir le ménage rapidement après votre offensive et lancer bientôt une attaque contre le Fléau.$B$BTenez, prenez cet argent en paiement de vos services, sinon il risque de faire un trou au fond de ma bourse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9216,'Prenez ce breuvage, $N. Après l’avoir bu, votre force physique contre le Fléau sera largement augmentée. Si vous voulez avoir plus que cet échantillon, apportez-moi d’autres cœurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9217,'Ceci vous fournira plus de puissance contre le Fléau. Apportez-moi d’autre cœurs si vous en trouvez, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9220,'Le Fléau a senti notre courroux, $N. Dans peu de temps, cette citadelle maudite ne sera plus qu’une ruine.$B$BMaintenant qu\'ils sont affaiblis, il est temps de lancer une attaque sur nos objectifs stratégiques.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9229,'C\'est son anneau ! Mais il est détruit. Vous n\'avez pas trouvé d\'autres traces de son passage ?$B$BCela n\'augure rien de bon pour Ramaladni. En ce qui concerne l\'anneau, par contre... il est peut-être récupérable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9233,'Il devrait vraiment avoir complètement perdu la tête lorsqu\'il a écrit ça. Omarion et moi étions comme les deux doigts de la main !$B$BQuoi qu\'il en soit, cela ouvre quelques possibilités intéressantes, $N. Je vais pouvoir fabriquer de nouveaux objets – à prix coûtant plus une modeste rétribution, bien sûr.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9252,'Mille mercis, $N. Notre travail est ingrat, mais grâce à vous, il sera un peu plus facile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9253,'Vous devez venir de la part de quelqu’un de Brise-clémente. Je savais que c\'était juste une question de temps avant qu\'on vienne m\'aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9254,'C\'est si gentil de la part de mon ancien mentor de prendre de mes nouvelles. Dommage qu\'elle ait perdu foi en mes recherches il y a longtemps déjà.$B$BNe perdez pas votre temps à essayer de me faire revenir à ses côtés. Aidez-moi dans mes recherches ou bien partez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9255,'Ces notes... sont choquantes. Si elles sont correctes, cela veut dire que les dégâts subis par la terre de la Malebrèche sont irréversibles.$B$BJe vais immédiatement notifier le grand magistère. Voilà une raison de plus de nous échapper de ce monde et de retrouver notre véritable destin dans l\'Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9256,'Merci d’être venu, $N. La situation est bien pire que nous ne le pensions. Les Déshérités se sont emparés de la totalité du mouillage des Voiles du soleil.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9258,'Ah, c’est mon frère qui vous envoie. Justement, il me fallait quelqu\'un pour m\'aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9274,'J’apprécie votre aide, $N. Cela me fait de la peine de voir les esprits de mes ancêtres en si piteux état. Puissent-ils enfin obtenir le repos qu’ils méritent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9276,'Bien, très bien ! Vous avez parfaitement accompli votre tâche ! Maintenant, voyons si vous êtes d’attaque pour quelque chose d’un peu plus difficile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9277,'Incroyable ! Vous devriez vraiment demander au capitaine de vous engager dans les Pérégrins.$B$BTrès bien, $N, vous nous avez donné un peu d’air pour nous permettre de continuer à accroître nos forces. En fait, vu votre rapport on dirait même qu’il n’y a quasiment plus de trolls ! Peut-être allons-nous pouvoir faire directement la jonction avec Tranquillien et attaquer Mortholme ?$B$BJe crois que vous avez bien mérité un petit quelque chose. Faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9281,'Merci de m’avoir donné un coup de main, $N. L’idée de m’aventurer dans les bois aussi près de Mortholme ne me tentait guère.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9282,'C’est Kaendris qui vous envoie ? J’ai peut-être du travail pour vous, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9287,'Je suis enchanté que vous ayez pris l\'initiative de venir me voir. Dans le passé, j\'ai été responsable de l\'entraînement des jeunes paladins qui entraient dans notre ordre. C\'est un devoir et un privilège que je reprends aujourd\'hui avec humilité. On m\'a parlé de vous comme de quelqu\'un qui cherche à faire le bien au nom de la Lumière. Ce serait un honneur pour moi de vous guider dans vos premiers pas en tant que $C.$B$BÊtes-vous prêt à commencer ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9288,'Je suis heureuse que vous soyez venu me voir. Cela fait maintenant bien longtemps que je suis responsable de l\'entraînement des jeunes chasseurs, et c\'est une responsabilité que je souhaite poursuivre dans ce nouveau monde. Vous avez attiré mon attention depuis quelque temps, et ce serait un honneur pour moi de vous apprendre la voie du $C.$B$BÊtes-vous prêt à commencer ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9290,'Je suis très satisfaite de constater que vous recherchez la connaissance. Nous avons beaucoup à faire si nous voulons affûter vos capacités magiques.$B$BVoilà plus de cent ans que j\'enseigne la magie des arcanes, du feu et du givre, et je sens que leurs énergies sont aussi puissantes sur ce monde. Voulez-vous que je vous transmette une part de ce que je sais ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9293,'Ils devraient faire l’affaire. Merci, $c !$B$BPendant votre équipée, je suis parvenue à rassembler un peu de matériel pour analyser les échantillons. Ça ne devrait prendre qu’un petit moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9294,'D’après ce que vous me décrivez, le produit neutralisant a bien fonctionné ! Ce que j’aimerais savoir, c’est combien de temps il restera efficace. Nous devons vraiment enlever ce cristal de puissance du lac.$B$BMerci, $N ! Je vais dire à Tedon d\'essayer immédiatement le produit neutralisant sur l\'une des bêtes capturées.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9305,'Laissez-moi jeter un coup d’œil là-dessus.$B$BOui, je crois que ça devrait très bien faire l’affaire. Beau travail, $N ! L\'émetteur est un appareil complexe et les réparations vont prendre quelque temps. Lorsqu’elles seront terminées, je vous préviendrai.$B$BEn attendant, vous pourriez aller voir si le redresseur de torts Aldar a une tâche à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9309,'Aidez-moi… elfes de sang... Ils m\'ont... embuscade... tiendrai pas... longtemps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9311,'Je vous remercie de vous être occupé de cette géomètre elfe de sang. Elle était certainement leur chef. Soyez tranquille, nous allons nous occuper de tous ceux qui pourraient encore traîner aux alentours.$B$BJe vous en prie, prenez une de ces armes en gage de ma gratitude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9313,'Ah, ça fait plaisir de vous revoir ! Heureusement que nous avons tous deux réussis à réparer nos émetteurs, sinon nous ne nous serions jamais trouvés. Et ne vous inquiétez pas, nous allons veiller à ce que ceux du val d’Ammen reçoivent aide et approvisionnement.$B$BÀ propos d’aide, maintenant que vous êtes là, faites le tour et présentez-vous aux autres. Vous verrez qu’il y a beaucoup à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9314,'Oh, vous devez être l\'un des survivants dont nous avons entendu parler !$B$BJe suis heureuse que vous soyez venu. Ne vous inquiétez pas, nous allons envoyer quelqu\'un soigner la jambe blessée d\'Aeun.$B$BIl faudra me raconter toutes vos histoires de survie les plus poignantes ! Vous avez bien du courage d\'être venu jusqu\'ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9322,'Votre esprit brille de la chaleur des feux de Kalimdor, ami. Cette chaleur n\'est-elle pas revigorante ?$B$BLorsque cet effet s\'estompera, voilà qui pourra peut-être raviver cette sensation.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9323,'Ah, vous revoilà. Un peu plus fatigué, un peu plus poussiéreux, mais illuminé ! La chaleur nous atteint tous en cette saison et nous unit ; vous luisez de la puissance des feux que vous avez approchés.$B$BC\'est vrai que de nos jours, l\'illumination est considérée comme une piètre récompense pour avoir accompli une tâche. Prenez ceci, et allez vous amuser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9324,'Qu\'est-ce que c\'est ? Sauf erreur de ma part, cette flamme a été prise au cœur même d\'Orgrimmar ! Sa chaleur ardente reflète la férocité des cœurs des orcs et des trolls. Quel bel ajout à notre collection, et quelle bravoure de votre part : pénétrer dans l\'antre de l\'ennemi pour prendre la flamme sacrée !$B$BJe me demande quel pouvoir se cache dans les autres villes...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9325,'À moins que je ne me trompe, ce feu provient des falaises des Pitons du Tonnerre ! Comme le pouvoir des esprits y résonne ! Vous êtes une sacrée voleuse, $N. Prenez ceci en paiement de votre habileté. Si seulement nous avions les flammes des quatre villes...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9326,'Hm... que ce feu est étrange ! Il couve, presque étouffé, mais sa chaleur est intense. Et vous l\'avez obtenu à Fossoyeuse, vous dites ? C\'est fascinant. Avec les flammes des quatre villes, qui sait ce que nous pourrions accomplir ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9328,'Je n’espérais pas revoir ce visage de sitôt.$b$bC’est une excellente nouvelle, $N. Excellente à une multitude de niveaux, dont beaucoup vous échappent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9329,'Nous autres Réprouvés sommes ici pour nous occuper d’un ennemi que nous partageons avec les elfes de sang : Dar’Khan ! Il est revenu et commande maintenant l’armée du Fléau qui envahit ces terres depuis sa forteresse de Mortholme, au sud.$B$BDame Sylvanas, qui est originaire de cette région et était elle-même une elfe, partage une partie de son histoire avec Dar’Khan, et elle veut sa mort !$B$BNous allons l’abattre, $C, et vous allez nous y aider !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9330,'Et ce feu qui brille si vivement... Vous dites qu\'il provient de Hurlevent ? Remarquable ! Voilà qui a dû être une sacrée aventure ! Je vais vous payer, évidemment. Si vous trouvez quoi que ce soit de semblable, surtout revenez me parler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9331,'Cette chaleureuse flamme provient sûrement des halls de Forgefer ; elle est aussi robuste que les nains eux-mêmes. Une belle prise, $N. Si seulement j\'avais le feu des autres villes... ah, ça ne fait rien. Voici votre paiement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9340,'Bon travail, $N. Voilà qui devrait apprendre aux écorche-rocs à garder leurs distances avec nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9345,'Cela fera l’affaire. Je vais préparer le baume et terminer mon attelle avant de rentrer à Thrallmar. Pourquoi ai-je comme une vague idée de ce que la prophétesse Regulkut va dire lorsqu’elle me verra ?$B$B<Grelag soupire sans grande conviction.>$B$BMerci de votre aide, $N. Il me reste quelques feuilles d’atric. Si vous les voulez, prenez-les donc. Qui sait quand elles pourront s’avérer utiles ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9349,'Pour faire de la bonne cuisine, il faut de bons ingrédients, et ces œufs ont l’air excellents !$B$BJe viens de finir de nettoyer ma poêle à frire. Si vous voulez vous joindre à moi, vous êtes le bienvenu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9351,'C’est parfait ! En fait, je pense que ça va tellement bien marcher que je vais devoir redessiner le moteur pour qu’il tire parti de toute cette puissance supplémentaire. Si… pardon, quand nous serons tirés d’affaire, je montrerai mes plans à tout le monde dans la Zone 52 !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9352,'Des elfes de la nuit ? Ici ? Les rats !$B$BPensez-vous qu’ils pourraient avoir un rapport avec la panne de mon sanctum ? Si vous avez des informations, transmettez-les tout de suite au capitaine Signesol !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9355,'Bon boulot, $N. Mais ne crions pas victoire trop tôt, je pense que nous n’avons pas fini d’entendre parler de ces vers. S’ils ressortent leurs vilaines têtes dans la région, les Fils seront prêts à les recevoir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9356,'Des œufs de ravageur. Bam !$B$BDu bacon de sanglier infernal. Bam !$B$BDes ailes de busard. Bam ! Bam !$B$BQuel bon repas. Vous devriez vraiment essayer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9358,'Vous venez nous aider ? Pourquoi ne pas l’avoir dit plus tôt ? Nous avons toujours besoin de bras !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9359,'Vous venez nous aider ? Excellent !$B$BLa bataille contre les trolls Amani nous a coûté cher, et les combattants aguerris dans votre genre sont toujours les bienvenus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9360,'Les trolls nous maintiennent ici pendant qu’ils se préparent à attaquer le village de Brise-clémente. Nous ne nous y attendions pas du tout.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9361,'Hmmm.$B$BBon, ça a l’air mangeable, quand on y aura mis assez d’épices. Ne dites pas à Brailleur d’où vient son petit déjeuner, d’accord ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9363,'Ces informations sont d’une importance capitale, $N. Maintenant que nous connaissons les plans des trolls, nous pouvons nous préparer à leur attaque.$B$BIls ne nous prendront pas au dépourvu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9366,'Ces échantillons contiennent une énergie gigantesque, $N. Maintenant, il faut veiller à ce nous ayons continuellement accès à du gangresang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9369,'Il est regrettable de devoir tuer des créatures innocentes pour que nous puissions vivre. Le massacre aveugle n’est pas une pratique draeneï. Toutefois, tout ce sang va nous permettre de recharger nos cristaux de soin. Ces créatures ne seront donc pas morts en vain.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9370,'Cela apprendra à ces fanatiques à s\'occuper de leurs propres affaires.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9371,'Oh, heureusement que vous êtes là ! Nous avons beaucoup à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9372,'Bon travail, $N. Ces échantillons de sang serviront mes recherches et permettront à l’expédition de mieux comprendre les créatures de l’Outreterre.$B$BSi je pouvais déterminer ce qui cause ces changements incessants chez ces créatures, je pourrais peut-être préparer un antidote.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9373,'Merci de me l’avoir remis, $C. Je me demandais pourquoi je n’avais plus de nouvelles de l’expédition depuis un long moment. Je me demande ce qui est arrivé au porteur de ce message… et quand cela s’est produit.$B$BTenez, voilà un peu d’argent pour votre peine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9374,'Le journal de mon mari… Il n’y est pas du tout question de ses recherches !$B$BQuelle idiote je fais ! « Les propriétés magiques des gelées imprégnées de gangresang »… Il m’a bien eue !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9375,'<Taleris appelle plusieurs elfes de sang de l’avant-poste.>$B$BAmenez-la à l’intérieur et occupez-vous de ses blessures !$B$B<Taleris se retourne vers vous.>$B$BElle a de la chance que vous l’ayez trouvée, $C. Je ne crois pas qu’elle aurait survécu beaucoup plus longtemps à l’extérieur.$B$BAvez-vous compris ce qu’elle racontait ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9376,'Merci de l’avoir retrouvé, $N. Je ne sais pas quelle signification il peut avoir pour notre patiente, mais elle refusait de nous laisser la soigner tant que nous ne le lui rendions pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9381,'Elles devraient faire l’affaire. Je craignais que les forestiers ne se retrouvent à court de flèches pendant un moment, et c\'est déjà un souci de moins. Merci de votre aide, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9383,'Vous avez fait du beau travail, $N. On dirait que le cristal de confinement tient le coup pour le moment, mais nul ne sait combien de temps il durera. Nous garderons un œil dessus et préparerons plus de cristaux pendant ce temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9385,'Bon boulot, $N. Voilà qui devrait apprendre à ces bestioles qui est le chef ici !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9387,'Vous avez été d\'une grande aide, $N. Voyons maintenant ce que nous pouvons apprendre de notre ami bleu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9388,'Ahhh, ainsi, ils brûlent encore. C\'est bien. Ils ne doivent pas s\'éteindre avant leur temps. Vous avez bien agi, $N. Prenez ceci, avec ma bénédiction.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9389,'Vous voilà de retour, et vous avez contemplé toutes les flammes d\'émeraude de ce continent. Qu\'en pensez-vous ? N\'est-ce pas un spectacle fascinant ? Mais j\'ai bien conscience que vous appréciez davantage les récompenses tangibles… Tenez, prenez ceci pour votre peine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9391,'Même si elle reste un endroit dangereux, la Grande fissure sera un chemin bien pratique pour nos pèlerins.$b$bAvec l’Alliance qui surveille ce qui entre et sort du Guet de l’épervier sur toutes les routes, c’est d’actes désespérés comme celui-ci dont nous avons besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9392,'J’ai entendu votre nom murmuré dans les recoins obscurs, $N. On raconte que vous cherchez quelqu’un d’expérimenté pour vous montrer les ficelles du métier... quelqu’un comme moi. Je peux le faire, mais cela vous coutera une petite part de vos gains chaque fois que j’aurai quelque chose à vous apprendre. Et effectivement vous apprendrez ce que signifie être un $c.$b$bMais rappelez-vous que si jamais vous êtes pris la main dans le sac, cette discussion n’a jamais eu lieu. Maintenant filez et montrez-moi de quel bois vous êtes fait.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9393,'$N, vos yeux sont-ils aussi perçants que ceux d’un faucon, vos gestes aussi déliés que ceux d’un singe ? Êtes-vous capable de courir aussi vite qu’un guépard ? C’est mon cas, et ce pourrait aussi être le vôtre si vous recevez la formation adéquate. La voie du chasseur passe par la maîtrise des bêtes de ce monde, par une précision inégalée au tir et par la capacité à survivre aux situations qui seraient mortelles pour les autres.$B$BSi ce sont bien les choses que vous souhaitez apprendre, alors je vous entraînerai... pour une somme modique, bien sûr. Quand commençons-nous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9394,'Qui êtes-vous ? De toute évidence, vous n’êtes pas l’un des apprentis du magistère !$B$BIls vous ont envoyé là pour m’aider à nettoyer ce gâchis, j’imagine ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9395,'Ah, c’est bien aimable à la magistrice Aube-glorieuse de condescendre à répondre enfin à mes demandes. Je devrais toucher un mot de son attitude au seigneur régent, à Lune-d’argent. Elle est d’une impolitesse !$B$BMais bon, vous n’avez pas à vous en préoccuper. Maintenant que vous êtes là, vais-je enfin pouvoir récupérer les fournitures que je réclame à cor et à cri ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9396,'C’est du bon travail, $N. Les secrets de l’Outreterre ne nous échapperont plus très longtemps.$b$bNotre destin est de devenir les maîtres de ce monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9397,'Vous y êtes arrivé ! Vous avez capturé une jeune femelle !$B$BElle est inestimable. Je vous suis redevable, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9398,'Vous avez bien fait, $N. Il est toujours malheureux d’être contraint de prendre une vie, même celle d’une bête vicieuse comme un écorche-roc.$B$BJe vous remercie d’avoir accompli cette triste tâche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9399,'Vous avez réussi ! Je suis votre débiteur, $N. Regardez le nombre des Crapuches qui nous rejoignent.$B$BSous ma direction, ils apprendront tout des voies anciennes, vous verrez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9400,'Le cadavre correspond à la description de Krun Brise-échine, l’assassin de la citadelle des Flammes infernales. Lorsque vous le retournez, vous vous apercevez qu\'il a une hache de pierre plantée dans le dos.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9401,'Il a été tué par cette arme ? Ce n’est pas possible !$B$BEst-ce que… nous les aurions trouvés ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9405,'Je comprends la requête de Nazgrel, $C. N\'en dites pas plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9406,'Vous êtes sûr ? De véritables orcs... ici dans les Flammes infernales ! C\'est une nouvelle très importante, $N.$b$bNous devons avertir le chef de guerre immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9407,'Notre Expédition a réussi à traverser la Porte et à implanter une base appelée Thrallmar. Mais comme vous pouvez le voir, la Légion ardente s\'est avancée et nous a séparés de nos frères. Il est clair que les démons espèrent reprendre la Porte des ténèbres pour nous empêcher de faire venir des renforts d\'Azeroth.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9409,'Beau travail ! Cela fera bien l\'affaire pour recharger nos cristaux de soins épuisés.$B$BTant que vous êtes là, puis-je vous demander un autre service, si vous voulez bien ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9410,'Qui croyez-vous être pour entrer ici sans vous faire annoncer ? J’ai demandé à mes gens de retenir leurs bras uniquement parce que Ryga a senti que les esprits marchent avec vous.$B$BParlez librement, mais choisissez bien vos mots. Nous faisons rarement confiance aux étrangers, si près de la citadelle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9417,'Bon boulot, $N ! Désormais, vous êtes un Barbe-longue honoraire.$B$BRestez donc un moment et prenez un verre avec nous, d’accord ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9418,'Grâce à cet orbe, je vais regagner ma liberté. Prenez votre récompense, mortel et nous serons quittes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9423,'Sedaï, mon frère chéri…$B$BCes orcs lâches ! Il n\'était pas armé. Comment ont-ils pu ?$B$BLaissez-moi, $N. Je vous remercie de votre aide, mais j\'ai besoin de me recueillir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9424,'Oui… la vengeance ! C’est bien.$B$BPrenez ceci. C’était un cadeau de Sedaï. Le voir rend Makuru triste, maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9427,'L’essence d’Aggonar survivait sous la forme de son vil rejeton Aggonis. Maintenant que vous avez vaincu le démon, nous pouvons entreprendre de rendre leur ancienne pureté à ces bassins.$B$BNous vous remercions, $N. Vos actions auront un grand effet sur ce monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9428,'Je vous attendais. L’ambassadeur m’a fait savoir que vous étiez en route.$b$bNotre objectif est simplement de consolider nos relations avec le reste de la Horde. Faites tout ce que vous pouvez pour aider les habitants du coin.$b$bDemandez autour de vous – il y a des gens qui ont besoin d’aide en d’autres endroits du poste. Et j’ai entendu dire qu’il existait un autre avant-poste de la Horde loin à l’ouest, sur la côte – un endroit appelé l’avant-poste de Zoram’gar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9429,'Salutations, $C. J’espère que votre voyage s’est bien passé ?$B$BCes pauvres gens sont assiégés de toutes parts par des créatures de la nuit. Nous voulons les aider à chasser les ténèbres, dans la mesure de nos moyens.$B$BVisitez la ville, parlez à ses habitants. S’il vous plaît, $N, aidez-les de votre mieux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9430,'Vous avez beaucoup de chance. Comme je l\'espérais, l’une de ces reliques est très particulière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9431,'Comment ? Elle ne vous a pas parlé du puits de lune ? C’est pourtant ce qu’elle a en tête depuis le début. Entre nous, son plan est un peu loufoque, mais je ne vais pas dire non à une cliente. Surtout quand c’est ma seule cliente.$B$BBon, s’introduire dans un camp des elfes de la nuit pour voler l’eau du puits de lune n’est pas exactement l’entreprise la plus prudente dans laquelle je me sois lancé… Mais son or est aussi bon que celui de n’importe qui !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9432,'C’est toujours agréable de voir un visage vaguement familier. Vous devez être $N. L’émissaire Valustraa m’a fait savoir que vous étiez en route.$B$BLes habitants d’Orneval ont besoin de votre aide, $C. Parlez aux citoyens d\'Astranaar et voyez en quoi vous pouvez les aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9433,'Ça s’est mieux passé que je ne m’y attendais ! Un autre triomphe pour la bonne vieille ingéniosité gobeline !$B$BLe seul problème, c\'est qu’il est couvert de poussière. Il va me falloir une éternité pour le nettoyer et le ranger dans sa caisse.$B$BMais bon, je ne peux pas dire que je suis pressé par le temps…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9434,'Excellent, on dirait bien que tout est là. Maintenant, je n’ai plus qu’à tout mélanger et à faire un essai. Si mon tonique fonctionne comme mes recherches le prédisent, j’ai peut-être découvert un moyen d’atténuer la dépendance à la magie de mon peuple.$B$BVous allez voir l’histoire en marche, $N. Et sans vous, rien n’aurait été possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9435,'Louée soit la Lumière ! À en juger par le ton de la lettre du contremaître, on dirait que les cristaux de cette boîte sont les seuls échantillons de la mine. Si nous les avions perdus, nous n’en aurions peut-être jamais trouvés de semblables, $N.$B$BVotre aide a été plus précieuse que je ne saurais le dire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9436,'Bien joué. Voilà qui est curieux…$B$BCe totem porte une inscription dans une langue que les trolls n’ont pas l’ombre d’une chance de maîtriser, mais qui nous est familière. À l’en croire, son porteur est l’allié d’un élémentaire d’eau nommé Naïas, et est digne de canaliser son pouvoir.$B$BC’est inattendu, mais ce n’est pas forcément une mauvaise chose, $N. Si vous acceptez de m’aider, j’aimerais bien en savoir plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9438,'<La mâchoire de Thrall se relâche à mesure qu’il commence à lire le message de Nazgrel.>$b$bMon peuple... nous devons les retrouver. Nous devons atteindre Nagrand le plus vite possible !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9440,'Oh, excellent ! J’attends avec impatience de pouvoir mesurer les effets de cette fournée !$B$BBien, trésor, vous avez fait un boulot admirable. J’aimerais pouvoir vous donner plus – le spectacle valait davantage, mais vous savez ce que c’est, c’est dur de se faire de l’argent dans les marais.$B$BMais entre nous, ça valait le coup rien que pour l’amusement, pas vrai ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9441,'Votre présence ici à l’heure du péril signifie beaucoup pour nous. Nous ne vous oublierons pas, et nous n’oublierons pas celui qui vous a envoyé.$B$BNotre gratitude vous est acquise.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9442,'Gorkan disait du bien de vous. On dirait bien qu’il avait raison.$b$bMerci de votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9444,'Il me pardonne ?! Il me PARDONNE ?!!!!$B$BJe me fiche complètement de ce que raconte le fantôme de ce vieillard ! C’est entièrement de sa faute ! Tout ce qui s’est passé à Quel’Thalas est le résultat de son incompétence !$B$BIl est clair que la profanation n’a pas fonctionné. Hors de ma vue ! Je dois réfléchir à tout cela.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9447,'Que les esprits vous bénissent, $N. Les Mag\'har sont vos débiteurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9448,'C’est donc fait. Je vous remercie d’avoir fait preuve de compassion. Une fois qu\'ils ont été corrompus par ce que leur donnait Cersei, nous ne pouvions plus rien faire pour eux.$B$BIls sont maintenant en paix, et on peut espérer que mes expériences sur les autres portent leurs fruits. Nous pourrons peut-être les guérir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9452,'J’espère que les murlocs ne vous ont pas causé trop d’ennuis, $N. Ma gratitude vous est acquise pour tout ce que vous avez fait.$B$BJe pourrais peut-être vous apprendre à pêcher ? Je peux même vous fournir une canne à pêche et un peu de verroterie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9453,'Pauvre Diktynna… ce murloc lui a fait drôlement peur.$B$B<Actéon soupire.>$B$BEspérons qu’elle se remette bientôt de ses blessures…$B$BJe suppose que vous cherchez du travail. Vous n’en manquerez pas au Guet d’azur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9454,'Bon travail, $N, bon travail !$B$BTenez, j\'ai cuisiné quelques filets pendant votre absence. Peut-être que vous voudrez aussi la recette ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9455,'Comment cette chose a-t-elle pu finir dans l’estomac d’un traquenuit ? Les débris de l’accident ont-ils pu contaminer d’autres bêtes ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9456,'J\'espère juste qu\'il n\'est pas trop tard…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9457,'Je sens la puissance brute contenue dans cette gemme, $N. Je vais l’envoyer à Lune-d’argent pour que nos magistères l’étudient plus avant, mais je suis sûr qu’il nous aidera dans notre lutte contre les Amani.$b$bSans vous, nous n’aurions pas pu nous la procurer, et je veillerai à ce que les pérégrins connaissent le nom de la personne à qui nous devons cette trouvaille, $r.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9461,'Salutations, $N. Je vous attendais. J\'espère que cette journée vous sourit ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9462,'Juste au bon moment, $N. J\'espère que vous êtes prêt à poursuivre votre formation. La prochaine tâche sera difficile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9463,'Espérons que cette pommade donnera de la force à son esprit !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9464,'Le feu que je vois briller dans vos yeux vient-il de votre désir de progresser et de mieux comprendre le monde ? Bien !$b$bTuluun vous a envoyé ici parce qu\'il croit en vos capacités à apprendre et à contribuer à la résolution d\'un problème causé par l\'accident de votre Exodar.$b$bNous verrons bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9465,'Voyez-vous comme ce feu ne s\'éteint jamais ? C\'est l\'œuvre d\'Arrogance. Il est le symbole de son orgueil. Les flammes sont destinées à consommer leur combustible, puis à s\'éteindre pour renaître plus tard.$B$BJe vous aurais aidé à éteindre la torche, mais elle doit rester allumée pour vous permettre de vous occuper d\'Arrogance. Nous allons devoir la laisser brûler encore un peu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9466,'Vous êtes un courageux $C, $N. Cette bête féroce a pris la vie de nombre de mes meilleurs chasseurs.$B$BAcceptez cette récompense, vous l\'avez bien méritée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9467,'Vous avez appris une leçon importante aujourd\'hui. C\'est l\'histoire de la fin et d\'un nouveau commencement.$B$BLorsque nous avons parlé pour la première fois, je vous ai dit que le feu n\'était pas uniquement la destruction, mais aussi une force de renouveau pour les éléments. À travers vos actes, vous avez à la fois détruit et sauvé Arrogance, car il renaîtra de ses cendres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9468,'Vous avez traversé le feu purificateur de la destruction et en êtes sorti régénéré, $N. Ce n\'est pas si différent de ce que les $R sont en train de vivre. Et en sauvant Arrogance de lui-même, vous avez assuré votre connexion au feu élémentaire de ce monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9469,'Le journal de Barbe-de-plumes semble contenir un grand nombre de notes récentes. En feuilletant les dernières pages, vous commencez à chercher des indices sur l’endroit où il a pu se rendre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9470,'Bien joué, $N. Les Marteaux-hardis seront heureux de savoir qu\'ils ne sont pas seuls face aux trolls Fânécorces. Si nous leur montrons que l\'Alliance est un partenaire fiable qui peut les aider à protéger les griffons, notre proposition aura plus de poids.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9471,'<L\'ambassadeur Rualeth hoche la tête pendant que vous faites votre rapport.>$B$BTrès bien. L\'élimination des Crins-d\'argent ne manquera pas d\'être remarquée par les Marteaux-hardis. Lorsque je rencontrerai leurs chefs, je suis certain que vos actes contribueront à la bonne réputation de l\'Alliance. Veuillez accepter cette pièce comme un modeste gage de ma gratitude, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9472,'Très bien ! Cette petite garce ne recommencera pas de sitôt à séduire les maris des autres.$B$BVoilà un petit quelque chose pour votre peine. J’espère que cet incident restera entre nous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9473,'Regardez la plante accomplir son miracle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9475,'<En tendant les œufs à l’ambassadeur, vous décrivez ce que vous avez découvert au taudis de Barbe-de-plumes et à Shadra’Alor.>$B$BLes Fânécorces ont tué Barbe-de-plumes ?$B$B<Rualeth a l’air horrifié par la description du destin du nain et par ses conséquences sur sa mission.>$B$BJe comprends pourquoi il est parti à la recherche des œufs, mais il aurait mieux valu qu’il ne parte pas seul. Sa mort va mettre Falstad Marteau-hardi en rage, déclencher des représailles contre les trolls… et mon audience va être reportée encore et encore.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9476,'Vous trouvez sur l’autel une pile d’ossements qui semblent avoir appartenu à un nain de sexe masculin. Il ne reste rien pour l’identifier réellement, mais vous décidez de fouiller le corps pour vous assurer qu’il s’agit bien des restes de Barbe-de-plumes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9483,'Vous savez, on pourrait devenir amis, après tout. Suivez-moi… Ce n’est pas la peine que nous partagions ceci avec les autres, n’est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9490,'Oui, je me souviens de ces griffes aiguisées !$b$bPrenez cette récompense, $N. Vous la méritez bien. Ce que vous avez fait était dangereux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9492,'Bien joué, $N. Grâce à votre victoire à la citadelle des Flammes infernales, nous avons porté un coup décisif aux orcs.$B$BJe dois conférer avec le commandant Romus pour organiser la suite et nous assurer que les orcs restent sur la défensive. Maintenant que nous avons reçu des renforts, nous pouvons faire bien plus que simplement défendre le bastion de l’Honneur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9493,'Voilà une excellente nouvelle, $N. Si nous pouvons rendre compte de progrès à la citadelle des Flammes infernales, cela nous permettra peut-être de reporter notre attention sur les manifestations de la Gangr’horde dans d’autres zones de la péninsule et dans l’ensemble de l’Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9494,'Bien joué ! Je ne peux pas espérer reproduire les exploits du Grand démoniste Néanathème, ce ne serait d’ailleurs pas très sain, mais nous serions bien bêtes de négliger la puissance des gangrebraises.$B$BIl en est pourtant qui voudraient interdire le type de recherches dont je vais à présent m’occuper, et pour cette raison je dois rester aussi discrète que possible sur mes travaux. Je vous prie de ne parler de ceci à personne, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9495,'C’est bien, $N. Dans sa jeunesse, Kargath Lamepoing était un grand guerrier, un héros et un exemple pour son peuple.$B$BSa mort nous porte un coup à tous, et le chef de guerre Thrall le ressentira durement. Quoi qu’il ait pu lui arriver dans ses derniers jours, nous ne devons pas oublier l’orc qu’il a été… et les leçons que nous devons tirer de sa chute.$B$BPour avoir servi la Horde, $N, faites votre choix parmi ces armes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9496,'Très bien, $N. Maintenant que les légionnaires sont vaincus, la Gangr’horde sera plus facile à affronter sur le champ de bataille, même si elle reste redoutable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9498,'Bienvenue au Guet de l’épervier, $R. Tous nos alliés de la Horde sont les bienvenus ici, surtout ceux qui nous sont recommandés par Martik.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9499,'Bienvenue au Guet de l’épervier, mon frère. De nombreux elfes de sang n’ont pas la chance d’arriver aussi loin.$B$BC’est fort dommage, notre tâche dans l’Outreterre ne fait que commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9501,'N’ayez pas peur, $N. Tant que vous serez ici, nous communiquerons en utilisant nos esprits.$b$bJe suis reconnaissante au long-voyant Nobundo de vous avoir fait venir. Une grande perturbation pollue les eaux de l’île de Brume-sang, tant à l’intérieur de l’île qu’aux alentours. Il faudrait être aveugle – et encore ! – pour ne pas s’apercevoir de ses effets sur les créatures qui y vivent.$b$bNous allons travailler ensemble pour mettre un terme à cette corruption avant qu’elle ne se répande.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9502,'Nous nous retrouvons donc. J\'ai observé de loin vos progrès, chaman. Je suis satisfait.$B$BIl est temps pour vous d\'apprendre à communier avec l\'eau, de découvrir ses mystères et de vous y abandonner afin d\'apprendre à la maîtriser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9504,'L\'eau est facile à écarter, mais si vous en accumulez assez, elle finit par représenter une force impossible à arrêter. Elle balaye la terre et le feu, et chasse l\'air devant elle.$B$BNous sommes cette force irrésistible, $N, pas ceux qui ont empoisonné l\'île de Brume-sang !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9505,'Vous dites que vous avez trouvé un membre de notre équipage ? Et qu’elle est blessée ? Je vais tout de suite envoyer des gens à votre village !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9506,'Vous êtes plein de ressources ! Maintenant que nous avons retrouvé notre matériel de navigation, nous allons pouvoir calculer jusqu’où nous avons dévié.$B$BAttendez une minute, qu\'est-ce que c\'est que ça ? Il y a quelque chose d\'enroulé dans la carte. Voyons voir...$B$BCe sont des ordres du nabab Razdunk de la KapitalRisk. D\'après ces plans, ils sont ici pour dépouiller l\'île des cristaux présents dans les débris, et ils comptent s\'emparer de nos navires quand ils auront fini.$B$BPar les sourcils broussailleux de Barbe-de-Bronze ! Voilà donc pourquoi ils nous ont forcés à toucher terre ! Comment ont-ils fait pour connaître nos projets ?$B$BIl y a un traître là-dessous...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9508,'C\'est terminé ! La crise est évitée, et vous avez amorcé la purification des eaux de l\'île de Brume-sang. Avec le temps, l\'eau se guérira d\'elle-même, en conjonction avec les autres éléments.$B$BIl est désolant de constater que les elfes de sang ne réalisent pas qu\'ils se tuent eux-mêmes en contaminant leur environnement !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9509,'Vous avez fait preuve d\'une sagesse très supérieure à nos espérances, $N. Je sens que l\'eau est satisfaite de vos actions. Ce sera pour moi un grand honneur que de prendre l\'eau pure que vous portez et d\'imprégner votre nouveau totem d\'eau de son essence.$B$BSi vous vous souvenez de la leçon de l\'eau lorsque vous progresserez, la compréhension et la maîtrise de cet élément viendront plus facilement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9513,'Qu’Elune soit louée ! Les esprits sans repos vont peut-être enfin trouver la paix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9514,'Je suis incapable de lire ces runes, mais je connais quelqu’un qui saurait...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9515,'Maintenant que le chef de guerre Sriss’tiz est mort, l’éventualité d’une invasion des nagas n’est plus qu’un lointain souvenir. Nous sommes en sécurité, pour le moment...$B$BJe dois admettre que j’avais tort de penser du mal de vous, $N. Vous avez prouvé que vous n’avez rien de commun avec l’immondice qu’était Archimonde. Veuillez accepter ce présent de la part de tous les elfes de la nuit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9516,'Vous avez mes remerciements et mes respects, $C. Peut-être que cette fois, nous pourrons fonder un nouveau foyer ici sans avoir à nous inquiéter de la Légion ardente.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9517,'Le bois coupé avec les lames brutes des orcs est faussé aussi sûrement que celui qu’on laisserait exposé aux éléments les plus rigoureux. Rien de durable ne peut être construit avec, mais je peux le purifier de manière à ce que l\'architecte Nemos et les siens puissent s\'en servir. Un peu de bien sortira peut-être de cette tragédie, après tout.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9518,'Enfin nous expédions un message que les orcs n’oseront pas ignorer. Et le prochain surveillant ou contremaître qui posera un pied dans ce camp verra de quel bois je me chauffe !$B$BNous devons profiter de notre avantage, $N, et ne pas relâcher nos efforts jusqu’à ce que le camp de bûcherons Chanteguerre soit devenu un lointain souvenir, et qu’un bosquet d’arbres majestueux occupe le terrain défriché.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9519,'Excellent travail, $N. Il y a certainement un pouvoir latent là-dessous, un pouvoir que même l’exposition permanente à la corruption des satyres n’a pas pu étouffer. Voyez-vous comme il brille encore, après toutes ces années ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9520,'Par les sept Cristaux d’Ata\'mal, c’est impossible ! Ils projettent de nous attaquer ici au Chant des forêts ?!$B$BPas tant que je serai là !$B$B<Le redresseur de torts Vedaar froisse dans son poing les plans des démons.>$B$BNon. Nous ne le permettrons pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9522,'La Légion ardente ne nous menacera plus jamais ici ! Vous nous avez épargné une bataille que nous aurions vraisemblablement perdue, $C.$B$BVous méritez les remerciements et la plus profonde gratitude de la Main d’Argus. Je suis honoré de pouvoir compter sur votre amitié.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9524,'Je vous remercie, $N. Je dois reconnaître que je ne m’attendais pas à l’intervention d’un groupe de sauveteurs.$B$BJe vais rassembler les autres prisonniers et les reconduire au bastion de l’Honneur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9525,'Ma journée sera meilleure grâce à vous, $C. Lorsque je mourrai, je veillerai à ce que ce soit sur le champ de bataille, couvert du sang de mes ennemis, et en les emportant avec moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9526,'Bien. À la manière dont vous comptez les années, il l faudra longtemps pour que ces boutures deviennent des anciens, mais en temps voulu, ils nous aideront dans notre lutte contre les démons de la colline Gangrefeu.$B$BAllez en paix, petit frère.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9527,'Merci, $N. Leurs esprits seront en paix, à présent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9528,'<Cowlen pleure de joie.>$B$BComment pourrais-je vous récompenser, $N ? Tenez, prenez cet objet. C’est un souvenir de famille. Il symbolise le lien sacré de l’amitié, de la confiance et de l’amour parmi les elfes de la nuit. À compter de ce jour et jusqu’à la fin des temps, vous êtes une sœur pour moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9530,'Il faut que je vous prévienne, la prochaine tâche que je souhaite vous confier est dangereuse. Mon estime pour vous ne sera nullement affectée si vous décidiez de ne pas m\'aider, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9533,'C’est toujours bon de voir de nouveaux arrivants au Chant des forêts.$B$BLe redresseur de torts Palanaar m’envoie toute l’aide qu’elle peut réunir, et chaque nouvelle paire de mains est la bienvenue.$B$BRegardez autour de vous, $C. Pour l’instant, ce n’est pas grand-chose, mais avec le temps et l’aide de nos alliés elfes de la nuit, nous y construirons un village et nous en ferons notre foyer. Il y a beaucoup à faire ici, et toute l’aide que vous pourrez nous prodiguer sera la bienvenue.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9534,'C’est mieux ! Débarrasser le monde d’un démon, il n’y a rien de tel. Et contrairement aux peuples de l’Alliance, qui sont trop faibles, ce sont des opposants dignes de ce nom.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9535,'Des seigneurs de l’effroi ! Et ils projettent de nous attaquer ici, au poste de Bois-brisé ?$B$BPas tant qu’il me restera un souffle de vie !$B$B<Valusha froisse rageusement les plans des démons.>$B$BNon. Nous ne le permettrons pas ! Ils sont la plaie de ce monde !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9537,'Incroyable ! Tout cela faisait partie de leur plan !$B$BCette information doit parvenir au roi et à vos propres dirigeants. Ce que cela implique est… stupéfiant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9538,'Le totem porte plusieurs gravures primitives. Vous reconnaissez des chouettes, des ours, des loups et des cerfs.$B$BVous remarquez une série de symboles étranges, que vous prononcez A-K-I-D-A sans en avoir vraiment conscience.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9539,'Le totem porte plusieurs gravures primitives. Vous reconnaissez des chouettes, des ours, des loups et des cerfs.$B$BVous remarquez une série de symboles étranges, que vous prononcez C-O-O sans en avoir vraiment conscience.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9540,'Le totem porte plusieurs gravures primitives. Vous reconnaissez des chouettes, des ours, des loups et des cerfs.$B$BVous remarquez une série de symboles étranges, que vous prononcez T-I-K-T-I sans en avoir vraiment conscience.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9541,'Le totem porte plusieurs gravures primitives. Vous reconnaissez des chouettes, des ours, des loups et des cerfs.$B$BVous remarquez une série de symboles étranges, que vous prononcez Y-O-R sans en avoir vraiment conscience.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9542,'Lorsque vous lisez le totem, votre bouche forme le mot V-A-R-K, et vous savez que cela veut dire « justice ».') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9543,'Puis-je vous être d’une aide quelconque, $N ? Vous semblez troublé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9545,'J’ai bon espoir que votre vision vous aura aidé à voir la mort de Sedaï autrement. La relique vous a montré une série d’événements probables menant au présent. La vérité était peut-être légèrement différente, mais nous ne le saurons jamais.$b$bAuriez-vous agi différemment en sachant ce que vous savez maintenant ?$b$bQui peut affirmer que notre conflit avec les orcs va continuer ? Il faut garder l\'esprit ouvert à toutes les possibilités.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9548,'C’est formidable ! Le vol de mon équipement m’a permis d’obtenir plus d’informations sur la nature des murlocs que je n’aurais pu en rassembler pendant des semaines d’observations !$B$BJe sais déjà ce que je vais écrire dans mon compte rendu.$B$B« Confrontés aux produits d’une culture technologiquement supérieure, les Ailerons vaseux n’ont montré aucun des signes caractéristiques de curiosité qu’on observe dans les cultures émergentes des espèces humanoïdes. »$B$BC’est génial ! Ces messieurs de Forgefer vont adorer ! Vous méritez toute ma gratitude, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9549,'Étonnant, tout simplement étonnant ! Ils sont parfaits, $N. Je les imagine déjà dans une vitrine du musée de Forgefer. Le texte de présentation est déjà en train de s’écrire tout seul dans ma tête !$B$BVotre aide a été inestimable, et m’a permis de remettre mes recherches dans le droit chemin. Comment épelez-vous votre nom ? Je m’assurerai qu’il apparaisse dans mon rapport, en tant que co-auteur.$B$BL’un des gars du vaisseau m’a donné cette « carte au trésor » pour rembourser une dette de jeu, mais la mythologie ne figure pas dans mon domaine d’expertise. Ces marins sont tellement superstitieux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9550,'Un examen attentif du livre vous permet de conclure qu’il s’agit d’un journal. Ses pages sont couvertes d’une écriture élégante, très différente de celle de la carte. Malheureusement, l’auteur de la carte a copieusement gribouillé par-dessus.$B$BLe texte original disparaît presque entièrement sous des histoires de virées à terre et de cuites mémorables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9552,'Les vents m\'ont murmuré que vous alliez arriver, $C.$B$BLe long-voyant Nobundo pense beaucoup de bien de vous, et d\'après ce que j\'ai entendu sur vos voyages, je suis du même avis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9553,'J\'attendais votre venue, $C. Vous cherchez la sagesse... et quelque chose d\'autre, à ce que je sens.$B$BTrès bien, commençons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9554,'Je suis fier de vous, $N. Vous avez persévéré là où d\'autres ont vu leur résolution vaciller, et en chemin, vous avez appris beaucoup de choses sur les éléments et sur vous-même. Souvenez-vous de leurs leçons lorsque vous avancerez sur la route de la vie, et vous deviendrez encore plus sage.$B$BMaintenant, donnez-moi la volute de Susurrus pour que je puisse en imprégner votre totem d\'air. Comme les autres totems, il vous servira de focus et vous permettra de vous souvenir du lien que vous avez formé avec les éléments.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9555,'Salutations. C\'est toujours un plaisir de rencontrer un $r qui soit réceptif à la voix du chamanisme. Il y en a si peu.$b$bVous avez appris à ne pas juger la flamme sur son apparence, tout comme vous ne devriez pas me juger sur la mienne.$b$bVous êtes ici parce que vous êtes prêt à créer votre totem de feu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9557,'Hmm… c’est très intéressant. Oui, je devrais pouvoir déchiffrer ce qui a été écrit dans ce livre.$B$BJ’ai tout ce dont j’ai besoin pour ça. Cela va quand même me prendre un moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9558,'Comment vous nous avez trouvés, $c ? Peu importe, j\'imagine que vous êtes là pour nous filer un coup de main. Alors mettons-nous au travail !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9559,'Pendant des siècles, nous avons vécu dans une paix relative avec les créatures de la région. Il y a plusieurs mois, Kurz a commencé à voir de sombres présages. La paix dont nous avions bénéficié si longtemps allait être perdue. L\'étendue de la catastrophe serait incommensurable !$B$BLes dieux allaient détruire nos terres, tournant contre nous nos amis comme nos ennemis. Mais il y avait autre chose... Au milieu du chaos, un héros s\'élèverait, un héros qui ne serait pas de sang Calmepin. Celui dont la venue nous a été promise allait nous sauver de la destruction.$B$BCe héros dont parle la prophétie, c\'était vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9560,'Non seulement la prophétie dit vrai, mais en plus cette armure est vraiment incroyable ! C\'est vraiment une armure de champion ! Et je vais vous la laisser à un prix bradé, sans-fourrure.$B$BJe plaisante... la première pièce est offerte par la maison.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9561,'L’herbe et la broussaille recouvrent une bosse qui n’a pas l’air naturelle.$B$BAprès quelques minutes passées à creuser, vous découvrez une vieille boîte, certainement celle dont il est question dans le journal de Nolkai.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9562,'Mmmmm… Bonnes céréales… Parkat va être ravi !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9565,'Une aura malsaine émane du cristal de sang. Elle se répand dans l\'eau de la caverne.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9566,'Ces cristaux de sang que vous avez vus ; mes éclaireurs en ont vus plus encore au nord.$B$BJe vous remercie pour votre aide, mais je dois à présent vous demander de me quitter afin que je puisse m\'entretenir avec les anciens. Je ferai appel à vous une fois que j\'aurai fini de parler aux autres anciens du village.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9567,'Très bien, $N. Voyons ce que ce glyphe peut m\'apprendre, afin de mettre un plan au point pour la suite.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9569,'Maintenant que nous les avons privés de leur chef et que nous avons commencé à récupérer les cristaux corrompus, nous pouvons considérer que les satyres sont neutralisés. La Lumière seule sait combien il y a de ces misérables créatures aux alentours.$B$BLe messager Mikolaas et moi vous sommes reconnaissants de votre aide. Grâce à vous, la menace que les satyres représentent ne grandira pas. La vigilance est la clé de la victoire contre la Légion et ses séides. Vos actions l’ont rappelé à tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9570,'Celui dont la venue a été promise a triomphé !$B$BLa prophétie est presque accomplie. Et maintenant, à propos de cette peau…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9571,'C’est l’armure la plus solide que j’aie jamais fabriqué ! Faites-en bon usage, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9572,'C’est un bon début. Maintenant que ces trois-là sont morts, leurs forces doivent être désorganisées. Et comme nous avons fait taire leur artillerie, nous allons avoir moins de mal à nous rapprocher pour prendre la citadelle !$B$BMais je sens qu’il y a autre chose… Je vous confierai bientôt une autre tâche.$B$BPour l’instant, je vous félicite. Choisissez ce que vous voulez dans l’armurerie de Thrallmar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9573,'C’est peut-être l’occasion que nous attendions ! Je lance une attaque immédiatement ! Les Calmepins vous remercient pour vos services, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9574,'C’est amplement suffisant pour mes recherches. Merci, $N. Si vous trouvez d’autres preuves montrant que les cristaux corrompent les créatures originaires de Brume-sang, venez me voir tout de suite.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9576,'C’est très bizarre, $C. Je ne crois pas avoir jamais vu de murlocs porter d’ornements auparavant.$B$BCompte tenu de ce que nous savons de l’influence corruptrice de ces éclats de cristal, ce murloc devait s’imaginer que le pendentif allait lui donner du pouvoir sur ses congénères. Je ne serais pas étonnée s’il était devenu plus grand et plus fort qu’eux, d’ailleurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9578,'Le cadavre est bien vêtu comme un technicien de l’Exodar, mais le pendentif décrit par Morae brille par son absence.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9579,'<Vous rapportez à Morae ce que vous avez découvert dans les débris du cryocœur.>$B$BAinsi... il est...$B$BJe suppose que je le savais déjà d\'une certaine manière, mais je refusais de le croire. J\'espérais d\'autres nouvelles, mais je vous remercie de tout mon cœur d\'avoir trouvé Galaen.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9580,'Voilà qui va regarnir nos réserves pendant un moment, et la préparer pour la consommation va bien m’occuper. Merci de votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9581,'Cet éclat de cristal vient de l’une des parties les moins corrompues de l’île. Il donnera à nos chercheurs une base de comparaison avec des échantillons récoltés dans d’autres régions.$B$BJe ne l’enverrai pas tant que je n’en aurai pas une série complète, mais c’est un excellent début. Si vous êtes prêt à nous aider à collecter d’autres échantillons, je veillerai à ce que vous soyez récompensé pour vos efforts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9584,'<Le messager Mikolaas examine l’éclat de cristal.>$B$BCe fragment diffère sensiblement de l’échantillon initial.$B$B<Le messager Mikolaas tient le cristal devant la lumière.>$B$BVous voyez ces pulsations ? Elles m’inquiètent. Je mentionnerai dans mon rapport que les elfes de sang ont altéré ce cristal. Merci encore pour votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9585,'<Le messager Mikolaas prend le dernier cristal.>$B$BIl complète la série. Il ne reste plus qu’à les empaqueter et à les expédier à l’Exodar.$B$B<Le messager a l’air soulagé d’avoir terminé le travail.>$B$BNe vous méprenez pas, $N, je suis convaincu que ces recherches sont importantes, mais nous avons de nombreux autres problèmes urgents sur les bras.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9586,'Merci d’avoir aidé Tavara. Nous sommes encore nombreux à mal connaître la région, et cette ignorance nous vaut régulièrement des ennuis imprévus.$b$bJe serais honoré que vous portiez cette robe. Elle vous désigne comme l’un des protecteurs du Guet d’azur et comme un fidèle disciple de la Lumière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9587,'Signée par Illidan, vous dites ? Montrez-moi ça.$B$B<Le commandant lit la lettre une première, puis une deuxième fois, et prend un instant pour réfléchir avant de continuer.>$B$BVoilà effectivement d\'inquiétantes nouvelles. Cela veut dire que nous allons devoir précipiter nos plans contre la citadelle des Flammes infernales et la Fournaise du sang. Vous avez fait preuve d\'efficacité, aussi est-ce à vous que je vais demander de les mener à bien.$B$BFlingot vous confiera votre prochaine mission. Attention, elle sera sans doute bien plus dangereuse que la première.$B$BQue la lumière soit avec vous, $N  !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9590,'Vos capacités m’impressionnent, $N. Vous avez pénétré dans la citadelle des Flammes infernales – pas une seule fois, deux ! – et vous avez rempli les missions qui vous étaient assignées.$B$BJe vais veiller à ce que ce sang soit livré à ceux qui pourront percer ses mystères. Qui sait, nous découvrirons peut-être un moyen d’inverser le processus ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9601,'Ahh... Il est temps...$B$B<Mehlar hoche la tête d\'un air entendu.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9602,'<L’exarque Menelaous prend la lettre et commence à la lire.>$B$BQu’ils soient damnés… damnés et jetés dans le Néant. Ils avaient un espion qui a observé tout ce que nous avons fait ! Et depuis combien de temps ?$B$BJe vais avertir Velen immédiatement !$B$BVous nous avez rendu un grand service, $N. Restez en alerte, je vous contacterai dès que le Prophète m’aura dit quoi faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9603,'Vous avez besoin de faire un tour à l’Exodar ?$B$BC’est une longue balade, mais ne vous inquiétez pas, j’ai un moyen de vous faire gagner du temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9604,'Ah, vous m’apportez la liste de Topher. Excellent ! J’espérais bien la recevoir aujourd’hui. Voyons ce dont il a besoin.$B$B<Nurguni lit la liste et commence à remplir une boîte avec divers objets.>$B$BVoilà à peu près tout ce qu’il a demandé. Les éléments des lits sont trop grands pour tenir sur un hippogriffe, mais je ferai le nécessaire pour les envoyer en chariot.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9606,'<Vous passez la caisse à Topher et lui dites que Nurguni prend des dispositions pour faire livrer les objets les plus volumineux par chariot.>$B$BFormidable ! Je vais enfin pouvoir installer quelques lits et un poste de secourisme pour faciliter le traitement des blessés et des survivants que nous retrouvons.$B$BJe ne pourrais jamais assez vous remercier, $N. Vous avez ma gratitude et celle des redresseurs de torts du Guet du sang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9607,'ILS ONT UN SEIGNEUR DES ABÎMES ?!$B$B<Le commandant remarque les coups d’œil des personnes assemblées et baisse la voix.>$B$BC’est la fin de tout. Ils doivent utiliser son sang pour créer de nouveaux gangr’orcs qui, pour une raison ou pour une autre, ne sont pas liés à la Légion ardente. Et s’ils peuvent faire ça aux orcs bruns, ils peuvent le faire aussi aux orcs verts. Pas bon du tout, surtout avec tous les orcs de la Horde qui franchissent la Porte des ténèbres.$B$BIl faut que nous les frappions au cœur, et vite !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9608,'ILS ONT UN SEIGNEUR DES ABÎMES ?!$B$B<Nazgrel remarque les coups d’œil des personnes assemblées et baisse la voix.>$B$BC’est la fin de tout. Ils doivent utiliser son sang pour créer de nouveaux gangr’orcs qui, pour une raison ou pour une autre, ne sont pas liés à la Légion ardente. Et s’ils peuvent faire ça aux orcs bruns des Mag’har, ils peuvent nous le faire !$B$BIl faut que nous les frappions au cœur, et vite !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9610,'Je vous remercie, $C. L’étude de ces artefacts devrait m’occuper pendant un moment. Si nous autres Roués et draeneï ne comprenons pas l’histoire de ce monde, comment pourrions-nous nous y adapter ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9616,'Par la tête imberbe et géométrique d’O’ros ! Heureusement que vous avez pensé à me la remettre, $N. Ces elfes de sang veulent… eh bien, du sang. Velen va être prévenu immédiatement. Prenez ceci en récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9620,'Les corps des explorateurs draeneï sont dispersés aux alentours. Ils ont visiblement été tués par des armes nagas. Leur matériel de cartographie et leurs affaires jonchent le sol, mais leurs cristaux de données ont disparu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9621,'C’est donc fait. Le vil traître a eu ce qu’il méritait.$B$BL’avez-vous fait vous-même ? Cet exploit montre que votre peuple mérite encore de vivre, $N.$B$BJe vois que Lor’themar a d’autres nouvelles, qui amélioreront beaucoup ses relations avec Thrall.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9622,'Des visions, vous dites ? Intéressant… Et cette prophétie s’est réalisée ?$B$BVous dites qu’ils ont vu la source d’énergie de l’Exodar ? Et qu’O’ros figurait dans la vision ? Qu’est-ce que cela peut bien vouloir dire ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9623,'<Torallius soupire.>$B$BTrès bien. Laissez-moi jeter un coup d’œil à ces ordres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9624,'Vous n’avez pas eu trop de mal à en trouver assez ? Cela me prend de plus en plus de temps à chaque voyage.$B$BUn de ces jours, je serai obligé de renoncer, faute de temps. Merci d’avoir récolté ces poires pour moi, $N. Cela va me donner la possibilité de faire une ou deux tartes avant la fin de la saison.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9625,'Eh ben vous vous en sortez pas mal ! L’est temps de commencer le vrai boulot avant que vous soyez trop abîmé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9627,'Grâce à vous, la cause de notre peuple a fait des progrès considérables. Thrall estime que nous sommes capables d’affronter nos ennemis. Il s’imagine aussi qu’il pourra se servir de notre lien avec l’Outreterre pour atteindre son peuple.$b$bCe n’est pas tout à fait vrai, mais ce n’est pas non plus un mensonge.$b$bNous sommes à l’aube de grands changements, $N. Nous appartenons désormais à la Horde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9628,'<Vous expliquez au messager Mikolaas ce qui est arrivé aux explorateurs. Il prend le cristal, mais reste silencieux pendant un long moment.>$B$BC’étaient de braves gens, $N, et ils savaient que la mission était dangereuse. Je vous suis reconnaissant de votre aide. Vous avez repéré l’équipe et vous avez retrouvé le cristal.$B$B$B$BNous avons déjà perdu trop d’hommes, et notre travail commence à peine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9629,'C’est du bon travail, $N. J’avais peur que la machine à marquer tombe en panne, mais on dirait que tout s’est passé comme prévu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9630,'Tant d’informations… Je pourrais passer des années ici ! Je suis sûr qu’ils comprendraient, à Dalaran…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9631,'Alturus veut relever un dragon d’entre les morts ? Quel que soit le bout par lequel on considère la question, ce ne sera pas facile.$B$BVoyons comment nous pouvons nous entraider, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9632,'Je peux vous aider à vous rendre à Auberdine. En bateau, ce n’est pas très loin !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9633,'<Thundris prend la lettre, la lit rapidement et hoche la tête.>$B$BIl y a longtemps, mon peuple a vécu sur les îles que les draeneï appellent Brume-azur et Brume-sang. Certaines des menaces que l’anachorète Paetheus et les siens ont affronté sont d’anciens ennemis des elfes de la nuit.$B$BJe suis convaincu que le peuple d’Auberdine aidera nos nouveaux alliés de son mieux. Dès que j’aurai parlé à la population et aux Sentinelles, j’enverrai une réponse à Paetheus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9634,'C’est du bon travail, $N. Il faudra garder la population des ravageurs à l’œil pendant quelque temps, mais c’est un excellent début.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9635,'Super ! Maintenant, il me faudrait une boucle en velcro, une pince à parchemin, un tube siffleur et une bonne longueur de ruban collant. Avec ça, on pourrait vraiment faire des trucs !$B$BBon bon, je pense que vous l’avez bien mérité, $N. Amusez-vous bien !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9636,'Brillant ! Entre nous, vous connaissez beaucoup d’ingénieurs qui ont assez de pièces détachées ? Ooh, je pourrais peut-être vendre les pièces surnuméraires et me payer quelques glaces à la fraise d’Aguilor et Dagharn ? J’aime tellement les fraises ! Vous pensez qu’ils en ont, dans le coin ?$B$BBon bon, d’accord, je suppose que vous avez mérité votre récompense, $N. Amusez-vous bien !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9638,'Vous ne voyez pas que je suis en plein travail ? Que voulez-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9639,'Ce journal dont vous parlez... J’ai été envoyée ici pour le chercher, c’est bien ça ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9640,'Avez-vous trouvé ce que vous cherchiez ? Vous cherchiez bien quelque chose ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9641,'Bravo. Voilà qui va me permettre de préparer une autre fournée de cristaux d’amélioration.$B$BVeuillez choisir entre les trois types de cristaux que je peux fabriquer. Chacun d’eux peut être utile, selon le type de proie que vous poursuivez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9642,'Très bien, voici les cristaux dont je dispose, $N. Utilisez-les avec discernement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9643,'Elles ont l’air assez solide pour faire l’affaire. Merci de votre aide, $N. Votre contribution à la défense du Guet du sang ne sera pas oubliée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9645,'Quel dommage que les agents que nous avions envoyés aient succombé à la magie de Karazhan. Au moins, vous avez pu obtenir ce qu\'ils cherchaient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9646,'Bien joué. D\'après ce que j\'ai entendu, cela n\'a pas dû être un combat facile. Vous avez plus que mérité votre récompense, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9647,'Plus tard, il faudra que nous mettions au point une stratégie pour faire retourner les espèces à leur état naturel. Mais pour l\'instant, nous ne pouvons espérer mieux que de réduire leur nombre de temps à autre. Merci pour votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9648,'Eh bien, je vous avais prévenu, n\'est-ce pas ? J\'espère que cet argent fera plus que compenser les petits désagréments que vous avez pu rencontrer. Revenez me voir quand vous aurez gagné en force, j\'aurai peut-être une autre tâche pour vous - des champignons à chercher, bien sûr !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9649,'J\'espère que la tâche n\'a pas été trop ardue, $N. Une fois de plus, vous avez montré que vous étiez un $R compétent et fort aimable. Je vous offre ma gratitude ainsi que cette petite compensation financière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9663,'Bien joué, $N. Cette épreuve était difficile, mais vous l\'avez passée sans aucun problème. Pour devenir un soldat de la Main d’Argus, vous devrez passer de nombreuses épreuves comme celle-ci.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9666,'Je suis désolé que vous ayez dû faire cela, $N. La violence arbitraire n’est pas dans les habitudes des draeneï, mais c\'est parfois la seule solution.$B$BIl est des vérités de l’existence qu’on ne peut comprendre que trop tard. Ce fut le cas pour notre peuple lors de son massacre par les orcs.$B$BEntrer dans la Main d’Argus est un processus de renaissance. Et toute naissance vient avec son lot de douleurs...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9667,'Vous avez prouvé une fois de plus à quel point vous êtes digne des prédictions. Vous avez la gratitude éternelle du grand chef, $N... et le choix entre ces reliques des Calmepins…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9668,'J’avais le sentiment que vous arriveriez jusqu’ici, $C. Si vous êtes prêt à aller plus loin, je suis disposé à vous guider...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9669,'Incroyable ! Vous avez trouvé des survivants ?$B$BÀ vrai dire, $N, personne d’autre n’avait accepté de se charger de cette mission. Vous avez vraiment fait preuve d’une bravoure peu commune, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9670,'Vous avez sauvé plus de la moitié de l’équipe ! Ce haut fait sera raconté en détail au Guet du sang et à l’exarque. Merci encore, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9672,'Avez-vous entendu parler de la malédiction du sang, bouseux de terrien ? Bien sûr que non. La malédiction du sang est ce qui a fait sombrer tous ces navires. L\'endroit où les eaux sont profanées est connu sous le nom de récif du Sang maudit - une partie du monde que vous voudriez ne jamais visiter. J\'y ai moi-même passé vingt ans.$B$BLe scorbut, mon œil ! Je suis mort sur ces côtes sauvages en servant de pâtée aux dragons... Ah, mais c\'est une autre histoire, que je raconterai une autre fois. Pour l\'instant, nous devons aider les malheureuses âmes qui sont piégées dans ce récif.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9673,'Vous avez appris quelques trucs, pas vrai ?$B$B<Halthenis vous regarde avec attention.>$B$BVous servirez bien la ville, et notre cause ultime, grâce à ces nouvelles compétences. Laissez-moi vous montrer comment dresser votre familier à réaliser quelques tours intéressants, comme éventrer votre ennemi, puis vous pourrez repartir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9674,'C\'est un bon début, mais il y a encore beaucoup à faire !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9675,'Savoir nourrir et ressusciter son familier n\'est pas qu\'un petit "détail" supplémentaire, contrairement à ce que votre dernier maître a dit avec tant de légèreté. Le dressage permet à votre familier de progresser comme il n\'aurait jamais pu le faire seul.$B$BJ\'ai déjà appris beaucoup des furbolgs, soyez donc bien attentive et je vous transmettrai mes connaissances.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9682,'Vous avez rendu un grand service aux sans-espoir, $N. Il ne reste plus qu\'une tâche : éliminer le chef des Sang maudit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9683,'Vous avez réussi ! Des centaines d\'âmes vous sont reconnaissantes pour ce que vous avez fait.$B$BPermettez-moi de vous faire ce don...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9687,'Un rituel ? Les chouettides ont vécu en harmonie avec ces terres pendant des milliers d\'années. Une telle chose est une aberration !$B$BQuel dommage...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9688,'Aussi répréhensible qu\'ait été votre tâche, il fallait qu\'elle soit accomplie. Vous devez à présent regarder le mal dans les yeux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9689,'Cela fait combien de temps ? Un millier d’année ? Dix mille, peut-être ? Vous avez rendu un immense service à moi-même et à la mémoire de mon peuple, $N. Veuillez accepter cette objet de puissance en gage de la reconnaissance de Loreth’Aran, en l’honneur de vos exploits.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9690,'Dès que vous serez prêt, je vous en dirai plus sur l’épreuve que vous allez entreprendre. Faites vos préparatifs et revenez me voir quand vous souhaiterez commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9691,'Je savais que vous aviez le potentiel pour passer l’épreuve, $N. Les devoirs qui vous incombent encore sont essentiellement cérémoniaux, mais ils ne sont pas moins dangereux que de regarder fixement un de nos champions qui aurait dégainé son arme. Écoutez-moi attentivement, je vais vous dire ce qu’il vous reste à faire pour vous réclamer de votre nouveau rang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9692,'Excellent, $N. Tout est là. Il ne reste plus qu\'à forger l\'arme.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9693,'Ah, $N... J\'ai entendu parler de vous. Vous êtes celui qui a fait la tournée de Kessel en moins de 15 minutes, n\'est-ce pas ? Oh, on dirait que non, en fait.$B$BÊtes-vous prêt à verser le sang au nom de la Lumière ? Pour Velen ? Pour Argus ?$B$B$B$BJe vais aller plus doucement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9694,'Vous voilà de retour, et en un seul morceau !$B$BJ’ai de bonnes nouvelles, $N. Nous avons reçu des informations sur la localisation possible d’un autre groupe de survivants. Nous avons découvert un nouveau point d’impact ! Quand j’aurais fini de m’occuper de ces affaires, je vous ferai appeler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9696,'<Elysia lit le document.>$B$BSi ce que dit ce document est vrai, les elfes de sang ont ouvert un portail vers l\'Outreterre ! Voilà qui expliquerait pourquoi ils semblent être en si grand nombre...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9697,'Oh, bien... Enfin de l\'aide ! Il y a tant à faire, et je dois rester ici pour tout organiser.$B$BJ\'espère que vous êtes prêt à vous salir les mains.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9698,'<Velen commence à lire le document.>$B$BIntéressant... Voilà qui effectivement explique beaucoup de choses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9699,'C\'est un bon plan, mais un plan dangereux. Je suis sûr que vous vous en sortirez très bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9700,'Combien dites-vous que vous en avez vus au piston de distorsion ? Combien de fois ont-ils donc ouvert ce portail du soleil ? Voilà une très mauvaise nouvelle...$B$BHélas, vous avez appris tout ce que je suis capable de vous enseigner, $N. Kuros fera appel à vous le moment venu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9701,'Quoi ?! Les seigneurs-tourbes de la crête des boues MANGENT les cosses de sporelins ? Mais ça ne va pas du tout !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9702,'C’est ce que vous avez trouvé ? C’est bizarre. Ces restes de champignons décortiqués sont inhabituels, mais ils me semblent néanmoins étrangement familiers.$b$bIl va falloir que je réfléchisse un peu à tout cela. Ne partez pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9703,'Seulement des elfes de sang ? Pas de survivants ? Voilà qui est troublant. J\'ai besoin d\'un peu de temps pour réfléchir, $N. Peut-être qu\'Aesom ou Boros ont une tâche à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9704,'Toutes les possessions de l’estafette ont été volées, à l’exception d’un paquet. Celui-ci ressemble au paquet d’Erona tel qu’il vous a été décrit par Alarion.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9705,'Par le puits de soleil ! C’est la troisième estafette que nous avons perdue ce mois-ci.$b$bJ’apprécie le courage dont vous avez fait preuve en vous aventurant dans l\'allée du Point-du-jour. Il faut que les gardes surveillent de plus près ces maudits Déshérités.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9706,'<Kuros pâlit en lisant le journal et des larmes coulent sur son visage.>$b$bSaruan était mon maître... mon professeur... mon mentor... Ce n\'est que tout récemment que j\'ai pris sa place au sein du Triumvirat, lorsque nous avons dû renoncer à le rechercher.$b$b<Le visage de Kuros se crispe de colère.>$b$bMatis...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9707,'On dirait que vous avez tout ce dont j\'aurai besoin. Nous pouvons commencer !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9708,'Nous avons clairement une correspondance. La présence des ogres, et leurs activités, permettent de tout expliquer. Je comprends pourquoi on appelle ça la Tourbière taillée !$B$BNous devons faire quelque chose pour régler ça, mais quoi ? On ne peut pas simplement éradiquer tous les ogres, ils ont autant le droit de vivre ici que toutes les autres créatures de ces marais !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9711,'Le triumvirat a décidé de juger Matis sans attendre. En ce jour, vous avez conduit ce grand criminel devant ses juges, jeune $R.$B$BVous vous êtes comporté de façon admirable pour deux des trois. Il ne reste plus qu’Aesom.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9715,'Ils font parfaitement l’affaire, mais il nous en faudra d’autres. Comptez-vous retourner à la Basse-tourbière dans un proche avenir ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9716,'Les nagas sont derrière tout cela ! Mais pourquoi ? D\'après ce que vous décrivez, cette pompe à vapeur doit faire partie de ce qui cause la baisse du niveau des eaux du marais !$B$BEnfin, cela n’a pas d’importance. Mais cela explique leur hostilité ouverte à notre égard. Ne perdons pas de temps, j’ai besoin de vous pour une autre mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9717,'<Le sporelin émet un son qui rappelle vaguement un rire méprisant.>$B$BParfait ! Il va sans dire que le moral des géants à spores s’effondrera comme jamais quand ils réaliseront ce que vous avez fait.$B$BOu alors ça va tellement les énerver qu’ils nous réattaqueront très bientôt.$B$B<T’shu a un haussement d\'épaules exprimant l\'indifférence.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9718,'C’est bien ce que je soupçonnais. Les nagas ont installé des stations de pompage dans tous les lacs principaux du marécage de Zangar.$B$BIl faut les arrêter si nous voulons que le marais ait un avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9719,'La Traqueuse noire est morte ! En temps normal, je ne me réjouirais pas d\'une telle boucherie, mais la douleur que la grande mère et son espèce ont infligée à mon peuple à travers les siècles est indescriptible.$B$BIl est bien malheureux qu\'à présent une de ses filles soit sur le point de se transformer pour la remplacer, mais cela va prendre du temps, et nous n\'aurons plus à nous inquiéter au sujet des marcheurs des marais d\'ici là.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9720,'C\'est donc fait. Le marais est sauvé pour l\'instant.$b$bMais ne croyez pas une seconde que nous n\'entendrons plus parler des nagas. Nous devons rester vigilants lors de la poursuite de notre mission en Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9724,'Les nouvelles que vous apportez au sujet de l\'activité des nagas dans le marécage de Zangar sont terribles. Ysiel a été sage de vous demander de nous en informer. Elle n\'a pas oublié que l\'Expédition ne peut exister sans le soutien du Cercle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9726,'<Gzhun’tt opine.>$B$BNous sommes heureux que vous vous soyez montré digne de notre amitié, $N. Ces barbares de nagas y réfléchiront à deux fois avant de revenir nous tourmenter, maintenant que nous avons un allié si puissant !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9727,'<Gzhun\'tt vous adresse un signe de tête.>$B$BNous sommes heureux que vous ayez réaffirmé notre amitié, $N. Maintenant que vous avez exprimé notre point de vue en de multiples occasions, leurs attaques insensées contre notre peuple devraient en toute logique cesser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9728,'Bon travail, $N. Vous feriez mieux de vous débarrasser du moindre sentiment de remords. Ces nagas sont des créatures mauvaises - pires encore que ceux d\'Azeroth.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9729,'Fhwoor est un bon géant. Nous l’avons sauvé des nagas il y a quelque temps, et depuis il est resté pour nous aider.$B$BNous n’avons plus qu’à espérer que les nagas comprendront que si nous pouvons infiltrer leur village et voler leur plus précieuse possession, nous pouvons bien pire encore. Peut-être qu\'à présent, ils vont retourner à leur réservoir et nous laisser en paix ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9730,'Je n\'aimais pas les nagas en Azeroth et je les aime encore moins ici. Cela me désole que notre mission n’ait pas pu rester pacifique, mais vous ne me verrez jamais pleurer la mort d\'un naga.$B$BVoici votre récompense pour vous être occupé du chef Sombrecrête, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9731,'Les nagas ont transformé le lac des Serpents en un gigantesque collecteur pour le reste du marécage de Zangar. Qu’est-ce qu’ils trafiquent ?$b$bVous avez bien fait de nous annoncer la nouvelle, $N. Nous allons envoyer une équipe pour enquêter sur votre découverte. J’ai une autre tâche à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9732,'$N, je suis heureuse de vous revoir. Les choses n\'ont fait qu\'empirer au Refuge cénarien depuis que vous êtes parti.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9738,'Je suis heureux d\'apprendre que certains de mes amis sont en vie, mais cela me brise le cœur d\'apprendre le destin des autres. <soupir>$B$BAu moins sont-ils morts en faisant ce qu\'ils aimaient le plus. Vous méritez ma reconnaissance éternelle pour l\'aide que vous m\'avez apportée, $N.$B$BS\'il vous plaît, acceptez l\'un de ces objets en signe de ma gratitude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9739,'Vous l\'avez fait ! Mon peuple vous remercie.$B$BJ\'espère que vous comprenez... C\'est de là que viennent nos jeunes. Nous ne pouvons pas laisser ces bêtes dévorer les sacs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9740,'Formidable ! Nous avons coupé leur ligne d\'approvisionnement. Il ne nous reste plus qu\'à les achever !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9741,'C\'est vraiment la pagaille là-bas, hein ? Vous avez fait du bon travail, $N. Je vais envoyer des anachorètes pour aider Loryi et Jorli.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9743,'Vous êtes rentré vivant ! Je vais parler de vous aux autres sporelins ! $N, le tueur de géants !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9746,'Voilà qui va sûrement affaiblir leurs défenses et les faire réfléchir avant de bêtement se précipiter sur nos rangs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9747,'Merci, $N. Je vais enfin dormir en paix la nuit. Si je n\'étais pas si vieux et faible, je m\'occuperais moi-même de mes ennemis.$B$BPrenez cet or. Ce n\'est pas grand-chose, mais je me devais de récompenser votre gentillesse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9748,'Comme je m\'en doutais, l\'eau est devenue rouge suite à une fuite de liquide de la batterie.$b$bJ\'espère que vous n\'avez pas nagé dans l\'eau contaminée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9752,'Vous avez sauvé l\'une de mes druides. Nous ne pourrons jamais vous remercier assez, $N.$B$BVous méritez toute ma gratitude, ainsi que celle de l\'expédition.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9753,'J\'ai besoin de vos services, $N. J\'ai établi un plan pour renverser l\'armée des Éperviers du soleil toute entière, mais avant de pouvoir faire toute avancée, nous devons nous procurer quelques informations d\'une importance vitale.$B$BNous devons identifier les faiblesses de leurs défenses principales. Malheureusement, nous n\'avons pu nous approcher suffisamment de la Bobine vectorielle pour les évaluer. Si nous pouvions faire parler le prisonnier, nous aurions les informations nécessaires pour traverser la ligne et détruire la Bobine vectorielle.$B$BVous m\'avez bien entendu, je veux faire sauter cette saleté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9756,'A-ha ! Bien joué, $N. Vraiment bien joué. Êtes-vous prête à éradiquer pour toujours la menace des elfes de sang de notre île ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9757,'Commençons les leçons tout de suite !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9758,'Oh, formidable, vous êtes ici ! Et juste au bon moment... Il y a beaucoup à faire !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9760,'Peut-être êtes-vous celui qui offrira à notre peuple un nouvel âge de prospérité et de paix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9761,'Espérons qu\'un héros arrive avant qu\'ils ne puissent appeler des renforts pour garder la zone que vous venez de sécuriser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9763,'Notre plus grand ennemi dans la région est enfin mort. Vous avez rendu un grand service à l\'expédition, $N.$B$BNous serons à jamais vos débiteurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9765,'Elles feront parfaitement l\'affaire, $N. Apportez-moi toutes les autres que vous trouverez. Nos besoins sont grands et nos ressources peu abondantes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9766,'Excellent travail, $N. Les nagas apprendront à ne pas nous sous-estimer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9769,'Elles sont parfaites, $N. Voilà ce que je vous dois.$B$B$B$BNon, ce n’est pas mon truc, mais je ne vais pas me plaindre.$B$B$B$BL’argent parle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9770,'Vous avez déjà votre dose ?$B$B<Reavij éclate de rire.>$B$BC’est pour ça que nos visiteurs ne restent pas longtemps.$B$BSi j’avais le choix, j’installerais ce poste dans un coin plus agréable, mais entre les Crocs-du-marais et la colère de Denjai, le choix est vite fait.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9771,'Le cadavre meurtri correspond parfaitement à la description de Zurai. Ce qui a tué l\'éclaireur l\'a sûrement pris par surprise, car son arme est dans son fourreau et le contenu d\'un petit encrier forme une tache sur le sol près de lui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9772,'<Zurai prend le rapport et le parcourt.>$B$BNous connaissions déjà la plupart de ces informations. Tout ce qui se trouve dans cet endroit semble desséché ou flétri, mais voilà quelque chose de neuf.$B$BIl dit que les géants fongiques semblent devenir fous furieux en raison du manque d\'humidité. D\'après ce que vous dites, ce doit être ce qui l\'a tué.$B$BJ\'ordonnerai à mes hommes d\'éviter cet endroit. Nous ne pouvons nous permettre d\'en perdre davantage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9773,'Enfin de quoi briser la monotonie des champignons ! Si vous ne sentiez pas aussi fort le poisson, je vous serrerais dans mes bras.$B$BVoyons à quel point les autres vont être jaloux quand ils sentiront l’odeur de cette viande en train de griller.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9774,'Merci, $N. Chaque écaille est la bienvenue.$B$BJ\'ai encore beaucoup de travail devant moi, mais il faut bien l\'avouer, je n\'ai pas grand-chose d\'autre à faire entre les patrouilles…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9775,'Pourquoi n\'avez-vous pas dit que vous aviez un rapport de Zurai ? J\'attendais de ses nouvelles.$B$BJe l\'ai envoyé là-bas pour établir notre présence sur la frontière orientale, pas pour qu\'il reste les bras croisés. Voyons ce qu\'il a à dire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9776,'Si l\'anachorète Ahuurn vous considère comme un ami, on peut probablement se fier à vous. Pardonnez ma méfiance, $R, mais mon peuple et moi n\'avons guère d\'autre protection face aux dangers mortels qui nous entourent. Vous êtes le bienvenu chez nous. Peut-être que notre confiance mutuelle grandira.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9777,'Ce sont de bonnes spores, et elles devraient nous permettre de continuer nos récoltes pendant un certain temps. Merci de nous avoir aidé à reconstituer nos réserves, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9778,'C’est Ysiel qui vous envoie ? Bien sûr que j’aurai l’usage de quelqu’un comme vous. Nous avons toujours besoin de muscles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9779,'<Le redresseur de torts Boros examine le document.>$B$BC’est écrit en thalassien. Heureusement, je connais une personne capable de le traduire…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9781,'Très bien. Cela atténuera nos besoins en ravitaillement pendant un petit moment, même s’il va falloir que nous trouvions d’autres sources de nourriture. Le poisson et les champignons suffisent, mais un peu de variété ne ferait pas de mal.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9782,'Mmm... La terre semble amoindrie, elle ne peut donc pas être à l\'origine du problème, comme je l\'avais pensé. Mais quel est le lien ? Pourquoi tout est-il soudainement en train de mourir ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9783,'Merci de m’avoir aidé dans cette tâche difficile, $N. Notre travail à la Morte-bourbe n’est pas encore achevé, mais maintenant nous pouvons concentrer nos efforts pour restaurer l’équilibre de la région.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9785,'Vous êtes revenu. Avez-vous reçu la bénédiction des anciens ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9786,'Donc les perdus Tourbe-farouches se sont emparés des ruines ? Comme c’est étrange. Ils doivent avoir quelques souvenirs de leur patrimoine et de l’importance de cet endroit. Nous devons en savoir plus, $N. Ce temple pourrait être la clé de la rédemption des perdus et du rassemblement des différentes ramifications des draeneï.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9787,'Cela suffira très largement, $N. Ils semblent fascinés par les oiseaux. C’est bizarre, parce qu’il n’y a pas énormément d’espèces d’oiseaux dans le marécage de Zangar. Qu’est-ce que cela peut bien vouloir dire ?$B$BEst-il possible qu’ils aient rencontré les arakkoa ? Pour un peuple qui pratique le chamanisme, j’imagine qu’ils ressemblent à de puissants esprits-oiseaux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9788,'Mes affaires ! Elles sont toutes là !$b$bJe vous remercie, $N. Comme promis, je vous laisse choisir l\'un des objets pour votre propre usage. Je n\'ai pas grand-chose à vous offrir, mais mon peuple a toujours partagé le peu qu\'il avait.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9789,'C’est un bon début. Mais cela ne fait que commencer.$B$BTuer les petits sabots-fourchus ne signifie pas grand-chose. Et si vous vous attaquiez à un plus grand défi ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9790,'Merci, $N.$B$B$B$BAu moins vous n\'avez pas à les laver. C\'est la partie du travail la plus pénible, mais une fois que c\'est fait, on ne devinerait jamais qu\'elles faisaient partie d\'un insecte géant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9791,'Merci de nous avoir aidés à nous débarrasser de quelques éventreurs Croc-du-marais, $N. S\'ils avaient un tant soit peu d\'intelligence, peut-être qu\'ils pourraient apprendre qu\'il vaut mieux vivre et laisser vivre.$B$B$B$BDes insectes géants dotés d\'intelligence. Je me demande à quoi ça ressemblerait...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9793,'Hmm... Je me souviens avoir entendu nos éclaireurs parler des ruines d\'une colonie draeneï aux confins du nord de la forêt. Pour ma part, je ne sais pas grand-chose au sujet des ruines, mais je vous invite à parler aux éclaireurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9794,'Alors comme ça vous apportez la réponse de Timothy ?$B$B<Kialon s\'arrête un instant pour lire la lettre, puis se met à rire.>$B$BTout est sous contrôle, qu\'il dit. Il n\'a pas besoin d\'aide, qu\'il dit. J\'aurais pu le parier !$B$BCertaines personnes ne changent jamais. Regardez, il a même pris le temps de corriger mon orthographe.$B$B<Kialon soupire.>$B$BJe n\'aurais pas dû envoyer cette lettre. J\'avais oublié. Le spécialiste a toujours le contrôle de la situation. Toujours.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9795,'Denjai a besoin d’aide ? J’aimerais pouvoir lui envoyer des renforts, mais nous sommes déjà beaucoup trop dispersés. Nous avons nos propres ennuis avec les ogres là-haut.$B$BLorsque je le pourrai, je lui ferai part de nos informations sur les tribus ogres locales et leurs tactiques. S’il survit assez longtemps, nous pourrons peut-être prendre ces vermines en tenaille.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9796,'Il est plus que temps que cet avant-poste commence à servir à quelque chose. Les estafettes de l\'Alliance nous ont coûté trop de messagers.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9797,'<Bien qu\'il tente de le cacher, Kroghan a visiblement l\'air soulagé.>$B$BIl était temps que vous arriviez ! Vous n\'êtes pas une armée, je vous l\'accorde, mais tout $R robuste et capable de manier une arme ou de lancer un sort est le bienvenu ici. Les gens de Garadar sont les frères de la Horde tout entière et nous sommes fiers de verser notre sang pour leur défense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9798,'Laissez-moi lire ces plans.$B$BLes elfes de sang nous ont suivis jusqu\'ici ? Ils sont pourris jusqu\'à l\'os, il faudrait les rayer de la surface du monde !$B$B<Le redresseur de torts parvient à retrouver son calme après quelques instants.>$B$BJe vous prie de m\'excuser, je n\'aurais pas dû dire cela. Nous vous sommes redevables pour nous avoir fourni cette information, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9799,'Ces spécimens ont l\'air parfaits. Merci pour ce travail de terrain. Lorsque j\'aurai trouvé le temps de les analyser, je devrais être en mesure de dire ce qu\'il faut faire pour remettre les champs en état.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9800,'Veuillez ne pas vous laver dans les eaux sacrées du Trône.$B$B<L’élémentaliste Lo’ap examine le comprimé qu’il vient de préparer à partir des caracolis.>$B$BPlacez ceci sous votre langue, et laissez le fondre lentement. Quand il sera dissous, vous pourrez respirer dans l’eau comme si vous vous trouviez à l’air libre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9801,'Ils feront parfaitement l’affaire. Donnez-moi un moment pour préparer la potion.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9802,'La diminution du nombre des espèces indigènes est une véritable source d’inquiétude. L’augmentation des espèces invasives pourrait être liée à un déséquilibre récent de l’écosystème. Pour le moment, je ne dispose pas d’assez d’informations pour en tirer des conclusions.$b$b<Lauranna prend quelques notes sur un journal, tandis qu’elle examine les morceaux de plantes.>$b$bPrenez ceci, $N. Cela pourra vous être utile.$b$bApportez-moi tous les morceaux de plantes que vous trouverez. Je les intégrerai dans mes statistiques.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9803,'Ils ont refusé ? Ils sont libres de choisir leur voie, bien sûr, mais cela m’étonne. Je pensais que tous les draeneï, y compris les Perdus et les Roués, se souviendraient qu’ils font partie d’un seul et même peuple.$B$BJe suppose qu’il a raison lorsqu’il dit qu’il ne fallait pas les tromper, mais comment se fait-il qu’il ne comprenne pas que nos intentions sont bonnes ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9804,'<L\'élémentaliste Lo\'ap s\'agenouille dans l\'eau et dit une prière.>$B$BLe Cercle terrestre ne tire nulle fierté des actes qui viennent d\'être commis. Nous faisons notre devoir pour guérir la terre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9805,'Vos efforts ont permis de réduire l’extension de la pollution, mais d’autres problèmes sont apparus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9807,'Votre aide est très appréciée, $N. Vous continuez à nous en apporter, hein ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9808,'Cela va nous permettre de faire des échanges avec d’autres sporelins contre de la nourriture et des fournitures. Sporeggar vous remercie, $N') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9809,'Merci, $N. En tant qu’ancien de Sporeggar, je dois m’assurer que mon peuple est suffisamment approvisionné. Vous rendez ma tâche bien plus facile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9810,'Les éléments ont chanté votre victoire au moment où l’essence difforme a été détruite ! Le Cercle terrestre vous remercie, et souhaite que vous choisissiez une récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9814,'C’est d\'la bonne, mon pote !$B$BJ’vais vous dire. Comme vous avez été sympa et qu’vous avez aidé avec les champis, j’vais vous faire profiter d’la suite !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9815,'Le Cercle terrestre vous remercie, $N. Les éléments vous remercient aussi. Vos efforts répétés pour purifier notre monde sont appréciés et notés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9816,'Excellent boulot, mon pote ! J\'espère que ça leur a plu !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9817,'Je parie que les Écailles-sanglantes y réfléchiront à deux fois avant d\'attaquer à nouveau des éclaireurs de l\'expédition. Acceptez cette récompense, $N. Vous l\'avez méritée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9818,'<Gordawg semble hocher la tête vers vous.>$B$BAsseyez-vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9819,'<Gordawg hoche la tête, approbateur.>$B$BBien. Esprits dormir maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9820,'Bien joué, $N. La présence de ces ogres si près de notre avant-poste m\'inquiète cependant. On dirait qu\'ils arrivent peu à peu des montagnes du nord depuis quelque temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9821,'< Gordawg crache la pierre mâchée, vous arrosant d’une grêle de cailloux.>$B$BPoison. Ces rochers pas être Nagrand. Ces rochers être du poison. Vous détruire rochers poisons. Vous trouver usurpateur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9822,'<Le chasseur des ombres Denjai examine les plans.>$B$BJe le savais ! La puanteur des ogres est toujours porteuse d\'une menace implicite. Maintenant que nous avons la preuve de leurs intentions, nous devons agir avant eux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9823,'Votre victoire sur les Ango\'rosh mérite d\'être fêtée, $N. Je me demande combien de temps il faudra à ces brutes d\'ogres pour se trouver un autre chef assoiffé de sang.$B$BPeu importe, nous serons prêts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9824,'Ces relevé ne me disent rien qui vaille, $N. Karazhan devrait émettre toutes sortes de courants arcaniques… et au contraire il semble que ce soit devenu une espèce de vide énergétique. Aucun signal. Rien du tout, à part un très faible écho démoniaque.$B$BC’est très préoccupant, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9825,'Fascinant. Je vais étudier ces essences, $N. Je vous remercie pour votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9829,'L\'Œil pourpre ? Vraiment ?$B$BMontrez-moi ce rapport.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9830,'Merci de m\'avoir apporté ce venin, $N. Il contribuera largement à me permettre de faire ma démonstration sans vider mes réserves personnelles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9831,'Bien joué, $N. Je n’étais pas sûr de votre réussite.$b$bLes récipients sont enchantés de telle manière qu’ils sont invisibles aux yeux de ceux qui ne sont pas dignes de les voir. Je suis content qu’il ait été visible pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9833,'Excellentes nouvelles. Le chemin n’est pas encore tout à fait sûr, mais les messagers sont rusés et pleins de ressources.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9834,'Maktu penser ça être bonne peaux. Elles faire très bonnes armures.$B$BQui sait ? Peut-être en rester assez pour que Maktu faire armures pour draeneï.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9835,'La menace des Ango’rosh est jugulée pour l’instant, mais ils ne lâcheront pas prise si facilement. J’ai oublié bien des choses depuis la fin de mon existence de draeneï, mais l’obstination des ogres n’en fait pas partie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9836,'Cette clé, je la reconnais. C\'est la clé de Khadgar... Évidemment, je ne la lui ai pas encore donnée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9837,'Sa propre clé ? C’est incroyable !$B$BJe ne sens aucune perturbation dans notre ligne temporelle, je suppose donc que c’est ce qui devait se produire depuis le début. Impossible de faire marche arrière désormais, $N. La clé est à vous et rien qu’à vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9838,'Je vous envoie porter un rapport et vous revenez avec une clé de cet endroit ? Vous devez être plus compétent qu’il n’y paraît, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9839,'Enfin ! Je vous remercie de nous avoir aidés à consolider notre position au Havre d’Orebor. Je parlerai de vos exploits à Telaar, la ville des Kurenaï en Nagrand. Nos deux peuples auront beaucoup d’autres occasions de travailler ensemble.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9840,'<Koren vous regarde d’un air dubitatif.>$B$BJe ne sais rien de cet Œil pourpre dont vous me parlez. Je ne suis qu’un forgeron.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9841,'C’est bien ce qu’il me semblait. Grâce à vous, je vais enfin pouvoir me remettre au travail. Si vous avez un jour besoin de fournitures d’artisanat, n’oubliez pas le vieux Gambarinka !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9842,'Ça devrait me suffire pour quelque temps ! Je crois que certains autres ont commencé à le remarquer. On m’a déjà fait plusieurs offres pour m’acheter des lames. En vendre pour arrondir mes fins de mois pourrait même me rapporter plus que mes marchandises habituelles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9843,'Vous avez trouvé le journal. J’espère bien que les informations que nous cherchons sont là-dedans, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9844,'Vous avez réussi ! Oui, les relevés sont en train de revenir à la normale !$B$BNous devons porter la nouvelle à Cédric. Il sera très impressionné par votre exploit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9845,'Je meurs d’envie de me remettre à pêcher ! Je vais enfin pouvoir revenir en ville avec de vrais poissons dans mon seau, et Gambarinka ne pourra plus se payer ma tête !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9846,'Hmm... On dirait qu\'ils se divisent entre les images d\'un esprit serpent et d\'un esprit oiseau. Aucun troll Sombrelance qui se respecte ne rend de culte aux oiseaux. Leurs esprits sont faibles, capricieux, et il vaut mieux les laisser aux Amani.$B$BMais le serpent, $N, le serpent possède une puissance considérable, et c\'est l\'esprit que je vais étudier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9847,'<Vous racontez au prophète Janidi ce qui vous est arrivé quand vous avez utilisé le totem.>$B$BL’esprit vous a attaqué ? Il devait avoir une plus grande affinité pour les Perdus que je ne le pensais. Impossible de le forcer à me servir sans dépenser des efforts considérables. Je vais devoir chercher une nouvelle source de puissance dans ce monde misérable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9848,'<Timothy feuillette le manuel.>$B$BIl est à base de voile-misère ? Mais ça ne tient pas debout. Le voile-misère n’est pas toxique.$B$BMettre du voile-misère dans un poison, c’est comme de porter deux masses lorsque vous êtes voleur. C’est possible, mais normalement, vous n’êtes pas là pour ça ! Je ne comprends pas…$B$B<Timothy s’éclaircit la gorge.>$B$BEnfin, merci d’avoir été chercher ça pour moi. J’essayerai ce poison dès que possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9849,'GUROK ! Gurok a trahi les éléments !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9850,'Impressionnant. Vraiment impressionnant.$B$BVous avez du potentiel, petit. Maintenant, je vais vous donner l\'occasion de vraiment vous amuser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9851,'Vous avez réussi ! Vous avez triomphé de Banthar ! Je n\'en avais jamais douté, $N.$B$BTenez, je pense que vous l\'avez plus que mérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9852,'$N ! Vous remplissez de joie le cœur du vieux nain que je suis.$B$BVous avez à présent fait vos preuves ; vous avez rejoint les rangs de l\'élite ! D\'autres ont fui, terrorisés, ou bien sont morts, piétinés par la bête. Vous avez utilisé votre intelligence, votre ruse, votre détermination pour prouver votre maîtrise de la chasse.$B$BPrenez ceci et sachez que vous serez toujours le bienvenu pour chasser à mes côtés !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9853,'<Gordawg mâche violemment la tête de terre de Gurok, désintégrant presque la formation rocheuse.>$B$BLe règne de Gurok être fini. Les éléments de la terre être libres. Tous dormir maintenant. champion avoir sa récompense !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9854,'Chaque jour est un cadeau. Tirez-en le maximum. Car demain nous marcherons sur les plaines plus vite qu\'aujourd\'hui. Nous étendrons nos bras plus loin et nous efforcerons de réussir ce dont nous ne pouvons que rêver ce soir, même si cela doit nous rester inaccessible pour toujours.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9855,'Vous avez prouvé votre talent une fois de plus, $C. Vous devez maintenant traquer le plus féroce des venterocs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9856,'On dirait que son œil est toujours vivant. Croyez-vous qu\'elle peut toujours regarder dans votre âme ?$B$B$N, vous pouvez désormais vous compter dans les chasseurs de safari d’élite. Et vous vous êtes rapproché d’un pas pour traquer la proie ultime de ce pays, Longues-défenses !$B$BVous avez gagné le droit de posséder ceci. Qu’il vous serve bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9857,'Passionnant... <tousse>… la façon dont vous avez pris tous ces cerfs, $C. Mais je crois que vous pouvez faire mieux. J\'ai autre chose en tête pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9859,'Waou ! Vous avez réussi ! C\'est vraiment le sabot de Bach\'lor !$B$BHum, on dirait que je commence à me sentir beaucoup mieux. Tenez, laissez-moi vous donner quelque chose pour fêter la preuve de vos talents de chasseur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9861,'C’est un appel au secours, $R. Une force extérieure tente de subvertir les éléments.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9862,'Vous les avez vus contrôler les éléments ? Le vent s’est plié à leur volonté ?$B$B<Morgh est perdu dans ses pensées pendant un moment.>$B$BC’est troublant, $N. Je dois consulter les autres.$B$BNous vous remercions pour vos efforts, $N. Vous devriez peut-être retourner au village et voir s’ils ont d’autres informations sur les Bourbesang et leurs projets néfastes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9863,'Vous avez rendu l’espoir aux Fils de la Foudre, $N. Si nos chefs ne nous protègent plus, peut-être que d’autres en seront capables… comme vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9864,'J’ai entendu les histoires de mon peuple. Elles disent qu\'autrefois, nous étions des guerriers…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9865,'<Saurcroc se tourne vers vous.>$B$BCette odeur, c\'est celle du sang ? Je regrette vraiment de ne pas avoir pu vous aider. Comme vous devez être fier de vous. Ma poitrine se gonfle de joie à l’idée de ce que vous avez fait.$B$BIl y en a d’autres comme vous ? Il existe d’autres héros d’où vous venez ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9866,'<Le long-voyant Corhuk regarde le sol, perdu dans ses pensées. Il hoche la tête.>$B$B< Le long-voyant Corhuk essuie une larme.>$B$BLe fils est le père… Que les esprits prennent en pitié ceux qui se mettront sur son chemin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9867,'Voici donc le visage de notre ennemi ? Je vais la faire monter sur une pique et la placer devant Garadar, près des portes. S’ils songent encore à nous attaquer, ils verront les conséquences de leurs actions en train de les regarder…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9868,'Quelle importance ? La grande-mère se meurt. La vie ne vaut plus la peine d’être vécue…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9869,'Ah, merci pour le message. Peut-être que vous accepteriez d’aider le Cercle terrestre ? Les éléments sont en proie à des changements continuels. Toute aide est la bievenue.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9870,'Ah, merci pour le message. Peut-être que vous accepteriez d’aider le Cercle terrestre ? Les éléments sont en proie à des changements continuels. Toute aide est la bievenue.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9871,'<Arechron frappe sa paume de son poing.>$B$BOrtor… Le sale traître !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9872,'<Garrosh froisse la carte et la jette dans le feu.>$B$BEt alors ? Ils nous attaquent depuis des semaines. Ce n’est pas nouveau.$B$BVous ne comprenez pas ? Nous sommes finis… La Grande-mère Geyah est en train de mourir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9873,'Un millier d’orcs massacrés, vous dites ? Qu’est-ce qui a pu déclencher une avancée aussi audacieuse en territoire orc ? Il est bien qu’il soit mort, mais à vue de tentacule, la situation est sûrement moins simple qu’il n’y paraît.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9874,'<Otonbu soupire.>$B$BCela va encore retarder de dix ans toutes les chances de conclure une paix avec les orcs. Au moins, nous serons en vie pour voir s’écouler ces années, ce qui n’aurait pas été le cas si on avait laissé ces cadavres pourrir dans le lac.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9876,'Cénarius soit loué, vous êtes là. Mes blessures m\'empêchaient de sortir chercher de l\'aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9877,'Janeda vous envoie au secours des prisonniers de Mortholme ? Elle doit avoir une très haute opinion de vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9878,'Il est peu probable que les orcs comprennent ou apprécient ce que vous venez de faire, mais le Nagrand ne se portera que mieux après votre intervention. Merci d’avoir résolu notre problème…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9879,'Oui, j’ai entendu parler du totem… mais cette histoire est bien plus complexe qu’il n’y paraît. Hélas, je n’ai pas l’autorité nécessaire pour vous révéler cette information. Seuls les élus peuvent avoir accès à de telles connaissances.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9882,'Voilà qui est impressionnant. La plupart sont en excellent état.$b$bJe glisserai un mot en votre faveur aux miens.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9883,'Continuez à apporter des fragments de cristal, $N. Nous ne pouvons pas laisser ces voleurs s\'emparer de notre propriété.$B$BMême si elle n\'est pas encore à nous pour l\'instant. Ce n\'est qu\'une considération d\'ordre technique, bien sûr.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9884,'Le Consortium prend soin de ses amis, c\'est bien connu. Au début de chaque mois, j\'aurai des gemmes pour vous, en paiement pour vos services. Leur qualité dépendra de votre loyauté. Espérons que vous ferez preuve d\'intelligence et que vous resterez avec nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9885,'Cela fait plaisir de vous revoir, $N. Vos gemmes pour le mois sont prêtes.$B$BJ\'ai ajouté un petit supplément, juste pour vous montrer à quel point nous tenons à vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9886,'Le Consortium prend soin de ses amis, c\'est bien connu. Au début de chaque mois, j\'aurai des gemmes pour vous, en paiement pour vos services.$B$BLeur qualité dépendra de votre loyauté. Espérons que vous ferez preuve d\'intelligence et que vous resterez avec nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9888,'<Kilrath parle à voix basse.>$B$BCes ogres sont extrêmement particuliers. Ils sont aussi extrêmement stupides. Regardez comme le gros fait danser les… moins gros. C’est hypnotique.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9889,'Laissez-moi en vie et je vous dirai tout ce que vous voulez savoir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9890,'Moins vite, $N. Je ne suis qu’un pauvre voleur. Je n’ai aucune idée de ce qu’il faut faire de telles informations.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9891,'Donc ils pensent qu’ils sont dans leur droit en chassant et en massacrant des orcs quand cela leur chante, hein ? Je suis sûr que cela n’a rien à voir avec notre chef qui est un chiot impuissant… Si seulement il avait ne serait-ce qu’une partie de la passion qui dévorait son père…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9892,'Nous allons en tirer un bon profit, $N. Je ferai en sorte que Khoraazi entende parler de votre travail ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9894,'Vous avez toute ma gratitude, $N, ainsi que celle des guetteurs. Cela les réconfortera d\'apprendre qu\'ils peuvent poursuivre leur travail au sud sans craindre d\'être attaqués.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9895,'Maintenant que vous avez vu les symptômes du déséquilibre de vos propres yeux, vous pourrez les reconnaître pendant vos voyages.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9897,'Bon, je ne sais pas si vous avez vraiment participé au sauvetage de Kristen… Mais si elle vous a donné l’un de ses paquets de peaux, c’est que vous êtes quelqu’un de bien.$B$BVoici votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9898,'Fantastique ! Je n’oublierai jamais que vous m’aurez aidé à gagner son cœur. En fait, vous serez l’invité d’honneur de notre mariage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9899,'Au moins, il y a quelqu’un qui fait sa part du travail, ici. Merci de vous être chargé de cela, $N. Je vais parler à Zurai de Reavij. Ses ruses et ses rêvasseries ont duré suffisamment longtemps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9900,'Nous n\'aurons plus à nous préoccuper de Gava\'xi maintenant, grâce à vous. Nous allons trouver de quoi vous récompenser à présent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9901,'Bon travail, $N. À nous deux, nous avons réussi à nous rendre plus fameux que toute une équipe de prospecteurs. Lorsque je rentrerai à Forgefer, je pourrai choisir mes missions, pour sûr.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9902,'Merci, $N. Peut-être qu\'avec l\'aide des draeneï, ce marécage sera un jour libéré des nagas. Je n\'arrive pas à imaginer ce que cela doit faire d\'être contraint de les servir.$B$BIl n\'en parle pas souvent, mais Maktu était autrefois un esclave.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9903,'Je suis certaine que ce pauvre vieux voyait bien que son temps se terminait. Avec tous ces nouveaux venus, l\'ancien ordre ne pouvait durer. C\'est tout aussi bien que son esprit connaisse le repos à présent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9904,'Enfin ! On dit que chaque grand pêcheur a sa propre histoire sur "celui qui a pu s\'enfuir", mais je n\'ai pas encore croisé de créature que je n\'ai pas pu battre d\'une façon ou d\'une autre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9905,'<Maktu fait un signe de tête approbateur.>$B$BMaktu remercie pour votre aide. La fierté de Maktu est satisfaite. Il ne se fera plus surprendre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9906,'Notre tâche n\'est pas encore terminée. Il y en a d\'autres à qui nous devons donner une bonne leçon !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9907,'Si cela ne glace par leur sang dans leurs veines, alors rien ne le fera. Vous avez rendu justice aux Mag’Har, $N. Et pour la justice, les Mag’har offrent de belles récompenses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9910,'Vous voulez peut-être un autre travail ? Quelque chose de plus délicat, hein ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9911,'Vous êtes sûr que c’est une vraie ? Non, parce que d’accord, il y a de grandes créatures dans le marécage, c’est entendu, mais il y a géant et GÉANT.$B$BQuoique… maintenant que j’y pense, les sporelins parlaient d’une raie du Néant monstrueuse qui les terrorisait avant l’arrivée des seigneurs-tourbe.$B$BOn dirait bien que cette histoire était vraie. Il vaudrait mieux que je la mette à l’abri. Elle intéressera le reste de l’expédition.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9912,'Bienvenue au Refuge cénarien, $N. J\'espère que vous venez nous aider dans notre mission. Nous avons beaucoup à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9913,'Prêt à vous mettre au boulot, elfe de sang ? Je crois que j\'ai exactement ce qu\'il vous faut.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9914,'Je n’ai pas douté de vous un instant, mon ami. Ces spécimens m’ont l’air très bien. Un peu crasseux et éraflés, mais bien. En tout cas, il valent le prix que nous avions négocié.$B$BJ’espère que nous continuerons à faire des affaires à l’avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9915,'Excellent. Ces défenses sont très bien, même si certaines ont l\'air un peu ternes.$B$BLa reconnaissance du Consortium vous est acquise, $N, et elle va loin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9916,'La plupart de nos biens ont été détruits ou volés lors des attaques. Je ne peux pas vous offrir grand-chose, mais voici quelques objets qui vous seront peut-être utiles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9917,'<Bintook lit les plans.>$B$BPAR LA LUMIÈRE ! Leur écriture est atroce. D’après ce que je peux déchiffrer, soit ils se préparent à « manger les peaux bleues et prendre leur village », soit à cuisiner une tarte aux myrtilles. Cela peut être l’un ou l’autre, vraiment. Nous devons aller au fin fond de cette affaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9918,'Oh ciel ! Un petit groupe de chasseurs et d’éclaireurs? Il faut aller en parler à Mo’mor.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9919,'Vous avez contribué à protéger la prochaine génération de sporelins, $r. La moindre des choses pour nous serait de vous accueillir dans nos foyers. Restez un peu et rencontrez les autres sporelins. Ils ont beaucoup de questions à vous poser, j\'espère que ça ne vous dérangera pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9920,'<Mo’mor a l’air perplexe.>$B$BC’est donc une nouvelle tribu d’ogres qui repousse les Rochepoing de plus en plus loin vers le sud. C’est assez troublant. Mais nous devons d’abord nous occuper des problèmes les plus proches de notre demeure…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9921,'Excellent. Est-ce que vous n’auriez pas, par hasard, repéré cette créature nommée Lantresor, mentionnée dans la lettre de cet idiot ?$B$BDe toute façon, nous devons continuer. J’ai reçu des rapports mentionnant des activités ogres auxquelles nous devons mettre terme immédiatement !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9922,'Excellent travail ! Je suis actuellement en train de faire des recherches sur la tribu Cognepierre mentionnée par le lieutenant Rochepoing. Il est temps de mettre ce que vous avez déjà accompli à l’épreuve.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9923,'Je suis vraiment désolé, $R. Il se fourre toujours dans les ennuis. J’aimerais pouvoir le garder en laisse…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9924,'Merci beaucoup, $N. Sa mère va s\'occuper de lui à partir de maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9925,'Vous mettez un sourire sur mon visage, $N. Enfin, ce serait vrai si j\'avais un visage.$B$BContinuez comme ça et vous et moi deviendrons les meilleurs amis du monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9928,'Excellent ! Notre prochaine cible sera les ruines du Crâne ricanant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9931,'Le plan est parfait, $N. Je vois déjà les fruits de votre travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9932,'Je dois reconnaître que je ne me suis pas senti aussi vivant depuis des décennies. Vous vous en êtes bien sorti , $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9933,'Je vous en prie, $N, prenez dans cette offrande tout ce qui vous ferait plaisir. Après tout, sans vos efforts, tout cela n’aurait pas été possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9934,'<Garrosh donne un coup de pied dans la caisse.>$B$BVous perdez votre temps, $R. Prenez ce que vous voulez dans la caisse. Ni Garadar ni moi n’avons besoin de ces babioles inutiles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9935,'La mégère a été tuée ! Voilà une merveilleuse nouvelle, $N. Prenez votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9936,'La mégère a été tuée ! Voilà une merveilleuse nouvelle, $N. Prenez votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9937,'La poigne meurtière de Durn se desserre ! L’avenir de Nagrand sera meilleur grâce à vous, héros ! Bien joué !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9938,'La poigne meurtière de Durn se desserre ! L’avenir de Nagrand sera meilleur grâce à vous, héros ! Bien joué !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9944,'Trente orcs, elfe de sang ! Et de ces trente orcs, seuls Ungriz et moi avons survécu. Nous avons trouvé le jeune orc, Saurcroc, à moitié mort près de Berceau-de-l’Eté. Apparemment, il était là-bas pour une toute autre raison…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9945,'C\'est un bon début, mais il faut s\'occuper de leur chef pour que vos actions aient un impact durable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9946,'Cette tête sera placée aux portes de Garadar, afin que tous puissent la voir. Les ogres y réfléchiront à deux fois avant d’interrompre un rituel sacré mag’hari.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9948,'Vous avez fait ce que nul ne croyait possible possible et ramené nos frères et sœurs disparus. Vous êtes un héros pour les Mag\'har, $N. Votre nom et les exploits que vous avez accomplis pour nous seront connus de tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9951,'Cela vaut mieux, en fait. S’il ne peut pas accepter poliment une invitation, alors il n’a aucune raison de venir.$B$B<Le gardien Arblos semble troublé un instant.>$B$BQui êtes-vous, et que faites-vous ici ? Vous devez quitter rapidement les lieux, avant qu’il ne soit trop tard !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9954,'Cette fois, ils m’ont bel et bien bouclé, $N. C’est Cho’war, le roi des Cogneguerre, qui a la clé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9955,'Merci, $N. J’ai envoyé Corki vivre avec les elfes de la nuit des Tranchantes. Avec un peu de chance, ils l’empêcheront de s’attirer des ennuis.$B$BMaintenant, à propos de cette récompense…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9956,'Stupéfiant ! Comment vous êtes-vous débrouillé pour nous ramener tout ça sans vous faire aider ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9957,'C\'est une très bonne chose que le Refuge vous ait envoyé. Les druides du Fourré ont été tués ! Il n\'y a que moi et un autre à avoir survécu, et il a perdu la raison.$B$BJ\'ignore ce qui s\'est passé, mais j\'ai bien l\'intention de l\'apprendre. Quoi que cela ait pu être, c\'est arrivé très vite et cela semblait surnaturel.$B$BM\'aiderez-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9960,'C\'est une très bonne chose que le fort des Brise-pierres vous ait envoyé. Les druides du Fourré ont été tués ! Il n\'y a que moi et un autre à avoir survécu, et il a perdu la raison.$B$BJ\'ignore ce qui s\'est passé, mais j\'ai bien l\'intention de l\'apprendre. Quoi que cela ait pu être, c\'est arrivé très vite et cela semblait surnaturel.$B$BM\'aiderez-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9961,'C\'est une très bonne chose que le Bastion allérien vous ait envoyé. Les druides du Fourré ont été tués ! Il n\'y a que moi et un autre à avoir survécu, et il a perdu la raison.$B$BJ\'ignore ce qui s\'est passé, mais j\'ai bien l\'intention de l\'apprendre. Quoi que cela ait pu être, c\'est arrivé très vite et cela semblait surnaturel.$B$BM\'aiderez-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9962,'Hmm… pas mal, pas mal du tout… Vous avez du potentiel, gamin. Voilà un peu d\'or pour vous lester les poches…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9967,'Je dois admettre que je ne pensais pas que vous aviez la moindre chance, $N ! C\'était fantastique ! Que diriez-vous d\'un autre combat ? Gurgthock a exactement ce qu\'il vous faut sous le coude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9968,'C\'est bizarre. Les échantillons prélevés sur les térophalènes vicieux sont imprégnés de ce qui semble être du mana pur.$B$BIl semblerait que ce qui a ainsi répandu la mort a également laissé derrière lui ce puissant champ d\'énergie résiduelle. Pour une raison qui m\'échappe, ce champ n\'a pas tué les térophalènes, mais les a plongés dans un état d\'excitation.$B$BIl paraît évident que cette étrange énergie est un sous-produit du phénomène qui a affecté le bosquet.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9970,'Bravo petit, les ogres commencent à transpirer ! Voilà un petit extra – économisez-les, surtout.$B$BAlors, prêt pour un autre combat ? Gurgthock fera miser la banque sur vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9971,'J\'avais donc raison. C\'était le cadavre d\'un Roué ? Et vous confirmez qu\'il y avait un objet étrange posé par terre juste à côté ?$B$BC\'est absurde. Qu\'est-ce qu\'un Roué aurait fait là-bas ? Et quelle est cette chose qu\'il avait avec lui ?$B$BEst-ce que c\'est la cause de cette tuerie ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9972,'BON SANG ÇA Y EST ! Le prochain combat sera le plus dur ! Le titre de champion est proche !$B$BSurtout, gardez la tête froide. Faut pas laisser les ogres réaliser ce qui arrive. Je tiens à mon pourcentage, quand même.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9973,'Aïe aïe aïe. Mogor a réclamé le droit d’aller se battre, en tant que héros des Cogneguerre. Il va falloir que vous le battiez !$B$BPersonne n’a dit que les ogres se battaient à la régulière…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9977,'Gurgthock vous avait dit que ça en vaudrait la peine, gamin. Faites votre choix !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9978,'Bon, d\'accord… Je vous dirai ce que je sais, mais ce n\'est pas grand-chose !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9979,'Oui ? Que puis-je faire pour vous aider aujourd\'hui, mort-vivant ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9982,'Êtes-vous effrayé par mon apparence ? Savez-vous qui je suis ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9983,'Êtes-vous effrayé par mon apparence ? Savez-vous qui je suis ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9986,'Bien joué, $N. Nous avons déjà assez de raisons d\'inquiétude sans avoir en plus à nous demander si les arakkoa vont à nouveau s\'en prendre à nos marchands et messagers.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9987,'Bien joué, $N. Nous avons déjà assez de raisons d\'inquiétude sans avoir en plus à nous demander si les arakkoa vont à nouveau s\'en prendre à nos marchands et messagers.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9990,'Des éthériens ? Des marchandises livrées à Tuurem? Des pièces d\'ingénierie exotiques ? Et un elfe de sang qui s\'apprête à livrer cette dernière boîte à la halte Aile-de-feu ?$b$bQu\'est-ce que tout cela peut bien signifier ?! Quel rapport cela pourrait-il avoir avec ce qui est arrivé aux druides du Fourré cénarien ?$b$bJe crois que nous devrions jeter un œil à l\'intérieur de cette boîte.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9992,'Merci d\'avoir apporté ces graines. J\'en ai presque assez pour en envoyer un premier lot !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9993,'C\'est un bon début, mais il va nous en falloir plus si nous voulons presser une bonne quantité d\'huile !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9994,'Oh non ! Quelle terrible nouvelle ! Je n\'arrive pas à croire que tous nos amis cénariens sont morts, excepté deux d\'entre eux.$b$bLaissez-moi regarder ces pièces. J\'espère seulement que ce n\'est pas ce que je crois.$b$bSi, c\'est bien ce que je craignais. Je pense qu\'il s\'agit de pièces de bombes. Nos yeux et nos oreilles à Shattrath nous ont rapporté des informations concernant des éthériens qui importent des marchandises interdites depuis d\'autres dimensions avec lesquelles ils sont en contact.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9995,'Oh non ! Quelle terrible nouvelle ! Je n\'arrive pas à croire que tous nos amis cénariens sont morts, excepté deux d\'entre eux.$b$bLaissez-moi regarder ces pièces. J\'espère seulement que ce n\'est pas ce que je crois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9996,'C\'est un bon début, mais si l\'on se fie à ce que vous avez vu ici dans la cour et aux informations que j\'ai reçues, nous avons bien plus urgent à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9997,'C\'est un bon début, mais si l\'on se fie à ce que vous avez vu ici dans la cour et aux informations que j\'ai reçues, nous avons bien plus urgent à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9998,'<La haute-elfe acquiesce.>$B$BC’est un bon début, mais Bertelm a eu raison de vous envoyer ici. J’ai fait une découverte qui pourrait expliquer la présence des gangr’orcs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (9999,'C\'est ce que je soupçonnais. Il n\'existe pas de moyen conventionnel de détruire le gangracier. Mais tout n\'est pas perdu…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10000,'Pour arrêter les gangr\'orcs, il faudra faire bien plus que harceler leurs ouvriers, je le crains. J\'ai fait une découverte qui explique en partie leur présence ici, et elle me conforte dans ma conviction que nous devons agir rapidement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10001,'Je connais quelqu’un qui aura peut-être une idée de la manière de détruire les camps. C’est un ancien ingénieur de la Légion, après tout…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10002,'<Theloria hoche la tête.>$B$BTrès bien. Nous avons gagné un peu de temps. Les elfes de sang vont se demander ce qui est arrivé à leur amie. Si tout va bien, d’ici à ce qu’ils aient compris, nous aurons une idée plus claire de leurs intentions.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10003,'<Kaide hoche la tête.>$B$BTrès bien. Nous avons gagné un peu de temps. Les elfes de sang vont se demander ce qui est arrivé à leur amie. Si tout va bien, d’ici à ce qu’ils aient compris, nous aurons une idée plus claire de leurs intentions.$B$BLorsque le moment sera venu, j’informerai Rogak de nos progrès.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10004,'Du calme, yeux-brillants ! Sal’salabim va aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10005,'Une bombe utilisant du mana pur capable de détruire des villes entières ! Mais pourquoi ? Pourquoi les elfes de sang voudraient-ils créer une chose pareille et l\'utiliser contre nous ? Le Fourré cénarien était un havre de paix et de repos.$B$BQuelle qu\'en soit la raison, elle doit se trouver dans la tête du gardien Arblos, et je ne sais pas du tout comment je pourrais le guérir. Peut-être que la raison lui reviendra avec le temps ?$B$BQuoi qu\'il en soit, je veux vous remercier pour m\'avoir aidé à découvrir ce qui s\'est passé. Je ne peux qu\'espérer qu\'une telle tragédie ne frappera plus jamais personne !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10006,'Une bombe utilisant du mana pur capable de détruire des villes entières ! Mais pourquoi ? Pourquoi les elfes de sang voudraient-ils créer une chose pareille et l\'utiliser contre nous ? Le Fourré cénarien était un havre de paix et de repos.$B$BQuelle qu\'en soit la raison, elle doit se trouver dans la tête du gardien Arblos, et je ne sais pas du tout comment je pourrais le guérir. Peut-être que la raison lui reviendra avec le temps ?$B$BQuoi qu\'il en soit, je veux vous remercier pour m\'avoir aidé à découvrir ce qui s\'est passé. Je ne peux qu\'espérer qu\'une telle tragédie ne frappera plus jamais personne !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10007,'Les choses commencent à s’améliorer. Je pense que si nous parvenons à empêcher les gangr’orcs de renforcer leurs amis, nous pourrons garder ce poste sous contrôle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10008,'Je sais que vous avez beaucoup voyagé, $N, mais comprenez-moi bien : certaines histoires gagnent à rester là où elles se sont produites. Est-ce clair ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10009,'Bon, un marché est un marché. Mais quand Sal’sabim va vous dire, vous pas vous fâcher pas, d’accord ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10010,'Mais bien sûr ! Nous utiliserons leurs propres armes contre eux !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10011,'Nous avons gagné ! L\'avancée de la Légion a été stoppée !$B$BJe vous propose ce choix de récompenses en remerciement de vos actes héroïques !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10012,'<Bertelm prend les plans que vous lui tendez et les examine.>$b$bSi vous n\'aviez pas apporté cette carte, je dirais que vous avez perdu la raison, mais la preuve est bien là. Les gangr\'orcs sont non seulement ici pour servir les elfes de sang, mais en plus il semble qu\'ils aient reçu l\'ordre de nous tenir occupés.$b$bCette carte soulève plus de questions qu\'elle n\'apporte de réponses, mais elle nous fournit une idée plus précise de ce que nous avons à affronter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10013,'<Rokag prend les plans que vous lui tendez et les examine.>$b$bKaide avait donc raison ! Ces vermines de gangr\'orcs préparent quelque chose. Je n\'aurais jamais deviné qu\'ils s\'associeraient aux elfes de sang, cela dit.$b$bSelon cette carte, les gangr\'orcs sont chargés de nous tenir occupés... mais pourquoi ? Ces nouvelles sont inquiétantes, $N. Vous avez eu raison de m\'apporter ceci immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10016,'Ah, excellent travail, mon ami. Elles sont bien plus belles que ce à quoi je m\'attendais. Elles feront une cape superbe.$B$B<Bertelm lance un regard vers l\'auberge.>$B$BOui, cette cape sera superbe.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10020,'Merci, $N. Prendre soin des gens en difficulté est une tâche ardue, mais j\'ai découvert avec le temps que c\'est en soi une récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10021,'Je vous remercie, $N. Nous sommes les gardiens de la Lumière et ne pouvons abandonner nos responsabilités, même dans les périodes les plus difficiles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10022,'Je m\'incline devant vos talents, $N. Vous avez démontré votre excellence dans l\'art de la chasse.$B$BJe n\'oublierai pas votre aide dans la confection de cette cape. Ce sera véritablement une pièce unique et je la porterai avec fierté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10023,'Cette fourrure est encore plus magnifique que je ne l\'avais espéré ! C\'est un bon présage, $N, et les esprits vous offriront leur faveur pour votre contribution à cette cérémonie.$B$BJe vous ai confectionné un casque à partir des fourrures restantes, $N. Il vous identifiera comme un grand chasseur et un allié du grand esprit du loup de la forêt de Terokkar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10024,'Ils sont tous en excellent état, $N. Continuez comme ça et bientôt vous compterez les Clairvoyants parmi vos amis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10025,'Je vous remercie, $N. Les visions de Voren\'thal décideront peut-être un jour du destin de notre race. Il nous appartient de faire de notre mieux pour que ces visions soient aussi précises que possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10026,'<Andarl s’éponge le front avec la manche de sa robe.>$B$BLe Ciel soit loué. Je commençais à me demander si ces choses n’avaient pas chassé toutes les autres créatures de la forêt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10027,'Keb’ezil est soulagé que vous vous soyez chargé de ce petit problème, pas vrai Keb ?$B$B<Le diablotin, probablement indigné, ignore son maître.>$B$BPardonnez ses mauvaises manières, vous savez comment sont les démons…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10028,'J\'espère que ce ne sont pas les seuls calices intacts de la ville. C\'est un bon début, mais je pense qu\'il nous en faudra beaucoup plus encore.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10030,'Génial, exactement ce dont j\'avais besoin... encore des os.$B$B<Ramdor soupire.>$B$BOui, oui, je veillerai à ce que les restes de nos honorés ancêtres reçoivent un enterrement décent, ne vous en faites pas.$B$BIl y a autre chose que vous pourriez faire si vous souhaitez véritablement aider les morts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10031,'Vous avez fait votre devoir et vous n\'avez nul besoin de demander le pardon. Cela m\'attriste d\'apprendre qu\'ils étaient corrompus et plongés dans une terrible non-mort, mais par vos actions vous leur avez donné le repos.$B$BMerci de les avoir libérés, $N. Acceptez cet humble témoignage de mon admiration pour vous et votre altruisme.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10033,'Oui, je suis sûre que vous avez tué tous ces fouette-radius. C’est évident, puisque le capitaine a demandé que vous fournissiez une preuve pour cet avis de recherche.$B$B<Taela vous regarde, l\'air sarcastique.>$B$BJe vais vous croire sur parole. Je ne sais pas exactement qui j\'ai mis en colère pour qu\'on me confie cette tâche, mais je vous remercie de vos efforts au nom de l’Alliance. Voici un petit quelque chose pour vous dédommager de vos frais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10034,'Vous devez avoir tué des tas de ces fouette-radius ! Parfait, je les déteste ! Depuis que l\'un d\'eux m\'a mordu, je souffre d\'évanouissements répétés.$B$BVous vous rendez compte à quel point c\'est embarrassant ? Tenez, prenez ceci en remerciement de cette petite vengeance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10035,'Je suis très impressionnée, $C. Torgos était l\'une des créatures les plus coriaces que j\'aie connues de ce côté de Nagrand.$B$BEh bien, j\'imagine que ceci n\'est pas trop mal pour le trésor du Bastion allérien. Faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10037,'Merci ! Je me souviens même pas de quand j\'ai mangé de l\'anguille pour la dernière fois !$B$BComment on fait pour les cuire ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10038,'Il était temps que quelqu\'un vienne ici. J\'ai envoyé ce rapport au Bastion allérien il y a plus d\'une semaine !$B$BMaudite bureaucratie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10039,'Il était temps que quelqu\'un vienne ici. J\'ai envoyé ce rapport au fort des Brise-pierres il y a plus d\'une semaine !$B$BCes elfes de sang et leur fichue bureaucratie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10040,'Bien, vous êtes enfin de retour ! Alors, qu\'avez-vous découvert ? Qui sont-ils ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10041,'Bien, vous êtes enfin de retour ! Alors, qu\'avez-vous découvert ? Qui sont-ils ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10042,'Voilà une terrible nouvelle, en effet ! Eh bien, on dirait que j\'ai fait le bon choix en vous envoyant là-bas pour aider Weeks. La dernière chose dont nous avons besoin, c\'est que le Conseil des ombres s\'installe juste à notre porte !$B$B$N, en récompense de vos efforts à Grangol\'var, je vous offre le droit de choisir l\'un de ces beaux objets.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10043,'Voilà une bien mauvaise nouvelle ! Cependant, bien sûr, j\'ai fait le bon choix en vous envoyant là-bas pour aider Neftis. La dernière chose dont nous ayons besoin, c\'est une place forte du Conseil des ombres juste à notre porte !$B$B$N, vous avez mérité quelque chose de beau. Allez-y, faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10044,'Nous devons d’abord élargir le champ de votre esprit afin que vous puissiez communier avec les ancêtres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10045,'Vous êtes plein de ressources, $N. Nos meilleurs cueilleurs auraient mis deux fois plus longtemps à se procurer ces herbes.$B$B$B$BN’ayez pas peur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10047,'Je vous offre mes remerciements sincères pour vos efforts, $N. Bien qu\'il reste beaucoup à faire, cela me réjouit de savoir que nous avons aidé quelques-uns à trouver le repos qu\'ils méritaient depuis si longtemps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10050,'Les Fils apprécient vos efforts, même si peu d\'entre eux acceptent de parler de l\'armurerie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10051,'Isla Tressétoile vient de partir, mais elle m\'a fait un rapport complet concernant les activités à la halte Aile-de-feu. On peut comprendre qu\'elle soit très choquée par ce qui s\'est passé au Fourré cénarien.$B$BElle m\'a raconté le rôle que vous avez joué dans sa libération afin que nous puissions obtenir ces informations. Le Bastion allérien a une dette envers vous pour le service que vous nous avez rendu.$B$BS\'il vous plaît, acceptez ce cadeau de notre part à tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10052,'Isla Tressétoile vient de partir, mais elle m\'a fait un rapport complet concernant les activités à la halte Aile-de-feu. On peut comprendre qu\'elle soit très choquée par ce qui s\'est passé au Fourré cénarien.$B$BElle m\'a raconté le rôle que vous avez joué dans sa libération afin que nous puissions obtenir ces informations. Le fort des Brise-pierres a une dette envers vous pour le service que vous nous avez rendu.$B$BS\'il vous plaît, acceptez ce cadeau de notre part à tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10057,'Il est permis d’espérer que maintenant que les fantômes des officiers sont calmés, ceux des simples soldats suivront. Merci encore de votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10058,'Vraiment ? J’ai du mal à croire qu’il ait survécu à la bataille. Le livre a souffert du séjour dans les ruines, mais je suis content de l’avoir.$B$BC’est mon seul souvenir de Turalyon.$B$B<Le père Devidicus semble lutter contre les larmes.>$B$BLorsque vous vous battez aux côtés de quelqu’un pendant tant d’années, il finit par devenir plus proche de vous que votre propre famille.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10063,'C’est bien ce que je pensais ! Ce vieux nain grincheux était censé m’aider à transporter mon équipement et à collecter des données, mais il se contente de rester dans cette drôle de ville draeneï, à boire comme un trou.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10064,'J\'espérais bien que le Guet du sang enverrait des renforts une fois qu\'ils auraient appris ce que nous avons à affronter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10065,'Ça a l\'air un peu mieux là dehors, mais je me demande toujours s\'il ne vaudrait pas mieux que j\'attende un médecin ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10066,'Bon travail, $N. Il va être beaucoup plus facile d\'obtenir des renforts, ou de lancer des attaques contre les Éperviers du soleil, sans avoir à se demander ce que les noueurs préparent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10067,'Bon travail, $N. Il est important de ne négliger aucune occasion de priver les Éperviers du soleil d\'une ressource.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10074,'Formidable, $N. Voilà qui nous aidera dans notre lutte contre ces vermines de l\'Alliance qui ont fait surface en Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10076,'Formidable, $N. Voilà qui nous aidera dans notre lutte contre ces vermines de la Horde qui ont fait surface en Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10078,'C’est le bon esprit !$B$BCes renforts sont une très bonne nouvelle, même si je suis un peu sceptique quant à leur attitude envers la Horde. D’où je viens, toute personne qui pointe une arme vers vous est un ennemi et mérite d’être traitée comme tel !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10079,'Par la… barbe de bronze de Barbe-de-bronze, vous avez réussi ! Vous êtes un héros, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10081,'La potion que vous avez bue n\'avait en réalité aucun effet. Vous ne pouvez voir un esprit que s\'il vous le permet. La potion n\'est que le symbole de votre foi et de votre dévouement. Il s\'agissait d\'une épreuve, et vous l\'avez réussie...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10082,'Sert à rien. Ils continuent. Il doit y avoir quelque chose de plus subtil là-dessous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10085,'Voilà qui est extrêmement troublant. Vous dites qu\'aucun ancêtre n\'était dans leurs villages ? Qu\'ils partaient tous pour le sud ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10086,'Ces matériaux sont sensass ! Un peu tordus et brûlés, sans doute, mais je ne laisserai jamais des composants de seconde main m’empêcher de faire des explosifs de haute précision.$B$BMerci, $N. Vous avez vraiment l’œil pour repérer les ordures de qualité !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10087,'C’est ce que je pensais ! Je n’ai pas pu voir la destruction d’ici, mais j’imagine à quoi cela devait ressembler. Splendide !$B$BBien joué, $N. Le haut commandement de Thrallmar sera heureux de recevoir la nouvelle de votre succès !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10093,'Ah, ainsi vous avez rencontré le prophète Kryv. Il est sage et talentueux, et tout $R qu\'il considère comme un ami est aussi mon ami.$B$BMettez-vous à l’aise puis allez vous présenter aux autres résidents du temple.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10094,'Lorsque vous ouvrez le livre flottant par magie, vous êtes submergé par l’angoisse.$B$BIl y a quelque chose d’anormal, de très anormal !$B$BVous entreprenez de le lire. Son contenu est incroyable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10095,'Marmon s\'est presque échappé ?! Cela faisait deux ans qu\'ils gardaient cette créature enfermée là-dedans... Je me demande ce qu\'ils ont fait de travers pour qu\'elle échappe à leur contrôle après tout ce temps.$B$BQuoi qu\'il en soit, $N, en triomphant de cette bête vous nous avez probablement tous sauvés ! Je frémis en pensant à ce qui serait arrivé à Shattrath et au reste de l\'Outreterre si cette chose avait réussi à s\'échapper !$B$BJe suis soulagée que vous nous ayez aidés à prendre les choses en main et à en finir avec la menace du Conseil des ombres à Auchindoun. Comment pouvons-nous vous récompenser ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10096,'Bien ! Ces bêtes des marais n’ont pas le droit d’envahir les demeures des sporeloks !$B$BIl serait de loin préférable que ces créatures apprennent à vivre en harmonie, mais si elles en sont incapables, nous prendrons la situation en main !$B$BTenez, prenez l’un de ces objets en remerciement de votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10097,'Je ne vous remercierai jamais assez, $N. Maintenant que Lakka est libre, je peux couper les ponts avec les Sethekk.$B$BJe ne me pardonnerai probablement jamais la mort de Syth, mais c’était un acte nécessaire. Lorsque j’aurai rejoint Skettis, j’accomplirai les rites funéraires pour lui. Lorsqu’il aura expié le crime d’avoir égaré notre peuple sur des voies néfastes, son esprit trouvera peut-être la paix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10098,'Je ne recevrai jamais un pardon complet pour mon rôle dans les crimes des Sethekk, mais en rendant les reliques de Terokk à mon peuple, je peux commencer à me racheter.$B$BMerci de votre aide, $N. Vous n’avez aucune idée de l’ampleur de ce que vous avez accompli aujourd’hui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10099,'C’est une bonne chose que vous vous soyez débarrassé de ce… comment avez-vous dit qu’il s’appelait ? Z’kral ?$B$BÀ en juger d’après votre description, c’était plutôt un « ça » qu’un « il », mais il est mort, c’est l’essentiel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10101,'<Une voix douce et mélodieuse emplit votre esprit.>$B$BJe suis K\'ure des naaru, $N. Vous vous trouvez au cœur de mon ancien vaisseau.$B$BOshu\'gun, comme l\'appellent les orcs, est le vaisseau qui le premier a conduit les draeneï dans ce monde. Bien que nous soyons tombés des cieux pour nous écraser ici il y a bien des siècles déjà, mes énergies affaiblies sont restées piégées dans ces décombres. Je suis malheureusement la source de la douleur des esprits orcs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10102,'K\'ure a été sage de vous envoyer ici. Nous ne pouvons vous offrir d\'aide concernant la souffrance des ancêtres orcs, mais voilà quelqu\'un qui le peut.$B$BQuelqu\'un qui bientôt renaîtra dans la Lumière...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10103,'Pour parler franchement, j\'en attendais plus, mais il faudra bien se contenter de vous. Bienvenue au poste du Rat des marais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10104,'Il est très flatteur d’être considéré par votre ami Roué comme un expert en reliques de son peuple, mais pour être honnête, je n’ai pas eu tellement d’occasions de les étudier depuis mon arrivée ici. C’était bien mon intention, mais je n’ai pas tardé à m’apercevoir que d’autres problèmes requéraient mon attention.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10105,'J’espérais que l’avant-poste serait déjà terminé, mais ce n’est pas son argent... Bah, il progresse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10106,'Très bien, $N. Vos actions sur le terrain jouent un grand rôle dans la bataille pour la péninsule des Flammes infernales.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10107,'Alors, quelle est votre décision ? Sera-ce la guerre ou allez-vous offrir votre aide ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10108,'Alors, quelle est votre décision ? Sera-ce la guerre ou allez-vous offrir votre aide ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10109,'Excellent ! Quelques réglages, et il sera comme neuf. Oh oui, votre clé ! Tenez, la voilà.$B$BAu fait, le Bond-o-tron a encore quelques petits défauts qu’il faut que je résolve. Heu, soyez prudent .') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10110,'C’est du bon travail, $N. J’entends presque le bruit des batailles qui ont eu lieu dans ces forts. J’aurais aimé y être pour les voir de mes yeux !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10111,'Bon, ce n’est pas un œuf… Hé ! J’aime aussi le poulet ! Je vais dévorer cette énorgigantesque griffe ! Merci !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10112,'Oui, je crois qu\'effectivement, tout est en train de redevenir plus clair.$B$BEt je pense que vous méritez plus que simplement l\'information que vous recherchez en récompense de votre diligence.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10113,'Je suppose que nous devrons trouver un autre porteur d’eau. Dites, vous avez l’air d’un $C solide. Le boulot vous intéresserait ? À moins que vous ne soyez là pour la chasse ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10114,'Je suis soulagé d\'apprendre qu\'il va bien. Êtes-vous venu pour vous joindre à nous et participer à la chasse ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10115,'C’est du bon travail, $N. Les Tourbedague ont beau être au-delà de tout espoir de rédemption, je doute que les draeneï auraient réagi aussi rapidement à cette situation.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10116,'Remarquable ! Beaucoup d’autres sont partis récupérer la prime, mais aucun n’est revenu. Il n’est pas bien difficile de s’imaginer ce qui leur est arrivé.$B$BNous ne serons plus dérangés par Mummaki et sa bande de dégénérés. C’est un soulagement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10117,'Vous avez toute ma gratitude, $N. Je commençais à me dire que j’allais devoir partir m’occuper moi-même de Mummaki, avec une bonne partie de la garnison. Bien sûr, impossible de dire ce qui serait arrivé à Zabra’jin dans ce cas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10118,'Je pense que vous avez réussi à leur faire passer un message fort et clair. Mes hommes auront peut-être moins peur d’aller affronter les Tourbedague. Ou au moins, ils auront honte de leur manque de courage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10119,'Bienvenue en Outreterre, $N. Bienvenue en enfer ! Bien que le premier Corps expéditionnaire ait réussi à passer sans dommage, la Légion cherche à reprendre la Porte des ténèbres et à empêcher tous renforts de traverser.$B$BBien que votre aide aurait été précieuse ici, nos troupes et les soldats de la Horde sont capables de contenir les bataillons de la Légion qui essaient de s\'emparer de cette position.$B$BIl faut que vous alliez là où vos talents seront le mieux mis à contribution.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10120,'Alors comme ça vous êtes le nouveau messager d\'Orion ? J\'espère que vous réussirez mieux que le dernier qu\'il a envoyé, $C. Avec la Légion qui avance, vous n\'arriveriez jamais à Thrallmar à pied. Il vous suffit de demander, et ma fidèle wyverne vous conduira là-bas en toute sécurité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10123,'Très bon travail, soldat. La fréquence de leurs attaques va diminuer, au moins jusqu’à ce qu’ils fassent venir de nouveaux seigneurs de l’effroi.$B$BÀ part ça, mauvaise nouvelle, j’ai reçu vos nouveaux ordres…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10124,'Alors c’est vous qui avez fait le ménage à Gangrétincelle, hein ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10129,'Cela va les retarder de plusieurs semaines ! Excellent travail, $N. La Légion ne s’attendait pas à une résistance aussi acharnée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10132,'Bon travail.$B$BSi vous voulez mon avis, tout ce que nous avons à faire, c\'est tuer assez de ces colosses, et nous n\'aurons plus à nous inquiéter au sujet de la crête ou de l\'étrange cristal en son milieu.$B$BTenez, prenez l\'un de ces objets en guise de récompense de la part de l\'Expédition cénarienne.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10134,'Hmph. C\'est juste un gros morceau de cristal brut à mon avis.$B$BIl est vrai que je sens une aura malsaine et maléfique qui en émane, mais ce n\'est pas vraiment mon domaine. Je suis là seulement pour mettre fin à la menace que représentent les géants des montagnes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10136,'Les générations à venir chanteront ce jour, $N. Elles chanteront votre vaillance. J\'aurais aimé que Thrall soit ici pour célébrer cette victoire avec nous. Le Légion est vaincue, et les Flammes infernales appartiennent à nouveau à la Horde ! Il reste peut-être encore un espoir pour cette terre ravagée, notre peuple y a peut-être encore sa place.$B$BLok\'tar ogar !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10140,'La progression de notre expédition dans ce monde désolé est presque bloquée, $N. Nous avons rencontré plus de résistance que nous ne l\'avions prévu.$B$BComme si affronter à nouveau la Légion ardente n\'était pas suffisant, cette terre regorge d\'horreurs pires que tout ce que nous avons jamais rencontré.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10141,'Le commandant de corps Danath a dû mal comprendre ma demande de renforts. Vous avez l\'air capable, mais… j’avais demandé un bataillon complet !$B$BIl se trouve que nous avons comme un problème avec les démons…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10142,'Très bon travail, soldat. La fréquence de leurs attaques va diminuer, au moins jusqu’à ce qu’ils fassent venir de nouveaux seigneurs de l’effroi.$B$BÀ part ça, mauvaise nouvelle, j’ai reçu vos nouveaux ordres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10143,'Heureux de vous rencontrer, soldat.$B$BBon, assez papoté, écoutez-moi. J’ai une mission capitale à vous confier. Je veux que vous la réussissiez… et que vous vous en sortiez vivant !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10144,'Bon travail, $N. La mise hors service de ces portails va ralentir l\'arrivée des renforts de la Légion pendant un bon bout de temps !$B$BMais ce n\'est pas encore le moment de se reposer...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10146,'Cela va les ralentir, aucun doute là-dessus ! Je crois que grâce à vous, je suis exceptionnellement de bonne humeur, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10159,'Sans ravageurs, les voyageurs qui vont et viennent du Refuge cénarien dans le marécage de Zangar seront plus en sécurité.$B$BL’Expédition cénarienne a une dette envers vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10160,'<Le lieutenant Amadi hoche la tête.>$B$BBon. Nous avons besoin de toute l’aide possible. Les gangr’orcs sont de plus en plus nombreux autour du rempart sud, et cela m’inquiète. J’ai envoyé un éclaireur pour enquêter, mais il n’est pas encore rentré.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10161,'Tout n’est pas en bon état, mais je devrais avoir de quoi travailler. Moyennant un peu d’ingénierie créative, ça marchera, aucun doute là-dessus !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10162,'Vous volez comme si vous aviez fait ça toute votre vie, $N. Remarquable travail. Pas même une égratignure sur les wyvernes bombardiers !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10165,'Un autre concurrent mord la poussière... Vous faites du bon boulot pour une bestiole de chair, $R. Si un jour vous passez par le Raz-de-Néant, venez me voir. Ma demeure se trouve dans la Foudreflèche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10166,'Je n\'appartiens plus à ce monde et dois admettre ma défaite. Ces terres ont changé pour toujours et plus rien ne sera jamais comme avant.$B$BLaissez ce pendentif ici près de moi, $N. Peut-être qu\'un jour, longtemps après le départ des elfes, un nouvel arbre poussera exactement en cet endroit, au milieu d\'une forêt brûlée et des enveloppes vides de tréants morts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10167,'Je m’en souviens très bien, $N. Mon énergie avait été entièrement absorbée par la catastrophe. Lorsque le prophète Velen et les draeneï ont récupéré mes restes et m’ont conduit ici, je n’étais plus qu’une faible étincelle d’énergie du vide. Après une longue cérémonie, ma forme affaiblie fut déposée dans ce sarcophage. Voici près de mille ans que je récupère. Le cycle est presque achevé…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10168,'Vous avez accompli un long et périlleux voyage et risqué votre vie pour assurer la sécurité des Mag\'har, ainsi que la sérénité de nos ancêtres. Pour cette raison, je vous suis reconnaissante, au-delà de ce que les mots pourraient jamais exprimer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10170,'Je veux que vous en informiez personnellement Garrosh.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10171,'Tout le monde est fier. Fier que notre peuple puisse voir un nouvel hiver. Mais ensuite ? Qu\'y aura-t-il ?$b$bPeut-être que vous devriez diriger ce clan, $N. Peut-être qu\'alors on me permettra de mourir quand la Grande-mère partira, et d\'effacer enfin la honte qui entache le nom de ma famille. J\'aspire à une telle paix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10172,'<Les larmes coulent sur le visage de la Grande-mère Geyah.>$B$BAllez trouver votre chef de guerre. Dites-lui que je l\'attends ici...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10173,'Ah, vous avez donc réussi à récupérer le bâton. Impressionnant, $N. Vous êtes peut-être celui que je recherche.$B$BOh oui, votre récompense...$B$B$B$BJe pense bien que vous vous attendiez à mieux que ça, mais cela aussi viendra en son temps. Pour le moment, dites-vous que votre véritable récompense est une opportunité à saisir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10174,'<L\'image de l\'archimage Vargoth vous examine pendant que vous lui transmettez le message de Ravandwyr.>$B$BRavandwyr possède tout ce qu\'un maître peut espérer de son apprenti. Quand je lui ai confié le bâton et que je lui ai dit de fuir, j\'espérais qu\'il s\'en servirait pour trouver de l\'aide et me sortir de là après le départ des troupes de Kael\'thas. Depuis, j\'ai beaucoup appris sur la nature de cette malédiction.$B$BIl est possible de la briser, $N, mais pas sans votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10175,'<La voix de Thrall se charge de nuées d’orage.>$B$BJ’ai… j’ai une grand-mère ? Elle est en vie ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10176,'Mes félicitations, $N. La destruction du champ atténuateur m\'aidera énormément à déployer la magie qui, enfin, lèvera la malédiction qui pèse sur la tour.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10177,'Il était temps que vous arriviez.$B$BMehlisah a dit qu\'elle enverrait de l\'aide il y a plusieurs jours déjà. Et nous nous battons ici depuis tout ce temps !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10178,'Comment ? Grik\'tha vous a envoyé ici pour me trouver ?$B$BJe ne sais pas si je devrais être touché ou la traiter d\'imbécile !$B$BVous croyez que vous pourriez me faire sortir de cette cage ? Je suis un peu à l\'étroit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10180,'J\'aurais dû penser qu\'il vous enverrait à ma recherche. Il a essayé de me dissuader de retourner dans les salles des Sethekk, mais je ne supportais pas de vivre en laissant Lakka mourir ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10182,'C\'est bien, $N. Je ne ressens plus d\'agitation dans l\'esprit de Dathric. Je donnerais cher pour pouvoir lui parler encore une fois, mais c\'est déjà suffisant qu\'il connaisse enfin le repos.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10183,'Oh, Pokernikus s\'est finalement décidé à me faire part de ses découvertes, on dirait ? Ces fainéants de scientifiques !$b$bQu\'est-ce que c\'est ?$b$b<Le chef parcourt les notes plusieurs fois, visiblement incrédule.>$b$bIl dit que les violentes énergies du Néant qui parcourent le Raz-de-Néant auront tout réduit en poussière dans quelques mois seulement.$b$bVoilà qui est ennuyeux - cela va nous obliger à réorganiser le calendrier de la construction de la fusée !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10184,'<Le protecteur Valemort secoue doucement la tête.>$B$BCe n\'est pas ce qu\'ils auraient mérité, mais c\'est le mieux que l\'on puisse faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10185,'<Le protecteur semble consterné.>$B$BJe peux déjà apercevoir la prochaine vague sur l\'horizon. Les massacrer est utile dans l\'immédiat, mais nous devons prendre des mesures plus permanentes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10186,'Bah ! Ils ont l\'air grossier. Nous pourrons peut-être les utiliser dans la chambre tubulaire tertiaire du moteur ?$B$BMais bon, vous avez bien travaillé, Technicien Subalterne de Troisième Échelon ! Continuez comme ça, vous passerez Deuxième Échelon en un rien de temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10188,'Ah, il est aussi magnifique que dans mon souvenir. Vous sentez le pouvoir qui en émane ?$B$BBien sûr, il nous reste encore beaucoup à faire, mais vous méritez déjà ma plus profonde reconnaissance pour m\'avoir rendu le cachet.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10189,'Excellent ! Cette liste nous permettra de faire de meilleurs choix quand nous ciblerons les fidèles de Kael aux manaforges.$b$bDommage, je commençais à apprécier de tuer ses larbins sans aucune discrimination.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10190,'Eh, ne pointez pas ce truc n\'importe où ! Il est réglé sur « Tuer » !!$B$BC\'est bon, on dirait bien que vous avez rechargé la batterie plus qu\'assez. Ça va vraiment aider à faire marcher mes robots.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10191,'Vous avez réussi ! Vous avez réussi ! Oh, j\'ai envie de vous embrasser !$B$BAh zut, le Maxx A. Million Mod. V est encore à plat. Enfin bon, il a eu assez d\'énergie pour accomplir sa tâche, c\'est tout ce qui compte !$B$BLe chef-de-fusée Karlingue sera content de pouvoir ajouter ces machines draeneï à la fusée-de-néant X-52. Ça veut dire que j\'aurai une promotion ! C\'est tellement génial, il faut que je vous donne une récompense !$B$BVoilà, faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10192,'<L\'image de l\'archimage Vargoth semble examiner le compendium.>$B$BIl a un peu souffert, mais si on considère les traitements qu\'il a subit, c\'est un miracle que tout soit encore lisible. Gardez-le précieusement, $N. Sans lui, nous aurions peu de chance de réussir à briser le sceau de la tour.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10193,'Vous êtes une fille fiable, $N. S\'il y a une chose que j\'aime plus que tuer les valets de Kael, c\'est de les faire tuer par quelqu\'un d\'autre.$B$BMoins de sang sur mes vêtements comme ça.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10194,'Votre vol a coûté un joli prix. Espérons que vous serez à la hauteur de votre mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10197,'Excellent ! Quand j\'en aurai fini avec vous, vous pourrez vous glisser dans les rangs des Solfurie sans vous faire remarquer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10199,'Waouh ! Bien, maintenant on peut discuter !$B$BConfiez-moi ces petits joyaux que j\'en extraie tout le vice. On devrait obtenir un mélange propulsif pour fusée qui fera voler les chapeaux !$B$BJe vais mélanger l\'huile de lauze et le venin d\'aiguillon, et on verra ce qui se passe...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10200,'Vous ne cessez de me surprendre, $N. Vous avez réussi des prodiges en matière de camouflage à la manaforge Coruu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10201,'<Vous décrivez le résultat à Rakoria et elle éclate de rire.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10202,'Il était temps que vous arriviez. Je commençais à me demander si les Clairvoyants étaient vraiment intéressés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10203,'Vous devez être la personne qui nous a renvoyé tout le matériel de sape depuis les ruines ! Houra !$B$BJ\'ai déjà redistribué le matériel à nos autres installations. Nous allons maintenant pouvoir accélérer nos opérations d\'excavation sur toute l\'île de manière incroyable ! La fusée-de-néant sera terminée en un clin d\'œil !$B$BMmm, c\'est bizarre. Attendez une minute, vous avez bien dit que vous nous avez renvoyé les quatre ? Je n\'en ai reçu que trois...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10204,'Mmm… je m\'y attendais.$B$BL\'exposition à un tel niveau d\'énergie pure amplifie grandement notre addiction naturelle à la magie.$B$BJe ne suis pas surprise que Kael puisse faire à sa guise : tous ses subordonnés sont ivres d\'énergie, en quelque sorte.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10205,'Quel soulagement de savoir que quelqu\'un a enfin réglé son compte à cette vermine. Vous faites du bon travail, $N... est-ce que vous permettez que je vous appelle par votre nom ?$B$BSi vous le voulez bien, j\'aurais une autre tâche à vous confier. Une tâche très importante que quelqu\'un de votre talent devrait pouvoir accomplir sans peine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10206,'Héhé, imbéciles d\'éthériens !$B$BMerci de nous avoir rapporté ces modèles, $C. J\'espère qu\'on pourra les intégrer directement à la fusée. Je me demande à quoi sert tout ça. On devrait bien s\'amuser à le découvrir !$B$BMmm, voyons-voir si je peux trouver un peu de menue monnaie à vous jeter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10208,'Bien joué ! J\'ai presque senti les tremblements des explosions jusqu\'ici !$b$bNous avons à présent une nouvelle mission nécessitant des explosifs à vous confier...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10209,'<Vous ne savez pas s\'il s\'agit seulement d\'un effet de distorsion ou si l\'archimage est réellement en train de sourire.>$B$BMaintenant que j\'ai récupéré la dernière de mes possessions, j\'ai tout ce dont j\'ai besoin pour rompre la magie de Kael\'thas. Je vais commencer immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10210,'<La lumière qui a empli tous vos sens lorsque vous vous êtes approché d’A’dal s’intensifie lorsque vous lui adressez la parole. Un carillon mélodieux retentit dans votre tête.>$B$B<Vous êtes en sécurité ici.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10211,'J\'espère que vous en avez beaucoup appris sur Shattrath, $N. Il vous faudra peut-être quelque temps pour tout assimiler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10212,'Vous êtes véritablement le héros des Mag\'har, $N. Sans vous, nous aurions sûrement été écrasés par les ogres et les Roués.$b$bNotre peuple est pauvre, mais nous possédons des artefacts puissants. S\'il vous plaît, j\'insiste pour que vous preniez quelque chose dans notre coffre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10213,'Nous avons été abattus par la Légion ardente, malgré notre drapeau blanc. Qui aurait pu savoir que la Légion ardente était si méchante ? $B$BNous ne pouvons pas vous suivre au poste de Brise-échine. Nous devons réparer notre zeppelin et poursuivre notre chemin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10216,'<Vous fermez les yeux et appuyez sur un bouton.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10218,'Comme c\'était à l\'origine une idée de Morphalius, j\'ai décidé de lui rendre son travail. Bien travaillé, petite créature de chair. Vraiment bien travaillé !$B$BN\'oubliez pas, si jamais vous cherchez du travail et passez du côté du Raz-de-Néant, passez me voir à la Foudreflèche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10220,'Les Inflexibles ont fait l\'expérience de la force de la Horde. Il ne fait nul doute qu\'ils seront bientôt d\'humeur à écouter ma proposition d\'alliance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10221,'Scarbille me manquera toujours. <sniff> Mais nous allons pourvoir dormir sur nos deux oreilles maintenant que son alter ego le Dr Boum n\'est plus là pour semer la terreur !$B$BQue cela vous serve d\'exemple : ne vous aventurez jamais par ici sans un casque du Néant !$B$BBien, comment puis-je vous remercier pour ce que vous avez fait ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10222,'Ce que vous avez fait aujourd\'hui ne nous rendra jamais nos disparus, mais cela apaisera peut-être leurs esprits. Même si à dire vrai, nulle quantité de sang ne pourra étouffer ma colère face aux actes de Kael\'thas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10223,'<Vous n\'en êtes pas sûr, mais le protecteur Valemort semble être au bord des larmes.>$B$BEnfin, tout est fini. Si je pouvais me faire oublier de cette vie par la simple force de ma volonté, je le ferais, mais en vérité je ne sais pas comment lâcher prise. Pour les habitants du village, c\'est une voie clairement tracée mais difficile à emprunter. J\'imagine que c\'est le prix à payer pour ceux qui gardent des liens aussi forts avec cet endroit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10224,'Eh beh, ça en fait de l\'essence !$B$BBon, voyons ce qui se passe quand je les mélange avec les matrices à cristaux d\'étherlithium.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10225,'Ooh, des cristaux de matrice d\'etherlithium. Ouais, ça a l\'air très important !$B$BOn va les poser par ici et je m\'en occuperai dans un petit moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10226,'Ah, c’est bien mieux comme ça ! Très bien, maintenant, nous sommes dans la course.$B$BLaissez-moi le temps de déposer ce machin dans le bidulo-magico-truc, et je suis sûr qu’il va nous cracher un noyau de phase totalement fonctionnel pour le moteur.$B$BOh, oui, je pense que je dois vous récompenser pour m’avoir sauvé la peau ! Héhé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10227,'L\'enfant dit vrai. J\'étais autrefois un "prêtre de mort."$B$B<Ramdor grimace.>$B$BQue ce titre est déplaisant.$B$BAu-delà de ce couloir se trouvent les cryptes Auchenaï. Vous trouverez à l\'intérieur les restes de mon prieuré. Bien sûr, ils sont tous devenus fous maintenant. Des forcenés, jusqu\'au dernier ! Je suppose que je devais faire tache, moi qui étais le dernier à garder un minimum de sens commun. Et forcément, mes croyances ont fini par me valoir d\'être excommunié.$B$BVous voulez savoir quelles étaient mes croyances ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10228,'Le livre des morts ? Jamais entendu parler... De quoi parle-t-il, de toute façon ? Qui vous a envoyé ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10229,'J\'ai étudié l\'histoire ancienne pendant toute ma non-vie. Je n\'ai jamais rien vu de semblable à ce livre. Il raconte l\'histoire entière de l\'Armurerie, y compris les événements qui s\'y sont déroulés après sa destruction.$B$BLes Inflexibles ont consigné leur histoire, même après être tombés au combat. Grâce à ce livre, nous pourrons comprendre les Inflexibles et les convaincre de nous rejoindre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10230,'Bon travail, $N. Ce cor ancien nous permettra d\'invoquer les Inflexibles.$B$BEnfin, s\'ils l\'acceptent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10231,'C\'est bon ! C\'est bon ! Pas taper ! On avait le bouquin, mais on l\'a vendu…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10232,'Bon, c\'est une bonne et une mauvaise nouvelle, n\'est-ce pas ? On leur a fait mal, mais avec la Légion ardente qui se promène dans tout le Raz-de-Néant - et qui se rapproche de nous, je ne sais pas trop comment ça va tourner.$B$BJ\'ai le pressentiment qu\'il va falloir changer de régime ici pendant un moment. J\'espère que vous pourrez nous aider, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10233,'<Le lieutenant-ensorceleur Morran hoche la tête d\'un air sinistre.>$B$BLe Kirin Tor n\'apprécie guère la destruction, mais nous n\'avons aucun scrupule à prendre des mesures contre nos ennemis, même dans la mort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10234,'Cela conviendra pour le moment, je suppose. Si seulement on pouvait les faire s\'enfuir…$B$BHé, ça me donne une idée !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10235,'Il… euh… il a dit quoi ? IL VONT S\'EN PRENDRE À LA ZONE 52 ?!!$B$BOh, c\'est pas bon… pas bon du tout !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10236,'Hourra, vous avez trouvé ! Maintenant, je vais peut-être réussir à faire marcher mon déchiqueteur. Si je gagne assez d\'argent, j\'arriverai peut-être à rentrer à Baie-du-Butin.$B$BJ\'espère bien que mon cousin, Laïus Airbuse, va s\'écraser avec son zeppelin. Je n\'arrive toujours pas à croire que ce sont ses boniments qui m\'ont poussé à venir en Outreterre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10237,'Hé, vous plaisantez, j\'espère ? La Légion ardente nous considère comme responsables de tout ça ?$B$BMais c\'est VOUS qui l\'avez fait !$B$BAïe, j\'ai un mal de tête aussi puissant que cette fusée. D\'accord, d\'accord, il va falloir s\'y prendre autrement.$B$BSi la Légion ardente s\'imagine qu\'elle va pouvoir venir ici, détruire notre ville et briser mon rêve de voyager à travers le Néant distordu, elle se trompe lourdement.$B$BEt je connais justement le gobelin qui pourra nous aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10238,'Merci d\'avoir sauvé mes péons. Maintenant je vais peut-être réussir à leur faire réparer mon déchiqueteur avec les pièces détachées que vous avez trouvées, puis gagner de l\'argent et quitter l\'Outreterre. Je suis vraiment impatient de rentrer à Baie-du-Butin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10239,'<Morran manipule l\'un des conteneurs d\'un air hésitant.>$B$BJe ne pense pas avoir jamais vu un tel objet. Il contient manifestement beaucoup d\'énergie en suspension, mais sous une forme brute. Il faudra procéder avec attention, mais je crois que nous pourrons en tirer un moyen de tenir les créatures de mana éloignées.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10240,'Excellent travail. Croisez les doigts, $N. Je vais activer le bouclier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10241,'Excellent travail, $N. Les Clairvoyants ont obtenu des informations précieuses grâce à votre diversion. Peut-être même qu\'ils les partageront avec nous cette fois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10242,'Un test sanguin, vous dites ? Avec plaisir… J\'ai toujours aimé travailler avec du sang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10243,'Vous déroulez le parchemin et commencez à copier les étranges symboles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10245,'Bon travail, $N. Accordez-moi quelques instants pour parcourir votre transcription. Les prêtres vous remercient, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10246,'Excellent travail, $N. Grâce à votre dévouement, nous sommes certains de vaincre notre ennemi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10247,'Ma parole, on dirait que c\'est notre jour de chance, jeune homme.$B$BJe viens juste d\'achever la construction de ma dernière invention, le Saccageur ferrailleur X6000 !$B$BEt vous allez avoir l\'honneur de m\'aider à le tester, afin qu\'on puisse l\'utiliser pour défendre la Zone 52 !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10248,'Eh bien, mon garçon, voilà qui était très excitant ! Je dirais que le saccageur ferrailleur X6000 a fourni d\'excellentes performances, malgré son novice de pilote.$B$BHé hé, non, inutile de vous vexer, je plaisantais. Après tout, vous venez de sauver la Zone 52 et la fusée-de-néant X-52 d\'une ruine certaine !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10250,'Je suis heureux d\'apprendre que les Inflexibles vous ont rejoint dans la bataille. Je pensais qu\'ils viendraient au son de leur propre cor de bataille, mais je n\'en étais pas sûr. Peut-être que nous avons offert à certains la vengeance qu\'ils désirent si désespérément.$B$BVous avez tué Urtrak et nous devons faire part de votre victoire au commandant Hogarth à l\'Armurerie de l\'expédition. Il mesurera l\'étendue des risques que vous avez encourus pour lui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10251,'Les signes étaient tous présents mais j\'ai refusé de les voir.$B$BL\'emprise de la Légion se renforce chaque jour. Même ici...$B$BSi j\'avais su... Si j\'avais su que mon garçon communiait avec des démons... Ils lui ont offert du pouvoir et ils lui en ont donné un avant-goût. Il n\'en fallait pas plus...$B$BLe livre est parti. Emporté par Lexivus... Ses projets ne sont connus que de moi et de son sombre maître.$B$BÉtranger, je ne sais pas si vous avez jamais fait une bonne action dans votre existence, mais sachez bien ceci : il faut arrêter ce garçon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10252,'Étranger... Je n\'ai pas été franc avec vous. Une fois que vous aurez bu cette potion, vous verrez le monde des morts pour toujours. Cette recette que vous allez boire constitue un rite initiatique auquel se soumettent tous les prêtres de mort d\'Auchindoun. Nombreux sont ceux qui deviennent fous à force de subir ses effets. Voir les morts peut être... choquant.$B$B<Nitrin porte la potion à vos lèvres.>$B$BSouhaitez-vous continuez ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10253,'Si le vieux draeneï vous a demandé de détruire le livre, pourquoi ne pas l\'avoir fait ?$B$B<Ramdor vous jette un regard noir.>$B$BBah, qu\'est-ce que ça change ? Vous êtes peut-être cupide, mais au moins vous êtes honnête.$B$BMoi, par contre... J\'ai menti pour avoir ce livre. Je n\'ai pas la moindre idée de l\'endroit où ces pauvres âmes égarées pourraient cacher leur trésor, et même si je le savais je ne vous dirais rien. Cependant, j\'ai tout de même quelque chose pour vous. Vous avez fait quelque chose de bien aujourd\'hui. Peut-être même quelque chose de grand... Vous devriez avoir une récompense.$B$BÀ propos, bienvenue parmi nous.$B$B<Ramdor désigne les esprits.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10254,'Heureux de vous voir, mon frère. Je suis content que vous soyez là. Je suis Danath, chef des Fils de Lothar et commandant de corps de ce bastion.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10255,'<Thiah Crin-rouge écarquille les yeux quand vous lui décrivez les résultats de l\'expérience.>$B$BMais comment est-ce possible ? Je suis sûre d\'avoir préparé l\'antidote correctement !$B$BÇa marche très bien avec les venins d\'araignée ou de serpent, pourquoi dans le cas présent on obtiendrait l\'effet inverse ? C\'est peut-être encore l\'une des nombreuses bizarreries propres à l\'Outreterre, $N. Je ferais bien de passer le mot à mes camarades.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10256,'<Vous décrivez le résultat de la divination.>$B$BLe commandant Sarannis, dites-vous ? Mmm… C\'est une conseillère de Kael\'thas, mais certainement pas une mage. Je me souviens l\'avoir vue lors de l\'attaque de Kirin\'Var. Je pense que votre ressenti est le bon, $N. Ce n\'est pas elle qui entretient la malédiction personnellement, mais elle en détient la clé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10258,'Nous avions perdu la bataille contre les gangr\'orcs il y a si longtemps. Vous nous avez en partie rendu notre honneur en tuant Urtrak.$B$BPrenez l\'une de nos armes avec vous. Quand vous combattrez nos ennemis jurés, utilisez-la, et ceux qui seront libres de la malédiction viendront à votre aide.$B$BAvant que vous ne partiez, ceux qui sont morts à la tour de siège souhaitent vous rendre hommage pour avoir détruit nos ennemis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10261,'You-hou ! Est-ce que vous savez seulement comme c\'est difficile de se procurer ces machins ? Ce n\'est pas comme si je recevais régulièrement des livraisons de pièces par ici.$B$BVous savez quoi, je voudrais que vous preniez quelque chose dans ma boîte à bric-à-brac en guise de paiement. Je suis sûr que vous trouverez là-dedans quelque chose que vous pouvez utiliser. Et sinon, vous pouvez toujours vendre un de ces objets.$B$BTrès bien, laissez-moi vous décharger de ça et l\'installer dans mon analyseur de spectre à long cou avant que le servomoteur défectueux n\'explose !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10262,'Ces insignes sont un bon début.$B$BMalheureusement, pendant que vous étiez au Monceau, l\'un de mes autres agents parmi les Zaxxis m\'a fait prévenir que l\'écumeur-dimensionnel Nesaad est encore en vie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10263,'Bonjour, $R.$B$BNe seriez-vous pas par hasard disponible pour une mission de récupération de quelque importance ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10264,'Bonjour, $R.$B$BNe seriez-vous pas par hasard disponible pour une mission de récupération de quelque importance ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10265,'Laissez-moi y jeter un coup d\'œil.$B$BHmm, je ne vois rien de spécial. Je doute que ce soit le bon, bien que d\'après votre description des activités de la Légion ardente dans les ruines, on dirait qu\'ils recherchent quelque chose en particulier eux aussi.$B$BEspérons qu\'il ne s\'agit pas de ce cristal que le prince-nexus désire tant se procurer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10266,'Oui, c\'est vrai. Les elfes de sang sont encore revenus sur un achat de marchandises qui avaient déjà été livrées.$B$BLe traqueur-du-Néant Khay\'ji vous recommande, j\'espère donc que vous pourrez m\'aider à résoudre ce problème.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10267,'Eh bien, vous me voyez heureux d\'apprendre que cet épisode malheureux est maintenant derrière nous. Je n\'ai pas souvenir d\'avoir vu le Consortium faire des affaires avec des gens aussi rustres et peu fiables.$B$BVous, par contre, semblez d\'une fiabilité à toute épreuve, $N. Peut-être pourrais-je vous demander de me rendre encore un petit service ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10268,'Bienvenue à la Foudreflèche, $C. Je vous offre l\'hospitalité du Consortium.$B$BVous pouvez poser cet équipement où vous le voulez. Je pense que vous aurez très bientôt à le reprendre avec vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10269,'<Le camelot Hazzin murmure tout bas.>$B$BAh, je suis au courant de votre mission. Elle est d\'une grande importance pour le prince-nexus Haramad !$B$BMaintenant que nous connaissons l\'emplacement du premier point de triangulation, vous devez vite trouver le deuxième !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10271,'Et quand je pense que ce satané éthérien comptait revendre les essences aux elfes de sang comme de vulgaires friandises…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10272,'Voilà qui conviendra parfaitement, $N. Merci d\'avoir accepté de nous aider.$B$BCependant, avant de continuer, il y a autre chose dont nous devons nous occuper.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10273,'Maintenant que nous nous sommes débarrassés de cet éthérien envahissant, nous pouvons consacrer toute notre énergie à comprendre ces dragons du néant. J\'ai eu l\'occasion d\'examiner les œufs et j\'ai fait quelques découvertes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10274,'Bon travail, $N. Très bon travail. Les draconiens du néant n\'accepteront pas un dragon bleu comme chef au premier abord, mais avec le temps et l\'affirmation claire de mon autorité, ils s\'y feront. Ils seront divisés, isolés et sans chef établi. Nous devrons faire preuve de vigilance pour les empêcher de tomber sous la coupe d\'une puissance maléfique, et les garder sous contrôle tout ce temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10275,'Excellent. Le prince-nexus sera satisfait !$B$BNous connaissons maintenant le deuxième point, ce qui nous mènera au troisième, et donc à l\'emplacement approximatif du cristal !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10277,'Vous avez maintenant, je l\'espère, une meilleure vision de ce que nous attendons de vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10278,'Incroyable. Vous avez touché le Vide ! $N, vous venez de sauver le travail de toute une vie. Mais il reste encore à faire, et vous pouvez m\'aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10279,'Nous devons vous préparer à la bataille qui vous attend…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10281,'Mon nom est Tyrygosa, de la lignée de Malygos, mais on m\'appelle le plus souvent « Tyri ». Mon compagnon est un paladin, Jorad Masse.$b$bDes rumeurs ont déjà couru bien loin à propos de ces étranges draconiens, et je crains qu\'on ne voie trop de monde accourir pour tenter d\'en tirer un profit sans même comprendre la vraie nature de ce à quoi ils ont affaire. Avec votre aide, nous espérons en apprendre plus sur ces créatures avant que d\'autres ne découvrent leur existence.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10282,'Nos plus grandes peurs pourraient bientôt devenir réalité. Les forces qui se cachent derrière cette perturbation temporelle appartiennent à un nouveau vol de dragon, appelé les Infinis. Nous ignorons d\'où ils viennent et pourquoi ils détruisent les voies temporelles.$B$BDans cette niche temporelle, ils ont capturé Taretha Foxton, la fille de Tammis Foxton, secrétaire d\'Aedelas Landenoire, le chef de Fort-de-Durn et responsable de tous les camps d\'internement d\'Azeroth.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10283,'Vous êtes des amis de Taretha ? C\'est donc là son nouveau plan ? Très bien …') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10284,'Vous avez accompli de grandes choses, $N. Hélas, les souvenirs du jeune chef de guerre devront rester les mêmes qu\'à l\'origine… Andormu vous attend dans le repaire du maître.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10285,'Veuillez accepter un présent du Vol de bronze. Ces objets vous seront utiles lors de vos voyages à travers le temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10286,'Je vais parler, $C. Déposez votre arme. Je ne veux pas d\'ennui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10287,'Viera Murmesoleil ? Ah la sale gamine.$B$BJe vais lui montrer de quel bois je me chauffe !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10288,'Des rapports pour le bastion de l\'Honneur ? Aucun problème : pour un voyage rapide et sûr, montez sur l\'un de mes griffons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10289,'Je vais réunir toutes les troupes dont je dispose et les envoyer en renfort aux forces d\'Orion à la Porte des ténèbres. La Légion n\'oubliera pas de sitôt le cri de guerre de la Horde ! Quant à vous, $N, vous avez rendu un grand service à Thrallmar aujourd\'hui. Je pense que vous nous serez d\'une grande aide ici... si vous êtes assez malin pour survivre, bien sûr.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10290,'Ah, oui. C\'est précisément la qualité que j\'espérais. Nous arrêterons peut-être totalement l\'exploitation des formations de cristaux si nous pouvons nous approvisionner auprès des géants.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10293,'Bien joué ! Je suis si impatient d\'en tester les propriétés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10294,'Excellent. Le générateur de faille dimensionnelle est presque terminé. Il ne manque plus qu\'un dernier ingrédient. Bientôt, nous pourrons ouvrir une faille dimensionnelle vers les ultimes profondeurs des abysses.$B$BQui sait ce qui en sortira ? Pensez-y un instant, $N, de telles connaissances seraient la source d\'un pouvoir sans limite.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10295,'Vous avez sauvé le travail de toute une vie, $N.$B$BIls me traitaient de fou, ils se moquaient de moi, ils pensaient que j\'avais perdu la raison à cause de mon obsession pour la crête du Vide et les Champs de distorsion. Maintenant, grâce à cet éclat d\'âme, je suis en mesure de découvrir les secrets des marcheurs du Vide. Je vais disposer de la puissance des abysses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10296,'En effet, si les orcs ne parviennent jamais jusqu\'en Azeroth, l\'Alliance ne se constituera jamais. La guerre civile finira par éclater, et achèvera d\'affaiblir les royaumes humains.$B$BLa Légion ardente finira par envahir Azeroth et la détruire en l\'absence de tout défenseur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10297,'Vous excellez, $N. L\'enfant, Andormu, souhaite vous parler une nouvelle fois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10298,'Une fois de plus, vous avez assuré le présent et l\'avenir de ce monde, $N. Veuillez accepter ces objets en guise de récompense pour vos exploits.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10300,'<Ravandwyr examine attentivement les cristaux, puis en choisit un.>$B$BCe cristal devrait faire l\'affaire. Je vais refaçonner la châsse du bâton pour y placer cette nouvelle pièce.$B$BQuand l\'archimage Vargoth verra ça, il sera déçu. Mais je peux supporter la déception de mon maître si elle implique que nous ayons réussi à le libérer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10301,'Excellent, $N. Nous avons à présent plus de la moitié de ce dont nous aurons besoin pour tenter de briser la magie de Kael\'thas.$B$BEt si les elfes de sang souffrent par la même occasion de la perte de leur commandant local, tant mieux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10302,'Vous avez terminé ? Voilà une bonne nouvelle. Espérons que nous trouverons le moyen d\'éviter de tuer ces bêtes mutées dans l\'avenir.$B$BJe pense avoir établi un plan qui pourrait représenter une solution alternative à ce problème, mais j\'aurai besoin de votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10303,'Ces elfes de sang sont déterminés à tous nous tuer. Comment pourrions-nous les faire changer d\'objectif ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10305,'Ah, oui. J\'avais entendu que l\'abjuriste Belmara possédait un vieux livre d\'histoires, mais j\'ignorais qu\'elle l\'avait emporté en Outreterre. Je suis certain que son esprit sera apaisé de savoir que vous l\'avez trouvé et rapporté chez elle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10306,'Nous faisions souvent des commentaires sur la façon qu\'avait Luminrath de porter cette cape avec absolument tout. Pour lui, le rouge allait tout aussi bien avec le blanc, le noir, le pourpre, le bleu, le jaune, l\'orange et le vert. Il ne portait jamais la même robe deux jours de suite, mais la cape était toujours là...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10307,'<Le protecteur sourit en entendant le nom de Cohlien.>$B$BVous avez absolument raison au sujet du chapeau. Il le portait en permanence et ne le perdait jamais de vue.$B$BEn quelques occasions, un de ses collègues mages, que je ne nommerai pas, a "emprunté" le chapeau et l\'a caché pour lui faire une farce. Inutile de dire que sous la menace d\'un éclair de givre de Cohlien, il a vite changé d\'avis.$B$BLe petit Cohlien va me manquer. Il savait comment s\'y prendre avec les femmes elfes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10309,'Waou, regardez-moi ça... un cœur de saccageur gangrené qui bat ! Enfin, il ne "bat" pas à proprement parler, mais vous voyez ce que je veux dire.$B$BJe suis si impatient de l\'utiliser. Ou bien peut-être le vendre. Je connais quelques cré... euh, clients que cela pourrait intéresser.$B$BTenez, vous avez largement mérité votre paie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10310,'Voilà une excellente nouvelle, mon ami !$B$BDrijya et vous nous avez rendu un grand service. Maintenant que ce portail dimensionnel est hors d\'usage, les démons de la région ne pourront plus obtenir de renforts.$B$BPermettez-moi de vous récompenser d\'une façon digne du Consortium.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10311,'J\'espère que Gahruj vous a envoyé pour m\'aider à accomplir ma mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10312,'<Le protecteur Valemort accepte le registre que vous lui tendez et le feuillette.>$B$BHmm...$B$BOn dirait que j\'avais raison. Il y a une constante.$B$BLes fantômes les plus agressifs et dangereux correspondent aux membres du Kirin Tor les plus puissants et de plus haut rang qui habitaient au village. Les villageois et les marchands semblent oubliés en comparaison. Qu\'est-ce que cela signifie ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10313,'Voilà des nouvelles inquiétantes, $N. Les niveaux d\'énergie dimensionnelle émanant des canalisations sont dangereusement élevés.$B$BNous devons trouver un moyen d\'éteindre les manaforges, ou le peu qu\'il reste de l\'Outreterre sera déchiqueté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10315,'Tout ce que nous pourrons faire pour les encourager à arrêter ce qu\'ils font avec ces manaforges sera une bonne chose.$b$bIl semble absolument impossible de leur faire entendre raison. Et selon moi, il apparaît clairement que quoi que ce soit que leurs chefs aient en tête, ils sont fous.$b$bEn guise de récompense pour vos loyaux services en faveur du Consortium, j\'aimerais vous payer en espèces sonnantes et trébuchantes, si cela ne vous offense pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10316,'Un orbe luminescent repose sur un piédestal de forme carrée. Au premier abord, il semble s\'agir d\'un dépôt d\'énergie magique, mais de quel type d\'énergie, et à l\'usage de qui ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10317,'<Le contremaître parle à voix basse.>$b$bVous êtes venu me tuer ? Hmph. Mais les éthériens ne savent pas tout, n\'est-ce pas ?$b$bJe ne suis pas celui que vous cherchez, croyez-moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10318,'Un grand seigneur garde funeste ? Comme c\'est étrange ! Qu\'est-ce que la Légion ardente peut bien faire là-bas ?$b$bAlors comme ça certains elfes de sang désertent. Nous garderons cela à l\'esprit si nous tentons jamais de prendre cet endroit par la force. Voilà au moins une bonne nouvelle que nous pouvons tirer de cette histoire, non ?$b$bS\'il vous plaît, $N, acceptez ceci, avec ma gratitude la plus profonde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10319,'Excellent travail, $N. La possession du phylactère sera la clé de notre victoire. Lorsque commencera votre combat face à Naberius, je vais le briser, ce qui le rendra sensible à vos attaques.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10320,'La destruction de Naberius est un grand accomplissement, $N. Je ne peux m\'empêcher de penser que nous aurions eu une chance contre les forces de Kael\'thas si le disciple avait choisi le bon camp ce jour-là.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10324,'Merveilleux ! Vous devenez un sacré chasseur, $N.$B$BÇa vous dirait de me ressembler encore plus ? Eh bien voici votre chance ! Pendant que vous chassiez, j\'ai confectionné ces objets avec des peaux de chevreuil qui me restaient. Faites votre choix !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10325,'Faire face aux démons de la Légion ardente et aux sectateurs fous qui les vénèrent n’est pas un mince exploit, $N. Vous avez fait preuve de beaucoup de courage et de volonté. Continuez ainsi, et votre renom au sein de l’Aldor ne cessera de croître.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10327,'Vous continuez à faire la preuve de votre valeur, $N. Combattez les ennemis de la Lumière partout où vous les trouverez, vos actions seront généreusement récompensées.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10329,'Bien sûr qu\'il a fonctionné ! Je suis un maître-espion, mes informations sont toujours exactes.$B$BQuoi qu\'il en soit, j\'ai une nouvelle mission très intéressante pour vous. Vous voulez que je vous en parle ? Bien sûr que vous voulez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10331,'Oh, merci ! Je peux enfin me remettre au travail. Vous devez penser que je suis fou de travailler sur la pièce qui me vaudra le statut de compagnon hors de la forge, mais je ne veux pas courir le risque que l\'un des autres apprentis ne copie ce modèle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10332,'Maître Rhonsus m\'a appris tout ce que je sais de mon métier. J\'honorerai sa mémoire en mettant mes compétences au service du peuple de Kirin\'Var.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10333,'Quoi ?! Il m\'a appelée son « associée » ? Je suis sa femme !$B$BEt il a dit que ma langue est acérée ! Ooohh, attendez que je rentre à la Zone 52, je vais lui boxer les grands machins verts qui lui servent d\'oreilles !$B$BMais je suis contente de vous voir. Il avait raison sur un point : j\'ai bien besoin de votre aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10334,'<Vous sortez la clochette de votre sac et la faites tinter avant de la montrer à Marguerite, qui semble la reconnaître. La vache vous laisse lui passer le collier de la cloche au cou et vous regarde, attendant visiblement quelque chose de vous.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10335,'Vraiment ? Vous ne dites pas ça pour vous payer ma bandelette ? C\'est une nouvelle fantastique !$B$BMaintenant que le travail de préparation de base est terminé, je vais pouvoir faire monter mon équipe dans les ruines et voir ce que nous pouvons y trouver.$B$BJe vous en remercie, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10336,'Excellent travail.$B$BMaintenant que les démons de Culuthas sont morts, Zephyrion pourra conduire son équipe de fouilles dans les ruines de Farahlon en toute sécurité.$B$BAcceptez cet argent en témoignage de ma gratitude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10337,'Marguerite, c\'est bien toi ?$B$B<Le fermier se tourne vers vous.>$B$BMerci de m\'avoir ramené ma Marguerite, $N. Je ne pourrais pas vivre sans elle !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10338,'Cela fait à présent trois manaforges que vous avez éteintes, $N. Kael\'thas doit être en train de piquer une crise.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10339,'Nous devons rassembler toutes les données stockées dans cette zone.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10341,'Bon travail, $N. L\'armée de Kael ne se remettra pas si facilement du coup que vous lui avez infligé aujourd\'hui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10342,'D\'accord ! C\'est terminé pour l\'ingrédient numéro 1.$B$BMaintenant, si vous êtes toujours partant, nous allons passer à quelque chose qui donnera à l\'huile de lauze le petit punch en plus qui permettra de projeter la fusée-de-Néant jusqu\'au Néant distordu... ou dans l\'oubli, on verra.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10343,'Une bombe de mana ?$B$B<Morran fait tourner le fragment entre ses doigts.>$B$BC\'est quasiment impensable ! Même les esprits les plus brillants de Dalaran n\'auraient jamais pu concevoir une telle arme. La puissance même de la perturbation engendrée a dû créer une déchirure dans le Néant, et ouvrir à ces créatures un accès vers nos terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10344,'Vous avez parlé à Runetog ? C\'est un bon nain qui sait garder ses griffons en bonne forme et prêts à la bataille.$B$BJe suis Griffongar, commandant de la halte du Fracas. Je sais qu\'il n\'est guère beau à voir, mais ce morceau de roche est une base vitale pour les sorties dans les Flammes infernales. Vous verrez des griffons décoller et atterrir sans interruption !$B$BSi j\'ai un conseil ? Gardez votre matériel bien arrimé, l\'estomac vide et le regard vers l\'horizon... si la halte du Fracas commence à chanceler, agrippez-vous à quelque chose qui ne risque pas de se mettre à flotter !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10345,'Vous m\'avez sauvé les bandelettes, $N. Le Protectorat sera informé de ce que vous avez fait aujourd\'hui, mon amie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10346,'Comment cela s’est passé, cette fois ? Vous me semblez en bonne forme… peut-être même assez pour une nouvelle tentative !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10347,'Les autres pilotes de coursier du vent n’ont que des compliments pour vous, $N. Vous avez réussi quelques beaux coups sur la Saillie abyssale. Continuez comme ça !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10348,'Un choix intéressant, vous ne trouvez pas ? Il vaudrait mieux que leurs propriétés curatives soient miraculeuses. Je fais payer beaucoup d\'argent pour une fleur d\'aspect tout à fait quelconque.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10349,'Oh, excellent ! Ça faisait longtemps que je voulais mettre la main sur un morceau de cette chose, mais Tola\'thion traînait les pieds.$B$BIl est censé m\'aider à enquêter sur les événements étranges qui se déroulent à la crête Tombeciel. Au lieu de ça, il envoie là-haut de pauvres naïfs comme vous - sans vouloir vous vexer - se faire massacrer.$B$BSi vous me donnez le cristal, je pourrai peut-être trouver le lien entre les colosses et lui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10351,'Goliathon ? Pathaleon le Calculateur ?$B$BKAEL\'THAS !?$B$BLe prince Kael\'thas est mêlé à cela ?$B$B<La lieuse de terre fulmine.>$B$BC\'est de la pure folie que ce qu\'il a fait ! Larguer des cristaux géants depuis le ciel et anéantir la terre ! Ce ne peut être que l\'œuvre d\'un dément !$B$BJe vous assure que maintenant que nous savons quoi faire, l\'Expédition cénarienne va contrer toutes les tentatives de leurs forces de refaire une chose pareille.$B$BNous avons une grande dette envers vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10353,'Et Ya-six ? S\'en est-il sorti ?$B$BJ\'espère bien que oui. Je ne pouvais pas leur envoyer de renforts... L\'Ethereum couvre la région entière à présent.$B$BToutes mes excuses, j\'ai presque oublié votre récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10363,'Well, well. Even more runecloth.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10366,'$N, je vous attendais.$B$BTullas m\'a chanté vos louanges et je suis impatient de poursuivre votre formation sur le chemin de la Lumière. Venez me trouver lorsque vous serez prêt à vous ouvrir à une meilleure compréhension de vos compétences et pouvoirs, et je vous guiderai.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10367,'Je vous remercie, $N. Mon peuple sera bientôt libre grâce à vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10368,'Je le sens, $N ! Les esprits reviennent à nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10369,'C\'est la vérité, $N. J\'étais autrefois Naladu le Gardien de la Terre.$b$bC\'est moi qui ai trahi les autres aînés crapuches en échanges de vaines promesses de pouvoir. Vous pouvez me mépriser si vous le souhaitez. Tout ce qui m\'importe, c\'est que ma tribu soit à nouveau libre et que les esprits nous soient revenus.$b$bJe ne vais pas rejoindre le reste de la tribu, mais je peux mourir en paix à présent. Que l\'esprit de la terre trouve un nouveau serviteur parmi mes frères.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10380,'C\'est donc terminé. Nous venons ici, traquons les créatures et les abattons à la demande de nos maîtres. Il n\'y a pas de quartier, la pitié n\'est pas envisagée.$B$BParfois, ça fait réfléchir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10381,'Les mauvaises nouvelles que vous apportez remplissent mon cœur de chagrin. Deux de nos ennemis les plus mortels se sont alliés et l\'un des fils les plus chéris de Shattrath s\'égare.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10382,'Salutations, $C. Je suis content que ce vieux nain croûteux ait finalement daigné nous envoyer un peu d\'aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10384,'<Vous tenez la cellule de données de façon à ce qu\'Ameer puisse lire les plans.>$B$BRien... Qu\'ils soient maudits ! Ils sont malins, mais pas autant qu\'Ameer !$B$BCe que je suis sur le point de vous demander est très dangereux. Je comprendrai si vous ne souhaitez pas continuer, créature de chair.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10385,'Le Protectorat a désormais atteint son but fondateur.$b$bL\'Ethereum n\'est pas là pour pourchasser Dimensius, mais pour rejoindre le Vide !$b$bSes membres manipulent l\'énergie du Vide traitée dans cette manaforge pour incarner leur propre essence en une créature appelée traqueur sombre.$b$bIls utilisent sans aucun doute un proto-accélérateur pour effectuer la transformation.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10388,'Ah, $N, vous venez juste à temps. Nos éclaireurs ont découvert que les positions de la Légion sur la crête derrière nous sont en réalité des "camps de forge". C\'est là que les démons construisent leurs saccageurs gangrenés infernaux. Si nous agissons rapidement contre eux, nous pourrons en perturber la production !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10389,'Bravo, $N. Je savais que vous seriez victorieux ! La défaite de la Légion se rapproche !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10391,'Je savais que vous aviez du répondant, $N, mais cette fois vous vous êtes vraiment surpassé ! On a entendu l\'explosion de ces maudits canons jusqu\'ici ! Ça apprendra à la Légion à sous-estimer les fils de Durotar !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10393,'Vous avez eu raison de porter ceci à mon attention. Il pourrait s\'agir d\'un ordre de production pour des saccageurs gangrenés supplémentaires - ou bien de nouveaux plans d\'attaque ! Il faudra quelque temps pour le déchiffrer. Laissez-moi. Je vous convoquerai quand j\'en saurai plus.$B$B<Le magistère Faucon-de-sang vous adresse un signe approbateur au moment où vous vous tournez pour partir.>$B$BVous avez l\'esprit vif, $N. Je suivrai vos progrès avec intérêt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10394,'Eh bien, je dois dire que je suis impressionné, $N. Je ne pensais pas que vous seriez à la hauteur de cette mission. Bon travail. Très bon travail, même.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10397,'Excellent travail ! Voilà qui devrait réduire le nombre de démons tentant de nous envahir de manière drastique. Je ne sais comment vous remercier pour votre aide, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10399,'J\'avais prévu cette grande victoire, $N. Les naaru vous sourient en ce jour.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10403,'Êtes-vous venu pour aider ma tribu, mort-vivant ? Comme c\'est étrange. Bien peu nombreux sont ceux qui se soucient du sort des Roués en ces terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10405,'Excellent ! Passons maintenant à la calibration de l\'appareil.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10406,'Grâce à vous, leurs plans sont ruinés ! Plus qu\'une chose maintenant... Salhadaar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10408,'Cela faisait un millier d\'années, peut-être plus, que Salhadaar avait commencé sa croisade contre tous ceux qui s\'opposaient à lui. J\'ai du mal à croire que nous ne le verrons plus jamais... Vous nous avez rendu à tous un grand service, $N, et pour cela vous serez récompensé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10409,'C\'est terminé, $N. Socrethar a été détruit.$B$BLes autres et moi-même nous remettrons de nos blessures, $N. Le courroux de la magie de Socrethar a cependant été trop violent pour le jeune Kaylaan. Pas même ma prière la plus puissante n\'a pu le relever.$B$BC\'est un malheur insupportable qu\'une si jeune personne tombe au combat. Cependant, sa volonté a finalement été assez forte pour qu\'il se remettre de la corruption de la Légion, et cela nous apporte quelque réconfort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10410,'Socrethar... Je me souviens de ce nom. Il était autrefois un chevalier de la Lumière renommé et l\'orgueil était son seul défaut.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10411,'J\'espère qu\'il n\'est pas trop tard. Avez-vous remarqué des gelées d\'une taille anormale dans les environs de la zone où se déversent les rebuts du vide ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10412,'Bon travail, $N. Vous finirez peut-être par devenir un allié utile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10413,'QUOI !? Vous avez affronté une horreur du Vide ? Et vous êtes toujours en vie ?! Incroyable !$B$BCet échantillon vaut son pesant d\'or. Une découverte pareille mérite une récompense.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10416,'Comme promis, $N. La totalité de la puissance brute du livre, condensée dans une seule rune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10417,'<Mihrdad hoche la tête et examine les résultats du diagnostic.>$B$BVoilà qui est préoccupant. Les dégâts sont bien plus graves que ce que j\'aurais cru. Je peux demander des outils à la Foudreflèche pour entamer les réparations, mais ce ne sera guère utile à moins que nous ne sachions ce qui cause ces dégâts sur notre équipement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10418,'La région semble déjà plus dégagée. Les dômes sont assez utiles, mais leur défaut essentiel est la façon dont ils incitent par endroit à une croissance effrénée, ce qui accélère la prolifération et la stature des espèces locales.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10420,'Regardez comme les matières souillées se désintègrent. Regardez le métal devenir poussière.$b$bLa Lumière purifie tout et ce qui reste est immaculé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10421,'Les substances gangrenées sont éliminées de ce monde. Seuls les résidus de Lumières demeurent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10422,'Merci, $N. Tyralius a subi de lourdes blessures mais nous pensons qu\'il survivra.$b$bIl a parlé d\'étendues de prisons, tout à fait similaires à celle dont vous l\'avez libéré. Des prisons remplies de créatures provenant de tout l\'univers !$b$bNous resterons en contact, au cas où nous aurions besoin de les ouvrir. Le Consortium a déjà manifesté son intérêt quant à l\'envoi d\'équipes là-bas et il travaille à une technologie permettant de briser les verrous de l\'Ethereum.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10423,'<Vous vous présentez et rapportez les résultats des diagnostics de Mihrdad à l\'écodôme Terres-médianes.>$B$BMihrdad n\'est guère plus qu\'un technicien, mais il est très consciencieux. Si ses observations sont exactes, nous devrons faire parvenir ces diagnostics au reste des générateurs des dômes aussi vite que possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10424,'Ces résultats correspondent exactement à ceux de Mihrdad, mais pourquoi ? Selon moi, la seule explication possible serait qu\'une partie de l\'équipement du générateur du dôme est en panne ou bien ne s\'y trouve plus. Cela affaiblirait significativement les dômes et détruirait leur équilibre comme l\'indiquent les diagnostics.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10425,'<Le commandant Ameer semble satisfait.>$b$bBon travail, créature de chair ! Ce soldat pourrait bien être la clé de la destruction de toute l\'installation de l\'Ethereum.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10426,'Ça alors ! La focalisation de l\'énergie du dôme semble poursuivre l\'accélération de la croissance au point qu\'elle engendre une agressivité extrême. Si nous parvenons à utiliser cette technologie, nous devrons nous assurer de la calibrer correctement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10427,'Excellent travail. J\'observerai attentivement ceux que vous avez marqués pour voir s\'ils se développent aussi rapidement que les autres formes de vie du dôme.$B$BSi nous parvenons à la garder sous contrôle, cette technologie pourrait être employée pour faire renaître la vie dans les zones dévastées d\'Outreterre et d\'Azeroth.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10428,'Ma famille… Mais qu\'ai-je fait ? Qu\'aurais-je pu faire ?$B$BPourquoi suis-je puni ainsi ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10429,'<Aurine accepte le cœur.>$B$BMême pour une créature de cette taille, ce cœur est beaucoup trop gros. Il luttait pour réussir à soutenir le corps gigantesque de la créature. J\'ai peu de doutes sur le fait qu\'elle serait morte avant d\'avoir atteint la moitié de son espérance de vie normale.$B$BMême avec tous les risques que ça présente, je suis déterminée à convaincre le Consortium de partager leur technologie. Le projet est trop prometteur pour que j\'abandonne maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10430,'Il a l’air un peu bizarre. Visiblement, Ghabar ne pensait pas à Raz-de-Néant quand il l’a conçu.$B$BN’ayez pas l’air si surpris, $N. Raz-de-Néant est un environnement plutôt stable, comparé à certains endroits dans lesquels j’ai travaillé. En tout état de cause, un dôme qui flanche est toujours un souci.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10431,'Orelis n\'envoie pas d\'autre aide que vous ? Il doit vous tenir en haute estime.$B$BFinissons-en avec tout ça.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10432,'C\'est énorme, $N. Énorme !$b$bVoren\'thal voudrait sûrement être mis au courant le plus vite possible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10433,'<Shauly admire ostensiblement les fourrures.>$B$BElles sont magnifiques, absolument magnifiques ! Je vous les payerai au prix fort ! Combien pour conserver vos services ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10434,'<Vous vous présentez et dites à Audi que Shauly vous a envoyé.>$B$BAh, oui, nous attendions quelqu\'un pour nous aider, euh, à transporter des, euh, marchandises.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10435,'Excellent travail ! La partie la plus difficile du projet est terminée. Maintenant, nous n\'avons plus qu\'à trouver un moyen de les rapporter à la Zone 52 et attirer l\'intérêt de l\'Expédition cénarienne. Il devrait y en avoir assez pour nos propres besoins plus de quoi faire un petit profit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10436,'Beau travail. On dirait que tout est en ordre. Nous sommes prêts à commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10437,'Excellent. Avec ces fragments, nous pouvons calibrer une bombe qui détruira le conduit du Vide en haut d\'Ultris. Une fois le conduit du Vide détruit, la connexion de Dimensius avec le Vide sera rompue et il se retrouvera sans défense !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10438,'Le moment est venu de frapper ! Sans la déchirure, Dimensius est vulnérable aux attaques physiques et magiques !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10439,'Depuis mille ans, nous ne connaissons que le combat. Nous défendons notre peuple à la fois contre les attaques des créatures du Vide et contre celles de certains éthériens.$B$BMaintenant, l\'un de nos pires ennemis a enfin trouvé la mort.$B$BJe vous remercie au nom de cent millions d\'éthériens, créature de chair.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10440,'J\'envoie immédiatement mes techniciens faire les réparations.$B$BLes soupçons de sabotage de Tashar m\'inquiètent, cela dit. Je ne connais personne d\'assez téméraire pour nous dérober notre technologie. Personne qui sache de quoi nous sommes capables, en tout cas. Le moment semble être venu de sécuriser la Foudreflèche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10442,'Oh, merveilleux, vous devez m\'apporter l\'aide que j\'ai demandée il y a déjà des semaines au Guet de l\'épervier.$B$BEnfin, maintenant vous êtes là, et il y a beaucoup à faire. J\'ai une tâche à vous confier qui sera parfaite pour commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10443,'Oh, merveilleux, vous êtes sûrement là pour m\'apporter l\'aide que j\'ai demandée il y a des semaines déjà au temple de Telhamat.$B$BJe suis heureuse de vous voir, il y a beaucoup à faire. J\'ai une tâche à vous confier qui sera parfaite pour commencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10444,'Des pièces de bombe. Mes soupçons étaient donc justifiés. Croyez-moi, j\'aurais préféré avoir tort.$B$BTrès bien, vous et moi avons dans ce cas une triste tâche à accomplir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10445,'La puissance détenue même par une aussi petite quantité d\'eau du Puits d\'éternité est incommensurable.$B$BJe vois clairement chaque événement lié dans le temps à Hyjal… la création du second Puits d\'éternité, l\'emprisonnement d\'Illidan, l\'enchantement de l\'Arbre-monde et... oui ! La bataille du Mont Hyjal.$B$BNous devons nous hâter, cette voie temporelle est menacée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10446,'VOUS AVEZ RÉUSSI ! VOUS AVEZ SAUVÉ LE BASTION ALLÉRIEN !!$B$BMaintenant que leur troupes sont décimées, que leur chef est mort et que leur bombe de mana est détruite, nous pouvons tous respirer.$B$B$N, je n\'ai jamais vu un tel altruisme… un tel héroïsme ! Je vous en prie, acceptez ceci, de notre part à tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10447,'VOUS AVEZ RÉUSSI ! VOUS NOUS AVEZ SAUVÉS ! VOUS AVEZ SAUVÉ LE FORT DES BRISE-PIERRES !!$B$BMaintenant que leur troupes sont décimées, que leur chef est mort et que leur bombe de mana est détruite, nous pouvons tous respirer.$B$B$N, je n\'ai jamais vu un tel altruisme… un tel héroïsme ! Je vous en prie, acceptez ceci, de notre part à tous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10448,'Des pièces de bombe. Mes soupçons étaient donc justifiés. Croyez-moi, j\'aurais préféré avoir tort.$B$BTrès bien, vous et moi avons dans ce cas une triste tâche à accomplir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10449,'Ah, oui. Le sang du clan Mâche-les-os. Ces orcs ont éveillé ma curiosité... Ils sont toujours les monstres dépravés du passé, mais leur force et leurs pouvoirs sont bien supérieurs à ce que j’avais entendu dire...$B$BEh bien, si nous nous mettions au travail ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10450,'Ha ! Vous avez donc rencontré les Mâche-les-os, nos cousins les plus dépravés. Bien joué, $N. Mon seul regret est que tous n’aient pas abandonné l’existence et répandu leur sang pour calmer mon ressentiment !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10455,'Voilà qui était rapide. Vous êtes sûr que vous en avez tué autant que nécessaire ?$B$BTrès bien, si vous voulez encore nous aider, il y autre chose…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10456,'Bien. Je verrai si je peux confectionner quelque chose d\'utile avec ces queues.$B$BIl ne fait aucun doute que la Horde trouvera un moyen de repeupler ses meutes de loups, mais pour l\'instant nous pouvons respirer un peu mieux.$B$B$N, si vous le voulez bien j\'aimerais vous confier une autre tâche pour la défense de Sylvanaar et du Bosquet vivant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10457,'Maintenant que vous avez renforcé la protection du bosquet, je suis beaucoup plus sereine.$B$BVous avez mérité notre estime et nos remerciements, $N.$B$BÀ propos, je viens à l\'instant de me rappeler qu\'il y a une autre affaire dont nous devons nous occuper !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10458,'Quand toutes les âmes élémentaires de la région auront été placées dans ce totem, nous entrerons en communion avec elles pour découvrir si nous pouvons faire quelque chose pour la vallée d\'Ombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10476,'Vous commencez à montrer votre valeur en tant qu\'allié et combattant. Continuez à bien travailler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10477,'Vous continuez à nous prouver votre valeur, $N. Que votre force ne vous abandonne jamais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10479,'Vous êtes assurément un allié de poids, $N. Affronter face à face les ogres d\'Outreterre n\'est pas à la portée de tout le monde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10480,'Il ne manque plus que l\'air, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10481,'Permettez-moi de vous récompenser pour avoir entrepris une tâche aussi ardue et héroïque.$B$BEt maintenant, mettons-nous au travail ! Reculez-vous un peu que je puisse planter le totem et libérer les âmes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10482,'Très bien ! Je pense que leur perte se fera sentir à la citadelle des Flammes infernales. Même si ce sombre bastion nous menace encore et semble quasiment imprenable, c’est avec des actions audacieuses comme celle-ci que nous finirons par trouver un moyen de vaincre les gangr’orcs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10483,'Ah, vous avez récupéré l’insigne d’un orc de l’Orbite-sanglante ? Bien. C’est une honte qu’ils utilisent nos propres symboles contre nous, et qu’ils bafouent l’honneur de nos camarades qui ont succombé face aux monstres à peau rouge !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10484,'Merci, $N. Mon cœur est lourd à la vue de ces talismans, car ils soulignent les terribles pertes que nous autres du bastion de l’Honneur avons subies contre les gangr’orcs. Mais cela me réconforte de voir que vous les avez vaincus. Si nous parvenons à en tuer suffisamment, nous sortirons peut-être vainqueurs de cette guerre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10485,'Vous avez réussi ! Morkh n’est plus ! Maintenant nous allons avoir une chance contre ces monstres de gangr’orcs !$B$BMerci, $N. Votre contribution à notre effort de guerre est allée au-delà de nos espérances.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10486,'Voilà qui a pris moins de temps que je ne le pensais. Vous êtes sûr que vous en avez tué autant que nécessaire ?$B$BTrès bien, vous pouvez maintenant faire autre chose pour nous aider si vous le voulez bien. Quelque chose de bien plus important.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10487,'Vous avez non seulement affaibli leurs défenses, mais nous allons faire bon usage de cette poussière pour renforcer les nôtres contre l\'Alliance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10488,'Maintenant que vous avez fortifié les loups et amélioré les défenses de la Crête dentelée, nous pourrions peut-être à nouveau tourner notre attention vers des affaires plus importantes, comme le problème des ogres ?$B$BVous avez fait du bon travail. Nous aurions besoin de l\'aide de quelqu\'un de capable tel que vous, si vous décidez de rester.$B$BQuoi que vous fassiez, vous avez gagné mon respect et mon estime.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10489,'Le tronc de Fermebranche Basseracines ! Vous l\'avez débité vous-même ?$B$BJe parie que oui. Vous savez, Rexxar et moi recherchons un $C jeune et fort, comme vous l\'êtes, pour nous aider, en particulier avec les problèmes que nous posent les ogres. Pensez bien à revenir me voir à ce sujet.$B$BBon, ce tronc est une belle preuve, et ça veut dire que vous êtes venu chercher la récompense et pas écouter mes bavardages. Je vous en prie, faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10490,'Nous nous retrouvons donc. J\'ai observé de loin vos progrès, $C. Je suis satisfait.$B$BIl est temps pour vous d\'apprendre à communier avec l\'eau, de découvrir ses mystères et de vous y abandonner afin d\'apprendre à la maîtriser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10502,'C\'est un bon début pour garantir la sécurité de Sylvanaar et du bosquet.$B$BS\'ils sont moins nombreux, les Masse-sanglante y réfléchiront à deux fois avant de nous attaquer ici.$B$BSi seulement c\'était le seul clan ogre à nous poser problème…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10503,'C\'est un bon début pour asseoir notre position ici contre les ogres.$B$BUne fois leur population décimée, les Flèchelame y réfléchiront à deux fois avant d\'essayer de reprendre le bastion des Sire-tonnerre.$B$BSi seulement c\'était le seul clan ogre à nous poser problème…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10504,'Vos sorties contre les Masse-sanglante et les Flèchelame ont grandement contribué à garantir l\'avenir de Sylvanaar. Nous ne cherchons certes pas à nous étendre au-delà de ce territoire, que nous avions trouvé inoccupé à l\'origine, mais nous n\'allons pas non plus tolérer qu\'on cherche à nous détruire.$B$BVous nous avez rendu un grand service, et je veux vous en récompenser en vous offrant la considération de l\'Alliance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10505,'Vos sorties contre les Masse-sanglante et les Flèchelame ont grandement contribué à garantir l\'avenir des Sire-tonnerre. Nous ne tolèrerons aucun obstacle sur le chemin de notre destinée.$B$BVous avez bien travaillé contre ces ogres, et je veux vous en récompenser en vous offrant la considération de la Horde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10506,'Je suis heureuse d\'apprendre que cela a marché. Moins il faudra tuer de créatures de la Nature, mieux ce sera.$B$BAprès tout ce que vous avez déjà fait pour nous, je dois dire que je commence à vraiment apprécier votre compagnie.$B$BPrenez soin de vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10509,'Vous ne pouvez savoir tout ce que cela représente pour les Clairvoyants, $N. Veuillez m\'excuser, le temps que je reprenne mon souffle et que j\'évalue la situation.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10510,'Ooh, si on peut se fier à leur aspect, ce sont de très beaux spécimens. Je suis si impatiente de déballer mes outils pour pouvoir les examiner de près !$B$BMerci beaucoup !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10511,'Qu\'est-ce que c\'est que cette odeur ? Oh non, ne me dites pas que c\'est cette bière ogre ?!$B$BJ\'ai presque peur de la goûter. Eh bien, qu\'est-ce que je risque après tout ? Cul sec !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10512,'Ah, hahaha ! C’est bien ce que je pensais. Je suppose que les ogres sont prêts à boire n’importe quoi.$B$BQu’est-ce qu’ils peuvent être bêtes !$B$BBon, et bien je peux dire que même si je n’ai pas eu ma gnole, mes vacances ont très bien commencé grâce à vous.$B$BVous savez quoi… ? On a plein de trucs ici qui ne nous servent à rien. Je peux vous offrir quelque chose ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10513,'Les mots de damnation ? Jamais entendu parler. Suivez mon conseil : laissez les morts en paix.$B$BMais puisque vous avez fait tout ce chemin, il y a quelques affaires pour lesquelles j\'aurais besoin d\'aide. Qu\'en dites-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10514,'Vous dites qu\'il y avait beaucoup plus d\'écorcheurs que ce à quoi vous vous attendiez ? On dirait qu\'il est temps de faire le ménage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10515,'Voilà qui apprendra à ces maudits animaux à ne pas tuer mes sangliers ! Bien joué, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10516,'J\'ai maintenant une grande dette envers vous, car vous m\'avez aidé à retrouver mon honneur. Mais notre travail ici n\'est pas encore terminé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10517,'Très bien. Vous êtes un $C plein de ressources, voilà qui est certain.$B$BJe me demande si vous pourriez encore faire quelque chose pour moi et Sylvanaar ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10518,'Le casque de Babin Graillebâfre et une bannière de Flèchelame ?$B$BLe redresseur de torts et vous avez été très malins d\'imaginer ce plan.$B$BEn maintenant l\'attention du clan Masse-sanglante sur le bastion de Flèchelame, vous nous soulagez de la pression qu\'ils commençaient à nous faire ressentir ici.$B$B$N, veuillez accepter cet humble présent de Sylvanaar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10519,'Comprenez-vous ce qu\'il faut faire ? Trouvez les fils d\'Oronok. Trouvez mes garçons…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10521,'<Grom\'tor grogne.>$B$BC\'est bien que vous soyez venu. Cette vermine vient de perdre ses boyaux. On les aura maintenant !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10522,'Ceci doit être rapporté à père immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10523,'Quand la Formule de damnation sera reconstituée, nous mettrons fin à la malédiction !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10525,'Au fond de la mine de draenéthyste ? Le clan Masse-sanglante a dû la voler aux ogres Flèchelame.$B$BBah ! C\'est trop loin… Trop enfoncé dans le territoire Masse-sanglante pour que je puisse m\'y rendre.$B$BMais vous… Vous connaissez le chemin. Vous irez pour moi !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10526,'Maintenant, vous m\'impressionnez ! Savez-vous seulement combien d\'autres sont morts en essayant de récupérer toutes ces reliques ?$B$BNous avons de la chance que vous travailliez avec nous, $N. Même si vous êtes un peu lent.$B$BPermettez-moi de vous récompenser pour votre dévouement à notre cause. Faites votre choix, mais faites-le sagement. Quand vous aurez terminé, j\'irai rendre les reliques pour apaiser les fantômes du bastion des Sire-tonnerre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10527,'Le corps d\'Ar\'tor gît, inerte, suspendu dans les airs. Vous ne savez pas à quand remonte sa mort, mais vous êtes pris d\'une grande douleur pour Oronok.$B$BPeut-être devriez-vous essayer de redescendre le corps pour le rapporter à son père.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10528,'Vous glissez la clé cristalline dans les fentes à la base de chacun des cristaux démoniaques.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10537,'Son nom signifie « le séjour du héros » dans ma langue maternelle. Il sonne vrai, même maintenant, dans cette époque où tous nos héros sont morts...$b$bC’est comme s’il en survenait toujours un.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10538,'Très bien. Maintenant je vais pouvoir effectuer mes tests plus facilement...$b$bMerci, $N. Vous avez un talent considérable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10540,'<Ar\'tor flotte entre l\'existence et le néant.>$b$bOn dirait que mon heure approche, héros.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10541,'<Oronok essuie la larme et vous sourit.>$b$bMerci. Je vous le promets, héros, un chant d\'honneur sera écrit en votre nom.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10542,'Ah, ça, ça plaît à T\'chali ! Mais je suis pas sûr de ce que les ogres ont mis dedans. C\'est pas l\'odeur du tabac de T\'chali que je sens dans le narguilé.$B$BC\'est pas grave, T\'chali est content. Assez content pour vous demander autre chose, en fait.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10543,'T\'chali est content que Korgaah et Grimnok Champ-d\'honneur mangent les pissenlits par la racine comme lui.$B$BMais la soif de vengeance de T\'chali n\'est pas apaisée. Il y a encore une chose que vous devez faire !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10544,'Hahaha, douce est la vengeance !$B$BMais T\'chali voit bien que vous voulez partir maintenant que vous l\'avez aidé pour sa vengeance. Ça me va… Faut vivre votre vie.$B$BJe vais vous dire, T\'chali a plein de jolis objets qui restent dans sa tombe. Vous prenez celui que vous aimez le plus !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10545,'Bonne nouvelle ! Cette bière va être utile pour ce que T\'chali va vous demander de faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10546,'<Borak reste silencieux un moment.>$B$BJ\'observe ces elfes depuis maintenant des semaines, en essayant de me faire une idée d\'où ils ont caché la troisième partie de la Formule de damnation.$B$BPour l\'instant, je n\'ai pas réussi à trouver le moindre indice. La seule chose que je sais, c\'est qu\'Illidan envoie un émissaire du Temple noir ici une fois par jour.$B$BCet émissaire est inattaquable. Je l\'ai suivi pendant toute une semaine pour trouver un moyen de le séparer de son garde du corps. Malheureusement, le garde du corps ne le quitte pas une seconde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10547,'Vous avez un œuf d\'arakkoa pourri ? Pourquoi ne pas me l\'avoir dit plus tôt ?! Je crois qu\'on peut faire affaire.$B$B<Tobias sourit, dévoilant une bouche pleine de caries et de saletés.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10550,'Et maintenant, installons le piège !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10553,'Khadgar m\'envoie une nouvelle recrue ? Nous allons vous donner du travail, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10554,'Bienvenue, $N. Je suis heureuse d\'apprendre que vous avez décidé de nous rejoindre dans notre mission. Que la Lumière vous protège toujours.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10555,'En parcourant les pages de notes griffonnées dans l\'écriture allongée des arakkoa lashh\'an, vous tombez sur un pictogramme représentant les cercles de pouvoir que vous avez aperçus au Voile Lashh.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10557,'C\'est fou, vous avez réussi ! Et sans la moindre ecchymose ou fracture multiple ! Vous voyez, je vous avais bien dit que ça se passerait comme sur du velours !$B$BVoici votre paye, $N, même si j\'y avais déjà ajouté les frais médicaux dont vous n\'aurez pas besoin... considérez-les comme un bonus !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10562,'Merci d’avoir relevé mes hommes, $N. Avec votre aide, et celles d’autres combattants, nous arriverons peut-être à tenir. Malheureusement, se contenter de résister n’est pas suffisant. Nous devons prendre l’offensive.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10563,'<Le chef d\'escadrille Nuainn écoute votre rapport, de plus en plus inquiet à chacune de vos phrases.>$B$BDonc vous me dites qu\'ils ont largement assez d\'infernaux pour intensifier le bombardement ? Si nous ne les arrêtons pas avant qu\'ils ne mettent en branle la phase suivante de leur plan, le Bastion des Marteaux-hardis est condamné.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10564,'Bien joué, $N ! J’aimerais pouvoir dire que la Légion va abandonner la lutte après un revers comme celui-là, mais vous et moi savons parfaitement que ce ne sera pas le cas. La Forgemort dont vous avez appris l’existence lors de votre mission de reconnaissance sera notre prochaine cible.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10565,'Ah, regardez comme il brille ! Je veux l\'essayer tout de suite.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10567,'Vous l\'avez !$B$BGrâce à ce pendentif, je vais pouvoir vous harmoniser avec les arakkoa grishnath de façon à ce que vous puissiez comprendre leur langage.$B$BAvec ceci, nous pourrons comprendre mieux encore les arakkoa, ainsi que la nature du Corbeau. J\'aurai besoin de votre aide pour cela.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10568,'Les tablettes de Baa\'ri ! Oui, voilà qui pourrait nous fournir de précieuses informations.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10569,'<Kieran parcourt les pages du journal.>$B$BLe texte est en grande partie inintelligible, mais j\'arrive à en déchiffrer des passages. Ça parle des préparatifs d\'un sort qui auraient mal tourné, de morts, et d\'une situation qui dégénère. Et il y a aussi une remarque étrange sur un « déserteur ».') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10570,'<Borak prend la missive que vous lui tendez et commence à lire.>$b$bLes petits futés ! C\'est une directive d\'Illidan qui désigne le prochain endroit où la formule doit être cachée. Apparemment, ils la déplacent sans cesse. Cela ne nous dit pas où elle se trouve en ce moment... Si seulement nous pouvions transmettre la missive maintenant que nous connaissons le lieu suivant.$b$bDommage que le sceau de la missive soit brisé, il est inutilisable.$b$bHrm... Et si...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10571,'C\'est bel et bien l\'écriture d\'Akama. C\'est vraiment triste, quand on pense ce qu\'est devenu quelqu\'un d\'aussi sage et aimé que lui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10572,'<Le chef d’escadrille glisse la batterie dans la plaque de blindage et referme l’appareil en hochant la tête.>$B$BVoilà qui devrait faire l’affaire. Ça devrait être une sacrée explosion, si j’en crois ma vieille expérience.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10573,'<Le nain hoche la tête.>$b$bCe sera bien d’avoir des renforts. Nous avons rassemblé quelques informations préliminaires sur ce que fabrique ici le Conseil des ombres, mais je me sentirai mieux quand nous pourrons lancer une action contre eux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10574,'Oui ! Les quatre fragments du médaillon. Et maintenant, assemblons-les...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10575,'Nous vous attendions, $N. Akama a dit que vous viendriez tôt ou tard.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10576,'Bien joué, $N. J\'espère que vous êtes une bonne actrice. La prochaine étape de mon ambitieux plan va nécessiter un certain talent dramatique !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10577,'Maintenant, tout ce qu\'il vous reste à faire est d\'aller récupérer la formule. Facile, non ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10578,'Enfin ! Le fragment de la formule nous appartient !$B$B<Borak place le fragment dans une boîte.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10579,'Dès que les trois fragments de la formule seront réunis, les mots anciens seront révélés.$b$bRécupérer ce fragment a sans doute été difficile. Vous devez être récompensée pour votre héroïsme.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10580,'SYLVANAAR ? LE COMMANDANT OMBRECIEL ?$b$bÇA NE COMPILE PAS !$b$bRECULEZ AVANT QUE JE NE SOIS CONTRAINT D\'ÉMETTRE DES SONS TRÈS PUISSANTS !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10581,'Bon, vous voulez vous rendre utile ? Bien, j\'ai justement ce dont vous avez besoin pour faire vos preuves.$b$bJe pense que ça vous plaira.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10582,'J’aurais bien aimé être là-bas avec vous ! Ça me démange de me servir de mon marteau, mais ma mission est d’observer, pas de tuer.$b$bMaintenant que vous avez percé un trou dans leurs défenses, occupons-nous d’arrêter la production de la Forgemort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10583,'<Ewan secoue la tête en prenant le sac que vous lui tendez.>$B$BJe ne crois pas que Flanis avait compris à quel point la Forgemort était bien gardée. Maintenant que nous savons ce qui se passe réellement là-bas, je ne le critique pas. J’aurais seulement voulu que Flanis le sache quand il s’est infiltré dans les lieux.$B$BJe ne peux qu’espérer qu’il y a quelque chose là-dedans qui nous aidera à fermer la Forgemort une bonne fois pour toute.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10584,'Excellent ! Avec toute l’énergie que vous avez récupérée, nous allons continuer à pouvoir faire fonctionner nos machines pendant un certain temps.$B$BLe Zephyrium Capacitorium est un vrai goinfre, pour la consommation d’énergie !$B$BJ’espère que vous charger de ces électromentaires n’a pas été trop difficile. J’ai pensé à une autre mission à vous confier, et j’ai l’impression qu’elle risque d’être un peu plus dangereuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10585,'Bien joué, $N. L\'interruption de l\'invocation du Conseil des ombres nous rapproche un peu plus de la fermeture de la Forgemort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10586,'<Vous faites votre rapport au chef d\'escadrille et lui remettez les ordres capturés.>$b$bLa défaite du porteguerre Razuun aurait dû signifier la fin de nos ennuis avec la Légion, mais ces plans décrivent un plan bien plus important que je ne l’avais imaginé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10587,'Regardons ces armes de plus près, $N. Hmmm... voilà qui est plutôt perturbant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10588,'<Le soigneterre Torlok vous prend la formule de damnation.>$b$bVous avez fait ce que les éléments vous demandaient. Pour cela nous vous sommes reconnaissants. Mais même si vous allez recevoir votre récompense, la menace est toujours présente. Les esprits du feu sont en émoi. Une déclaration a été faite. Il en est un autre qui connaît la formule de damnation.$b$bJe sais, c’est un peu abscons, mais c’est tout ce que les esprits ont bien voulu me faire savoir. Ça et ce symbole…$b$b<Le soigneterre Torlok se retourne et montre le ciel.>$b$bQu’est-ce que ça peut bien vouloir dire ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10589,'Voyons voir si je peux trouver comment fonctionne ce truc…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10590,'Très bien, $N. Peut-être avez-vous le goût de la vengeance, après tout...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10593,'La reine banshee vous a bien conseillée. C\'est exactement ce dont j\'ai besoin pour combiner les fragments.$B$B<Mehlar observe la liane qui s\'entrelace et lie les fragments entre eux.>$B$BVoilà ! Je vais la nommer Plaie-du-Fléau. Soyez prudente quand vous l\'utiliserez, car elle vous sert contre sa volonté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10594,'Oh, c\'est extraordinaire ! Je ne m\'en serais jamais douté... C\'est presque comme si ces cristaux étaient vivants.$B$BJe me demande s\'il existe une sorte de relation symbiotique entre eux et les drakes du Néant ?$B$BMerci, merci beaucoup ! Je vous prie d\'accepter un petit quelque chose de mon bric-à-brac que je préférerais mourir plutôt que porter moi-même.$B$BAprès tout, l\'un d\'entre eux vous ira peut-être.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10595,'Je suis impressionné de voir que tu as réussi à survivre au carnage. Ça fait peut-être de toi la personne dont j’ai besoin pour une mission dangereuse.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10596,'<Le garde de sang écoute votre rapport, de plus en plus inquiet à chacune de vos phrases.>$B$BComment ça, ils s\'apprêtent à intensifier le bombardement ? Nous ne le permettrons pas. Retourne là-bas et occupe-toi d\'eux tant qu\'il reste quelque chose du village d\'Ombrelune !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10597,'<Gulmok glisse la batterie dans le boîtier et le referme.>$B$BÇa devrait faire l\'affaire. Je voudrais pas être dans le bastion quand ce truc va exploser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10598,'<Gulmok hoche gravement la tête.>$B$BCe n’est pas le moment de se reposer sur des lauriers, $N. On n\'est pas encore sorti d\'affaire. J’ai de nouveaux ordres pour toi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10599,'<L’orc hoche la tête.>$B$BCe sera bien d’avoir des renforts. Nous avons rassemblé quelques informations préliminaires sur ce que fabrique ici le Conseil des ombres, mais il est temps que le couperet tombe.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10600,'Je me suis aussi promené là-bas pour fracasser quelques crânes, mais j’ai reçu des ordres stricts de ne pas engager l’ennemi.$B$B<L’éclaireur grommelle, en imitant assez bien la voix du garde de sang Gulmok.>$B$BBon, mettons-nous au travail, il s’agit maintenant d\'arrêter la production ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10601,'<Zagran secoue la tête en prenant le sac que vous lui tendez.>$B$BJe vous ai dit que c\'était un imbécile. J\'espère qu\'il y a quelque chose là-dedans qui justifie le temps que vous avez passé à sa recherche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10602,'Bien, on fait des progrès. Cela nous rapproche un peu plus de la fermeture de cette installation et de notre paisible retour au village d\'Ombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10603,'<Vous faites votre rapport au garde de sang et lui remettez les ordres capturés.>$B$BBon travail, $N, mais ne croyez pas qu’on va vous donner une médaille pour ça. Laissez donc les elfes de la nuit décorer leurs mignons petits uniformes, s’ils en ont envie. Les vrais guerriers partagent leurs récits de bataille devant une chope de bière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10604,'Enfin, nous avons un moyen pour repousser la Légion loin d\'Ombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10606,'Ah, c’est exactement ce dont on a besoin. Bon, je n’accuserai jamais la Légion de faire de la littérature, mais avec ça, on pourra faire notre boulot.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10607,'C\'est réellement troublant. Les arakkoa sont longtemps restés pacifiques. Ce culte du Corbeau n\'était rien de plus qu\'un rassemblement d\'exclus et de déments.$B$BMais ils ont gagné en influence, nous ne pouvons le nier. Peut-être ce Corbeau est-il plus important que nous ne le croyions.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10608,'Bon débarras, c\'est tout ce que j\'ai à dire. Sales vermines !$B$BBon, si vous êtes certain d\'avoir éliminé ces saletés, j\'ai un petit projet de recherches à vous confier. Je pense qu\'il vous plaira.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10609,'Vous ne pouvez pas savoir à quel point ces recherches pourraient être importantes. Merci !$B$BSe plonger dans l\'étude de ces essences sera intéressant. Je suis particulièrement curieux de voir si l\'énergie du Néant qui a transformé les œufs de dragons noirs en œufs de drakes du Néant aura des effets bénéfiques sur le sujet de mes recherches.$B$BEn fait, je pense que vous devriez être la première personne à tester les bénéfices de ma petite décoction. Tenez, prenez ces échantillons et utilisez-les quand vous en aurez besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10611,'J\'ai les informations que je cherchais. Encore quelques petits réglages, et vous pourrez prendre le contrôle d\'un saccageur gangrené en un rien de temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10612,'Formidable ! Vous avez réussi à faire ce dont tous les chevaucheurs de griffons du bastion des Marteaux-hardis étaient incapables ! Vous avez brisé l\'avancée de la Légion ardente et vous nous avez sauvés de la destruction qu\'auraient semée les infernaux. Vous méritez notre plus profonde gratitude, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10613,'Je dois vous avouer quelque chose, $N. Je suis très impressionné par ce que vous êtes arrivé à accomplir. Avoir détruit la capacité de la Légion à guerroyer en Ombrelune nous donne l’occasion de consacrer nos efforts à d’autres ennemis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10614,'Qu\'est-ce qui vous amène dans notre village ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10615,'Ah oui, Dertrok. Nous avons brièvement discuté des arakkoa. Je dois dire que nous ne nous y… intéressons pas de la même manière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10617,'Ce sont là des cocons de belle facture. Je vois que vous avez pris le coup de main pour les récupérer.$B$BNous avions tenté d’élever nos propres larves d’aile-de-soie, mais malheureusement les petites ne produisent pas assez de soie pour nous être utiles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10618,'Merci, $N. Nous allons les utiliser bien plus vite que vous ne pourriez le penser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10619,'Gloire aux naaru, $N. Vous avez accompli la volonté de la Lumière en défaisant les disciples d\'llidan.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10620,'Pas mal pour un débutant. En fait, nous avons un petit groupe de crânes d\'œufs qui veut aller "observer" les éthériens et leur technologie dans le nord. Ils seront ravis d\'apprendre que vous leur avez frayé un chemin.$B$BTenez, prenez ça. Nous n\'en avons pas beaucoup, mais vous en aurez probablement l\'usage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10622,'Très bien, $N. Votre allégeance ne fait plus de doute. Vous pouvez voir Akama à présent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10623,'<Grokom accepte le fragment d\'arme que vous lui tendez.>$B$BCela faisait longtemps que je n\'en avais pas vu. Non seulement ce fragment est fait d\'un minerai rare, mais il ne devait pas être utilisé pour une arme ordinaire, $N.$B$BCes runes imprègnent la lame d\'une puissance capable d\'éliminer les démons. Cela prouve à quel point la Légion hait Illidan, si elle est prête à équiper ses propres troupes d\'armes qui détruisent les démons. Nous pourrions tourner ceci à notre avantage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10624,'Votre monde est sur le point de changer, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10626,'Ils devraient parfaitement faire l\'affaire. Et maintenant, forgeons-les pour en faire quelque chose de plus utile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10627,'Ils devraient parfaitement faire l\'affaire. Et maintenant, forgeons-les pour en faire quelque chose de plus utile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10628,'Salutations, $N. Il faut que nous ayons une grande discussion.$B$BJ\'espère que vous êtes du genre ouvert d\'esprit. Peu de gens comprennent les décisions que je prends. Seuls mes collaborateurs les plus proches réussissent à concevoir les augures que je vois et les signes que j\'attends.$B$BQuand j\'ai choisi de rallier la cause d\'Illidan, je me reposais sur des visions annonçant l\'anéantissement de mon peuple si je ne le faisais pas. J\'ai patiemment attendu d\'autres signes ou visions... l\'exode de Velen... l\'ouverture de la Porte des ténèbres... et maintenant, votre arrivée...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10629,'Vous sentez très très mauvais. Mais vous avez trouvé mes clés ! Merci mille fois. Je peux enfin faire démarrer mon déchiqueteur et gagner de l\'argent. J\'aurai bientôt assez pour quitter l\'Outreterre. Je me demande pourquoi vous restez, moi je hais cet endroit. Vous ne préféreriez pas être à Baie-du-Butin ?$B$BAller pêcher, peut-être ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10630,'Tous ces gan\'arg vont sûrement dégager maintenant. Je serai de retour à Baie-du-Butin dans la semaine. Je suis si impatient de reprendre la pêche. Partir pour l\'Outreterre était une erreur. Suivez mon conseil et repartez par où vous êtes venu. Passez un peu de temps à Strangleronce, ou bien peut-être, si vous êtes d\'humeur aventureuse, allez au cratère d\'Un\'goro. Mais ne restez pas ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10632,'Bon travail, gamin. Cela vaut toutes les souffrances du monde, si la vie d’un de mes soldats est épargnée grâce à votre travail.$B$BJe pense que vous devriez vous aussi tirer un petit bénéfice d’avoir sué sang et eau pour récupérer ces dents. Comme nous allons avoir une nouvelle série d’armes, pourquoi n’en prendriez-vous pas l’une des miennes ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10633,'Fielsang ? Eh bien, je n’avais pas entendu ce nom depuis une éternité !$B$BAprès la Deuxième guerre, Fielsang est revenu ici avec ses chevaliers de la mort. Incapable de supporter la terrible nature de sa nouvelle forme, et privé du soutien de son chef vénéré Gul’dan, Fielsang a mis fin à ses jours.$B$BSi son esprit arpente encore ces terres, c’est vous qui me l’apprenez. Quoi qu’il en soit, je dois pouvoir effectuer une divination pour en apprendre plus, si vous acceptez de m’aider.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10634,'Il me faut tous les objets pour être en mesure de connaître le destin de Fielsang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10635,'Quand j\'aurai les trois morceaux en ma possession, je pourrai deviner où se trouve Fielsang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10636,'Ce n\'est qu\'en réunissant les trois objets que je pourrai deviner les secrets que vous désirez si vivement connaître !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10637,'Espérons que cette diversion nous donnera assez de temps pour apprendre tout ce dont nous avons besoin des terrains d\'entraînement de Karabor.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10639,'Vous avez fait quoi ? IMBÉCILE !$B$BVous devez réparer cette maladresse. Après tout, c’est votre faute. Prenez l’un de ces casques. Chacun d’eux est imprégné de l’essence de la cendre semperardente que vous avez récupérée pour moi. L’essentiel, c’est qu’ils vous permettront de percevoir les fantômes d’Ombrelune, y compris Teron Fielsang.$B$BSi vous réussissez à retrouver Teron Fielsang, détruisez-le.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10640,'Vous venez de loin, étranger. Je suis surpris que la personne qui vous a envoyé, qui qu\'elle puisse être, ait entendu parler de moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10641,'Vous avez prouvé que vous n\'étiez pas atteint par la corruption de la Légion, et les ennemis de mes ennemis sont mes amis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10642,'<Zorus commence à fabriquer quelque chose avec la cendre.>$B$BC\'est fait. Contemplez les... Lunectoplasmes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10643,'Vous prétendez entendre les fantômes qui vous murmurent des choses ? Et ils ont parlé de Teron Fielsang ?$B$B<Zorus frissonne.>$B$BOui... je connais Teron Fielsang. Disons que j’en ai entendu parler. On le croit mort depuis très longtemps. De quoi pouvaient bien parler ces fantômes ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10644,'Fielsang ? Dites donc, je n’ai pas entendu ce nom depuis des siècles !$b$bAprès la Deuxième guerre, Fielsang est revenu ici, avec ses chevaliers de la mort. Incapable de supporter sa nouvelle forme effrayante, et dépourvu du soutien de son chef bien-aimé Gul’dan, Fielsang s’est suicidé.$b$bS’il parcourt ces terres aujourd’hui sous la forme d’un esprit, c’est une nouveauté pour moi. Mais peut-être qu’avec votre aide, je pourrais effectuer une divination pour en savoir plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10645,'Vous avez fait quoi ? IMBÉCILE !$B$BVous devez réparer cette maladresse. Après tout, c’est votre faute. Prenez l’un de ces casques. Chacun d’eux est imprégné de l’essence de la cendre semperardente que vous avez récupérée pour moi. L’essentiel, c’est qu’ils vous permettront de percevoir les fantômes d’Ombrelune, y compris Teron Fielsang.$B$BSi vous réussissez à retrouver Teron Fielsang, détruisez-le.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10646,'Vous connaissez cette histoire à présent. Il ne reste qu\'une chose à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10647,'Un sacré machin qu’vous avez là, l’ami. ! Et vous aurez vot’récompense, vous en faites pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10648,'Ouaip, voilà votre récompense. N\'allez pas tout dépenser au même endroit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10652,'Bienvenue, $C. Essayez de ne pas révéler notre position.$B$BNous ne tiendrons pas longtemps si les acolytes de Kael nous détectent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10655,'Vous continuez à faire la preuve de votre valeur, $N. Combattez les ennemis de la Lumière partout où vous trouverez, vos actions seront généreusement récompensées.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10656,'L\'armée solfurie de Kael est extrêmement bien entraînée. Très impressionnant, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10657,'Youhou, ça a marché ! Pour être honnête je n\'y croyais qu\'à moitié... J\'avais calculé une probabilité de vingt-trois virgule soixante-douze pour cent que vous imploseriez après le troisième coup de foudre.$B$B<Toshley sourit innocemment.>$B$BDonc, maintenant que nous savons que la sphère fonctionne, nous ne devrions plus avoir de problèmes avec nos besoins en énergie pour le Zephyrium Capacitorium. Enfin, tant que nous pourrons trouver des volontaires pour aller là-bas et se faire griller.$B$BQuoiqu\'il en soit, vous avez été à la pointe de nos progrès et vous méritez un petit quelque chose en retour !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10660,'<Le chercheur Tiorus prend les rates et commence son examen.>$B$BIl se pourrait que cela prenne un peu de temps. Prenez ces pièces pour votre bon travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10661,'<Gnomus s’empare des rates, l’air affamé.>$B$BVoici vos pièces, comme promis. Je vous appellerai si j’ai besoin de plus de rates.$B$BElles sont si délicieuses… Ex-rate-ordinaires, si j’ose m’exprimer ainsi !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10664,'<Le forgeron accepte les matières premières avec un hochement de tête appréciateur.>$B$BCela suffira. Mais j’ai encore besoin d’un certain nombre de choses qui vont être plus difficiles à trouver.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10665,'C\'est encore plus efficace que ce à quoi je m\'attendais ! Avec une telle puissance, je pourrais forger une douzaine de lames !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10667,'Ça devrait faire l\'affaire. J\'aurais préféré en avoir un peu plus, mais pour être honnête, nous avons déjà eu de la chance d\'en trouver par ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10668,'Vous n\'êtes donc pas du côté d\'Illidan. Vous avez fait un pas de plus vers mon entière confiance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10669,'Beau travail, $N. Il se souvenait encore du jour où je l\'ai percé de ma lance ? C\'était il y a si longtemps...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10671,'Ces morceaux devraient faire parfaitement l\'affaire. Mais comment faites-vous pour supporter cette odeur ?$B$BJ\'espère que le jeu en valait la chandelle... Moi, je suis juste heureuse de ne pas avoir dû récupérer ça moi-même !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10672,'Écoutez, il n\'y a pas un instant à perdre. En observant les dimeurtrodons marqués, j\'ai découvert qu\'ils obéissent tous à un gigantesque, je dirais même plus, ÉNORME, dimeurtrodon appelé Gangréchine la Très-Grande.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10673,'Enfin ! Je possède enfin une protection totale contre la lave ! Bien sûr, vous allez pouvoir profiter vous aussi de cette technologie, $N. Vous l’avez bien mérité !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10674,'Hé ! Attendez une minute !!$B$BOh, ce n’est pas bon signe…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10675,'Bon débarras ! Merci d’avoir mis fin à leur déformation macabre de la magie et de la technologie.$B$BEn tant que vrai héros de tous les gnomes, je vous offre par la présente notre plus grand honneur… des convertisseurs de puissance, et un objet de votre choix là-dedans. Je sais que cela vous sera utile !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10677,'C’est fantastique, mais je viens de recevoir des nouvelles encore plus stupéfiantes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10678,'J’ai besoin de rester seul un moment, $N. Merci de votre aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10680,'C\'est une bonne chose que vous soyez venue, $R. Nous avons beaucoup de travail à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10681,'C\'est une bonne chose que vous soyez venu, $R. Nous avons beaucoup de travail à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10682,'QUOI ?! Ils ont rejeté notre proposition ?$B$BQuel outrage ! Nous allons à leur rencontre en toute bonne foi, et ils n\'essayent même pas de trouver un compromis ?$B$BTrès bien, nous allons voir ce que nous allons voir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10686,'Nous vous attendions, $N. Akama a dit que vous viendriez tôt ou tard.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10688,'Cela devrait nous donner un peu de temps... espérons que nous en aurons assez pour en apprendre plus long.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10689,'Vous venez de loin, étranger. Je suis surpris que la personne qui vous a envoyé, qui qu\'elle puisse être, ait entendu parler de moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10690,'Incroyable. Vous avez tué Rema tout seul ?$B$BÀ vous voir, je dirais que ce n\'est pas impossible. Vous savez, on recherche un $C jeune et fort comme vous l\'êtes pour nous aider, en particulier avec les problèmes que nous posent sans cesse les ogres. Pensez bien à revenir me voir à ce sujet.$B$BBon, vous avez indéniablement mérité la récompense que j\'avais mentionnée sur cet avis de recherche.$B$BJe vous en prie, faites votre choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10691,'Nombreux sont ceux qui paieraient une somme considérable pour le livre que vous portez. Quel dommage que nous devions le détruire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10701,'Oh ! Oh... vous vous êtes occupé de Néantroche. Voilà une bonne nouvelle !$B$BMaintenant que nous nous sommes débarrassés de ce gêneur, ce sera plus facile d\'exploi... euh, gérer les ressources de la Désagrégation.$B$BHeureux d\'apprendre qu\'il n\'écrasera plus ces pauvres élémentaires innocents.$B$BComment pourrais-je jamais vous remercier ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10702,'Fantastique ! Si d\'aventure j\'avais de nouveau du travail de grunt à confier, je vous contacterai.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10703,'Bon travail ! Voici quelques pièces pour vous récompenser de vos efforts. Si on a encore besoin de nettoyer le coin, je saurai qui appeler.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10704,'Je suis impressionné, $N, même si je n\'en attendais pas moins du héros qui nous a rendu le cristal d\'Ata\'mal.$B$BDonnez-moi les deux pièces et je ferai en sorte qu\'elles soient combinées en leur forme finale. Vous aurez alors accès à l\'Arcatraz.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10705,'Le voyant cendrelangue est mort depuis longtemps. En retournant son corps, vous voyez quelque chose d\'écrit sur le sol.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10706,'Oui… bien sûr ! Tout devient clair maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10707,'Le cristal ! Sa puissance… dans mes mains !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10709,'Donc mon père est en vie. Je ne m’attendais pas à ce qu’il me pardonne… Cela n’a jamais été son genre. Mais j’avais espéré que les années amoindriraient la colère qu’il a dû ressentir lors de mon départ.$B$BIl y a trente ans, j’ai quitté les Mok’Nathal pour rejoindre la Horde sur Azeroth. Leoroxx y était farouchement opposé mais, à l’époque, il ne m’avait donné aucune raison de rester. Cependant, j’avais espéré recevoir un meilleur accueil que celui-ci.$B$BIl voulait avoir un Mok’Nathal pour fils, et il en a un, maintenant, même s’il refuse de le voir.$B$BJe dois lui ouvrir les yeux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10710,'Incroyable ! Une fois encore vous êtes vivant ! Je suis un bien meilleur ingénieur que je ne croyais !$B$BTenez, voici votre dû ! Et revenez me voir plus tard... J\'aurai d\'autres expériences à faire et il me faudra encore des cobayes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10711,'Saperlipopette ! Vous êtes déjà de retour ! Je vous ai vu décoller et partir comme une fusée ! J’étais persuadé qu’il vous faudrait au moins un mois de convalescence pour soigner vos jambes brisées après ce vol ! Vous êtes coriace, et brave, et incroyablement casse-cou ! Mais surtout... brave !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10712,'Oh, vous avez pris des mesures avec la girouette néantine ? Formidable ! Les données recueillies avec cet instrument, combinées avec mes mesures de magie druidique, vont être hautement informatives !$B$BOh, je vous assure que vous ne pouvez pas imaginer les applications que je vais en tirer !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10713,'Merci, $N.$B$BNous allons veiller à ce que la faune se rétablisse au plus vite, mais faire repousser les arbres, surtout de façon naturelle, est un processus bien plus long.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10715,'Très bien, vous avez réussi cette tâche simple et banale. Maintenant, donnez-moi les glandes pour que j’accomplisse la partie la plus difficile du travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10717,'Oh, ils ont l\'air splendides. Ces sectateurs ont vraiment le coup d\'œil en matière d\'artisanat.$B$BDommage qu\'ils s\'en servent à de si mauvaises fins.$B$BEt maintenant que nous avons les filets, accepteriez-vous de donner encore un ou deux petits coups de main à la pauvre créature que je suis ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10718,'De qui me parlez-vous ? De Garm Frère-Loup ? Il était le dernier chef du clan des Sire-tonnerre. Si vous êtes entré en communion avec son esprit, alors ce doit être vrai.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10719,'C\'est très intéressant. Perturbant, mais intéressant. Je me demande si Samia sait qui est ce Kolphis Sombrécaille.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10720,'Pendant de longues années, j’ai perfectionné les différents moyens d’entrer en contact avec la nature. Ceci n’est qu’une infime partie du potentiel inexploité que les bêtes peuvent vous apporter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10722,'Nous attaquer ? Nous exterminer ? Je ne pense pas !$B$BCe convent de l\'Aile noire a encore beaucoup à apprendre s\'il pense qu\'on peut se débarrasser si facilement de l\'Expédition cénarienne !$B$BQu\'est-ce qu\'ils ont dit ? Faire volte-face est fair-play !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10723,'Les ogres de la Masse-sanglante et leur maître, Gorgrom, ne causeront plus d\'ennuis à Mok\'Nathal.$B$BCependant, je m\'inquiète des conséquences que pourraient avoir nos actions en ce qui concerne les autres gronns. Je crois que nous devons achever ce combat une fois pour toutes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10724,'Ce sera bien d\'avoir à nouveau l\'appui de Leokk.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10733,'Votre service nous fait honneur, $N. Je vais libérer le pouvoir de votre chevalière ! Regardez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10734,'Votre service nous fait honneur, $N. Je vais libérer le pouvoir de votre chevalière ! Regardez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10735,'Votre service nous fait honneur, $N. Je vais libérer le pouvoir de votre chevalière ! Regardez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10736,'Votre service nous fait honneur, $N. Je vais libérer le pouvoir de votre chevalière ! Regardez !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10738,'Les services que vous nous avez rendus n’ont pas été oubliés, $N. Votre chevalière a peut-être gardé la même apparence, mais son pouvoir grandit à chaque fois que vous nous prouvez votre loyauté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10740,'Les services que vous nous avez rendus n’ont pas été oubliés, $N. Votre chevalière a peut-être gardé la même apparence, mais son pouvoir grandit à chaque fois que vous nous prouvez votre loyauté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10741,'Vos états de services ne sont pas passés inaperçus, $N. Votre chevalière conserve son aspect initial, mais ses pouvoirs continuent de croître à mesure que vous démontrez votre loyauté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10742,'La bataille était difficile et vous vous êtes bien battu, $N. Ce fut un honneur pour moi d\'affronter Goc à vos côtés. Ma gratitude dépasse les mots.$B$BLes Mok\'Nathal devraient être informés de ces grandes défaites, mais je ne suis pas encore prêt à leur faire face. Je sais ce que pense mon père et je connais mon cœur. J\'ai encore beaucoup à apprendre et à accomplir pour lui montrer que je suis véritablement son fils.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10744,'<Kurdran écoute votre rapport.>$B$BVoilà effectivement de très bonnes nouvelles ! Il y a quelques jours encore, je n\'aurais même pas cru possible de briser le siège de la Légion sur le bastion.$B$BVous avez non seulement stoppé leur offensive, mais vous avez aussi détruit le gros de leur machine de guerre ! Votre valeur vous vaut la gratitude du clan Marteau-hardi, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10745,'<Le suzerain écoute votre rapport.>$b$bCe sont d’excellentes nouvelles ! Tenir le front contre les infernaux de la Légion nous coûtait bien trop de ressources. Je ne m’attendais pas à ce que mes hommes craquent, mais leur endurance était mise à rude épreuve.$b$bVous avez prouvé votre valeur à la Horde, aujourd’hui. La garde de Kor’kron sera pour toujours honorée de combattre à vos côtés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10747,'Ma parole, c\'est plus que je n\'espérais ! Vous méritez vraiment des éloges pour cet exploit !$B$BVoilà une belle couvée de dragonnets noirs pour commencer. À les examiner, bien sûr.$B$BJe vous en prie, acceptez ceci en guise de paiement. J\'insiste !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10748,'Nous pouvons maintenant respirer, sachant que nous sommes débarrassés du chef de notre ennemi. Plus encore, vous avez sauvé toute la chaîne de montagnes de leurs pillages.$B$BQuels qu\'aient été leurs ultimes objectifs, vous les avez contrecarrés !$B$BVous avez toute notre gratitude, $N. Veuillez accepter ce gage de notre estime, ainsi que notre hospitalité autant qu\'il vous plaira.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10749,'Ce n’est pas un travail très ragoûtant, cette utilisation de poison. Mais il accomplira ce dont nous avons besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10750,'Vraiment, ces satanés morveux préparent un coup tordu. Nous devons en apprendre plus...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10751,'Vous n\'allez pas le croire, grunt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10752,'Ainsi, Thundris Tissevent pense encore qu’on a besoin de prendre soin de moi ? Il faudrait que je lui rappelle qui a sauvé la vie à qui, il semble avoir oublié que c’est moi qui l’ai sorti d’un mauvais pas.$B$BBon, eh bien maintenant que vous êtes là, $R, je vais peut-être vous trouver quelque chose à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10753,'Je ne ressens aucune fierté car nous avons détruit ce qu\'Elune a créé. Il fallait cependant arrêter la corruption. Vous avez bien agi, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10754,'Serait-ce possible ? Laissez-moi regarder ce moule de plus près.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10756,'Nazgrel veut que je travaille à une clé ? Est-ce qu\'il n\'aurait pas oublié que nous sommes sur un champ de bataille ? Il y a des lames et des lances à forger !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10757,'Excellent. Voyons voir ce que ça donne.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10759,'<L’arakkoa caquette.>$B$BOui, c’est moi le déserteur mentionné dans le journal du commandant. J’attends le jour où d’autres verront le danger que représentent ceux que j’appelais autrefois mes frères.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10760,'<Le sergent examine les pages du journal.>$B$BJe ne vois pas grand-chose d\'utile ici, mais il y a une ou deux entrées qui pourraient être intéressantes. On dirait que ces arakkoa préparaient une sorte de rituel magique complexe jusqu\'à leur mort, mais pourquoi ? Il y a aussi une note étrange qui parle d\'un "déserteur".') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10761,'<L’arakkoa caquette.>$B$BOui, je suis le déserteur mentionné dans le journal du commandant. J’attends le jour où les autres se rendront compte de la menace posée par ceux qu’autrefois j’appelais des frères.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10762,'Une clé ? Danath devrait plutôt nous faire travailler à des engins de siège !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10763,'Bon, essayons maintenant. Voyons ce que vaut l\'artisanat gangr\'orc.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10764,'Vous avez réussi, ma fille ! Il ne vous reste plus qu\'à l\'emporter à la citadelle des Flammes infernales et à tuer des orcs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10765,'Alors ils essaient de gagner la faveur des géants, hein ? J’ai un plan qui pourrait mettre fin à leur union contre-nature.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10766,'Ravi de vous rencontrer, $N. Je m’appelle Plexi.$b$bBon, je ne vais pas vous noyer sous les salamalecs. Nous savons tous deux pourquoi nous sommes ici. Il est temps de se mettre au travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10767,'Vous devez être la personne dont le garde de sang Gulmok m’avait annoncé l’arrivée, $r. J’ai un plan en tête, mais j’aurai besoin de votre aide pour terminer les préparatifs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10768,'Ah-ah ! Voilà qui devrait faire parfaitement l’affaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10770,'Ils sont trop nombreux pour que nous puissions jamais tous les tuer, mais vous m\'avez rendu espoir. J\'essaierai peut-être encore quelques siècles de plus de rendre la vie à mon bois bien-aimé.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10771,'Vous avez détruit un bon nombre de ces immondes petites bestioles. Cette pensée m\'apaise.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10772,'Vraiment, ces satanés morveux préparent un coup tordu. Nous devons en apprendre plus...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10773,'Vous n\'allez pas le croire, soldat !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10774,'Alors comme ça ils essayent de gagner la faveur des géants ? J’ai une idée qui pourrait être utile pour rompre cette union contre-nature.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10775,'Ah-ah ! Voilà qui devrait faire parfaitement l’affaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10777,'<Parshah examine le totem.>$B$BBien. Ce vieux totem n\'a pas perdu sa puissance avec les années, mais seul il ne suffira pas à arrêter le sombre Conclave.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10778,'Bon travail. Un tel trésor mérite mieux que d\'être enfermé dans un coffre sombre. Il sera utilisé à une fin digne de lui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10780,'<Parshah accepte les plumes couvertes de cendres, en secouant la tête.>$B$BCela aurait été préférable s’ils étaient morts ce jour-là, mais rien n’est simple. Que la magie de Gul’dan les ait transformés dans le type même de créatures qu’ils tentaient d’arrêter est un tour cruel du destin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10781,'Il faut mener une enquête sur ce Cachet cramoisi. Il représente une menace pour tout ce qui vit sur Draenor. Je vois le jour où son sombre maître devra répondre de ses crimes. C’est peut-être vous qui nous ferez justice, héros.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10782,'<Parshah prend avec précaution le bourdon que vous lui tendez.>$B$BCeci contient la puissance dont nous aurons besoin pour mettre fin aux activités du sombre Conclave au campement Sketh\'lon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10783,'Bonjour, $R. Je suis le baron Sablecrin. Les amis de Rexxar sont mes amis.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10784,'<Tor\'chunk vous adresse un signe de tête approbateur en constatant votre exploit.>$B$BVous ne cessez de m\'impressionner, $N. Chaque fois qu\'un de ces ogres puants est abattu, nous sommes plus près de nous débarrasser d\'un ennemi indigne de nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10785,'Hmm, un piège confectionné à partir d\'essence de feu de dragon ? Je me demande comment Sablecrin se procure des substances devenues si rares.$B$BPeu importe. La seule chose qui compte, c\'est que nous allons l\'utiliser pour tuer un fils de Gruul.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10791,'C\'est incroyable ! J\'ai entamé ce voyage sans savoir si l\'esprit du loup répondrait à nos appels, et maintenant j\'ai l\'impression qu\'il a toujours été là. Peut-être qu\'il l\'était vraiment, $N.$B$BPeut-être qu\'il attendait que les orcs se rendent compte des conséquences de leurs choix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10792,'Ha ! J’ai pu voir la fumée et les flammes de Zeth’Gor d’ici-même ! Puissent les démons de l’Orbite-sanglante être réduits en cendres et dispersés loin des yeux des orcs véritables !$B$BMerci, $N. Vous avez aidé à faire disparaître un affront à l’esprit de tous les orcs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10793,'Vous avez tué leur conquérant ? Alors nous n’avons pas de temps à perdre…$B$BLe Cachet cramoisi est un groupe constitué des sbires d’Illidan les plus puissants. Ils se trouvent au sommet de la chaîne de commandement des forces illidari stationnées en dehors du Temple noir. Ces soldats communiquent directement avec le Traître, ici, exécutant ses ordres sans poser la moindre question.$B$BCe sont les démons qui mèneront sans le moindre doute l’attaque contre ce monde, écrasant sans la moindre pitié tous ceux qui se mettront en travers de leur route.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10795,'Maintenant que Dorgok est mort, les ogres Masse-sanglante sont privés de commandement et la confusion règnera parmi eux jusqu\'à l\'avènement d\'un nouveau chef parmi leurs rangs.$B$BMerci, $C, je pense que nous pouvons respirer un peu mieux à présent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10796,'<Le lieutenant vous adresse un signe de tête approbateur en constatant votre exploit.>$B$BJe suis impressionnée, $N. Votre réputation semble amplement méritée.$B$BChaque fois qu\'un ogre est abattu, nous sommes plus près de nous débarrasser d\'un danger qui ne nous laissait aucun répit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10797,'Oh, comme c\'est joli. Ça ressemble beaucoup à ces gronns qui mènent à la baguette les ogres de Flèchelame.$B$BC\'est bizarre que vous l\'ayez trouvée dans les mains d\'un des chefs Masse-sanglante.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10798,'Ah, un envoyé de cette tant vantée Alliance. Dites-moi, laquais, pourquoi êtes-vous ici à me mendier cette chose, à la place de votre illustre chef ?$B$BSe pourrait-il qu\'il ait peur de moi ? Voilà qui dirait quelque chose sur vous que vous ne méritez pas, mais je ne sais pas encore exactement ce que c\'est.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10799,'Fort bien, voilà une tâche simple, si ce n\'est banale, d\'accomplie. Donnez-moi maintenant les glandes et je m\'occuperai de la partie difficile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10800,'<Le baron Sablecrin regarde à l\'intérieur du sac du gronn et a l\'air satisfait.>$b$bTrès bien, vous avez rempli votre part du contrat. Et maintenant, je vais offrir le piège au commandant Lamuraille.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10801,'Hmm, un piège confectionné à partir d\'essence de flamme de dragon ? Je me demande comment Sablecrin se procure des substances devenues si rares.$B$BPeu importe. La seule chose qui compte, c\'est que nous allons l\'utiliser pour tuer un fils de Gruul !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10802,'Bon travail, $N. Bon travail !$B$BJ\'imagine que nous n\'entendrons plus beaucoup parler des ogres et de leur maître.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10804,'Vous êtes un $R gentil et plein de compassion, mon ami.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10805,'Très bien, j’ai donc choisi sagement quand je vous ai sélectionné pour diriger mes combats. Il est temps maintenant d’amener les choses à un autre niveau, je pense.$B$BVous vous souvenez de cette babiole que vous avez volée pour moi, sous le nez de Grulloc ? Vous allez avoir l’occasion d’en faire bon usage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10806,'Vous vous êtes étonnamment bien battu pour un $R, et ce fut un honneur de vous avoir à mes côtés. Ma transformation a dû vous surprendre. J’espère qu’elle ne vous a pas trop étonné ? Bon, nous garderons le secret de ma véritable identité entre nous, n’est-ce pas ? En échange, et pour vous récompenser de vos bons et loyaux service, je vous laisse choisir l’une de ces babioles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10807,'Gloire aux Clairvoyants, $N. Vous avez bien suivi les ordres du Voyant en vainquant les disciples d\'llidan.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10808,'J’ai cherché un moyen d’arrêter le sombre Conclave pendant des années, et vous avez réussi là où j’ai échoué. Les sombres rituels du conclave ne nous menaceront plus, désormais.$b$bJe me suis souvent senti coupable d’avoir abandonné mes camarades durant ces dernières années, mais maintenant je sais que j’avais pris la bonne décision. Sans ma conscience vacillante de l’époque, j’aurais pu terminer sous la forme d’une ombre, comme eux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10810,'Ah, qu\'est-ce que vous avez là ? Laissez-moi regarder de plus près, $C. Oui, oui... c\'est exactement ce que je pensais. Je vais réparer ce masque pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10811,'Mes enfants m’ont parlé de vos exploits héroïques, $R. Mais il vous en reste d’autres à accomplir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10813,'Je suis votre débiteur, $N. Vous avez à nouveau bravé Zeth’Gor et tenu sa noirceur en votre sein. Je vais étudier l’œil et peut-être percer les secrets de son maître, Grillok.$B$BEspérons qu’il ne puisse plus utiliser sa magie !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10814,'Alors, nous aiderez-vous ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10816,'Excellent travail, $c. Puisse la Lumière continuer à vous protéger.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10817,'Vous avez gagné mon respect le plus extrême, aujourd’hui, $N.$B$BTuer un gangr’orc n’est pas une tâche facile. Massacrer une vingtaine d’entre eux est… eh bien… héroïque.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10818,'Ah, je vois que vous ne vous êtes guère pressé à répondre à mon appel.$B$BCe n’est pas grave, j’ai tout mon temps pour prendre ma revanche, et j’ai l’intention que vous soyez mon mandataire lors de la bataille à venir !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10819,'Qu\'est-ce que cela signifie ? Personne n\'a le droit de me déranger ! Parlez, ou je vous réduirai au silence pour toujours !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10820,'Voilà qui donnera une bonne leçon à ceux qui pensent qu\'on peut me désobéir...$B$BÀ propos... où est Vocifuneste ? Pourquoi est-ce vous qui m\'avez signalé cette révolte et pas elle ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10821,'Voilà de bonnes, de très bonnes nouvelles, $N. Je n\'aurais pu espérer issue plus favorable. Nous apprécions grandement le service que vous avez rendu à notre peuple, veuillez choisir l\'un des objets héroïques suivants.$B$BVotre nom restera pour toujours dans nos cœurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10824,'Les elfes de Kael sont extrêmement bien entraînés. Du très beau travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10825,'Oui, c\'est cet orbe que vous avez là ! Bizarre, il semble de fabrication arakkoa. Étiez-vous récemment à Grishnath ?$B$BD\'accord, ceci explique cela, mais je me demande quel dessein diabolique cet objet est censé servir. Bien que le mal émane de lui, il donne l\'impression d\'être connecté d\'une certaine manière au monde naturel.$B$BSi vous permettez, je vais essayer de l\'activer. Le mal est puissant à l\'intérieur, il y a là comme des restes de souvenirs...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10826,'Votre courage est sans faille, mon ami. Que l’on fasse savoir à tous que vous êtes un véritable allié de la prêtrise !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10827,'Détruisez les ennemis de la Lumière partout où vous les trouverez, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10829,'Salutations, minuscule $R. Les oiseaux de mes branches m\'ont murmuré que vous arriviez.$B$BÊtes-vous ici pour libérer les arbres des bois de leur possession ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10831,'<Nasmara examine l\'étoffe en la retournant dans ses mains.>$B$BCet échantillon est parfaitement réussi, $N. Vous ferez un excellent tailleur d\'étoffe lunaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10832,'<Gidge examine l\'essence d\'âme en peine du Néant.>$B$BMême un si petit échantillon de l\'essence de cette créature rayonne de puissance. J\'ai peut-être mal interprété ce qui se passait. Nous ne provoquons pas la colère des âmes en peine du Néant en prélevant de l\'énergie dans l\'environnement. Les âmes en peine et l\'environnement sont en fait une seule et même chose !$B$BN\'hésitez pas à m\'en informer si vous faites d\'autres découvertes, maintenant que vous êtes un tailleur de feu-sorcier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10833,'Je vois que votre visite à l\'autel a été couronnée de succès. Le changement survenu en vous est si subtil que peu le remarqueront, mais il est bien là, à n\'en pas douter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10834,'Ah, oui. Tout comme certains de ceux qui perdent une main ou une jambe au combat continuent parfois à sentir leur membre manquant, je me demande si Grillok tente encore de se raccrocher à son œil perdu dans ses rêves les plus obscurs...$B$BJe vais moi aussi rêver de cela, et si la fortune est avec nous, alors peut-être apprendrai-je ce qui a poussé Grillok et les orcs de l’Orbite-sanglante à succomber aux démons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10835,'Ah, un rapport d’Albreck ? Très bien. La Société royale des apothicaires travaille d’arrache-pied pour découvrir comment les orcs de la péninsule des Flammes infernales sont devenus des gangr’orcs. Leur trahison est impardonnable... et nous devons nous assurer que nos amis orcs seront toujours à l’abri d’une telle corruption.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10836,'Bien joué, $N. J’ai découvert un moyen pour nous de libérer les drakes asservis qui sont retenus dans la forteresse Gueule-de-dragon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10837,'<Neltharaku prend les cristaux que vous lui donnez.>$B$BJe vais préparer les cristaux pour vous, maintenant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10838,'Vous avez obtenu un relevé ? Excellent ! Je suis certain que ces données seront inestimables pour nos recherches. Je vais les faire parvenir aux apothicaires Zelana et Albreck.$B$BVous pouvez être fier de vous, $N. Plus personne par ici ne mettra en doute votre force, votre bravoure... ou votre loyauté envers la Horde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10839,'J\'ai entendu l\'explosion depuis ici. Pas avec mes oreilles, mais avec mon cœur.$B$BSi le pouvoir d\'A\'dal, le naaru béni, ne suffit pas pour conduire les arakkoa vers la rédemption, rien ne le pourra. Ceux qui ne se sont pas rendus à la Lumière ne sont que des serviteurs du mal.$B$BIl faut les détruire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10840,'Ici, dans les terres sauvages de l\'Outreterre, nous sommes faibles avec peu de héros pour défendre nos droits, mais vous leur avez donné quelque chose à craindre, $C. Je ne pense pas que les éthériens oublieront de sitôt la force du bras justicier |2 $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10842,'Vous ne pouvez pas savoir à quel point ce que vous avez fait est important, $N. Vous avez sauvé tant des nôtres d\'une éternité de ténèbres. Je ne peux faire grand-chose pour les vivants et rien de ce que je pourrais vous donner ne suffirait à vous remercier. Prenez ce qui vous semble utile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10843,'<Leoroxx vous observe d\'un œil perçant, tentant apparemment de vous jauger.>$B$BLa mort de Gnosh Brognat est une bénédiction pour tous les Mok\'Nathal. C\'est une bonne chose pour vous.$B$BVoyons si l\'on peut encore repousser un peu plus loin les limites de ce dont vous êtes capable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10845,'Non ? Vous avez tué Aile-de-peur ? Je me suis peut-être trompé à votre sujet, $C.$B$BPeut-être.$B$BVous avez quand même tué les chefs des trois plus grandes menaces que nous avons à affronter. Il y a de quoi être fier.$B$BJe vous offre ce gage de ma gratitude, mais que ça ne vous monte pas à la tête. Vous ne comprenez toujours pas complètement ce que c\'est que d\'être un Mok\'Nathal, et nous aurons peut-être encore à faire appel à vos talents.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10846,'Les Vekh\'nir sont nos plus infimes adversaires.$B$BAlors comme ça, vous savez comment tuer un oiseau géant. Cela ne fait pas de vous un véritable guerrier. Ce n\'est pas cela qui vous permettra de pleinement comprendre nos coutumes.$B$BMais c\'est un début.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10847,'Votre bravoure est digne d\'éloges. Les gardiens de Skettis ne se séparent guère volontiers de leurs affaires.$B$BMais les actes héroïques du passé importent peu à présent. Nous verrons si votre bravoure persiste dans l\'avenir, car le regard de Terokk est fixé sur le sud.$B$BCes Yeux voient tout.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10848,'Ces vils esprits méritaient de mourir. Les morts dont ils se seraient rendus coupables sont une raison suffisante.$B$BNous n\'avons aucun espoir de racheter ceux qui sont sous l\'emprise de Terokk. Mais nous les frapperons d\'un coup dévastateur au nom de la Lumière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10849,'Les nouvelles de Rilak sont bien sombres, voyageur. Comme vous pouvez le constater en voyant l\'état de la caravane, le chagrin et les ténèbres sont partout dans la forêt de Terokk ces temps-ci.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10850,'Le moteur du saccageur gangrené commence à hoqueter et à cracher… Vous n’avez pas versé le bon carburant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10851,'Ça a l\'air d\'un bon assortiment. Nous devrions trouver comment en utiliser un ou deux d\'une façon digne.$B$BEn fait, je sais exactement ce que nous allons faire !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10852,'Vous avez trouvé mes amis ! Maintenant, j’ai quelqu’un avec qui jouer. Merci, monsieur $N.$B$BComme j’ai d’autres enfants pour jouer avec moi, maintenant, vous voulez peut-être un de mes jouets ? Comme ça, vous aurez quelque chose pour jouer, vous aussi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10853,'Vous avez accompli une bonne action aujourd\'hui, $C. Les esprits des drakes chanteront à nouveau maintenant qu\'ils ont été libérés. En plus, les résidus d\'esprit qu\'ils ont laissés sont un puissant médicament.$B$BJe me demandais si vous seriez prêt à partir vers le nord ? Quelque chose m\'intrigue concernant les activités des éthériens.$B$BJe sens une grande souffrance venant de leur direction.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10854,'<Neltharaku éclate de rire.>$B$BLes orcs ont dû avoir un choc quand les drakes se sont retournés contre eux de cette façon. Beau travail, $N. Vous méritez peut-être bien le titre de héros de notre vol.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10855,'Excellentes nouvelles, $N. Maintenant que nous savons quoi faire, je peux engager des sbires pour saboter les saccageurs qui restent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10856,'Bon travail, $N. Continuez comme cela, et je parlerai de vous au prince-nexus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10857,'Merci à vous, $N, je vais respirer un peu mieux maintenant. Enfin, c’est une façon de parler, bien sûr !$B$BJe suppose que vous allez vouloir une récompense, maintenant ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10858,'Ce sont les chaînes. Elles absorbent mon pouvoir. La seule solution est de prendre la clé à Zuluhed pour me libérer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10859,'Quelque chose ne va pas.$B$BS\'il vous plaît, $N, donnez-moi le totem. Il faut que j\'examine ces orbes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10860,'Mmm, j\'en sens déjà le goût. Vite, donnez-moi ces morceaux... Je vais les découper en dés et les mettre sur le feu !$B$BHeureusement pour vous, ça se conserve bien, très longtemps même ! Alors prenez ceci, et j\'imagine que vous avez aussi mérité les recettes pour avoir eu la gentillesse de m\'aider à remplir mon garde-manger.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10861,'C\'est une bien sinistre tâche que de s\'en prendre à des oisillons, mais ignorer le mal qui se prépare n\'est en rien préférable. Vous avez bien agi. La faveur d\'A\'dal rayonne sur votre cœur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10862,'Votre peuple est en colère mais je suis impuissant. Nous sommes quelques-uns à avoir été touchés par la puissance des naaru et nous avons changé pour toujours. Ceux qui restent dans la nature demeurent ce que nous avons toujours été.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10863,'Vous avez été sage de venir me trouver. Je peux vous montrer beaucoup de choses.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10864,'Bien joué, $N. Toutes ces morts pèsent sur votre âme... et le scrutateur démonien acceptera maintenant de fonctionner pour vous.$B$BEspérons que vous serez prêt pour l’épreuve à venir...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10865,'Que dites-vous, est-ce seulement possible ? Mais qu\'est-ce que je dis ? Bien sûr que ça l\'est, si les mande-esprit le disent.$B$BVous souvenez-vous de quand j\'ai dit que nous pourrions encore avoir besoin de votre aide ? On dirait que je suis capable de prédire l\'avenir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10867,'C\'est une bonne chose que ces vermines d\'éthériens et leur chef soient morts. Je souhaite tous les malheurs du monde à leurs frères !$B$BVous méritez une récompense pour vos actes au nom de tous les Mok\'Nathal, $N ! Vous êtes véritablement l\'un de nos héros.$B$BLibérons à présent les âmes de nos ancêtres dans le feu purificateur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10868,'Bon travail, $C. Les arakkoa ont appris à craindre la puissance de la Horde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10869,'Bon travail, $C. Les arakkoa ont appris à craindre la puissance de l\'Alliance.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10870,'Vous avez démontré que vous étiez un allié de l’Aile-du-Néant. Ma mère est libre et tous mes frères et sœurs sont sauvés !$B$BUn jour peut-être, nous ferons encore appel à vous. Quand ce jour viendra, sachez que vous serez reçu à bras ouverts, comme un frère au sein du vol de l’Aile-du-Néant') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10873,'Vous en avez sauvé tant. Je ne pensais pas que nous les reverrions un jour. Nous ne pourrons jamais assez vous remercier, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10876,'Vous avez accompli une grande prouesse, $N. Les gangr’orcs sont une honte pour tous les orcs véritables. Si nous devions n’avoir qu’une crainte, ce serait de succomber à nouveau à la corruption démoniaque. Comme vous le voyez, notre guerre contre les gangr’orcs est plus qu’un simple combat contre des ennemis acharnés, c’est aussi une bataille qui se livre en nous-mêmes.$b$bEt avec la force, celle dont vous avez encore une fois fait la démonstration, c’est une bataille que nous allons gagner.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10877,'C\'est incroyable que vous ayez réussi. La Relique de l\'effroi est encore bien plus puissante que je ne le craignais. Seul un puissant héros est capable de survivre au long trajet de retour en portant avec lui une telle abomination.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10879,'J\'applaudis votre ardeur au combat, $C. Vous avez prouvé que vous étiez un véritable défenseur de la Lumière. Que la bénédiction d\'A\'dal éclaire vos heures les plus sombres.$B$BMais regardez à l\'horizon. Le ciel se couvre au-dessus de Skettis. Terokk fomente sans doute aucun sa prochaine attaque. Shattrath est en sécurité pour l\'instant. Mais seul l\'avenir nous dira quelle horreur s\'abattra sur nous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10880,'Ah oui… c’est une forme assez simple du code des ombres. Je ne le connais pas particulièrement bien, mais je devrais pouvoir déchiffrer ce document.$b$bLorsque vous vivez parmi les hors-la-loi et les réfugiés de la Ville basse, vous finissez par en apprendre beaucoup sur une foule de sujets déplaisants.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10881,'La Lumière m’a peut-être oublié, mais je n’ai pas oublié la Lumière. Ces reliques étaient sacrées pour mon peuple autrefois.$b$bIl est hors de question que le Conseil des ombres puisse détourner leurs pouvoirs à de mauvaises fins.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10882,'<Le timbre cristallin de la voix d\'A\'dal porte une mélodie plus calme dans votre esprit que la dernière fois que vous vous étiez parlé.>$b$bUne fois encore vous avez prouvé votre valeur. Si le messager Cieuriss avait pu s\'échapper, des milliers de vies auraient été perdues dans le conflit qui aurait suivi, comme cela s\'est produit avec un autre serviteur des Dieux très anciens, Skeram, sur votre monde d\'Azeroth.$b$b$N, ce que j\'ai à vous donner en retour pourrait sembler dérisoire, mais sachez que nous y joignons l\'éternelle gratitude des Sha\'tar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10883,'Le donjon de la Tempête est une création des naaru, mortel. Il a toujours été en notre pouvoir d\'accorder ou non l\'accès au vaisseau. Un retour au donjon de la Tempête n\'a cependant pas été jugé nécessaire. Une race mortelle y aurait peut-être vu une affaire d\'honneur, mais les naaru se préoccupent peu de ces choses.$b$bNous agissons maintenant parce que c\'est notre devoir. Nous ne pouvons laisser Kael\'thas prononcer les mots de damnation.$b$bMême si le chemin est ouvert, seul un inconscient s\'y aventurerait sans avoir fait ses preuves. Ne sous-estimez pas le rôle de nos épreuves, créature mortelle.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10884,'Félicitations, $N. Vous avez réussi l\'épreuve de miséricorde.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10885,'Félicitations, $N. Vous avez réussi l\'épreuve de force.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10886,'Félicitations, $N. Vous avez réussi l\'épreuve de ténacité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10887,'Vous avez sauvé mon ami Akuno. J’ai une dette envers vous, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10889,'Les gardiens de Skettis s\'agitent sur leur perchoir. Shattrath est en danger. Nous aurons sûrement à essuyer le plus gros de la vengeance de Terokk.$B$BFormez un groupe de défenseurs en toute vitesse ! Parlez au défenseur Grashna et dites-lui que vous êtes prêts à porter les armes contre nos agresseurs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10893,'Si Draaca n’est plus dans le paysage, nous devrions pouvoir tirer parti de la situation. Ils vont se battre entre eux pour voir qui sera leur prochain chef, et cela devrait nous soulager un peu.$B$BEnfin, à moins que le surveillant mentionné dans la note que vous m’avez donnée ne vienne prendre sa place.$B$BVoyons voir si vous pouvez faire en sorte que cela n’arrive jamais !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10894,'C\'est bien ce que je pensais, et ce n\'est pas une bonne nouvelle !$B$BJe crois savoir comment vous aider, mais je me demandais si vous ne pourriez pas nous aider pour commencer ?$B$BUn petit service en vaut un autre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10895,'J’ai pu voir les flammes et la fumée d’ici ! Beau travail, $N ! Nos chevaucheurs de griffons vous ont amplement complimenté. Ce que vous venez de faire demandait une sacrée dose de courage...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10896,'Vous avez grandement aidé la forêt de Terokkar, $N. Si les plus grandes colonies de mites ont été détruites, nous aurons peut-être une chance de sauver cette terre dévastée.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10897,'Excellent ! Je vois que vous brûlez d’envie d’apprendre. Allons-y. Je vais vous expliquer comment tirer le meilleur parti des plantes que vous utiliserez dans vos potions alchimiques.$B$BVous verrez, si vous savez ce que vous faites, les herbes peuvent vous rendre davantage de services. Vous serez parfois capable de fabriquer deux potions avec les matières premières que vous pensiez d\'abord nécessaires pour une seule.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10898,'Hélas, le pauvre Aile-du-ciel était sous l\'effet de la terrible malédiction de Luanga l\'Emprisonneur !$B$BAile-du-ciel était allé jusqu\'au Voile Shalas pour tenter de montrer à d\'autres le chemin de la Lumière. Cela n\'a guère été apprécié, surtout sur le pas de la porte de Skettis.$B$BLuanga était l\'un des agents de Terokk les plus craints. Vous avez bien fait de libérer Aile-du-ciel ! Je vous remercie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10900,'Faites tout brûler, $R. Sans exception ! Ils ne méritent rien d\'autre ! Vous m\'entendez ? RIEN ! Ils doivent payer pour tout ce qu\'ils ont fait. Pour ce qu\'ils font encore.$B$BJe tuerais Vashj de mes propres mains si je pouvais me libérer de ces maudits liens.$B$BOu peut-être cherchez-vous à accomplir le travail de Neptulon ? Sa mort nous profiterait à tous deux, peau-lisse. M\'aiderez-vous à reformer le gourdin sacré ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10901,'Enfin !$B$BMaintenant que mes liens sont brisés et que j\'ai récupéré le gourdin, je vais renvoyer la sorcière des mers aux glaciales profondeurs…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10902,'Vous êtes très doué avec les élixirs, à en juger par ces échantillons. Vous ferez un très bon élève.$B$BCes essences me fourniront assez de matière pour mettre au point ma recette. Je serai célèbre entre tous les alchimistes pour cette découverte !$B$BEt maintenant, si vous êtes prêt à apprendre, je suis prêt à vous donner mes leçons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10903,'Oui, c’est la vérité. L’état du colonel Jules a considérablement empiré ces derniers jours. L’anachorète Barada se charge de prier pour lui... espérons qu’il puisse être guéri.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10904,'Ils sentent plus mauvais que je ne l\'aurais cru !$B$BVite, passez-les-moi, et je les imprègnerai de la force de la Nature pour qu\'ils deviennent extrêmement dangereux pour leurs maîtres gangrenés et leurs créations contre-nature.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10905,'Vous avez besoin de mon aide pour vos études en potions ? Très bien, $N. Voyons voir ce que l\'on peut faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10906,'Vous voulez suivre mon enseignement ? Hummm, oui. Vous ferez peut-être une étudiante acceptable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10907,'Vous désirez que je vous aide à étudier la transmutation ? Très bien, $N. Voyons ce qu’on peut faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10908,'Ainsi, nous nous rencontrons, $N. Pardonnez-moi de passer outre les politesses d\'usage, car le temps nous est compté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10909,'Les orcs de la Main brisée sont souillés au-delà de tout espoir de rédemption, mais mon cœur s’afflige tout de même de savoir que le salut du colonel Jules passe par de telles effusions de sang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10470,'Vous êtes effectivement un allié de choix. Plus vous gagnerez en puissance, plus la bague d\'Éternité s\'accordera à vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10910,'Quel soulagement que le seigneur sauvage Antelarion vous ait envoyé à nous. Le problème est bien pire que ce que nous avions cru tout d\'abord !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10911,'Vos prouesses sont étourdissantes !$B$BTrès bien, avec les portails dimensionnels hors d’état de nuire, il ne nous reste plus qu’une chose à faire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10912,'Vous êtes véritablement un $R surprenant ! Je pensais déjà que nous avions une grande dette envers vous, et maintenant nous n\'arriverons tout simplement jamais à la rembourser.$B$BMais nous essayerons. Merci, héros du Bosquet éternel !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10913,'<Le commandant Ra’vaj se prend la tête dans ses mains.>$B$BÇa ne suffira pas… ça ne suffira pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10915,'Victoire ! Cette défaite va faire perdre plusieurs semaines aux Auchenaï.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10916,'Vous avez le chapelet ! Bien joué, $N. Vous êtes vraiment formidable. Capable de vaincre les horreurs de la péninsule des Flammes infernales tout comme de retrouver les trésors disparus. Votre exemple nous inspire !$b$bC’est une bonne chose que vous ayez mis la main sur ce chapelet... il sera indispensable dans le rituel d’exorcisme qui se prépare.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10917,'<Vekax caquette de joie alors que vous lui présentez la preuve de la défaite de ses ennemis.>$b$bTrès bien, cela montrera à Skettis que nous autres les parias ne nous laisserons pas punir sans réagir. Voici la récompense que je vous ai promise. Je peux me débrouiller pour vous donner un supplément, si vous me rapportez d’autres plumes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10920,'J’ai entendu d’ici les bruits de votre combat, $C. Les échos de votre victoire ont empli mon cœur d’espoir. Si vous pouvez l’emporter dans des conditions aussi terribles, je trouverai peut-être la force de traîner mes compagnons loin de cet abominable endroit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10921,'Les crocs-d\'effroi sont vaincus. Vous en avez tué un grand nombre et même leur vile mère est tombée sous vos coups. Je suis trop affaibli par le poison pour me battre pour ma liberté.$B$BS\'il vous plaît, prenez une partie de mon équipement. Cela allégera mon fardeau et vous procurera les outils dont vous aurez besoin pour rentrer à l\'avant-poste sha\'tar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10922,'Un ver des os ! Fantastique ! Vous savez, c’est sans doute la première fois de toute l’histoire que Leglas fait une découverte.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10923,'Un grand mal a été chassé de Terokkar. Les Sha\'tar vous sont redevables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10924,'Cela devrait suffire à mes besoins.$B$BJ’espère que le diablotin ne vous a pas posé trop de problèmes. Il lui arrive de se montrer un tantinet caustique.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10926,'C\'est bon de savoir qu\'un groupe de nos guerriers s\'est bien battu contre les veuves croc-d\'effroi. Nous allons envoyer un groupe de sauveteurs immédiatement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10927,'C\'est du bon travail, $C. Ce tunnel est notre seul lien avec le marais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10928,'C\'est du bon travail, $C. Ce tunnel est notre seul lien avec le marais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10929,'Des gnomes des sables ? C’est cela, bien sûr… Le désert fait parfois des choses étranges aux imprudents.$B$BMais je pense que nous allons bientôt faire une découverte sur ces vers !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10930,'Stupéfiant ! Regardez ça ! Le chose-machin contient une sorte de poussière, là, à l’intérieur du bidule-chouette. Bon, je vous épargne tout le jargon scientifique. Dites, j’ai réussi à arracher quelques dents aux plus petits. Je m’en sers pour fabriquer ces couteaux. Ils coupent très bien. Vous en voulez un ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10936,'Il était temps ! J’ai entendu parler de ce que vous avez fait avec ce prêtre draeneï. Vous avez complètement affolé mon messager !$B$BMaintenant que vous en avez terminé avec cette affaire, j’ai une petite mission prévue pour vous à la citadelle des Flammes infernales.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10937,'Je ne voulais pas y croire avant de l’avoir personnellement entendu de votre bouche. Déjà nos éclaireurs commencent à arriver avec des informations sur la désorganisation des troupes de la Main brisée depuis que leur précieux maître de manœuvre n’est plus là pour leur dire quoi faire.$B$BVous avez parcouru une longue route, $N. J’espère que vous accepterez cette armure avec mes remerciements. Portez-la fièrement, vous l’avez méritée !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10466,'Vous avez fait la preuve de votre valeur, $R. Jusqu\'à un certain point, tout au moins.$B$BLa faveur de la première compagne de Nozdormu ne se gagne pas facilement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10948,'<La lumière d\'A\'dal vous entoure et il vous souhaite la bienvenue. Vous avez le sentiment qu\'il sait ce que vous allez lui demander.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10949,'<Xi\'ri semble prendre note de votre présence. Il semble concentré sur la bataille qui se déroule dans les environs.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10985,'<De l\'énergie pulse en Xi\'ri et vous sentez un objet se matérialiser dans vos mains. C\'est le médaillon que vous avez remis à A\'dal de la part d\'Akama, et sa puissance a été accrue par la magie des naaru. Les Sha\'tar vous ont confié le Médaillon de Karabor, et avec lui un accès au Temple noir.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10958,'Nous vous attendions, $N. Akama a grand besoin de votre aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10957,'C’est fait, $N. Le moment de frapper Illidan est venu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10566,'L\'information me sera très utile, $N. Je vais affiner mon processus de fabrication et voir s\'il n\'est pas possible d\'en améliorer l\'efficacité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10955,'<Morthis vous examine d\'un air légèrement sceptique.>$B$BCela fait longtemps que je recherche un apprenti à qui transmettre mon savoir. Bien que les druides de la Serre n\'existent plus formellement, je resterai l\'un d\'entre eux jusqu\'à la fin de mes jours.$B$BJe vous accepte comme apprentie à compter de ce moment. Pour ma part, je vous enseignerai les secrets du corbeau des tempêtes. Pour la vôtre, vous devez vous préparer à faire tout ce que je vous demanderai. Est-ce bien clair ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10965,'Vous avez eu de la chance que Clintar ait eu la force de maintenir divisée son essence pendant si longtemps, $N. Peu de druides sont capables d\'un tel exploit lorsque le Rêve d\'émeraude est attaqué. Prenez bien soin des reliques !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10978,'<Morthis accepte les reliques que vous lui remettez en écoutant votre description des événements survenus dans le refuge des saisons.>$B$BVoilà des nouvelles bien alarmantes, $N. Nous avons eu vent d\'un certain nombre de troubles dans le Rêve d\'émeraude, mais je n\'ai pas souvenir qu\'il ait jamais été question de l\'intervention de forces extérieures. Êtes-vous certain que c\'est bien la conclusion de Clintar ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10979,'<Arthorn vous écoute tandis que vous lui expliquez que Morthis Murmedaile vous a confié la mission de rechercher un lien entre le culte du dieu corbeau et les événements étranges survenus à Reflet-de-lune. Bien qu\'elle soit abasourdie par ce qu\'elle apprend, elle semble surtout déçue par la nature du message.>$b$bPar tous les…$b$bJ\'aide Timeon dans ses recherches sur le culte du Corbeau, mais nous n\'avions jamais imaginé que son maître ait pu exercer une quelconque influence au-delà des Tranchantes !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10980,'N\'est-ce pas étonnant de constater que même chez les arakkoa, les sectateurs étaient considérés comme des hérétiques ? Que les prêtres traditionnels les aient suffisamment haïs pour détruire leurs textes saints est incroyable ! Nous devons absolument mettre la main sur ce livre, $N.$B$BIl est d\'une importance capitale pour éclaircir le mystère du dieu corbeau et l\'empêcher de s\'emparer du Rêve d\'émeraude.$B$BPeut-être que Morthis acceptera finalement de faire de moi son élève si nous réussissons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10986,'<Elaira écoute votre récit de la recherche du Livre du Corbeau et la suggestion d\'Arthorn d\'utiliser des oiseaux pour en localiser les pièces manquantes.>$b$bC\'est une excellente idée, et Nagrand fourmille de candidats potentiels. Mais auxquels faire appel ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10988,'<Arthorn prend les fragments du Livre du Corbeau que vous lui tendez et commence à les assembler.>$B$BCertains caractères ont été effacés par l\'érosion, mais je devrais pouvoir en déchiffrer la plus grande partie...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10990,'<Arthorn semble percevoir la puissance de l\'essence que vous avez récupérée à travers les sens de la crécerelle.>$B$BMême après des milliers d\'années de captivité, le pouvoir de l\'Aigle reste intense. Si les autres essences sont aussi puissantes que celle de l\'Aigle, le dieu corbeau aura raison de vous craindre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10992,'Maintenant que nous avons toutes les essences, Morthis Murmedaile doit trouver un moyen de les combiner en une amulette que vous pourrez utiliser pour défier le dieu corbeau, l\'attirer hors du Rêve d\'émeraude et le vaincre. Je lui enverrai mes notes au sujet des esprits, espérons qu\'il appréciera à leur juste valeur mes observations.$B$BChacun des esprits a béni un charme que j\'ai préparé pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11001,'Je suis heureux de vous revoir, $N. Votre triomphe face au dieu corbeau compte plus que toutes les épreuves ou les rites initiatiques auxquels j\'aurais pu vous soumettre.$B$BVous vous êtes montré digne de recevoir la connaissance que les druides de la Serre conservent depuis d\'innombrables générations.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11048,'<Gulmok ronchonne en apprenant la décision de Kroghan.>$B$BJe comprends son point de vue, mais il nous faut de la viande fraîche pour tenir les tranchées ici aussi ! La Légion nous bombarde avec ses infernaux jour et nuit. Si Kroghan n\'arrive pas tout de suite, vous pouvez prendre sa place sur le champ de bataille !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11038,'Alors, vous êtes ici pour nous aider à découvrir ce que Kael\'thas prépare exactement ? Votre aide est plus que bienvenue. Raz-de-Néant grouille d\'agents elfes de sang dont les activités menacent de disloquer ces terres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10983,'Grok dit que je suis sage ? Ça, je ne sais pas.$B$BPeut-être est-ce parce que je suis le seul de mon clan à vraiment essayer de nous sauver de l\'éradication par le clan de la Flèchelame, et par Gruul et ses fils qui les soutiennent.$B$BJ\'espère que vous venez nous délivrer d\'une mort certaine, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10984,'Vous aider Grok ? Grok besoin d\'aide ! Masse-sanglante besoin d\'aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10995,'Le combat a effectivement dû être difficile, $C. Je suis très soulagé maintenant que nous ne sentirons plus son souffle sur nos nuques.$B$BJe vais envoyer ce crâne à Chort pour qu\'il le mette en sécurité. Je commence à penser que nous allons peut-être réussir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10996,'Vous dites qu\'il était vide ? Ce n\'est pas de chance, mais vous avez eu un aperçu de la brutalité aveugle à laquelle nous sommes confrontés.$B$BLa chute de Maggoc est un pas de plus vers la réalisation de mon rêve : donner aux ogres un foyer dans lequel ils pourront être maîtres de leur destin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10997,'Quel soulagement que Skori soit mort. Le spectre de son retour ne nous hantera plus !$B$BSi vous n\'y voyez pas d\'inconvénient, je vais garder cet étendard comme symbole d\'espoir pour tous les ogres de ces montagnes.$B$BMerci, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11037,'<Le chef écoute votre description de la vision du prophète.>$B$BEh bien, tous ces trucs-là j\'en sais rien, mais on aurait effectivement bien besoin de votre aide par ici. Regardez la fusée qui se trouve derrière moi. C\'est la X-52…$B$BN\'est-ce pas la plus belle chose que vous ayez jamais vue ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11096,'Bon boulot, l’as. J’ai comme dans l’idée que vous vous intégrerez bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11002,'Cette défaite n’est pas seulement un sale coup pour Illidan, $N. La Légion aussi s’en ressent. Un commandant des seigneurs des abîmes a été abattu. Le siège de la citadelle des Flammes infernales ne présente plus d’intérêt pour la Légion ardente. Tous ses efforts vont sans nul doute se concentrer sur le Temple noir.$B$BIllidan va récolter ce qu’il a semé... et très bientôt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11003,'Cette défaite n’est pas seulement un sale coup pour Illidan, $N. La Légion aussi s’en ressent. Un commandant des seigneurs des abîmes a été abattu. Le siège de la citadelle des Flammes infernales ne présente plus d’intérêt pour la Légion ardente. Tous ses efforts vont sans nul doute se concentrer sur le Temple noir.$B$BIllidan va récolter ce qu’il a semé... et très bientôt.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11009,'Mog\'dorg a envoyé un message pour me prévenir de votre arrivée prochaine. Je suis heureux que vous soyez venu.$B$BMaintenant que les fils de Gruul sont anéantis, les divers habitants de ce plateau montagneux et de celui qui se trouve plus au nord ne vont pas tarder à s\'en prendre à nos frères ogres qui se trouvent en bas. Ce n\'est qu\'une question de temps - et de peu de temps.$B$BJ\'ai bon espoir que vous nous aidiez à l\'empêcher, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11058,'< Chu\'a\'lor hoche la tête d’un air satisfait devant votre réussite.>$B$BVous avez l’esprit vif, $N. Cela nous a pris beaucoup plus de temps pour réussir à utiliser la relique.$B$BMaintenant que vous savez ce qu’il faut faire, vous pouvez recommencer autant de fois qu’il vous plaira. N’oubliez pas qu’un éclat apogide est nécessaire pour l’alimenter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11080,'Vous continuez à nous étonner par votre habileté à percer les secrets des reliques, $N. Pourrions-nous vous suggérer de vous entraîner à les utiliser au moins une fois par jour pour maintenir votre acuité mentale à son plus haut niveau ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11091,'Hé, mon gars c’est génial. Nous avons entendu que vous aviez fait des choses épatantes. C’est cool. Nous avons l’impression que vous allez remettre les choses en place à Ogri’la, et nous permettre de vivre en sécurité, et que tout soit chouette et sympa.$b$bVoilà, prenez ça. Ce n’est pas grand-chose, juste un paquetage pour vous remercier de vos efforts.$b$bN’hésitez pas à regarder nos marchandises. Nous avons tout un tas de trucs que vous voudrez sûrement avoir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11031,'Réfléchissez bien à votre prochaine décision. Nous faison de notre mieux pour graisser la pâte de nos alliés, mais même les ressources de Dalaran ont leurs limites.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11032,'Réfléchissez bien à votre prochaine décision. Nous faison de notre mieux pour graisser la pâte de nos alliés, mais même les ressources de Dalaran ont leurs limites.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11033,'Réfléchissez bien à votre prochaine décision. Nous faison de notre mieux pour graisser la pâte de nos alliés, mais même les ressources de Dalaran ont leurs limites.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10998,'J\'hésite ne serait-ce qu\'à toucher un objet aussi vicié par le mal. Mais nous devons le lire si nous voulons en extraire les informations qui permettront de faire sortir Crânoc de sa cachette.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11000,'Alors c’est terminé. Vous avez brisé les chaînes de notre asservissement aux fils de Gruul. Vous avez offert au clan de la Masse-sanglante un répit avant une extinction assurée.$B$BLes mots ne suffisent pas à décrire l’étendue de ce que vous doivent TOUS les ogres des Tranchantes, $N, ceux de la Masse-sanglante comme ceux de la Flèchelame.$B$BRegardez en bas, déjà les ogres se rassemblent pour vous rendre hommage. Que Gruul et sa marionnette, le vieux roi Maulgar, restent terrés dans leur repaire. Descendez rejoindre les ogres qui attendent en vous notre nouveau roi !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10940,'Ainsi donc, vous avez rassemblé une suite de Furies. En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11076,'Du bon travail, $N. Revenez demain pour une autre mission dans les profondeurs de la mine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11075,'Les mineurs travaillent dur, mais ils n’osent plus descendre très loin dans les mines. En fait, ils préfèrent mourir plutôt que de creuser plus profondément ! Vous allez devoir accomplir les tâches dont ils sont incapables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11055,'Une dure journée de travail ! Y a des compensations, pas vrai ? Ça réchauffe le cœur de voir ces avortons minables s’échiner sur ces cristaux… Bon, ce sera tout pour aujourd’hui. Revenez demain pour une nouvelle tournée de botterang.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11107,'Vous êtes le premier généralissime des Gueules-de-dragon, $N. Le maître en personne a décidé de venir ici pour vous accorder une promotion.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11092,'Le seigneur Illidan en personne m’a demandé de vous promouvoir au grade de commandant ! C’est sans précédent. Vous serez le premier Gueule-de-dragon a atteindre un tel grade hors du Temple noir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11018,'C\'est bon pour aujourd\'hui, mon lapin. Reviens demain si tu es encore en vie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11017,'C\'est bon pour aujourd\'hui, mon lapin. Reviens demain si tu es encore en vie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11016,'C\'est bon pour aujourd\'hui, mon lapin. Reviens demain si tu es encore en vie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11015,'C\'est bon pour aujourd\'hui, mon lapin. Reviens demain si tu es encore en vie.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11084,'<Mor’ghor hoche la tête.>$B$BOui, j’ai bien dit « capitaine ». Vous avez mérité une nouvelle promotion, $N.$B$BJe n’ai jamais vu un gangr’orc travailler comme vous. Continuez comme ça, et vous finirez suzerain un de ces jours.$B$BEt maintenant, fichez-moi le camp et allez prendre vos fonctions. Je vous suggère de mériter vos ailes de Brise-ciel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11108,'Je fus le premier, vous savez. L\'enfant abandonné d\'un monstre…$B$B<Barthamus secoue la tête.>$B$BNous vous devons tout, $N. Vous avez à vous seul ravagé l\'empire gueule-de-dragon et réuni assez d\'informations pour occuper mes frères pendant plusieurs de leurs vies.$B$BNous avons quelque chose à vous donner, même si ce n\'est pas beaucoup... Ceux de ma race offrent, chacun, de se joindre à votre mission en Outreterre. Vous n\'avez qu\'à demander, et ils lieront leur destin au vôtre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11431,'Quoi ! Ils existent vraiment ! Je vais m\'en vouloir d\'avoir donné un coup de pied dans le genou de ce nain...$B$BDonnez-moi un instant... et un verre...$B$B<Il prend une longue rasade à son bock.>$B$BJ\'imagine que je peux vous laisser en garder un... Une preuve que les nains bourrés (mais y\'en a-t-il qui ne le sont pas ?) disent quand même la vérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11117,'Ma parole, mais vous avez décroché tout un buisson de wolpertinger !$B$B<Il prend une longue rasade à sa chope.>$B$BJ\'vais vous dire ce qu\'on va faire. Puisque vous êtes si doué pour les chasser, j\'vais vous laisser en garder un pour vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10941,'Ainsi donc, vous avez rassemblé une suite de Déraison. En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11098,'Merci pour le matériel, nous en ferons bon usage ! Une nouvelle recrue, hein ? Voyons ce que vous avez dans le ventre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10989,'Enfin, Chort m\'envoie quelqu\'un qui a l\'air de pouvoir nous venir en aide. J\'essaie de sauver le clan de la Masse-sanglante de l\'anéantissement aux mains du clan de la Flèchelame, et des fils de Gruul qui les épaulent.$B$BJ\'ai bon espoir que c\'est vous qui aiderez notre société secrète et nous délivrerez de leur joug.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11404,'Allez-vous poser la chandelle et arracher le Cavalier sans tête à son repos maudit ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11356,'Vous êtes là pour rendre visite aux enfants ! Merveilleux ! Ils ont déjà eu tant de peine pendant leurs courtes existences. C’est bien qu’ils voient de vrais héros comme vous. Ça leur mettra du baume au cœur !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11360,'Vous êtes trempé et couvert de suie ! Vous devez avoir éteint plusieurs feux !$B$BBien joué ! Maintenant que vous êtes un membre honoraire de la brigade des pompiers, je vous supplie de revenir ici si jamais le village a besoin de vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11357,'Les enfants adorent voir les héros en action. J’ai espoir qu’un jour, chacun de ces enfants devienne un puissant membre de la Horde et ait la chance de mourir dans une glorieuse bataille !$B$BAh, de penser à un si beau destin, mes yeux se voilent...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11131,'Oh, merci ! Puisse la Lumière vous bénir pour vos bonnes actions, mon bon monsieur. L\'ombre du noir cavalier plane encore sur le village mais, au moins pour l\'instant, nous sommes à l\'abri de ses flammes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11439,'Vous êtes trempé et couvert de suie ! Vous devez avoir éteint plusieurs feux !$B$BBien joué ! Maintenant que vous êtes un membre honoraire de la brigade des pompiers, je vous supplie de revenir ici si jamais le village a besoin de vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11440,'Vous êtes trempée et couverte de suie ! Vous devez avoir éteint plusieurs feux !$B$BBien joué ! Maintenant que vous êtes un membre honoraire de la brigade des pompiers, je vous supplie de revenir ici si jamais le village a besoin de vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10938,'Ainsi donc, vous avez rassemblé une suite de Bénédictions. En prenant la peine de nous la rapporter, vous avez créé un lien entre la Sombrelune et vous, un lien qui ne sera pas oublié de sitôt. En témoignage de notre gratitude, permettez-moi de vous remettre l’une des cartes majeures de Sombrelune.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10464,'Vous avez fait la preuve de votre valeur, $r. Jusqu\'à un certain point, tout au moins.$b$bLa faveur de la première compagne de Nozdormu ne se gagne pas facilement.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10468,'Vous êtes effectivement un allié de choix. Plus vous gagnerez en puissance, plus la bague d\'Éternité s\'accordera à vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11024,'C\'est impossible… Ce livre appartenait autrefois à un prêtre de la serre. Où diable l\'avez-vous trouvé ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11028,'Les arakkoa cherchent à faire revenir Terokk de ce côté du voile du temps et Rilak... veut trouver un moyen d\'accélérer le processus ? A-t-il perdu la tête ?$B$B<Adaris s\'allonge à nouveau, abandonné par ses forces.>$B$BVous avez accompli votre devoir, $N. Le moment est venu pour vous de laisser agir mes propres hommes. Cette affaire est devenue purement militaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11041,'Si l\'on peut se fier aux restes de l\'un de mes propres surveillants, vous vous êtes emparé du commandement et avez pris les affaires en main ? Vous avez réussi à impressionner Mor\'ghor. Bravo...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11081,'Excellent travail, surveillant. Mor’ghor entendra parler des grands services que vous rendez aux Gueules-de-dragon.$B$BBon, revenons-en à ces chiens de Bourbesang. Ils ont prévu une évasion, hein ? Ils osent défier le seul véritable seigneur de l’Outreterre ! Leurs maîtres vont payer pour cela !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11082,'Rien à dire ? Ça lui reviendra peut-être quand il sera en train de se vider de son sang sur le sol de cette mine maudite… Il se souviendra qu’il ne faut pas contrarier les forces d’Illidan !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11419,'Beau travail, $N... Vous avez gagné la confiance des brasseurs du festival, obtenant le droit d\'acheter un Bélier de la fête des Brasseurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11123,'Je suis content de voir que le capitaine Vimaire a enfin décidé de nommer d\'autres personnes sur cette enquête.$B$BJ\'ai recouvert la zone d\'une poudre réfléchissante, qui révèlera les traces et objets louches, et vous aidera à voir sur quoi concentrer vos efforts. Examinez tout ce qui sera illuminé par la poudre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11124,'<L\'inspecteur vous observe avec méfiance.>$B$BOn m\'a informé que vous alliez... participer à cette enquête. Eh bien, soit.$B$BJ\'utilise cette poudre dans les ruines pour rechercher des indices qui pourraient nous aider à identifier les agresseurs. Elle va rendre luminescent tout ce qui a été impliqué dans l\'attaque. N\'hésitez pas à examiner tout ce qui semble suspect.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11126,'Bien joué, $N. Je crois que nous avons réussi à les prendre par surprise. Leurs agents pensaient sans doute être en sécurité dans les murs de la ville.$B$BAvec le temps, les agitateurs reviendront et recommenceront à propager leurs mensonges. Nous mettrons à profit le répit que vous nous avez apporté pour écarter les déserteurs de plus en plus.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11128,'<L\'agent du SI:7 hoche la tête en signe d\'approbation.>$B$BExcellent. Tout ce qu\'il nous reste à faire, c\'est de discréditer les déserteurs pour qu\'ils ne réussissent plus jamais à étendre leur influence dans Theramore. Et j\'ai un plan parfait pour ça.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11132,'<Budd paraît choqué par votre récit.>$B$BOh ? Vous l\'avez trouvée ?$B$BAhem, je veux dire, évidemment que vous l\'avez trouvée ! Bien joué, $C.$B$BLaissez-moi voir si je peux vous trouver un petit quelque chose... oui, voilà qui devrait faire l\'affaire.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11133,'<Calia éclate de rire quand vous lui décrivez les réactions des gardes aux tracts de propagande.>$B$BExactement comme je l\'espérais ! Je pense qu\'on peut dire sans trop s\'avancer que si un agent des déserteurs essaie d\'infiltrer Theramore, ils sera chassé sous les quolibets !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11134,'La demande de Gavis n\'est pas si délirante qu\'elle en a l\'air. En s\'y prenant bien, dame Jaina pourrait ramener les déserteurs au bercail. Mais c\'est à elle de décider, bien sûr.$B$BJ\'ai eu grand plaisir à travailler avec vous, $N. Sans votre aide, je ne pense pas que tout se serait aussi bien déroulé. Quand je ferai mon rapport à Hurlevent, vous y figurerez comme le $C qui a mis fin à la menace des déserteurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11136,'<Le capitaine ne dissimule pas une seconde qu\'il est en train d\'évaluer vos capacités.>$B$BDonc, vous avez entendu parler des récents naufrages dans le coin ? Bien, un peu d\'aide pour confirmer mes soupçons à propos des rescapés ne serait pas de trop. Bienvenue à bord, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11137,'<Le capitaine Wymor prend les ordres que vous lui tendez et les lit.>$B$BÀ quoi diable cette « précieuse cargaison » peut-elle faire référence ? Les Défias ont bien monté quelques petits trafics dans la région de Hurlevent, mais tout ceci semble bien hors de la catégorie dans laquelle ils jouent habituellement. Le niveau de langue employé dans ces ordres semble indiquer un commanditaire noble ou riche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11138,'<Renn parcourt les ordres.>$B$BIl y avait donc une précieuse cargaison à bord ! Nous devons la localiser avant que les Défias ne la récupèrent. Ces gars-là ne sont pas de vrais plongeurs, mais nous allons avoir besoin d\'un peu de leur équipement si vous voulez m\'aider à trouver la cargaison.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11139,'Eh ben, c\'est en plus mauvais état que je ne pensais. Et ces outils…$B$BBah, j\'ai dit que je vous remettrais tout ça en état, alors autant me mettre au boulot.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11140,'<Renn fouille les coffres que vous avez récupérés.>$B$BBon travail. Maintenant, voyons si notre « précieuse cargaison » est par là…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11143,'Le capitaine Vimaire pense que les Totems-sinistres sont derrière la destruction de l\'auberge du Repos ombragé ? Ils n\'auraient pas été en tête de ma liste de suspects, mais si le capitaine vous a envoyé suivre cette piste, il doit avoir ses raisons. Quoi qu\'il en soit, les Totems-sinistres sont une épine dans notre pied depuis quelque temps, et nous sommes toujours contents de recevoir de l\'aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11144,'<Le capitaine Darill jette un œil au plan de bataille.>$B$BDifficile de faire plus clair que ça. Ils ont décidé de contrer l\'installation des humains dans la région, et j\'ai peu de doutes sur le fait que Theramore est la prochaine sur la liste.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11145,'Les prisonniers libérés ont déjà commencé à rentrer de Sabot-noir. Les informations qu\'ils donnent au capitaine nous donnera un avantage dans notre prochaine bataille contre les Totems-sinistres.$B$BVous avez ma gratitude, ainsi que celle de mes hommes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11146,'Vous avez l\'air un peu égratigné, mais sans rien de grave. Ceux du Totem-sinistre seront dans un état bien pire quand nos nouveaux amis raptors en auront fini avec eux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11147,'<Le sergent ne prend pas la peine de cacher son sourire.>$B$BBien. Ça devrait retarder un ou deux de leurs raids.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11148,'<Le capitaine Darill examine les armes que vous avez rapportées de Sabot-noir.>$B$BIl n\'y a aucun doute. Elles correspondent parfaitement, mais il y a néanmoins un problème : ces armes n\'ont jamais servi au combat. Sabot-noir ne doit pas être le seul camp totem-sinistre du marécage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11149,'Alors vous voulez que j\'utilise mes talents de scrutatrice pour trouver des Totems-sinistres, c\'est ça ? Et si je vous dis qu\'il n\'y a pas besoin ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11150,'J\'espère que les Totems-sinistres auront bien compris le message. Et s\'ils essayent de revenir, ils seront accueillis par bien pire qu\'une torche. Mes apprentis et moi y veilleront.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11151,'<Le capitaine écoute attentivement votre rapport.>$B$BNous avons vengé James Hyal et sa famille. Mais même cela ne nous rendra pas ce qui a été détruit.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11152,'<Le capitaine Vimaire sourit légèrement quand vous lui racontez ce que vous avez vu sur la tombe de la famille Hyal.>$B$BJe suis heureux de savoir qu\'ils ont compris. Vous ne leur avez rien dit à propos de James, n\'est-ce pas ?$B$BJe lui transmettrai le message de sa femme, mais je doute qu\'il comprenne.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11156,'<L\'apprenti Morlann opine.>$B$BBien. Je ne peux pas dire que leur compagnie, si on peut appeler ça comme ça, me manquera. Vous savez, je croyais qu\'au beau milieu du marécage, on aurait au moins droit à un peu d\'intimité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11158,'<Brogg accepte les plumes.>$B$BBrogg est content des plumes. Magie très forte. Brogg sait pas comment les raptors donnent le pouvoir aux plumes, mais les plumes de raptors elles sont toujours le mieux pour le rituel.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11159,'Brogg dit merci pour l\'aide, même si il sait que le seigneur Mok\'Morokk il dira jamais merci. Au moins, les Cognepierres qui vivent, ils peuvent s\'occuper des problèmes des vivants et laisser les morts dans leur place. Il reste plus qu\'une chose à faire pour Brogg.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11160,'Brogg il vous dit merci, $N. Brogg a un grand projet pour la bannière.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11161,'Brogg il vous dit encore merci, $N. Quand la magie sera sur le totem de Brogg, elle pourra faire reposer les esprits des amis morts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11162,'<Brogg écoute votre récit des événements survenus devant l\'antre d\'Onyxia.>$B$BBrogg se doutait qu\'Onyxia elle aurait trop de peur pour vous affronter. Le Vol noir, il attaque que quand la victoire est garantie.$B$BBrogg a la gratitude pour votre aide, $N, et il oubliera jamais ce que vous avez fait. Brogg va jamais abandonner sa quête pour redonner la bonne place des Cognepierres.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11164,'Youhou, c\'est pile c\'qu\'y m\'faut !$B$BVoilà c\'que j\'t\'avais promis, $C.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11165,'J’suis libre !$B$BY m’ont presque tout pris quand y m’ont attrapé, mais voilà... prenez mes dernières pièces en r’merciement.$B$BEt l’moins que je puisse faire, c’est rester dans l’coin pour proposer mes services...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11166,'<Budd lutte pour garder son sang-froid.>$B$BEuh... Alors, $N, il, eeuuhh, était temps que vous reveniez. Oui... en fait toute l\'opération repose sur vous.$B$BEh bien maintenant, allons donc compléter cette carte...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11169,'<L\'apprenti écoute votre récit de l\'expérience.>$B$BUn brouillard et des éclairs ? C\'est tout ? Il doit y avoir autre chose ! Les Totems-sinistres n\'apporteraient sans doute pas un tel objet sur un champ de bataille s\'il n\'a pas une utilité quelconque.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11171,'Enfin ! Maintenant que les menus travaux sont faits, je vais pouvoir entrer une fois encore dans l’Histoire. Mais d’abord, il reste un petit détail à régler. Vous...$B$BJ’ai bien peur, $N, que ne soit venu le temps de nous séparer. Je pense que vous avez largement atteint votre potentiel, quand bien même vous ne l’auriez pas largement dépassé.$B$BMais ne le prenez pas mal. Après tout, il faut des êtres exceptionnels pour participer à des événements aussi extraordinaires sans perdre pied. Et puis voyez, j’ai un petit quelque chose pour que vous vous souveniez de moi.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11172,'Alors ce sont ces mages ermites qui vous envoient ? Et comment je saurais que je peux vous faire confiance ?$B$BEnfin, j\'aurais bien besoin d\'aide. Il n\'y a pas grand-chose qui pourrait intéresser un mage par ici, de toute façon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11173,'<L\'apprenti Garion examine le venin.>$B$BVoilà qui est absolument parfait ! Il n\'y verra que du feu.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11174,'Ma foi, ça a l\'air un peu plus propre là dehors… $B$BJe pense qu\'il est temps de récupérer ce qui peut l\'être sur cette épave.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11177,'Dégagez de ma propriété ! Hmm… Sauf si vous voulez aider ce bon vieil « Œil-des-marais » à faire un peu de cuisine. Qu\'est-ce que vous en dites ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11178,'Le... le sang de Zul’jin lui-même, vous dites ?$B$B<Budd rassemble ses esprits et continue.>$B$BEt bien, j’apprécie le geste, $C, mais j’aurais pu l’abattre facilement. Il est loin d’être aussi terrible que ce que racontent les légendes. Ces choses sont toujours passablement exagérées, comme vous le découvrirez un jour. Le plus probable, c’est que ce pauvre vieux sénile était perclus d’arthrite !$B$BEnfin, je suppose que c’était le moins que vous pouviez faire en échange de toute ma gentillesse envers vous.$B$BEt maintenant décampez, je dois disposer de cette fiole !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11180,'<Mordant sort une petite feuille de papier et un crayon, et commence à griffonner des notes sur vos découvertes.>$B$BD\'après ces informations, les esprits qui occupent cet endroit doivent représenter tous les gens qui ont un jour vécu sur cette île, et pas seulement les derniers occupants.$B$BQuelque chose en corrompt et tue les habitants. Et ceux qui les remplacent ne découvrent jamais la vérité avant qu\'il ne soit trop tard. Nous devons mettre fin à tout cela, $N !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11181,'<Mordant accepte votre paquet de plantes.>$B$BElles correspondent parfaitement à la description ! J\'ai préparé la torche pendant votre absence. Il ne reste qu\'à y fixer les tiges, à cette extrémité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11183,'Ça a marché ?$B$B<Mordant se racle la gorge.>$B$BJe veux dire... ça a marché ! Jarl et moi, nous sommes vos débiteurs, $N. Le seul problème qui reste, c\'est le goût de mon ami en matière de mobilier, et j\'ai peur que ça soit moins simple à résoudre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11184,'Ah, heureusement que quelqu\'un a fini par accepter cette offre. Je commençais à penser qu\'il allait falloir tripler la récompense pour faire tuer ce satané raptor, et notre budget ne pouvait pas encaisser ça !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11185,'<Andello lit la lettre, choqué par son contenu.>$B$BDepuis longtemps, nous avons des suspicions à l\'égard de la coopération entre la Horde et les Réprouvés, et cela ne fait que les confirmer. Appuyés par la magie et l\'armement des Réprouvés, les Totems-sinistres deviendraient un ennemi encore plus formidable. L\'équilibre des forces en Kalimdor pourrait s\'en voir considérablement modifié.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11186,'Si c’est bien ce qu’il semble, les Réprouvés auront des explications à donner !$b$bÇa fait longtemps que les pitreries du Totem-sinistre mettent à l’épreuve la patience du chef de guerre. Nous avons toujours considéré que c’était une affaire interne au peuple tauren, mais cette lettre pourrait changer la donne.$b$bCela prendra du temps pour enquêter sur ces soupçons, mais ne parlez à personne de ce que vous avez vu aujourd’hui.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11191,'Bien. Toute aide que je pourrai recevoir me sera utile. Ma première priorité est de rallumer la lampe.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11192,'Bon, j\'ai mes réserves, mais c\'est la seule solution disponible pour l\'instant. Une fois que la lampe sera remise en état de marche, je suis sûre que nous pourrons rechercher d\'autres moyens de l\'alimenter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11193,'Eh bien, la p\'tite Babs est bien gentille d\'avoir pensé à moi. Je ne sais pas si vous avez feuilleté le livre, mais il y a beaucoup de vrai dans les histoires qui y sont racontées. Les marins n\'ont pas tout inventé, vous savez.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11194,'Alors comme ça vous voulez en apprendre plus sur les monstres marins ? Mmm… Eh bien, je vais vous proposer un marché, mais je vous préviens : il y sera question de grandes quantités d\'alcool et de quelque chose de pas très gratifiant pour vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11198,'Bien joué, $N ! Je dois admettre que, quand j\'ai vu la bête pour la première fois, j\'ai eu mes doutes sur vos capacités à défendre les docks. Mais vous avez brillamment tenu le coup !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11200,'<Krog inspecte les armes et armures que vous avez rapportées de Sabot-noir.>$B$BC’est sans doute possible du travail de Mosarn. L’interroger encore risque d’attirer un peu trop l’attention, mais nous allons pouvoir nous occuper un peu plus librement de ceux du Totem-sinistre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11201,'<Krog parcourt le plan de bataille.>$B$BPour moi, il n’y a aucun doute, le clan Totem-sinistre se prépare à attaquer les humains. Ce que je ne comprends pas, c’est leurs intentions envers nous. Les actes du Totem-sinistre ont causé des tensions au sein de la Horde dans le passé, mais le Chef de guerre a toujours réussi à les désamorcer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11203,'<Tabetha amorce un léger sourire.>$B$BKrog souhaite que je détecte la présence du Totem-sinistre, hein ? Eh bien dans ce cas précis, pas besoin de divination magique.$B$BOn dirait que nous avons un ennemi mutuel. Ils ont construit un avant-poste près d’ici et ils ne cessent pas d’empoisonner mon existence et celles de mes élèves.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11204,'Il a vraiment dit que ceux du Totem-sinistre étaient ses plus gros clients ? Mosarn nous a aidés plus qu’il ne le pense. Avec tous ces éléments qui nous ramènent au Totem-sinistre, je crois que nous avons trouvé nos premiers suspects.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11205,'Les membres du Totem-sinistre ne devraient avoir aucun problème pour comprendre notre dernier message.$B$BDe votre côté, votre contact à Mur-de-Fougères voudra avoir écho de votre réussite. Je sais que la destruction de l’auberge du Repos ombragé pourrait être une source de tension entre la Horde et l’Alliance. Si je croise des enquêteurs de Theramore, je leur dirai volontiers que le Totem-sinistre a agi seul.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11206,'<Krog écoute votre rapport.>$B$BJe suis impressionné, $N. Je pensais que ces criminels du Totem-sinistre auraient été plus difficile à localiser.$B$BLes avertissements de Tabetha ne sont pas tombés dans l’oreille d’un sourd, mais ce n’est pas à moi qu’il revient de punir les membres du Totem-sinistre. Bien entendu, j’en ferai mention dans mon rapport au Chef de guerre. N’en parlez à personne avant que Thrall ne se soit occupé du problème. Vous avez fait du bon travail en résolvant le mystère de l’auberge du Repos ombragé et en nous évitant les soupçons de Theramore.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11207,'Dingue ! Vous en avez trouvé bien plus que ce que je pensais qu\'il en restait. Je ne sais pas exactement combien Drazzit espérait que nous pourrions en récupérer par ici, mais il faudra qu\'il se contente de ça pour le moment.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11208,'<Drazzit accepte votre chargement.>$B$BJ’ai tellement faim que je pourrais manger un dragon ! Je suis bien content que Moxie ait finalement pu faire livrer une partie de sa cargaison jusqu’ici. Nous en étions réduits à jouer aux dés avec l’ogre ce qu’il arrive à tuer quand il part chasser.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11209,'Pas mal du tout, mais vous savez, à votre place j\'irais prendre un bain le plus vite possible.$B$BBon, et pour ce qui est de votre monstre marin...$B$BPrenez donc une bière ou deux pendant ce temps.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11210,'<Vous racontez vos aventures avec Nat Pagle, en faisant bien attention à omettre l\'épisode du test de l\'appât.>$B$BEh bien, on dirait que la marche à suivre est toute tracée. Je vais faire les préparatifs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11211,'C\'est gentil de la part de Tabetha de vous envoyer ici. J\'aurais bien essayé de lui demander de la nourriture le temps de m\'occuper de l\'épave du zeppelin, mais je sais qu\'elle n\'en a pas de trop en ce moment. Si vous vous sentez d\'humeur aventurière, j\'ai mis la tête d\'un raptor particulièrement vicieux à prix.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11212,'Theramore a bien fait d\'envoyer quelqu\'un. Les suspicions de votre ami le garde sont fondées : nous avons de nouveaux voisins, et pas du genre à qui on apporterait une tarte.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11213,'C’est une chance que Nazeer ait pensé à envoyer quelqu’un. Nous avons de nouveaux voisins et ils n’ont cessé de nous nuire depuis que nous nous sommes installés.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11214,'Alors comme ça, Theramore veut faire des affaires ? Eh bien, ce n\'est pas le genre d\'offre que je refuserais. On manque un peu de ravitaillement ici en ce moment, alors on a besoin de tous les contacts commerciaux disponibles !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11215,'Toute aide est la bienvenue ! Nous sommes en train de nous installer ici et nous essayons de profiter au mieux de ce que nous avons, en attendant l’arrivée du ravitaillement du zeppelin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11216,'Je vous remercie d\'avoir pris le temps de venir à notre aide. Des tâches importantes nous attendent.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11217,'Merci ! Ça va permettre à nos gars d\'éviter les sorties jusqu\'à ce que Moxie revienne avec le reste des provisions du zeppelin accidenté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11222,'<Le [généralissime Bolvar Fordragon](/wotlk/fr/npc=1748/généralissime-bolvar-fordragon) écoute attentivement le message de Jaina.>$B$BÊtes-vous certain de ce que vous avancez ? C\'est une accusation très grave...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11225,'Vous êtes venu ici pour m\'espionner ? Non ?$B$BPeut-être que vous appréciez la cuisine raffinée, alors ? Bien, vous pouvez m\'aider !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11354,'Encore un client qui sera bientôt satisfait. Elle a l\'air d’être en bon état. Je vais vous récompenser.$B$BRevenez demain, et j’aurai une autre requête à vous soumettre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11362,'Peut-être que je vais demander qu’on y fixe quelques nouvelles plumes avant de l’envoyer à l’acheteur. Avec tous les arakkoa qui se trouvent dans les environs, ce ne devrait pas être trop difficile. Ce n’est qu’un détail, et cela ne retire rien à votre récompense, de toute façon.$B$BRevenez demain, et j’aurai une autre commande à vous proposer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11363,'C’est vraiment une très belle acquisition. Les bardes devraient en faire le récit sur le plus beau des parchemins. Tenez, vous avez amplement mérité cette récompense.$B$BRevenez me voir demain, et j’aurai une nouvelle requête à vous soumettre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11364,'Très bien, vous avez mérité votre prime.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11368,'Maintenant que j’y pense, c’est vraiment dommage que je ne vous aie pas demandé de me rapporter aussi les deux autres cœurs. Peut-être la prochaine fois… De toute façon, vous avez mérité votre commission.$B$BRevenez demain, et j’aurai une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11369,'C’est étonnant, n’est-ce pas, cette pulsation que l’on sent à travers la coquille ? Je dois me dépêcher de livrer l’œuf à l’acheteur. Ce serait bien dommage s’il venait à éclore prématurément, pas vrai ?$B$BVotre paiement est prêt.$B$BRevenez demain, et j’aurai une nouvelle commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11370,'Vous avez raison, je crains que mon client n’ait pas le temps de consulter la totalité de cet ouvrage. Néanmoins, ce n’est pas notre problème. Voici votre récompense.$B$BRevenez me voir demain, et j’aurai une autre commande à vous passer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11371,'Je gage que c\'était un combat digne de vous ? La prime le sera également.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah\'duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11372,'Je suis sûr que ces plumes seront du plus bel effet sur la coiffe du chef. Vous avez bien mérité votre compensation, $C.$B$BRevenez demain, et j’aurai une autre requête à vous proposer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11374,'Vous êtes une véritable héroïne, $N. Je suis certain que mon client trouvera un moyen de libérer l’esprit captif dans la gemme de la personne qui lui est chère. C’est du bon travail, et votre salaire vous attend.$B$BRevenez me voir demain et j’aurai une autre demande à vous proposer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11375,'Je craignais que vous ne reveniez plus. Je suppose que vous n’êtes pas devenu sourd en combattant Marmon ?$B$BVoici votre récompense. Le professeur sera sans nul doute ravi, mais je m’inquiète un peu de ce qu’il souhaite faire, au final, de cette chose.$B$BRevenez demain, et je vous confierai une nouvelle mission.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11376,'Je suis satisfait. Celui qui parle à travers le néant le sera également. Mah’duun a préparé votre prime.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11377,'Mais oui, c\'est bien l\'arôme d\'un mets délicieux ! J\'espère que vous avez bien tapé sur la viande de cet oiseau.$B$BJe vous en prie, servez-vous dans mes réserves. Quelqu\'un de votre talent saura en faire bon usage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11378,'Je vois que vous êtes revenu sain et sauf au présent.$B$B<Le marchand des vents regarde alentour.>$B$BOn dirait que rien n’a changé. Mais en fait, comment le saurais-je ?$B$BLa découpe est nette, mon client sera content. Voici votre récompense.$B$BRevenez demain et j’aurais une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11379,'Regardez-moi ça...$B$B<Le Rokk prend une gorgée de la décoction et son visage se déforme en une grimace où se mélangent douleur et plaisir.>$B$BBonté d\'A\'dal, c\'est délicieux ! Un cuisinier avec votre potentiel ne devrait jamais se retrouver sans ingrédient. Prenez donc un peu de mes réserves et faites-moi honneur.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11380,'Ce sont les baies de mana les plus juteuses que j\'ai jamais vu. Je sens que je deviens plus malin rien qu\'en les regardant.$B$BPuisque je n\'ai plus besoin de l\'essentiel de mes réserves de viandes et de poissons, pourquoi n\'en prendriez-vous pas un peu ? Je suis sûr que vous pourriez en faire quelque chose de délicieux.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11381,'Voilà un des arômes les plus délicieux de soupe spirituelle que j\'ai jamais senti. Il ne manque qu\'une pincée de poivre et c\'est prêt.$B$BComme promis, voilà votre part. Et puisque vous vous en êtes si bien tiré, je vais vous donner un peu de mes réserves avec.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11382,'Étonnant la façon dont le sable là-dedans tombe encore vers le haut. Je pense que je vais le faire livrer à son nouveau propriétaire en toute hâte.$B$BMerci pour ce travail bien fait, $C. Vous avez bien mérité votre commission.$B$BRevenez demain et j’aurai une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11383,'Vous avez trouvé votre chemin à travers le temps, et encore une fois pour revenir. Vous devez être un grand $C, $R. La prime est bien méritée.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11384,'Oh, vous avez réussi à l’avoir ! C’est si petit. Et pourtant, quand les druides en auront terminé - un processus extrêmement long, paraît-il - le Brise-dimension aura entièrement repoussé.$B$BEt voici comme promis votre récompense.$B$BRevenez demain et j’aurais une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11385,'Et maintenant ils sont morts et ne canalisent plus rien. Celui qui murmure dans le néant sera satisfait, et vous avez gagné la prime.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11386,'Je suis tenté de le garder pour moi et de rendre son argent à mon client. Ça me permettrait certainement d’étendre mon rayon d’action.$B$B<Le marchand des vents soupire.>$B$BMais j’ai une réputation à maintenir.$B$BÀ propos de ma réputation, merci de votre aide qui m’aide à la conserver. Voici votre commission.$B$BRevenez demain et j’aurais une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11387,'Mah’duun aime se battre contre les assemblages, c’est moins salissant qu’avec les créatures organiques.$B$BLa prime est à vous.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11388,'Je n’ose pas toucher le parchemin de peur d’attirer moi aussi l’attention des Dieux très anciens. Je vais charger un assistant de la livraison.$B$BVous avez plus que largement mérité votre récompense, $C, et je vous souhaite toute la chance des mondes connus.$B$BRevenez demain et j’aurai une autre commande à vous confier.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11389,'Les sentinelles étant détruites, les naaru demanderont peut-être au Consortium de les remplacer ? Mah’duun n’en sait rien et s’en moque.$B$BVous avez mérité la récompense.$B$BRevenez demain et les vents auront à nouveau soufflé aux oreilles de Mah’duun.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11451,'Comme c\'est touchant, merci !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11497,'Alors gamin, c’est Nutral qui t’envoie ? Brave type... faudra pas que j’oublie d’lui payer une pinte pour tous les clients qu’il fait débouler par ici.$B$BSi c’est d’apprendre à voler correctement qu’tu cherches, t’es venu au bon endroit. Personne vole mieux qu’un d’nous autres Marteaux-hardis ou ceux qu’on entraîne. Pour une somme -pas modique, faut avouer- j’t’apprendrai à t’élever dans les cieux !$B$BEt quand ce s’ra fait, oublie pas d’aller causer à Brunn si tu veux acheter un d’ses épatants griffons !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11498,'Sang et tempête, Nutral m’envoie encore un fantassin au pas pesant et aux pieds boueux ! C’est un brave gars... pour un draeneï.$B$B<Olrokk crache par terre près de vos pieds.>$B$BVous êtes au bon endroit si vous voulez apprendre à chevaucher votre propre monture à travers les cieux. Contre un gros sac d’or, je vous apprendrai ce que vous devrez savoir pour ne pas vous casser la figure et mourir dans le déshonneur.$B$BEt quand ce sera fait, vous pourrez passer voir Dama Crin-sauvage, là-bas, si vous voulez acheter un des coursiers du vent de nos écuries !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11004,'Je vous remercie, $N. Je vais en donner un peu au commandant… pour lui faire plaisir. Vous pouvez garder le reste, peut-être lui trouverez-vous une quelconque utilité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10962,'Génial ! Un dragon rien qu\'à moi ! Un jour, j\'espère que j\'aurai la chance d\'avoir un dragon pour ami.$b$b<Dornaa sautille de joie en serrant très fort dans ses bras son nouveau jouet.>$b$bC\'est le voyage le plus chouette du monde ! Je voudrais qu\'il ne finisse jamais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10963,'Terrible ! Un dragon rien qu\'à moi ! Un jour, j\'en aurai un vrai.$b$b<Salandria observe son nouveau jouet d\'un air entendu tandis que s\'activent les rouages de son cerveau.>$b$bC\'est le voyage le plus chouette du monde ! Je voudrais qu\'il ne finisse jamais.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10966,'Ça réchauffe le cœur de savoir qu\'il y a des héros comme vous qui sont prêts à offrir leur temps avec une telle abnégation.$b$bJe vois déjà que le temps que vous avez passé avec Dornaa a fait grande impression sur elle. C\'est très bon pour les enfants d\'avoir une occasion de sortir et voir le monde.$b$bTenez, elle m\'a dit qu\'elle voulait que vous vous occupiez de l\'un de ses familiers préférés, exactement comme vous vous êtes occupé d\'elle. En guise de souvenir.$b$bNe nous oubliez pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10967,'Ça réchauffe le cœur de savoir qu\'il y a des héros comme vous qui sont prêts à offrir leur temps avec une telle abnégation.$b$bJe vois déjà que le temps que vous avez passé avec Salandria a fait grande impression sur elle. C\'est très bon pour les enfants d\'avoir une occasion de sortir et voir le monde.$b$bTenez, elle m\'a dit qu\'elle voulait que vous vous occupiez de l\'un de ses familiers préférés, exactement comme vous vous êtes occupé d\'elle. En guise de souvenir.$b$bNe nous oubliez pas.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10969,'Oui, c\'est bien vrai. Mais le Consortium n\'est pas le seul groupe à faire état de pertes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10970,'Reculez, $N. Il pourrait parfaitement s\'agir d\'un piège de l\'Ethereum.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10971,'On dirait qu\'il ne s\'agit pas que d\'un moyen d\'identification. Ces plaques portent une sorte de code. Je suis sur le point de réussir à le décrypter. Peut-être que si j\'en avais d\'autres échantillons…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10972,'Nous sommes proches de la vérité, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11005,'Vous avez bien travaillé, $N. Vous avez porté un coup terrible à l\'ennemi en tuant les prêtres de la serre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11008,'Excellent travail, Valhaddon ! Nous allons montrer à ces hommes-oiseaux ce que signifie avoir la suprématie aérienne !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11010,'Bon, bon, on dirait que vous aviez l\'étoffe pour, après tout. Bon travail. P\'têt\' que le vieux Keller se trompait sur votre compte.$B$B<Le sergent Vanderlip de la Garde-ciel sourit d\'un air narquois.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11013,'<Mor\'ghor lit la lettre et éclate de rire.>$B$BUn chevalier de la mort ? Un ver de terre comme toi n\'est même pas digne de cirer les bottes d\'un chevalier de la mort.$B$B<Mor\'ghor vous examine des pieds à la tête.>$B$BMais d\'accord… tu réussiras peut-être à t\'élever au niveau de péon. Au pire, je te jetterai dans la fosse et je t\'y laisserai crever...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11014,'Varkule va te mitonner un boulot aux petits oignons. Tu peux choisir celui qui convient le mieux à ce que tu sais faire et à ta collection de cristaux de l\'Aile-du-Néant. On te donnera un ordre de mission à remplir une fois par jour.$B$BOuais, c\'est des boulots miteux, mais bon, même les ascendants ont débuté comme péons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11020,'<Yarzill murmure très bas.>$B$BExcellent travail, $N. Faites profil bas pour l\'instant. Revenez me voir demain et nous pourrons recommencer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11023,'V\'là du bon boulot, Axlord ! J\'vous renverrais bien là-haut les bombarder encore une fois, mais not\' politique ici c\'est de bien être sûrs que nos pilotes ont leurs périodes de récupération. Désolée, c\'est pas moi qui fais les règles, mais une chose est sûre, je les fais respecter !$B$BOn se revoit demain, champion ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11026,'That\'ll teach them!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11029,'Excellent ! Ce livre recense les descendants des anciens ennemis de Terokk. Il est prédit que leur mort sera suivie par le retour de Terokk.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11030,'Vous nous sauvez la vie, $N. Nos garçons vont être si contents d’apprendre cette nouvelle !$B$BBien, cela fait un flacon de moins à chercher. Au fait, nous vous avons parlé des autres flacons magiques dont ils auront besoin, n’est-ce pas ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11035,'<Yarzill murmure.>$B$BVous rendez un grand service à l\'Aile-du-Néant, $N. Peu à peu, nous renverserons les Gueules-de-dragon. Une maladie les ronge maintenant de l\'intérieur, et elle n\'a pas de remède…$B$BRevenez me voir demain si vous voulez à nouveau une mission pour le couloir aérien des Gueules-de-dragon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11039,'<La déception se lit un bref instant sur le visage du maître-espion.>$B$BJ\'espérais au moins une escouade, mais si Voren\'thal a jugé bon de n\'envoyer que vous, j\'adapterai mes plans en conséquence.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11040,'Je ne sais même pas ce que font certaines de ces pièces ! Je suis sûr que j’arriverai à en utiliser certaines, mais je n’aurais jamais cru que je devrais apprendre à penser comme un gnome !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11042,'<Le chef écoute votre description de la vision du prophète.>$B$BEh bien, tous ces trucs-là j\'en sais rien, mais on aurait effectivement bien besoin de votre aide par ici. Regardez le mastodonte qui se trouve derrière moi. C\'est la X-52…$B$BN\'est-ce pas la plus belle chose que vous ayez jamais vue ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11043,'<Le visage de Brunn devient si rouge qu\'on ne le distingue plus de sa barbe.>$b$bIl veut faire QUOI à mes griffons ?$b$bSi ce petit paltoquet pose quoi que ce soit d\'autre qu\'une selle sur eux, je me rendrai personnellement dans les Tranchantes pour lui faire manger sa fusée !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11044,'Une vision, que vous dites ? J\'en ai rien à faire que ça lui vienne d\'une vision ou directement de la bouche d\'un seigneur des abîmes, je sais juste une chose : il a complètement raison ! L\'important est que vous soyez là, l\'ami, et nous avons besoin de toute l\'aide que nous trouverons.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11045,'Fantei dit vrai et votre aide serait la bienvenue.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11046,'Fantei a une bonne mémoire. Ma dernière visite à Shattrath remonte à plusieurs mois ; j\'y achète des composants. Mais il a raison. J\'aurais besoin d\'aide.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11049,'Neltharaku sera extrêmement satisfait, $N. Bon travail.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11051,'Nous aimerions bien que le procédé de création d’une sombrerune soit sans faille, $N. Malheureusement, ce n’est pas le cas. Tenez, prenez ce sac, et regardez ce que nous avons récolté aujourd’hui. Nous ne supportons pas de le regarder nous-mêmes.$B$BN’oubliez pas que si vous obtenez une sombrerune, vous devez l’apporter à Gahk pour l’échanger contre une sombrerune cristalforgée. Cela vous permettra d’abattre une fois encore le transporteur de Shartuul.$B$BOh, $N, n’oubliez pas revenir demain et de reprendre le cristal de bannissement. Il y aura toujours des démons à bannir…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11056,'Excellent, $N. Vous verrez que je tiens parole.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11057,'Vous venez vraiment d’en haut ? Ma mission est véritablement bénie ! Je tente de sauver les Masse-sanglante de l’extermination par le clan Flèchelame et les Fils de Gruul, qui les soutiennent.$B$BJe suppose que c’est vous qui allez aider notre société secrète et nous donner la liberté.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11062,'Bienv’nue à l’avant-poste de la Garde-ciel ! J’l\'ai construit de mes propres mains, vous savez.$B$BOuais, tout ça !$B$B<Le commandant a l’air sérieux.>$B$BVous d’vez drôlement avoir envie d’vous lancer dans la bagarre, si vous êtes venu m’parler. C’est sympa de la part du vieux Chu’a’lor d’vous avoir envoyé. On a toujours besoin de chair fraîche pour la boucherie qu’a lieu ici.$B$BSi vous voulez bien, commencez par parler à mon sergent, qui est de l’autre côté, Vanderlip. N’faites pas trop attention à ses paroles, elles sont parfois plus tranchantes que l’espadon qu’elle trimballe.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11064,'Des citrouilles ? Oh, quelle déchéance… Je suis sûr que les autres cavaliers se montreront beaucoup plus coriaces.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11066,'Vous continuez à m’étonner ! Vous savez quoi ? Et si vous reveniez demain, et que nous laissions un peu le lasso refroidir pour aujourd’hui ?$B$B<Khatie rit de bon cœur.>$B$BEt encore merci, Silhantcat !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11067,'Intéressant… Le prochain duel sera sans doute bien plus difficile. Corlok n\'est pas un tocard.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11068,'Les deux prochains cavaliers étaient les deux meilleurs pilotes des nains et des orcs d\'Azeroth. Tu n\'as aucune chance !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11069,'C\'est incroyable ! Le prochain adversaire, c\'est Mulverick. Tu n\'y survivras jamais !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11070,'Eh bien, on dirait qu\'il ne reste plus que toi et le capitaine en lice, maintenant. Bonne chance ! Tu en auras bien besoin.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11071,'Je n\'avais jamais rêvé trouver un jour quelqu\'un d\'assez talentueux pour vaincre Fracasse-ciel. Tu sais ce que ça veut dire, hein ? Tu es le champion ! Il va falloir défendre ton titre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11073,'Nous sommes tous très fiers de vous, $N. J\'enverrai des nouvelles de vos exploits à Shattrath. La Garde-ciel vous est éternellement reconnaissante.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11074,'Excellent ! Prenez ceci. J\'ai mis dans ce paquet les objets que vous avez rassemblés. Ils vous permettront d\'invoquer Terokk.$B$BPrenez garde, $N. Il est le plus puissant des arakkoa à avoir jamais vu le jour. Ne le sous-estimez pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11077,'Ça suffira pour aujourd’hui, surveillant. Revenez demain pour une autre tournée de nettoyage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11079,'Gahk aime le fouet. Peut-être que Gahk y prend le fouet et y tape les démons avec !$B$BMoi dit à $R que $R appelle les chefs démons quand y veut, à chaque fois que $R a des amis et beaucoup d’éclats.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11083,'Ouais, je ne comprends pas… Après seulement deux jours, ils ne devraient même pas avoir très faim. Les Bourbesang…$B$B<Ronag secoue la tête.>$B$BBon sang qu’ils sont stupides…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11085,'Merci d’avoir secouru l’un de nos éclaireurs, $N. Nous perdons des gens compétents tous les jours, et nous n’avons pas assez de recrues pour les remplacer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11086,'Excellent travail, capitaine ! Le seigneur Illidan sera informé de votre héroïsme !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11089,'<Balthas assemble avec habileté les composants que vous lui avez apportés.>$B$BVous êtes maintenant prêt pour la seconde phase du plan, capitaine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11090,'Il reviendra, mais pour l\'instant la guerre de la Légion contre le seigneur Illidan est affaiblie. Il sera informé de vos exploits, capitaine.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11093,'Merci d\'avoir pris soin de cette raie, $N. Nos bêtes volent bien mieux quand elles sont bien nourries. Il serait stupide que nos gars se fassent abattre juste parce que leurs raies sont trop faibles pour tenir leur vol.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11094,'Vous avez bien fait de venir nous avertir. Peut-être pouvons-nous tirer avantage de cette attaque pour jouer un mauvais tour aux Gueules-de-dragon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11095,'<Hobb sourit.>$b$bUn piège des plus mortels qui soient…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11097,'<Mor\'ghor rit.>$B$BHAH ! Je savais que vous ne me décevriez pas, commandant ! Je veux que vous meniez un raid sur le Sanctum des Étoiles au moins une fois par jour. Ils n\'auront pas d\'autre choix que de quitter Ombrelune !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11099,'Vous avez bien fait de venir nous avertir. Peut-être pouvons-nous tirer avantage de cette attaque pour jouer un mauvais tour aux Gueules-de-dragon.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11100,'<Arcus sourit.>$b$bUn piège des plus mortels qui soient…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11101,'<Mor\'ghor rit.>$B$BHAH ! Je savais que vous ne me décevriez pas, commandant ! Je veux que vous meniez un raid sur l\'Autel de Sha\'tar au moins une fois par jour. Ils n\'auront pas d\'autre choix que de quitter Ombrelune !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11119,'Quoi que veuille en dire Keller, je préfère penser que nos missions ont pour objectif premier la recherche.$B$BMais oui, nous profitons de notre présence pour réapprovisionner la Garde-ciel. Quand nous pouvons y rester assez longtemps.$B$BVous avez l\'air d\'être partant pour tenir les éthériens à distance. Si vous réussissez à les occuper assez longtemps, nous vous vendrons le surplus de ce que nous aurons créé à la cristalforge, alors emportez vos cristaux et vos éclats apogides !$B$BNous partons dans 0 |4minute:minutes;.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11122,'Merci beaucoup de votre aide ! Tant que la fête des Brasseurs bat son plein et que les nains Sombrefer continuent à attaquer, j\'ai besoin de livraisons de tonneaux. Donc, si vous voulez gagner d\'autres bons, venez me voir tous les jours.$B$BMais assez avec ça, il faut que je vous paye pour le travail accompli. Voilà vos bons, profitez bien de la fête des Brasseurs !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11135,'L\'origine de ce sanctuaire est inconnue, mais il y a peu de doute sur le personnage à qui il est consacré…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11220,'L\'origine de ce sanctuaire est inconnue, mais on voit aisément à qui il rend hommage...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11293,'Bien joué ! Ce genre de clameur nous rapportera forcément de la clientèle.  $B  $BEt puisque nous vous avions promis une récompense, la voici. Les Brasselorge tiennent parole.  $B  $BEt surtout, n\'hésitez pas à revenir n\'importe quel autre jour si vous souhaitez nous aider à propager la bonne réputation des Brasselorge.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11405,'Allez-vous poser la chandelle et arracher le Cavalier sans tête à son repos maudit ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11407,'Vous avez tenu parole et annoncé la présence de nos brasseurs. Merci. Nous vous avions promis ces bons, et nous vous les donnons de bon cœur. J\'imagine que les trolls sont un peu moins généreux avec les leurs...$B$BRevenez un autre jour pour nous aider à faire connaître la fête des Brasseurs.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11408,'Vous avez réussi ! Nous devons nous préparez à la ruée des clients qui vont arriver ! Merci !$B$BAh, c\'est vrai, nous vous avions aussi promis une récompense. Pas moyen de l\'oublier...$B$BLibre à vous de revenir un autre jour pour nous aider encore à nous faire connaître.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11412,'Merci pour votre aide ! Tant que la fête des Brasseurs battra son plein, que les nains Sombrefer attaqueront et que notre fournisseur sera coincé dans ce canyon, j\'aurai besoin d\'aide pour récupérer des tonneaux. Donc si vous voulez travailler pour gagner quelques bons supplémentaires, revenez me parler tous les jours.$B$BLà, voici les bons que je vous avais promis. Amusez-vous bien !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11006,'Continuez à m’apporter de la poussière. Je préparerai tous les élixirs dont vous aurez besoin.$B$BCe sont les ordres du commandant.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11050,'Vous êtes un véritable héros, $N.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11060,'Petit $R, vous pas oublier que quand vous contrôlez le navilisseur, vous prendez son marteau pour crabouiller le bouclier du portail et lâcher l’démon qu’est dedans.$B$BPis vous crabouillez le démon et le contrôlez. Pis un aut’ démon viendre, et vous le contrôlez, jusqu’à que le surveillant érédar y viendre.$B$BPis vous le crabouillez lui aussi !!!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10975,'Il y a toujours plus à faire, $N. Trouvez une chambre de stase et détruisez le mal qui s\'y terre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (10981,'Comme promis, voici la clé de la chambre de stase personnelle de Shaffar.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11105,'Les sables du temps s\'écoulent vers l\'avant sans effort. Il est possible d\'en inverser le cours, mais cela est très difficile.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11481,'Un soldat de plus en provenance de Shattrath ? Excellente nouvelle !$B$BJ\'aimerais en avoir plus encore, mais on fera avec ce qu\'on a. Il se prépare quelque chose ici et ça n\'attendra pas qu\'on soit prêt.$B$BRegardez autour de vous, $C. Il y a beaucoup à faire. Mettez-vous au boulot et faites votre part.$B$BOh, et puis n\'allez pas trop énerver les larmoyants - euh, Clairvoyants. On dirait qu\'il va falloir travailler ensemble cette fois...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11482,'Bienvenue sur le Plateau du Puits de soleil, larmoyant - Qu\'est-ce qu\'il y a ? Oh, Clairvoyant, mais oui bien sûr. Ce n\'est pas ce que j\'ai dit ?$B$BBon, mettons bien les choses au clair. Il se passe quelque chose de grave derrière ces murs et c\'est dans l\'intérêt de nos deux groupes de s\'en occuper. Et comme aucun de nous ne dispose des forces nécessaires pour y aller seul, nous allons devoir travailler ENSEMBLE. Pigé ?$B$BAu boulot maintenant !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11490,'Je considère qu\'il n\'est pas une coïncidence que nos chemins se croisent en ce jour.$B$BJe sens les doigts du destin…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11492,'<Larethor écoute attentivement le récit de vos exploits sur la Terasse des Magistères.>$B$BTyrith nous manquera – c’était un bon élément. Mais grâce à vous, il n’est pas mort en vain.$B$BJe vous ai sous-estimé, $R. Je vous prie d’accepter ce cadeau au nom de l’opération Soleil brisé – il est digne d’un héros tel que vous.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11499,'Ainsi, le prince elfe de sang est véritablement mort cette fois ? Dommage, j’ai toujours trouvé qu’il avait de la classe. Quand on pense que quelqu’un de si haut rang peut être abattu pour une somme dérisoire !$B$BMais comme on dit, les affaires sont les affaires. Vous avez mérité votre récompense, aventurier.$B$BRevenez demain, j’aurai une nouvelle requête à vous proposer.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11500,'Qui peut dire pourquoi les sœurs démoniaques doivent être tuées ? Cela a-t-il une quelconque importance pour vous ?$B$BMah’duun pense qu’en revanche la prime vous importe suffisamment.$B$BRevenez demain, quand Mah’duun aura à nouveau entendu le murmure des vents.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11503,'Vous faites grand honneur à notre peuple. Soyez-en remercié.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11514,'Nous allons continuer d\'alimenter le portail avec ces cellules de mana.$B$BRevenez demain, je vous enverrai en chercher davantage.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11515,'Les imbéciles. Ils ont appris à drainer l\'énergie gangrenée mais pas à la conserver.$B$BNous avons eu de la chance, $N. Un gangresang expérimenté aurait sûrement été un adversable redoutable.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11516,'Excellent travail, $N. Les démons répareront le portail tôt ou tard. Je suppose qu\'il ne nous restera plus qu\'à le faire sauter une nouvelle fois.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11521,'Excellent travail, $N.$B$BEncore merci pour votre aide !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11523,'Bon travail, $N. Les protections retrouvent progressivement leur puissance. Le sanctum sera nôtre en un rien de temps !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11525,'Excellent. Les factionnaires convertis nous aideront à sécuriser notre périmètre.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11526,'C\'est très gentil de la part de Theris de s\'inquiéter pour moi, mais nous avons des problèmes plus sérieux en ce moment. Bien plus graves.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11533,'Chaque démon que nous tuons aujourd\'hui est un démon que nous n\'aurons pas à combattre demain. Continuez comme ça.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11534,'C\'est Portonuus qui vous envoie ? Bien, nous n\'avons pas de temps à perdre !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11536,'Excellent ! Voilà qui m\'aidera à faire en sorte que nos soldats soient toujours bien équipés en armes et armures.$B$BVotre aide compte vraiment beaucoup !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11537,'Votre dévouement est exemplaire, $N. Nous allons montrer aux forces de la Légion ardente de quoi nous sommes capables.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11540,'Quelles pensées peuvent bien traverser la tête du prince Kael\'thas Haut-soleil quand il apprend les défaites de ses armées ?$B$BRessent-il du désepoir ? Se sent-il impuissant ? A-t-il peur ?$B$BJe l\'espère bien.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11541,'C\'est suffisant pour aujourd\'hui. Le mot d\'ordre est lentement mais sûrement. De trop grandes perturbations leur feraient tourner leur attention directement sur nous, ce que nous ne voulons surtout pas.$B$BRevenez demain, nous reprendrons notre tâche.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11543,'Très bien, $N. Il s\'écoulera un bon moment avant que le port ne reçoive des renforts.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11544,'Merci, mon ami. Je vais pouvoir fabriquer davantage de cet alliage spécial dont je me sers pour créer les armes et les armures de nos troupes.$B$BEt il me reste quelques sous-produits de l’extraction. Vous les trouverez sûrement utiles pour vos armes. S’il vous plaît, prenez ce qui vous convient le mieux.$B$BRevenez me voir demain, j’aurai certainement besoin d’autres armes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11546,'Excellent, $N.$B$BJ\'espère que ceci vous sera d\'une quelconque assistance dans vos aventures par ici.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11547,'Oui, oui. Regardons ça maintenant.$B$BTout a l\'air en ordre. Très bien. Voici votre transposeur.$B$BSi l\'un de vos relevés était faux, il est impossible de prévoir où vous atterrirez, et notez bien que vous ne pourrez vous en prendre qu\'à vous-même.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11548,'Votre âme est vertueuse, $N. Il est aisé d\'oublier ceux qui sont tombés lorsqu\'on est dans le tumulte de la guerre ou dans l\'euphorie de la victoire. Les amis et les familles des morts vous remercient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11549,'Vous êtes vraiment une personne généreuse et un allié de valeur. À partir d\'aujourd\'hui, on vous appellera $N du Soleil brisé, et tous ceux qui se sont battus ici connaîtront vos exploits !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11554,'Votre contribution à l\'opération n\'est pas passée inaperçue, $N. Les forces unies de l\'Aldor et des Clairvoyants vous remercient.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11665,'Quelle sale petite bête ! Je suis sûr que le Rokk en fera quelque chose de fort goûteux.$B$BJ\'plaisante, bien sûr.$B$B<Le vieux Barlo vous fait un clin d\'œil.>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11666,'Hé bé… vous avez fait une sacrée prise ! Je connais quelqu’un qui va se faire un bon gueuleton ce soir.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11667,'Le voilà ! Impossible de ne pas reconnaître cette cicatrice.$B$BPour être franc, je pensais qu\'il serait... plus gros. Eh bien, j\'imagine qu\'il ne me reste plus qu\'à le remettre à l\'eau et réessayer un autre jour.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11668,'Vous vous en sortez bien avec un hameçon et avec un couteau. Passez-moi vos prises, et je vous laisserai goûter.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11669,'C\'est le poisson le plus gros et le plus laid que j\'aie jamais vu. Je me demande bien ce que vous avez utilisé comme appât.$B$BContentez-vous de poser ce monstre par terre, je m\'occuperai de lui quand je serai sûr qu\'il est bien mort.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11807,'Honorez la flamme des Tranchantes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11821,'Honorez la flamme de Nagrand.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11838,'Honorez la flamme de Tanaris.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11843,'Honorez la flamme des Tranchantes.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11875,'Merci de votre aide, $N. Aucune contribution à l’effort de guerre n’est insignifiante. Si nous voulons gagner cette bataille, nos hommes ont besoin de tous les avantages possibles.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11877,'<Le seigneur Torvos accepte les plans et les examine.>$B$BVous avez rendu un grand service à l’opération, $N, mais nous ne devons pas nous reposer sur nos lauriers. Je soupçonne nos ennemis de préparer d’autres actions.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11880,'Merci de votre aide. Vous n’avez aucune idée de ce que ça représente de travailler avec le "Docteur" Grillegaufre. Entre chaque "examen" de mes progrès, il essaye de fourguer des gadgets dérivés de ses inventions militaires.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11885,'Excellent ! Prenez ceci. J\'ai mis dans ce paquet des objets symbolisant les ennemis que vous avez vaincus. Ils vous permettront d\'invoquer Terokk.$B$BPrenez garde, $N. Il est le plus puissant des arakkoa à avoir jamais vu le jour. Ne le sous-estimez pas !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11915,'Bonjour. Vous venez apprendre de nouvelles méthodes pour manipuler les flammes ?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11922,'Bien joué ! Vous saurez jongler avec le feu en un rien de temps ! Et maintenant, préparez-vous ! La prochaine épreuve sera plus chaude.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11948,'Vous avez bien fait. Ça peut sembler peu de chose, mais c\'est tout de même utile à notre combat dans son ensemble. Prenez ceci avec ma bénédiction, et repassez plus tard. J\'aurais peut-être d\'autres services à vous demander.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11952,'Vous avez bien fait. Ça peut sembler peu de chose, mais c\'est tout de même utile à notre combat dans son ensemble. Prenez ceci avec ma bénédiction, et repassez plus tard. J\'aurais peut-être d\'autres services à vous demander.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11954,'Vous avez bien fait. Ça peut sembler peu de chose, mais c\'est tout de même utile à notre combat dans son ensemble. Prenez ceci avec ma bénédiction, et repassez plus tard. J\'aurais peut-être d\'autres services à vous demander.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11964,'Ah, et qu’est-ce que c’est ? Quel arôme délicieux ! Je suis sûr qu’il brûlera en créant une flamme pure et brillante !$b$bPrenez cette fleur, $N. Prenez-la et laissez-moi… Je dois m’occuper de ce précieux combustible…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (11966,'Ah, et qu’est-ce que c’est ? Quel arôme délicieux ! Je suis sûr qu’il brûlera en créant une flamme pure et brillante !$b$bPrenez cette fleur, $N. Prenez-la et laissez-moi… Je dois m’occuper de ce précieux combustible…') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12515,'Mon… mon chapeau ! Comment avez-vous… ?$B$BPeu importe. Eh bien… Vous connaissez donc mon secret. J\'ai été battu... une fois. Tenez, prenez ce chapeau en échange du mien. Vous l\'avez bien mérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12513,'Mon… mon chapeau ! Mais alors… C\'était bien VOUS. C\'est bien ce que je croyais. Mes vieilles cicatrices me faisaient souffrir lorsque vous n\'étiez pas loin, mais… vous êtes si jeune ! Vous n\'avez absolument pas changé !$b$bEh bien… Vous connaissez donc mon secret. J\'ai été battu... une fois. Tenez, prenez ce chapeau en échange du mien. Vous l\'avez bien mérité.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12286,'Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12331,'Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
