INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12339,'"Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !"$B$BThis is the NPC dialogue text displayed upon quest completion, appearing before the rewards list.') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
