INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12406,'Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12407,'Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`OfferRewardText_loc2`) VALUES (12408,'Vous trouverez des seaux de bonbons comme celui-ci dans des auberges un peu partout dans les royaumes. Allez-y, servez-vous !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc2`=IF(COALESCE(`OfferRewardText_loc2`,'')='',VALUES(`OfferRewardText_loc2`),`OfferRewardText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10939,'Je vois que vous avez réussi à réunir une suite de Tempêtes ! Félicitations !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8326,'Vous demander de tuer ces animaux ne me procure aucun plaisir. Autrefois, nous vivions dans une harmonie relative avec les créatures des bois, mais les temps ont changé. Maintenant, le premier impératif de tous les sin’dorei est la survie. Souvenez-vous-en.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8330,'Avez-vous eu l’occasion de récupérer mes affaires ? Lorsque nous aurons repris le contrôle de l’île de Haut-soleil, j’en aurai besoin pour mon travail. Pour l’heure, je dois me contenter de veiller sur le puits de soleil… ou sur ce qu’il en reste.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8335,'Écoutez-moi bien : Felendren le Banni n’est que le symptôme d’un mal plus profond. Son trépas résoudra nos problèmes immédiats, mais son sort menace tous les elfes de sang. Il suffit de laisser notre dépendance prendre le pas sur ce que nous sommes.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8336,'Grâce à notre magie, la plupart des créatures de l’île étaient paisibles et dociles. Hélas, lorsque le Fléau a détruit le puits de soleil, nous avons cessé de les contrôler. Les esquilles arcaniques sont les vestiges de notre ancienne domination. Elles pourraient nous servir à façonner un nouvel outil d’assujettissement.$B$BMieux encore, elles nous permettront peut-être de découvrir la véritable origine du malaise qui plane sur notre île…') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8338,'À en juger d’après votre attitude, il semble que l’affaire qui vous amène soit urgente. Puis-je faire quelque chose pour vous ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8350,'Bienvenue dans mon auberge, $C. Auriez-vous quelque chose pour moi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8463,'Avez-vous déjà retrouvé les cristaux volés ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8479,'Vous apporter à moi tête de Zul’Marosh ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8480,'Avez-vous récupéré les armes perdues ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8482,'Vous avez quelque chose pour moi ? Voyons cela.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8483,'Avez-vous réglé le sort de l’intrus ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8491,'Vous êtes de retour. Avez-vous les fourrures ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8884,'Nous autres forestiers de la retraite des Pérégrins nous consacrons à la réparation des dégâts qui ont frappé notre belle région. Nous sommes prêts à tout dans ce but.$B$BJ\'imagine que vous avez les têtes de murlocs que je vous ai chargé de rapporter ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8885,'Vous êtes l\'instrument de mon succès et de ma vengeance, $C. Avez-vous l\'anneau ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8886,'J\'apprécie beaucoup votre aide, $N. Ça me rend presque le sourire. Mais ensuite je repense à ce que ces monstres ont fait à mon bateau et à ce qui se passe à Quel\'Thalas.$B$BAvez-vous réussi à récupérer une partie de ma cargaison ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8889,'Je ne vois pas bien à cette distance… Avez-vous déjà coupé l\'alimentation à la flèche de Ternesoir ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (8891,'Qu\'est-ce que c\'est ? Ça me rappelle quelque chose. Oh non, ce journal... mes recherches... Voilà la cause de tout cela.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9062,'Toujours pas ? Bon, continuez à chercher. Ce livre est très important, $C.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9067,'Je ne vous ai pas envoyé chercher des provisions pour la fête ? C’était bien vous ? Je suis incapable de me rappeler des visages de tout le monde. Je rencontre tant de gens… intéressants.$B$BBon, que voulez-vous ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9076,'Alors, avez-vous sa tête, oui ou non ? Je n’ai pas de temps à perdre, $N.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9130,'Oui, qu’y a-t-il ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9133,'Dites donc, c’est une sacrée liste que vous avez là, l\'ami ! Voyons, laissez-moi jeter un coup d’œil.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9134,'Dites-moi, cette caisse de matériel a l’air très lourde. Vous voulez la charger sur l’une de mes bêtes ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9148,'Vous avez la lettre ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9162,'Dites-moi, $N, qu’avez-vous trouvé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9164,'Que sont devenus les prisonniers de Mortholme ? Avez-vous réussi à vous y aventurer ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9166,'Merci bien, vous tombez à pic !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9167,'Alors, c’est chose faite ? Dar’Khan est détruit ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9171,'J’ai l’impression d’entendre gargouiller l’estomac de dame Auriférias d’ici ! Je suppose que si vous êtes là, c’est parce que vous avez ce que je vous ai réclamé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9172,'Vous voulez me parler ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9174,'Ça y est, Aquantion est détruit ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9176,'Avez-vous déjà récupéré les cristaux ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9180,'Et vous êtes ?$B$BQu\'avez-vous donc là ? Ce collier me semble familier. Donnez-le-moi !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9193,'C’est une tâche sinistre et sans gloire, $C. Je compte sur vous pour la mener à bien à l’entière satisfaction de notre dame.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9199,'Inutile de vous rappeler que nous ne pouvons pas nous permettre d’avoir un problème de trolls morts qui se relèvent dans notre arrière-cour ! Nous avons assez d’ennuis comme ça avec Mortholme au sud !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9214,'Vous avez déjà trouvé les armes ? Une fois les troupes des Ombrepins décimées, nous pourrons enfin nous consacrer au combat contre le Fléau.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9255,'Vous avez quelque chose pour moi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9280,'$N, avez-vous pu récolter le sang de phalène dont nous avons besoin pour nos cristaux de soins ? Il reste des survivants éparpillés dans le val entier. Nous devons faire vite !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9293,'Je vais avoir besoin de tous ces échantillons en bon état si nous voulons avoir une chance de nettoyer le lac.$B$BNous n’avons pas beaucoup de temps, $c !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9305,'Quand nous aurons ces pièces de rechange, nous pourrons réparer l’émetteur. Avec un peu de chance, il restera également quelqu’un à qui parler.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9345,'Avez-vous trouvé les plantes ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9349,'Vous avez les œufs ?$B$B<L’estomac de Legassi gargouille d’impatience.>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9351,'Avez-vous pu récupérer l\'essence ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9356,'Je meurs d’envie de voir la tête qu’il fera. Depuis l’accident, il n’arrête pas de se plaindre que je ne pense qu’à manger. Il faut bien que quelqu’un s’occupe de nous nourrir pendant qu’il bricole avec le zeppelin !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9360,'Que voulez-vous me montrer ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9361,'Alors, avez-vous réussi à purifier la viande de sanglier infernal ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9366,'Alors, $N, avez-vous le gangresang ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9369,'Avez-vous pu récolter le sang de phalène dont nous avons besoin pour les cristaux de soin ? Il reste des survivants éparpillés dans tout le val, nous devons faire vite !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9370,'Vous êtes de retour, $N. Avez-vous mis un terme à la folie des draeneï ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9372,'Avez-vous trouvé ces échantillons de sang ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9373,'Bonjour, $C. Qu’est-ce qui vous amène à mon camp ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9374,'Alors, $N, quelles nouvelles ? Vous trouverez les bassins d’Aggonar au nord de la citadelle des Flammes infernales.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9376,'Le pronostic n’est pas très bon. À ce rythme, nous ne la remettrons jamais sur pied. Avez-vous trouvé son sac ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9381,'Avez-vous réussi à trouver toutes les plumes ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9383,'Avez-vous employé la magie du cristal sur un marcheur du Vide incontrôlé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9385,'Alors, avez-vous fait des progrès face aux ravageurs ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9387,'Avez-vous obtenu les échantillons ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9391,'Avez-vous fait ce que je vous avais demandé, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9396,'Avez-vous obtenu les parchemins, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9397,'Vous voilà de retour. Avez-vous la femelle kaliri ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9401,'Alors, l’assassin est-il mort ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9405,'Dites-moi ce que vous cherchez, que je puisse vous aider à le trouver.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9409,'Bonjour, $C. Qu\'est-ce que vous avez là ? C\'est pour moi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9410,'Vous avez de la chance d\'être en vie.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9417,'Vous êtes de retour ! Comment avez-vous fait ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9418,'La liberté à laquelle j\'aspirais est enfin mienne !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9420,'Avez-vous ces plumes de kaliri, $c ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9424,'Avez-vous vengé Sedaï pour Makuru ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9426,'Votre tâche est-elle achevée, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9427,'Vous êtes de retour, $N. Les eaux sont-elles purifiées ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9430,'Avez-vous récupéré les reliques de Sha\'naar, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9431,'Le message de la magistrice Elosai était un peu énigmatique, mais je crois que j’ai compris ce qu’elle veut. Si vous avez la terre dont elle parlait, je peux la mettre dans le récipient dont vous aurez besoin pour l’eau du puits de lune.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9433,'Alors, comment s’en est-il sorti ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9434,'Avez-vous réuni les composants, Wizlo et vous ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9435,'Êtes-vous parvenu à reprendre les cristaux des mains des Réprouvés ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9436,'Vous ne devez pas échouer, $N. Si nous pouvons plier la magie des Scalps-rouges à notre volonté, mon peuple pourra peut-être éliminer la menace des Amani.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9438,'Vous apportez des nouvelles de l\'Outreterre, $c ? Parlez sans tarder !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9440,'Alors, les animaux capturés ont bien tout mangé ? Oh, attendez ! Rassurez-moi, vous n’en avez pas donné à ce stupide humain qu’ils gardent en cage ?$B$BTrès bien, ç’aurait été du gâchis !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9442,'Avez-vous obtenu le champignon dont j\'ai besoin, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9444,'Est-ce fait ? La tombe d’Uther a-t-elle été profanée ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9447,'Vous voilà de retour, $N. Avez-vous achevé votre tâche ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9452,'Faites attention aux murlocs. Ces drôles de petites créatures sont extrêmement pénibles.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9453,'Que pensez-vous de mon armure ? C’est du fait maison ! Elle est un peu différente de ce que nous portons d’habitude, mais elle est très confortable.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9455,'Qu\'est-ce que c\'est ? Où l\'avez-vous trouvé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9463,'Je crains que son état ne cesse de se dégrader.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9466,'Y a-t-il du nouveau au sujet de Griffe-noire ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9475,'À voir votre visage, il semblerait que vous soyez le porteur d’une mauvaise nouvelle. Qu’avez-vous découvert ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9483,'Ce n\'est pas parce que je suis en pèlerinage que je dois abandonner tous les plaisirs de la vie. Cela fait des siècles que je n\'ai pas degusté un bon vin.$b$bJ\'en arriverais presque à tuer pour une bouteille d\'esprit-de-vin cénarien !$b$bJe sais, je sais, ce n\'est pas du tout la mode de boire quelque chose produit par les elfes de la nuit.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9490,'Avez-vous la preuve de la mort de Griffe-noire, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9492,'Êtes-vous revenu avec la preuve du trépas du "Chef de guerre" Kargath Lamepoing ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9493,'Je ne suis pas naïf au point de croire que la défaite des légionnaires de la Main brisée sera annonciatrice de notre victoire sur la Gangr’horde, mais c’est déjà une bonne première étape.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9494,'<Le magus Zabraxis jette un regard vers Amythiel Marche-brume et baisse la voix.>$B$BVous avez rapporté la, heu, la braise ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9506,'Comment ça se passe, étranger ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9517,'<L’ancien produit quelques craquements lorsqu’il se tourne vers vous.>$B$BL’architecte Nemos m’a fait savoir que vous apporteriez peut-être du bois récupéré au camp des défricheurs et dans la vile Satyrnaar.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9519,'Vous la sentez, $N, cette pointe de corruption portée par le vent ? Si nous ne faisons rien, elle continuera à progresser. C’est pourquoi je cherche le calice d\'Elune. L’avez-vous trouvé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9520,'Qu’avez-vous ici, madame ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9523,'Et ne revenez pas sans quelques reliques anciennes !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9527,'Ma femme s’appelait Thalrisa et ma fille Magwin.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9530,'J\'adore quand un plan se déroule sans accrocs…') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9531,'Ce traître va regretter d\'avoir cherché des histoires au commandement naval de l\'Alliance !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9535,'Qu’avez-vous ici, Éclaireur ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9537,'Avez-vous trouvé ce chien menteur ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9545,'Avez-vous déjà reçu la vision, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9548,'Avez-vous réussi à trouver mon matériel ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9549,'Vous avez trouvé les échantillons, que je puisse les envoyer à Forgefer ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9550,'C\'est peut-être ce vieux journal qui était représenté sur la carte.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9557,'La Lumière brille sur vous et sur toutes vos actions, $C. Qu’avez-vous là ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9560,'Ce sont de vilaines petites créatures. Même le Guetteur aveugle pouvait le voir… et il est aveugle.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9562,'Un murloc m’a donné un coup de pied au derrière et m’a craché dessus… en plein jour !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9563,'Vous avez du mal à trouver la bière ? Le bon vieux Bernie au Rempart-du-Néant a probablement des réserves.$B$BÀ moins qu’il ne soit à court… ce serait désastreux.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9564,'Est-ce que c\'est ce que je pense ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9567,'Êtes-vous parvenu à en apprendre davantage sur les satyres Nazzivus ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9569,'<Les yeux du redresseur de torts Aalesia semblent regarder à travers vous. Elle ne pense visiblement qu’aux satyres.>$B$BM’avez-vous obéi ? Avez-vous combattu les satyres ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9570,'<Kurz vous regarde et grogne.>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9571,'Salut, héros !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9572,'$N, c’est ça ? Stok’ton m’a fait savoir que vous viendriez faire votre rapport.$B$BJ’espère que ce sont de bonnes nouvelles ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9574,'Avez- vous réussi à vous procurer mes échantillons ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9575,'$N, c’est ça ? Chadwick m’a fait savoir que vous viendriez faire votre rapport.$B$BQu\'est-ce que vous faites en ma présence ? Votre mission est-elle terminée ? Qu’est-ce vous êtes au juste, l’idiot du village ? Vous me donnez envie de vomir !$B$BAlors maintenant, vous allez traîner votre peau de bon à rien-mauvais en tout sur ces remparts et faire ce qu’on vous a ordonné. Pigé ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9576,'Qu\'avez-vous là ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9579,'<Morae vous regarde avec espoir.>$B$BAvez-vous retrouvé la moindre trace de Galaen ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9580,'Comment se passe la chasse, $N ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9581,'Avez-vous pu récupérer le premier échantillon de cristal ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9584,'Avez-vous le deuxième échantillon de cristal ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9585,'Avez-vous le dernier échantillon de la série ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9589,'Alors, mon lapin, vous l\'avez, ce sang ? Vous savez, si on vous l\'a demandé, c\'est que c\'est important.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9590,'Vous n’avez sûrement pas encore tout le sang dont j’ai besoin ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9602,'Vous êtes de retour !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9603,'Bonne journée, $N. Voulez-vous louer un hippogriffe ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9604,'Salutations, mon amie. Vous avez l’air d’arriver de loin. En quoi puis-je vous aider ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9606,'Heureux de vous revoir, $N. Est-ce que Nurguni a pu réunir tout ce qu’il y avait sur la liste ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9607,'Soldat, au rapport ! Avez-vous reconnu la totalité de la Fournaise du sang ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9610,'J’attends que vous ayez récupéré assez d’artefacts atal’ai pour commencer à les étudier. Je suis impatient de découvrir ce qui a pu arriver à cette civilisation qui a été si grande.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9616,'Oui ? J\'ai beaucoup à faire, $N.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9621,'Ah, une visiteuse nous arrive de Quel\'Thalas ? Quelles sont les nouvelles ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9623,'< Torallius rajuste son couvre-œil.>$B$BEt c’est ce que nous avons de mieux à offrir à la Main d’Argus ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9624,'Les poires des sables sont de plus en plus difficiles à trouver et, bien sûr, cela veut dire moins de tartes et moins de douceurs pour les elekk. Avez-vous trouvé tous les fruits dont j’ai besoin ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9628,'Alors, savez-vous pourquoi l’équipe de reconnaissance a pris du retard ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
