INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9687,'Les guerres des dragons sont depuis longtemps passées. Tout ce qu\'il en reste, ce sont des os et les ombres agitées de la progéniture d\'Ysera.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
