INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9715,'Avez-vous tous les hibiscus que je vous avais demandé de récupérer ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
