INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9848,'Alors, vos recherches à Tourbedague vous ont-elles permis de découvrir les informations dont j’ai besoin pour tirer au clair cette histoire de poison ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
