INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9896,'Avez-vous réussi à récupérer l\'aiguillon ? Attention, s\'il est abîmé, je ne peux rien en faire.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9897,'Kristen est vraiment une… <tousse>… personne très gentille pour accepter ainsi de partager ses peaux. Vous ne trouvez pas ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9898,'La chance va tourner, je le sens.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9910,'Le respect obtenu par la peur en vaut un autre !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9911,'<La gardienne semble franchement déconcertée.>$B$BOù avez-vous eu ce… truc ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9914,'C’est de l’ivoire que je veux, pas des excuses. Bien sûr, si vous voulez, nous pouvons renégocier votre pourcentage sur les profits, mais je doute que le résultat vous plaise.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9916,'Les enfants pourraient peut-être passer une journée sans avoir le ventre qui crie famine.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9917,'Avez-vous découvert de nouvelles informations ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9928,'Nous allons provoquer une haine telle qu’il n’y en a jamais eu entre deux clans !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9931,'Vous pouvez prédire ce qui va arriver, maintenant ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9932,'Comprenez-vous pourquoi vous ne pourrez jamais me faire la guerre et me vaincre ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9933,'La paix, dites-vous ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9934,'<Garrosh ne semble pas ému par l\'offrande.>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9946,'Il sera sans nul doute entouré d\'une garde impressionnante.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9956,'Je me sens si bête. Corki, le fils d’Arechron, m’a demandé ce qui s’était passé, et j’ai été assez sotte pour le lui dire. Et maintenant, il a encore disparu !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9962,'Le combat se termine quand vous ou votre adversaire êtes mort sur le sol.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9968,'Avez-vous mes spécimens ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9992,'J\'ai commencé à collecter des graines, mais je vais avoir besoin d\'aide pour en avoir assez et pouvoir les envoyer au parc de Hurlevent.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (9993,'Avez-vous des graines pour moi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10001,'Évitez les surveillants à tout prix. Ils ne doivent surtout pas savoir que nous sommes là. Ce serait un désastre !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10004,'<Sal\'salabim se frotte la tête.>$b$b[Démoniaque] Ik il romath sardon.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10009,'Vous pas revenir sans or de Sal\'salabim !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10016,'Je vois que vous avez réussi à survivre aux rigueurs de la forêt. M\'apportez-vous des queues pour ma cape ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10017,'Vous êtes-vous procuré les glandes à venin, $N ? Les réfugiés ne peuvent plus attendre longtemps.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10022,'Alors, est-ce que le vieux Gueule-de-fer vous a ajouté à son tableau de chasse, mon ami ? Ou vous êtes-vous montré plus rusé que lui ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10023,'Les esprits attendent, $N. Avez-vous la fourrure du patriarche des loups ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10028,'Avez-vous pu trouver des calices intacts ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10030,'Qu\'est-ce que c\'est ? Qui êtes-vous ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10035,'Vous avez la plume ? Dois-je vous récompenser pour votre intrépidité ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10037,'<Seth tire sur votre cape.>$B$BVous avez trouvé les anguilles ? Hein ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10047,'Les cris semblent plus… lointains qu’avant. Fasse la Lumière que ce soit bien le cas !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10055,'Avez-vous réussi à trouver des matériaux utilisables sous la poussière, la cendre et la braise ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10058,'Je croyais vous avoir demandé de ne pas m\'ennuyer. Qu\'y a-t-il ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10066,'Avez-vous réussi à éliminer des noueurs mutés ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10074,'La poudre cristalline de la montagne est imprégnée d’énergie par le noyau terrestre de la région.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10076,'La poudre cristalline de la montagne est imprégnée d’énergie par le noyau terrestre de la région.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10078,'Vous avez l’air de bonne humeur. Est-ce parce que vous avez brûlé les engins de siège de la Horde ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10086,'Alors, comment se passe la mission de récupération ? Vous avez trouvé quelque chose d’utile ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10087,'J’ai cherché les signes révélateurs de canons en train de brûler… Un panache de fumée, ou les cris de grangr’orcs en feu…$B$BVous en êtes où, dans votre mission ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10098,'Il y a trop longtemps que les reliques de Terokk ont disparu de Skettis. Avez-vous réussi à les reprendre aux Sethekk ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10109,'Vous avez du gaz ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10111,'Je vous ai dit que j\'aimais les œufs ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10112,'Hmm, la mémoire serait-elle en train de me revenir ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10116,'Vous venez pour la prime du chef Mummaki ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10117,'Vous venez récupérer la prime pour le chef Mummaki ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10120,'Je vous ai vu parler avec Orion - ce doit être une affaire importante…') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10129,'Si vous n’y êtes pas arrivé du premier coup, réessayez.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10132,'La menace des colosses est-elle ramenée à ses vraies proportions ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10134,'C\'est un bien gros cristal que vous avez là. Est-ce que vous l\'avez eu en haut de la crête quand vous êtes allé tuer des colosses ?$B$BLaissez-moi y jeter un coup d\'œil.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10140,'Remerciez la Lumière d\'être arrivé ici vivant. Le bastion de l\'Honneur a besoin de tous les guerriers expérimentés qu\'il peut réunir.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10144,'Je regrette de ne pouvoir y aller pour admirer le feu d\'artifice. Ces explosifs sont drôlement costauds !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10146,'Cette mission est d\'une importance vitale, $N. Je ne la confierais pas à n\'importe qui.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10161,'Avez-vous trouvé assez de pièces ? Sinon, il va falloir que j’utilise cette poêle à frire que Legassi n’arrête pas de brandir. Et il faudra que je rebaptise le zeppelin « La poêle volante ».') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10162,'Montrez-leur que pas même le ciel n\'est sûr !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10163,'Montrez-leur que pas même le ciel n\'est sûr !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10166,'Vous êtes de retour, $N. Vous n\'en aviez pas fait assez ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10168,'<Mère Kashur est visiblement troublée.>$B$BCes naaru sont plus sages que toute forme de vie de ce monde.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10173,'Je n\'aurais de cesse d\'avoir rendu son bâton à l\'archimage Vargoth. Avez-vous réussi à le tirer des griffes du démon ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10186,'Est-ce que la fusée-de-néant X-52 a l\'air prête à décoller ? Est-ce que vous me voyez parcourir le Néant distordu bien assis dans mon fauteuil de commandant de bord ? Exploiter d\'étranges nouveaux mondes ? Rechercher de nouvelles technologies et ouvertures commerciales ? M\'aventurer courageusement là où aucun gobelin n\'a encore posé le pied ?$B$BNon !$B$BAlors j\'espère que vous avez ces cristaux que je vous ai demandé de récupérer.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10188,'Pour être libéré de la malédiction de la tour, il me faut ce cachet.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10190,'Avez-vous fini de charger la batterie de la pétoire ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10192,'Avez-vous apporté le livre ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10197,'Avez-vous les pièces d\'uniforme que je vous ai demandées ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10199,'Si je peux prélever du venin sur suffisamment de ces aiguillons de raie du Néant, je crois que nous pourrions obtenir le carburant le plus explosif jamais inventé !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10203,'Cet endroit n\'est-il pas super ? Et chaque jour nous apporte du nouveau et de l\'exotisme !$B$BQuelle chance que notre excavation ait presque détruit la ville.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10206,'Vous avez déjà récupéré leur technologie ? J\'espère bien que vous n\'êtes pas en train de me faire marcher, $C.$B$BLe succès du projet X-52 dépend de la vitesse à laquelle vous arriverez à tout récupérer !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10209,'Avez-vous la pierre de Glacius ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10221,'Sommes-nous à l\'abri des déprédations du Dr Boum ? Je vous promets que cette fois il n\'y aura pas de chariot explosif, même si on avait bien rigolé !$B$BIl faudrait vraiment faire ça plus souvent.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10224,'Vous avez toutes les essences ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10225,'Euh, bonjour. Je suis un peu occupé, là. Qu\'est-ce que c\'est ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10226,'Vous avez récupéré la puissance de ces élémentaires ? Oh, ce n’est pas la peine de vous dépêcher, hein. C’est juste ma vie et ma carrière qui sont en jeu.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10229,'Qu\'est-ce que c\'est ? Un livre qu\'avait sur lui un esprit inflexible ? Comme c\'est étrange. Permettez-moi de l\'étudier. Je pourrai peut-être apprendre quelque chose de l\'histoire des Inflexibles.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10230,'Nous devons aider les Inflexibles sans tarder. Si nous parvenons à les convaincre de nous rejoindre, la Horde aura gagné un allié puissant.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10234,'Vous avez les pièces ? La Légion ardente qui s\'installe au fur et à mesure sur tous nos emplacements ne nous laisse pas beaucoup de temps.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10235,'Vous vous êtes déjà occupé de Griffe-funeste ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10236,'Avez-vous trouvé des pièces de rechange pour mon déchiqueteur ? J\'ai vraiment hâte de le réparer pour pouvoir retourner miner. Il faut bien que j\'aie un moyen de gagner ma vie, ne serait-ce que pour pouvoir acheter un aller simple pour Baie-du-Butin.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10239,'Avez-vous pu leur prendre des sources d\'énergie ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10240,'Avez-vous activé toutes les runes ? Je suis impatient de voir si nous ne pourrions pas améliorer la méthode des elfes de sang. Tout ce que les hommes de Kael\'thas peuvent faire, le véritable Kirin Tor peut le faire mieux.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10242,'Bienvenue au poste de Brise-échine. Comment puis-je vous être utile ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10248,'Qu\'en pensez-vous ? Encore quelques réglages à faire, hein ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10250,'Avez-vous sonné le cor près de la tour de siège ? Il faut le faire rapidement. On ne sait pas quand Thrallmar pourrait avoir besoin des Inflexibles.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10252,'L\'armée de Levixus grandit en nombre et en puissance à chaque seconde qui passe. Vous devez faire vite.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10253,'Qui êtes-vous, et qu\'est-ce que vous voulez ? Oh… C\'est VOUS.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10255,'Avez-vous les résultats de l\'expérience ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10261,'J\'espère que vous êtes ici au sujet de mon avis de recherche !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10262,'Est-ce fait ? Avez-vous balayé la vermine Zaxxis de la surface de l\'Outreterre ? M\'avez-vous ramené leurs insignes ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10265,'J\'ai l\'impression que le prince recherche un cristal en particulier, mais je ne sais pas vraiment de quoi il s\'agit.$B$BAvez-vous déjà récupéré celui du seigneur de l\'effroi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10267,'Avez-vous repris possession de l\'équipement topographique que les elfes de sang ont refusé de payer ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10268,'Approchez.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10269,'Bonjour, voyageur. Vous venez trouver Hazzin pour vous procurer des marchandises ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10275,'C\'est pour un achat ou vente ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10277,'Ne revenez pas me voir avant d\'avoir au moins une connaissance rudimentaire de la situation.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10278,'Avez-vous déjà pu utiliser mon appareil expérimental ? Je pense que mon générateur de faille dimensionnelle instable fonctionnera là-bas si près des abysses.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10288,'Je vous ai vu parler avec Duron là-bas. Vous devez être sur une mission importante !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10289,'Un rapport d’Orion ? Donnez, et vite !$B$B<Sourcils froncés, le général Krakork parcourt le document déchiré.>$B$BDamnation ! C’est exactement ce que nous redoutions. Orion et ses guerriers peuvent se faire submerger n’importe quand !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10290,'Je sais bien que les dangers de la collecte de farahlite sont considérables, mais on peut en dire autant des opportunités. Un marchand qui n\'est pas prêt à prendre de tels risques peut tout aussi bien fermer boutique.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10293,'Vous êtes toujours en vie, ce qui ne peut vouloir dire que deux choses : soit vous avez le noyau, soit vous avez changé d\'avis. Alors ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10294,'Vous avez donc réussi ?? Vous avez les éclats dont nous avons besoin ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10295,'Avez-vous déjà détruit le baron du Vide Galaxis ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10300,'Êtes-vous parvenu à trouver des cristaux dignes de couronner le bâton de l\'archimage ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10301,'Avez-vous récupéré l\'oculus ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10309,'Ma vue doit souffrir de toutes ces radiations du néant. Vous avez déjà le cœur de saccageur gangrené ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10312,'Avez-vous pu trouver le registre ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10319,'Vous devez récupérer le phylactère de Naberius avant que nous l\'attaquions. Sinon, il sera invulnérable.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10324,'Les peaux des chevreuils sont raides et épaisses, et leur chair est coriace, presque immangeable, mais nous pouvons leur trouver d\'autres usages.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10329,'Le plan a-t-il fonctionné ? Je m\'attendais à moitié à ce que vous vous fassiez pulvériser, pour tout vous dire.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10331,'Avez-vous réussi à trouver mon marteau ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10334,'<La vache vous regarde d’un air méfiant et refuse de bouger.>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10335,'C\'était rapide. Vous devez être remarquablement efficace, sans quoi vous n\'auriez pas déjà placé ces trois marqueurs.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10338,'Vous avez réussi à tout fermer ? Dépêchez-vous avant que je ne reconsidère notre accord.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10342,'Vous avez ramassé assez de lauze ? Il va m\'en falloir beaucoup pour en extraire la quantité d\'huile nécessaire pour le carburant de la Fusée-de-Néant X-52.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10343,'Avez-vous trouvé des restes de l\'arme que Kael\'thas a utilisée contre le village ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10345,'Avez-vous pu trouver Ya-six ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10346,'Il reste encore plein de cibles sur la Saillie abyssale, $N. Attrapez un griffon quand vous serez prêt à retenter votre chance.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10347,'La Légion ne doit pas penser qu’elle est en sécurité sur la Saillie abyssale. Nous devons la frapper en permanence !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
