INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10642,'Si fait, il y a une dualité... je le sens.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10643,'Si vous perdez vos lunettes, venez me voir et je vous fabriquerai une nouvelle paire.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10647,'Z\'êtes là pour une récompense, mon vieux ? Non ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10648,'J’espère que vous avez fait quelque chose de spécial, ma fille. Autrement, fichez-moi le camp !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10656,'Parlez, $N.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10657,'L\'astuce pour utiliser la magnéto-sphère repolarisée, c\'est de savoir la débrancher avant de finir complètement grillé.$B$BBien sûr, il faut aussi prendre en compte le nombre de serpents volants qu\'on est prêt à affronter.$B$BEn parlant de ça, vous avez fini de charger la sphère ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10660,'Des rates ! Il me faut des rates !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10661,'Des rates ! Il me faut des rates !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
