INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10669,'Vous êtes de retour. Xeleth a-t-il été tué ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10671,'Vous avez ma livre de chair ? Quoi, vous ne trouvez pas ça drôle ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10674,'Je suppose que si vous revenez me voir, c’est que vous avez les orbes de lumière du Point d\'ancrage de Razan ? Ce serait très intéressant d’y jeter un coup d’œil pour voir ce que préparent les éthériens.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10675,'Vous êtes-vous déjà occupé de cette crapule de voleur d\'âmes de Razaan ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10677,'Spécialité du jour : du gésier.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
