INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10704,'<Les vibrations mélodiques de la voix d\'A\'dal résonnent dans votre esprit.>$B$BVous êtes de retour. Apportez-vous les deux pièces de la clé du satellite d\'Arcatraz ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10712,'Salut salut ! Mon clo… je veux dire mon cousin Tally m\'a dit que vous feriez un saut. Vous avez quelque chose pour moi ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10715,'Vous avez toutes les glandes à venin ? Si ce n\'est pas le cas, filez et ne venez plus me faire perdre mon temps tant que vous n\'aurez pas terminé.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10717,'Comment se passe l\'obtention des filets ? Pour ce que j\'ai pu en voir, ces filets utilisés par les braconniers devraient être assez résistants pour ce travail.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
