INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (10851,'Êtes-vous allé à l\'avant-poste Flèchelame ? Leur avez-vous pris leurs totems ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
