INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11181,'Vous avez pu cueillir certaines de ces plantes ? Nous devons nous mettre au travail rapidement, avant que le mal caché derrière cette infection ne consolide son emprise sur la région.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
