INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11378,'La tête du chasseur d’époque... Comment peut-on arriver à la décision de la mettre sur un mur ?$B$BEt quand bien même, le faire sans avoir chassé soi-même la créature, que dire ensuite aux amis qui demanderont le récit du combat ?$B$BJe suppose qu’il se contentera de mentir.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11379,'Comment marche ma petite expérience ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11380,'Vous avez trouvé, l\'ami ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
