INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11384,'Vous vous êtes perdu en allant à la Botanica ? Vous ne pouvez pas la rater... C’est au donjon de la Tempête, derrière le bord est du Raz-de-Néant.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11386,'Ce n’est pas que la technologie du projecteur soit quelque chose de particulièrement innovant, mais la portée de ce modèle est vraiment une percée !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11388,'Ce doit être particulièrement dangereux de se mêler des affaires des Dieux très anciens.$B$BJe vous laisse vous en charger !') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11451,'Oh, est-ce là un poème ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11010,'Alors, ces piles de boulets de gangrecanons, elles sont détruites ?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11013,'<Mor\'ghor pousse un grognement.>$B$BTu es en retard…') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
INSERT INTO `locales_quest` (`entry`,`RequestItemsText_loc2`) VALUES (11020,'C\'est un sale boulot, $N.') ON DUPLICATE KEY UPDATE `RequestItemsText_loc2`=IF(COALESCE(`RequestItemsText_loc2`,'')='',VALUES(`RequestItemsText_loc2`),`RequestItemsText_loc2`);
